/// Delegates to the writer gate. Kept as a `server.rs` item (not a re-export)
/// so the frozen item-4 sideways importer (`auth/coordinator`'s test module)
/// keeps its existing edge key until that inversion lands — a re-export would
/// re-key the frozen edge to `writer_gate` under the chained-re-export
/// analyzer without inverting anything.
pub(crate) async fn with_snapback<T, F>(state: &SharedSnapback, work: F) -> T
where
    F: FnOnce(&mut LocalSnapback) -> T + Send + 'static,
    T: Send + 'static,
{
    writer_gate::with_snapback(state, work).await
}

pub type SharedSnapback = Arc<Mutex<LocalSnapback>>;

static DETACHED_ACTION_WORKERS: AtomicUsize = AtomicUsize::new(0);
static DETACHED_ACTION_REJECTIONS: AtomicU64 = AtomicU64::new(0);
static DETACHED_ACTION_LIMITER: OnceLock<DetachedActionLimiter> = OnceLock::new();

const ACTION_WORKER_LIMIT_DEFAULT: usize = 32;
const ACTION_WORKER_LIMIT_MAX: usize = 1_024;
const CRON_DISPATCH_CONCURRENCY_DEFAULT: usize = 8;
const CRON_DISPATCH_CONCURRENCY_MAX: usize = 1_024;

struct DetachedActionLimiter {
    semaphore: Arc<Semaphore>,
    limit: usize,
}

/// Diagnostic/test visibility for the bounded-action worker invariant. A
/// timed-out action must interrupt its VM and return this count to baseline;
/// otherwise repeated hostile handlers would accumulate live CPU threads.
#[doc(hidden)]
pub fn detached_action_worker_count() -> usize {
    DETACHED_ACTION_WORKERS.load(Ordering::SeqCst)
}

/// Process-wide ceiling for detached native action workers. This is an
/// admission boundary, not merely a metric: once every permit is held, new
/// detached actions fail with a stable overload diagnostic instead of
/// allocating another OS thread.
#[doc(hidden)]
pub fn detached_action_worker_limit() -> usize {
    detached_action_limiter().limit
}

/// Workers admitted by the process-wide semaphore, including a worker that
/// has reserved capacity but has not entered its native execution thread yet.
#[doc(hidden)]
pub fn detached_action_admitted_count() -> usize {
    let limiter = detached_action_limiter();
    limiter
        .limit
        .saturating_sub(limiter.semaphore.available_permits())
}

#[doc(hidden)]
pub fn detached_action_rejection_count() -> u64 {
    DETACHED_ACTION_REJECTIONS.load(Ordering::SeqCst)
}

fn configured_action_worker_limit(raw: Option<&str>) -> usize {
    raw.and_then(|value| value.parse::<usize>().ok())
        .filter(|limit| *limit > 0)
        .map(|limit| limit.min(ACTION_WORKER_LIMIT_MAX))
        .unwrap_or(ACTION_WORKER_LIMIT_DEFAULT)
}

fn configured_cron_dispatch_concurrency(raw: Option<&str>) -> usize {
    raw.and_then(|value| value.parse::<usize>().ok())
        .filter(|limit| *limit > 0)
        .map(|limit| limit.min(CRON_DISPATCH_CONCURRENCY_MAX))
        .unwrap_or(CRON_DISPATCH_CONCURRENCY_DEFAULT)
}

/// Parse the `SNAPBACK_CRON_DISABLED` switch: `1` or `true` (any ASCII case,
/// surrounding whitespace ignored) disable autonomous cron claiming; every
/// other value — including empty and typos — leaves the scheduler on, so a
/// malformed variable can never silently disarm production crons.
pub(crate) fn cron_autonomy_disabled(raw: Option<&str>) -> bool {
    raw.is_some_and(|value| {
        let value = value.trim();
        value == "1" || value.eq_ignore_ascii_case("true")
    })
}

fn detached_action_limiter() -> &'static DetachedActionLimiter {
    DETACHED_ACTION_LIMITER.get_or_init(|| {
        let limit = configured_action_worker_limit(
            std::env::var("SNAPBACK_ACTION_MAX_CONCURRENCY")
                .ok()
                .as_deref(),
        );
        DetachedActionLimiter {
            semaphore: Arc::new(Semaphore::new(limit)),
            limit,
        }
    })
}

#[derive(Clone, Copy)]
struct DetachedActionWorkerCounters {
    active: &'static AtomicUsize,
    rejections: &'static AtomicU64,
}

fn global_detached_action_worker_counters() -> DetachedActionWorkerCounters {
    DetachedActionWorkerCounters {
        active: &DETACHED_ACTION_WORKERS,
        rejections: &DETACHED_ACTION_REJECTIONS,
    }
}

#[cfg(test)]
fn reserve_detached_action_worker(
    limiter: Arc<Semaphore>,
    limit: usize,
) -> SnapbackResult<OwnedSemaphorePermit> {
    reserve_detached_action_worker_with_counters(
        limiter,
        limit,
        global_detached_action_worker_counters(),
    )
}

fn reserve_detached_action_worker_with_counters(
    limiter: Arc<Semaphore>,
    limit: usize,
    counters: DetachedActionWorkerCounters,
) -> SnapbackResult<OwnedSemaphorePermit> {
    limiter.try_acquire_owned().map_err(|_| {
        counters.rejections.fetch_add(1, Ordering::SeqCst);
        SnapbackError::error(
            "SNAPBACK_ACTION_CAPACITY_EXCEEDED",
            "runtime",
            format!(
                "all {limit} detached action worker slots are busy; retry after an action finishes"
            ),
        )
        .with_details(json!({
            "activeWorkers": counters.active.load(Ordering::SeqCst),
            "workerLimit": limit,
        }))
    })
}

struct DetachedActionWorkerGuard {
    active: &'static AtomicUsize,
}

impl DetachedActionWorkerGuard {
    fn enter(counters: DetachedActionWorkerCounters) -> Self {
        counters.active.fetch_add(1, Ordering::SeqCst);
        Self {
            active: counters.active,
        }
    }
}

impl Drop for DetachedActionWorkerGuard {
    fn drop(&mut self) {
        self.active.fetch_sub(1, Ordering::SeqCst);
    }
}

fn spawn_detached_action_worker<T, R, F, Complete>(
    permit: OwnedSemaphorePermit,
    counters: DetachedActionWorkerCounters,
    task: F,
    complete: Complete,
) -> std::io::Result<std::thread::JoinHandle<R>>
where
    T: Send + 'static,
    R: Send + 'static,
    F: FnOnce() -> T + Send + 'static,
    Complete: FnOnce(T) -> R + Send + 'static,
{
    std::thread::Builder::new()
        .name("snapback-action".to_owned())
        .spawn(move || {
            // Both guards live in the native thread. In particular, an outer
            // watchdog returning cannot release admission for a native call
            // that has not actually unwound yet.
            let result = {
                let _worker_permit = permit;
                let _worker = DetachedActionWorkerGuard::enter(counters);
                task()
            };
            // Publication runs only after actual native teardown and permit
            // release. A completed response therefore never races a stale
            // worker count or spuriously leaves capacity exhausted.
            complete(result)
        })
}

async fn with_locked_snapback_then<T, U, F, A>(
    mut guard: tokio::sync::OwnedMutexGuard<LocalSnapback>,
    work: F,
    after: A,
) -> U
where
    F: FnOnce(&mut LocalSnapback) -> T + Send + 'static,
    A: FnOnce(T) -> U + Send + 'static,
    T: Send + 'static,
    U: Send + 'static,
{
    tokio::task::spawn_blocking(move || {
        let _sanction = crate::exec_guard::BlockingSanction::acquire();
        let mut local_scope = crate::exec_guard::LocalSnapbackWriteScope::enter();
        let output = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| work(&mut guard)));
        let batch = local_scope.take_after_local_batch();
        let handoff = batch.has_effects().then(|| {
            let handoff = guard.managed_local_handoff();
            handoff.close();
            handoff
        });
        drop(guard);
        drop(local_scope);
        crate::exec_guard::run_after_local_batch(batch);
        if let Some(handoff) = handoff {
            handoff.reopen();
        }
        match output {
            Ok(output) => after(output),
            Err(payload) => std::panic::resume_unwind(payload),
        }
    })
    .await
    .expect("snapback blocking task panicked")
}

/// Compose one inspect artifact in two blocking phases: SQLite/Local facts,
/// then ephemeral shard diagnostics after the Local guard is gone.
pub(crate) async fn inspect_snapback(state: &SharedSnapback) -> SnapbackResult<InspectState> {
    with_snapback_then(
        state,
        |snapback| {
            snapback
                .inspect_core()
                .map(|inspect| (inspect, snapback.ephemeral_api()))
        },
        |captured| {
            captured.map(|(mut inspect, ephemeral)| {
                inspect.ephemeral = ephemeral.diagnostics();
                inspect
            })
        },
    )
    .await
}

/// Once an authority marker has drained, its durable attempt and exact finish
/// must no longer be owned by the request future. Spawning this wrapper is
/// synchronous, so there is no cancellation point between receiving a
/// premarked carrier and transferring it to independently owned work.
///
/// @ref LLP 0059#locking-and-linearization — cancellation after premark either
/// completes the durable protocol or runs its exact known-rollback finish.
pub(crate) fn spawn_owned_auth_transaction<F>(transaction: F) -> JoinHandle<F::Output>
where
    F: Future + Send + 'static,
    F::Output: Send + 'static,
{
    tokio::spawn(transaction)
}

async fn await_owned_auth_transaction<T>(task: JoinHandle<T>) -> SnapbackResult<T>
where
    T: Send + 'static,
{
    task.await.map_err(|_| {
        SnapbackError::error(
            "SNAPBACK_AUTH_PROJECTION_UNAVAILABLE",
            "auth",
            "owned authentication transaction task failed",
        )
    })
}

/// Default coarse wall-clock watchdog for detached Ibex actions (ENG-23324):
/// the watchdog fires after this long even when the action's VM thread is
/// stuck inside a hung outbound fetch. Publishing the timeout may then wait
/// through the bounded interrupt-teardown grace below.
const ACTION_WATCHDOG_DEFAULT_MS: u64 = 30_000;
/// Local actions may raise the default for slow external APIs, but a malformed
/// environment value must not create an unrepresentable `Instant` or an
/// effectively unbounded worker lifetime.
const ACTION_WATCHDOG_MAX_MS: u64 = 15 * 60 * 1_000;
/// Bounded grace for Hermes async-break teardown after the public deadline.
/// Six simultaneous outer+nested VMs can need more than 500ms to unwind on a
/// saturated 2-core runner. Two seconds preserves pre-publication teardown for
/// CPU-bound JavaScript while keeping the native-host fallback finite.
const ACTION_INTERRUPT_GRACE_MS: u64 = 2_000;
const ACTION_LOCK_POLL_MS: u64 = 5;
// @ref LLP 0076#surface — the v1 bounded response-stream profile limits. LLP
// 0076 is the sole numeric authority; the first five match LLP 0075's frozen
// fixture, the 16 KiB host read size and 4-cursor cap are v1 profile limits.
const ACTION_STREAM_TOTAL_BYTES_MAX: u64 = 1_048_576;
/// Buffered `ctx.fetch` response cap — the workerd coordinator's
/// `MAX_HOST_RESPONSE_BYTES` (1,000,000), kept byte-identical so
/// `SNAPBACK_HOST_FETCH_RESPONSE_TOO_LARGE` fires at the same size on both
/// targets (0137 a4-f1/a5-f1 portability).
const HOST_FETCH_RESPONSE_BYTES_MAX: u64 = 1_000_000;
const ACTION_STREAM_CHUNK_BYTES_MAX: usize = 16_384;
const ACTION_STREAM_WALL_MS: u64 = 30_000;
const ACTION_STREAM_IDLE_MS: u64 = 5_000;
const ACTION_STREAM_OPEN_MAX: usize = 4;
/// Settlement grace reserved between the stream wall ceiling and the action
/// watchdog, so a default action that exhausts the full stream budget can
/// still reach and durably settle its timeout before abandonment
/// (LLP 0076 boundedness ticket).
const ACTION_STREAM_SETTLE_GRACE_MS: u64 = 2_000;

/// One pull request: the maximum byte count the helper may materialize.
struct StreamPullRequest {
    requested: usize,
}

/// One bounded upstream cursor, pull-driven through a dedicated reader
/// thread. The channels give the host: (a) an absolute wall-clock bound on
/// the pull itself (`recv_timeout` fires even while the socket read is still
/// blocked), (b) structurally at most one in-flight pull per cursor (the
/// rendezvous channel holds a single request), and (c) a physical close on
/// drop — dropping `pull_tx` ends the helper, which drops the ureq reader
/// and closes the socket within one socket-timeout window.
// @ref LLP 0076#surface — 4 cursors x one 16 KiB in-flight chunk each is
//   exactly the 64 KiB application-visible buffering ceiling; the accounting
//   domain is host-materialized bytes (queued chunk + handoff copy), with
//   kernel socket buffers excluded (they are bounded by the TCP window and
//   never visible to the application).
struct OpenActionResponseStream {
    pull_tx: std::sync::mpsc::SyncSender<StreamPullRequest>,
    chunk_rx: std::sync::mpsc::Receiver<std::io::Result<Vec<u8>>>,
    opened_at: Instant,
    /// Absolute per-stream wall deadline: `min(open + 30 s, action watchdog
    /// deadline - settle grace)` — never later than the profile ceiling, and
    /// always leaving room to durably settle before abandonment.
    wall_deadline: Instant,
    last_byte_at: Instant,
    total_bytes: u64,
}

/// Spawn the cursor's reader thread. The helper owns the response reader;
/// it materializes at most one bounded chunk per pull request and counts
/// those bytes against the shared per-invocation buffered-byte accounting.
fn spawn_stream_reader_thread(
    mut reader: Box<dyn Read + Send + Sync>,
    buffered_bytes: Arc<AtomicU64>,
    buffered_peak: Arc<AtomicU64>,
) -> (
    std::sync::mpsc::SyncSender<StreamPullRequest>,
    std::sync::mpsc::Receiver<std::io::Result<Vec<u8>>>,
) {
    let (pull_tx, pull_rx) = std::sync::mpsc::sync_channel::<StreamPullRequest>(1);
    let (chunk_tx, chunk_rx) = std::sync::mpsc::sync_channel::<std::io::Result<Vec<u8>>>(1);
    std::thread::spawn(move || {
        while let Ok(StreamPullRequest { requested }) = pull_rx.recv() {
            let mut bytes = vec![0; requested.max(1)];
            let outcome = match reader.read(&mut bytes) {
                Ok(read) => {
                    bytes.truncate(read);
                    Ok(bytes)
                }
                Err(error) => Err(error),
            };
            let len = outcome
                .as_ref()
                .map(|bytes| bytes.len() as u64)
                .unwrap_or(0);
            if len > 0 {
                let now = buffered_bytes.fetch_add(len, Ordering::SeqCst) + len;
                buffered_peak.fetch_max(now, Ordering::SeqCst);
            }
            if chunk_tx.send(outcome).is_err() {
                if len > 0 {
                    buffered_bytes.fetch_sub(len, Ordering::SeqCst);
                }
                return;
            }
        }
        // The host dropped its pull sender: the cursor is closed. Dropping
        // `reader` here closes the upstream socket.
    });
    (pull_tx, chunk_rx)
}

fn action_watchdog_timeout_ms() -> u64 {
    parse_action_watchdog_timeout(std::env::var("SNAPBACK_ACTION_TIMEOUT_MS").ok().as_deref())
}

fn parse_action_watchdog_timeout(raw: Option<&str>) -> u64 {
    raw.and_then(|value| value.parse::<u64>().ok())
        .filter(|ms| *ms > 0)
        .map(|ms| ms.min(ACTION_WATCHDOG_MAX_MS))
        .unwrap_or(ACTION_WATCHDOG_DEFAULT_MS)
}

const EXPO_PUSH_PRODUCTION_BASE_URL: &str = "https://exp.host";
// Static v1 pacing: one send attempt owns the provider lane at a time while
// its <=100-message batches run serially. This is deliberately conservative;
// adaptive pacing is an explicit later decision (LLP 0143 OQ9).
static EXPO_PUSH_SEND_PACER: StdMutex<()> = StdMutex::new(());

fn transmit_expo_push_batch(
    endpoint: &str,
    access_token: Option<&str>,
    payload: Value,
    timeout: Duration,
    deadline: Option<Instant>,
) -> crate::push::PushBatchSettlementV1 {
    match crate::push::post_expo_json(endpoint, access_token, payload, timeout) {
        Ok(response) => crate::push::classify_expo_send_response(
            response.status,
            &response.body,
            now_millis().saturating_add(60_000),
        ),
        Err(_) => {
            let code = if deadline.is_some_and(|deadline| Instant::now() >= deadline) {
                "timeout"
            } else {
                "transport-error"
            };
            crate::push::PushBatchSettlementV1::Ambiguous { code: code.into() }
        }
    }
}

fn loopback_provider_base_url(value: &str) -> bool {
    let Some(rest) = value
        .strip_prefix("http://")
        .or_else(|| value.strip_prefix("https://"))
    else {
        return false;
    };
    if rest.contains(['/', '?', '#', '@']) {
        return false;
    }
    let host = if let Some(ipv6) = rest.strip_prefix('[') {
        let Some((host, suffix)) = ipv6.split_once(']') else {
            return false;
        };
        if !suffix.is_empty() && !suffix.starts_with(':') {
            return false;
        }
        host
    } else {
        rest.split_once(':').map_or(rest, |(host, _port)| host)
    };
    matches!(host, "localhost" | "127.0.0.1" | "::1")
}

fn expo_push_provider_base_url(profile: ServerProfile) -> SnapbackResult<String> {
    let Ok(value) = std::env::var("SNAPBACK_EXPO_PUSH_BASE_URL") else {
        return Ok(EXPO_PUSH_PRODUCTION_BASE_URL.into());
    };
    if !matches!(profile, ServerProfile::Dev | ServerProfile::Test)
        || !loopback_provider_base_url(&value)
    {
        return Err(SnapbackError::error(
            "SNAPBACK_PUSH_PROVIDER_OVERRIDE_REFUSED",
            "push",
            "the Expo provider override is local/test-only and must name a loopback base URL",
        ));
    }
    Ok(value)
}

pub(crate) fn expo_push_fixture_clock_allowed(profile: ServerProfile) -> bool {
    matches!(profile, ServerProfile::Dev | ServerProfile::Test)
        && std::env::var("SNAPBACK_EXPO_PUSH_BASE_URL")
            .ok()
            .is_some_and(|value| loopback_provider_base_url(&value))
}

/// The action host for detached (off-mutex) Ibex action runs. Raw action
/// `ctx.db` operations are rejected before host dispatch; the trait's read
/// methods retain a short-lock defense in depth. Ibex mutations execute into
/// an owned effect buffer against an isolated read view. Instance/gate
/// acquisition is deadline-aware; HostPlan and buffered-write iteration poll
/// lifecycle outside the independent gate, which is returned only for final
/// SQLite commit. The gate linearizes that commit with watchdog abandonment,
/// so a mutation either commits before abandonment or is discarded — never
/// after the caller was told the action failed.
///
/// @ref LLP 0028#execution-the-action-class — ENG-23324: actions no longer
/// hold the global write mutex for the duration of the run.
struct DetachedActionHost {
    state: SharedSnapback,
    connected_clients: crate::connected_clients::ConnectedClientRegistry,
    connected_client_predicate_available: bool,
    abandoned: Arc<AtomicBool>,
    commit_gate: Arc<StdMutex<()>>,
    /// The one room-reservation wait currently owned by this action worker.
    /// The watchdog cancels it after linearizing abandonment, so an affected
    /// room permit cannot strand the worker past the public timeout.
    active_reservation:
        Arc<StdMutex<Option<Arc<crate::storage::AuthorizationReservationCancellation>>>>,
    deadline: Instant,
    app_generation: u64,
    app_generation_fence: Arc<AtomicU64>,
    authority: PreparedAuthority,
    /// The exact per-function config grant staged with this invocation. Push
    /// may consume only seam-declared entries that the action also named in
    /// `uses`; no app argument can widen this set.
    push_grants: Value,
    deferred_push_grant: Option<crate::push::PushDeferredGrantV1>,
    external_effect_open: bool,
    external_effect_permit: Option<ServiceAuthorityExternalEffectPermit>,
    response_streams: BTreeMap<String, OpenActionResponseStream>,
    closed_response_streams: BTreeSet<String>,
    last_stream_progress_commit: Option<Instant>,
    /// Control-plane identity of this exact invocation for the
    /// `StreamAttemptV1` lease and trusted terminalizer (LLP 0076).
    stream_runner: crate::stream_attempt::StreamRunnerIdentity,
    output_stream_attempt: Option<String>,
    output_stream_function_id: Option<String>,
    output_stream_initiator: Option<crate::stream_attempt::StreamInitiator>,
    ephemeral: EphemeralApi,
    /// Per-invocation application-visible buffered-byte accounting: bytes the
    /// host has materialized (queued chunk + handoff copy) and the invocation
    /// has not yet consumed, summed across all cursors, plus its high-water
    /// mark. Kernel socket buffers are excluded by definition.
    stream_buffered_bytes: Arc<AtomicU64>,
    stream_buffered_peak: Arc<AtomicU64>,
    /// True for automatically re-dispatched cron/durable invocations, which
    /// are excluded from streamed actions until resumable retry semantics
    /// exist (LLP 0076 §Evidence-status, retry-fencing gap).
    automatic_retry_invocation: bool,
    host_operation: HostOperationParentV1,
}

struct ScopedLocalSnapbackGuard {
    guard: Option<tokio::sync::OwnedMutexGuard<LocalSnapback>>,
    scope: Option<crate::exec_guard::LocalSnapbackWriteScope>,
}

impl std::ops::Deref for ScopedLocalSnapbackGuard {
    type Target = LocalSnapback;

    fn deref(&self) -> &Self::Target {
        self.guard
            .as_deref()
            .expect("scoped LocalSnapback guard remains live until drop")
    }
}

impl std::ops::DerefMut for ScopedLocalSnapbackGuard {
    fn deref_mut(&mut self) -> &mut Self::Target {
        self.guard
            .as_deref_mut()
            .expect("scoped LocalSnapback guard remains live until drop")
    }
}

impl Drop for ScopedLocalSnapbackGuard {
    fn drop(&mut self) {
        let batch = self
            .scope
            .as_mut()
            .expect("scoped LocalSnapback scope remains live until drop")
            .take_after_local_batch();
        let handoff = batch.has_effects().then(|| {
            let handoff = self
                .guard
                .as_ref()
                .expect("scoped LocalSnapback guard remains live until drop")
                .managed_local_handoff();
            handoff.close();
            handoff
        });
        drop(self.guard.take());
        drop(self.scope.take());
        crate::exec_guard::run_after_local_batch(batch);
        if let Some(handoff) = handoff {
            handoff.reopen();
        }
    }
}

impl DetachedActionHost {
    fn initialize_output_stream(&mut self) -> SnapbackResult<()> {
        let Some(function_id) = self.output_stream_function_id.clone() else {
            return Ok(());
        };
        let initiator = self.output_stream_initiator.clone().ok_or_else(|| {
            SnapbackError::error(
                "SNAPBACK_STREAM_INITIATOR_REQUIRED",
                "auth",
                "a streaming action requires session, scoped-token, or connection-bound authority",
            )
        })?;
        let namespace = self
            .lock_live("stream.initialize")?
            .stream_attempt_namespace();
        let client_key = format!(
            "stream-output:{function_id}:{}",
            self.stream_runner.invocation_id
        );
        let started = crate::stream_attempt::global_stream_attempt_registry().start_with_metadata(
            namespace,
            &client_key,
            &self.stream_runner,
            None,
            crate::stream_attempt::StreamAttemptMetadata {
                function_id: Some(function_id),
                initiator: Some(initiator),
                started_at_ms: now_millis(),
            },
        )?;
        if !started.lease_held {
            return Err(SnapbackError::error(
                "SNAPBACK_STREAM_RUNNER_FENCED",
                "runtime",
                "the streaming action did not acquire its attempt lease",
            ));
        }
        self.output_stream_attempt = Some(started.attempt_token);
        self.flush_stream_attempts_required("stream.initialize")
    }

    fn ephemeral_error(error: crate::ephemeral::EphemeralError) -> SnapbackError {
        SnapbackError::error(error.code.diagnostic_code(), "ephemeral", error.message)
    }

    fn persist_output_transcript_trusted(
        &self,
        result: &SnapbackResult<Value>,
    ) -> SnapbackResult<()> {
        let Some(attempt_token) = self.output_stream_attempt.as_deref() else {
            return Ok(());
        };
        let snapshot = crate::stream_attempt::global_stream_attempt_registry()
            .stream_output(attempt_token)
            .ok_or_else(|| {
                SnapbackError::error(
                    "SNAPBACK_STREAM_ATTEMPT_NOT_FOUND",
                    "runtime",
                    "the output stream attempt disappeared before transcript settlement",
                )
            })?;
        let terminal = snapshot.terminal.ok_or_else(|| {
            SnapbackError::error(
                "SNAPBACK_STREAM_TERMINAL",
                "runtime",
                "the output stream transcript cannot settle before its attempt",
            )
        })?;
        let final_text = (terminal.cause == crate::stream_attempt::StreamAttemptCause::Complete)
            .then(|| {
                result.as_ref().ok().map(|value| match value {
                    Value::String(text) => text.clone(),
                    value => serde_json::to_string(value).unwrap_or_else(|_| "null".to_owned()),
                })
            })
            .flatten();
        let record = crate::storage::stream_transcripts::StreamTranscriptRecord {
            attempt_token: snapshot.attempt_token,
            function_id: snapshot.function_id,
            initiator: snapshot.initiator,
            started_at_ms: snapshot.started_at_ms,
            settled_at_ms: snapshot.settled_at_ms.unwrap_or_else(now_millis),
            terminal_cause: terminal.cause,
            final_text,
            chunk_count: snapshot.chunk_count,
            prompt_tokens: None,
            completion_tokens: None,
        };
        let deadline = Instant::now() + Duration::from_millis(250);
        loop {
            if let Ok(guard) = self.state.clone().try_lock_owned() {
                if guard.managed_local_handoff().is_closed() {
                    drop(guard);
                } else {
                    let scope = crate::exec_guard::LocalSnapbackWriteScope::enter();
                    let mut guard = ScopedLocalSnapbackGuard {
                        guard: Some(guard),
                        scope: Some(scope),
                    };
                    return guard.settle_stream_transcript(&record);
                }
            }
            if Instant::now() >= deadline {
                return Err(SnapbackError::error(
                    "SNAPBACK_STREAM_TRANSCRIPT_SETTLE_TIMEOUT",
                    "storage",
                    "the stream transcript could not acquire its bounded settlement lane",
                ));
            }
            std::thread::park_timeout(Duration::from_millis(ACTION_LOCK_POLL_MS));
        }
    }

    fn push_access_token(
        &self,
        declaration: &crate::push::PushSeamDeclarationV1,
    ) -> SnapbackResult<Option<String>> {
        let entries = self
            .push_grants
            .get("entries")
            .and_then(Value::as_object)
            .ok_or_else(|| {
                SnapbackError::error(
                    "SNAPBACK_PUSH_CONFIG_GRANT_MISSING",
                    "push",
                    "the action has no staged config grants for the push seam",
                )
            })?;
        if declaration
            .uses
            .iter()
            .any(|name| !entries.contains_key(name))
        {
            return Err(SnapbackError::error(
                "SNAPBACK_PUSH_CONFIG_GRANT_MISSING",
                "push",
                "the action must declare every push-seam config entry in its uses list",
            ));
        }
        if !declaration
            .uses
            .iter()
            .any(|name| name == "expoPushAccessToken")
        {
            return Ok(None);
        }
        let Some(grant) = entries.get("expoPushAccessToken") else {
            return Ok(None);
        };
        if grant.get("set").and_then(Value::as_bool) != Some(true) {
            return Ok(None);
        }
        grant
            .get("values")
            .and_then(Value::as_array)
            .and_then(|values| values.first())
            .and_then(Value::as_str)
            .filter(|value| !value.is_empty() && !value.contains(['\r', '\n']))
            .map(|value| Some(value.to_owned()))
            .ok_or_else(|| {
                SnapbackError::error(
                    "SNAPBACK_PUSH_CONFIG_GRANT_INVALID",
                    "push",
                    "the staged Expo access-token grant has an invalid bounded shape",
                )
            })
    }

    /// Retire a cursor everywhere at once: the read-side closed set (so a
    /// post-cancel read returns EOF) and the attempt registry's child record
    /// (so the parent's certainty fold stops treating it as in flight). The
    /// durable row follows best-effort; a skipped write stays queued and the
    /// on-disk state remains conservatively `open`/`initiation_possible`.
    fn close_response_stream_cursor(&mut self, stream_id: &str) {
        self.closed_response_streams.insert(stream_id.to_owned());
        crate::stream_attempt::global_stream_attempt_registry().close_cursor(stream_id);
        self.flush_stream_attempts_trusted();
    }

    /// Required durable flush: the write-ahead pre-mark and the attempt-row
    /// creation must commit before their operation proceeds, so failures
    /// propagate. Runs under the ordinary live-validated instance lock; the
    /// registry namespace is the instance's own nonce, resolved under that
    /// lock.
    fn flush_stream_attempts_required(&self, op: &str) -> SnapbackResult<()> {
        let registry = crate::stream_attempt::global_stream_attempt_registry();
        let mut snapback = self.lock_live(op)?;
        let namespace = snapback.stream_attempt_namespace();
        let snapshots = registry.dirty_snapshots(namespace);
        if snapshots.is_empty() {
            return Ok(());
        }
        let mut rows = Vec::with_capacity(snapshots.len());
        for snapshot in &snapshots {
            rows.push(snapshot.to_row()?);
        }
        snapback.persist_stream_attempts(&rows)?;
        drop(snapback);
        registry.clear_flushed(&snapshots);
        Ok(())
    }

    /// Trusted best-effort flush for terminalizer and close paths: bypasses
    /// the action-authority fence (writing settlement bookkeeping is the
    /// host's own job even after abandonment) but never blocks unboundedly —
    /// rows left dirty ride the next flush point or, after a crash, the
    /// startup reconciler.
    fn flush_stream_attempts_trusted(&self) {
        let registry = crate::stream_attempt::global_stream_attempt_registry();
        let deadline = Instant::now() + Duration::from_millis(250);
        loop {
            if let Ok(guard) = self.state.clone().try_lock_owned() {
                if guard.managed_local_handoff().is_closed() {
                    drop(guard);
                } else {
                    let scope = crate::exec_guard::LocalSnapbackWriteScope::enter();
                    let mut guard = ScopedLocalSnapbackGuard {
                        guard: Some(guard),
                        scope: Some(scope),
                    };
                    let namespace = guard.stream_attempt_namespace();
                    let snapshots = registry.dirty_snapshots(namespace);
                    if snapshots.is_empty() {
                        return;
                    }
                    let mut rows = Vec::with_capacity(snapshots.len());
                    for snapshot in &snapshots {
                        let Ok(row) = snapshot.to_row() else { return };
                        rows.push(row);
                    }
                    if guard.persist_stream_attempts(&rows).is_ok() {
                        drop(guard);
                        registry.clear_flushed(&snapshots);
                    }
                    return;
                }
            }
            if Instant::now() >= deadline {
                return;
            }
            std::thread::park_timeout(Duration::from_millis(ACTION_LOCK_POLL_MS));
        }
    }

    /// The per-read authority fence (LLP 0076 §Authority and lifecycle): the
    /// full stream predicate is abandonment + generation + deadline PLUS the
    /// lock-free process-fence tier of the service-authority check, so an
    /// authority terminalization that lands during a blocked pull is observed
    /// before any byte is handed to the action. Terminal auth writers premark
    /// the process fence before commit (LLP 0059), which is what makes this
    /// tier exact without taking the instance lock on the read path.
    // @ref LLP 0076#authority-and-lifecycle — every open/read revalidates the
    //   exact invocation, generation, service authority, and deadline, and a
    //   read revalidates AFTER awaiting bytes, discarding late bytes on loss.
    fn validate_stream_authority(&self, op: &str) -> SnapbackResult<()> {
        self.validate_live(op)?;
        let ResolvedAppAuthority::ServicePrincipal {
            actor_user_id,
            effective_user_id,
            grant_id,
            token_id,
            credential_id,
            credential_generation,
            token_expires_at_ms,
            ..
        } = self.authority.resolved()
        else {
            return Ok(());
        };
        let (now_ms, monotonic_now) = self
            .authority
            .service_clock_sample(now_millis(), Instant::now());
        let witness = match self
            .authority
            .resolve_service_authority_act(now_ms, monotonic_now)?
        {
            Some(ServiceAuthorityActResolution::Current(witness)) => witness,
            Some(ServiceAuthorityActResolution::Terminal(disposition)) => {
                let wire = match disposition {
                    ServiceAuthorityDisposition::Carrier => "carrier",
                    ServiceAuthorityDisposition::DurableDelete => "durableDelete",
                };
                return Err(SnapbackError::error(
                    "SNAPBACK_AUTH_SCOPED_TOKEN_INVALID",
                    "auth",
                    "scoped agent token authority is no longer current",
                )
                .with_details(json!({ "authorityDisposition": wire, "operation": op })));
            }
            Some(ServiceAuthorityActResolution::Unavailable) => {
                return Err(SnapbackError::error(
                    "SNAPBACK_AUTH_POLICY_UNAVAILABLE",
                    "auth",
                    "finite service authority termination is unresolved",
                ));
            }
            None => {
                return Err(SnapbackError::error(
                    "SNAPBACK_AUTH_POLICY_UNAVAILABLE",
                    "auth",
                    "finite service authority has no exact process fence",
                ));
            }
        };
        if witness.actor_user_id() != actor_user_id
            || witness.effective_user_id() != effective_user_id.as_deref()
            || witness.grant_id() != grant_id
            || witness.token_id() != token_id
            || witness.credential_id() != credential_id
            || witness.credential_generation() != *credential_generation
            || witness.expires_at_ms() != *token_expires_at_ms
        {
            return Err(SnapbackError::error(
                "SNAPBACK_AUTH_POLICY_UNAVAILABLE",
                "auth",
                "finite service authority disagrees with its exact process fence",
            ));
        }
        Ok(())
    }

    fn validate_live(&self, op: &str) -> SnapbackResult<()> {
        if self.abandoned.load(Ordering::SeqCst) {
            return Err(action_abandoned(op));
        }
        let current_generation = self.app_generation_fence.load(Ordering::SeqCst);
        if current_generation != self.app_generation {
            return Err(action_generation_conflict(
                op,
                self.app_generation,
                current_generation,
            ));
        }
        if Instant::now() >= self.deadline {
            return Err(action_deadline_elapsed(op));
        }
        Ok(())
    }

    fn lock_live(&self, op: &str) -> SnapbackResult<ScopedLocalSnapbackGuard> {
        loop {
            self.validate_live(op)?;
            if let Ok(guard) = self.state.clone().try_lock_owned() {
                if guard.managed_local_handoff().is_closed() {
                    drop(guard);
                    let remaining = self.deadline.saturating_duration_since(Instant::now());
                    if remaining.is_zero() {
                        return Err(action_deadline_elapsed(op));
                    }
                    std::thread::park_timeout(
                        remaining.min(Duration::from_millis(ACTION_LOCK_POLL_MS)),
                    );
                    continue;
                }
                let scope = crate::exec_guard::LocalSnapbackWriteScope::enter();
                // Abandonment, deadline, or generation can advance between the
                // optimistic check and lock acquisition. Recheck before using
                // any instance authority.
                self.validate_live(op)?;
                let current_generation = guard.app_generation();
                if current_generation != self.app_generation {
                    return Err(action_generation_conflict(
                        op,
                        self.app_generation,
                        current_generation,
                    ));
                }
                return Ok(ScopedLocalSnapbackGuard {
                    guard: Some(guard),
                    scope: Some(scope),
                });
            }

            let remaining = self.deadline.saturating_duration_since(Instant::now());
            if remaining.is_zero() {
                return Err(action_deadline_elapsed(op));
            }
            // Never park while holding the commit gate or instance mutex. The
            // watchdog can therefore mark abandonment independently, and this
            // worker observes it within one short polling interval.
            std::thread::park_timeout(remaining.min(Duration::from_millis(ACTION_LOCK_POLL_MS)));
        }
    }

    fn lock_commit_live(&self, op: &str) -> SnapbackResult<std::sync::MutexGuard<'_, ()>> {
        loop {
            self.validate_live(op)?;
            let guard = match self.commit_gate.try_lock() {
                Ok(guard) => Some(guard),
                Err(std::sync::TryLockError::Poisoned(poisoned)) => Some(poisoned.into_inner()),
                Err(std::sync::TryLockError::WouldBlock) => None,
            };
            if let Some(guard) = guard {
                self.validate_live(op)?;
                return Ok(guard);
            }

            let remaining = self.deadline.saturating_duration_since(Instant::now());
            if remaining.is_zero() {
                return Err(action_deadline_elapsed(op));
            }
            std::thread::park_timeout(remaining.min(Duration::from_millis(ACTION_LOCK_POLL_MS)));
        }
    }

    fn reserve_authorization_commit(
        &self,
        ephemeral: EphemeralApi,
        preflight: crate::storage::AuthorizationCommitPreflight,
    ) -> SnapbackResult<Box<dyn crate::storage::AuthorizationCommitReservation>> {
        // @ref LLP 0059#authorization-write-handoff — detached actions publish
        //   one cancellable room wait to the watchdog and never retain Local.
        self.validate_live("runMutation")?;
        let cancellation =
            Arc::new(crate::storage::AuthorizationReservationCancellation::default());
        {
            let mut active = self
                .active_reservation
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            debug_assert!(active.is_none());
            *active = Some(cancellation.clone());
        }
        // Close the install-to-wait race with the watchdog: if abandonment
        // won just before publication, make the reservation observe it.
        if let Err(error) = self.validate_live("runMutation") {
            cancellation.cancel();
            self.clear_active_reservation(&cancellation);
            return Err(error);
        }
        let reserved = ephemeral.reserve_authorization_commit(preflight, cancellation.clone());
        self.clear_active_reservation(&cancellation);
        match reserved {
            Ok(reservation) => {
                self.validate_live("runMutation")?;
                Ok(reservation)
            }
            Err(error) => match self.validate_live("runMutation") {
                Ok(()) => Err(error),
                Err(lifecycle) => Err(lifecycle),
            },
        }
    }

    fn clear_active_reservation(
        &self,
        cancellation: &Arc<crate::storage::AuthorizationReservationCancellation>,
    ) {
        let mut active = self
            .active_reservation
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        if active
            .as_ref()
            .is_some_and(|current| Arc::ptr_eq(current, cancellation))
        {
            active.take();
        }
    }
}

impl IbexActionHost for DetachedActionHost {
    fn validate_host_call(&mut self, op: &str) -> SnapbackResult<()> {
        if crate::instance_fork::EgressFamily::for_derived_host_op(op).is_some() {
            let snapback = self.lock_live(op)?;
            snapback.deny_derived_fork_host_op(op, now_millis())?;
        }
        // This atomic generation fence keeps ordinary runtime/id/log calls off
        // the global instance mutex. A mutation rechecks while holding that
        // mutex, and detached mutation commit retains its own generation bind.
        match op {
            "action.externalEffectBegin" => {
                self.validate_live(op)?;
                if self.external_effect_open {
                    return Err(SnapbackError::error(
                        "SNAPBACK_AUTH_POLICY_UNAVAILABLE",
                        "auth",
                        "an external action effect is already initiating",
                    ));
                }
                {
                    let mut snapback = self.lock_live(op)?;
                    snapback.persist_service_deadline_if_due(&self.authority)?;
                }
                self.external_effect_permit = self
                    .authority
                    .begin_service_external_effect(now_millis(), Instant::now())?;
                self.external_effect_open = true;
                Ok(())
            }
            "action.externalEffectInitiated" => {
                if !self.external_effect_open {
                    return Err(SnapbackError::error(
                        "SNAPBACK_AUTH_POLICY_UNAVAILABLE",
                        "auth",
                        "no external action effect is awaiting initiation",
                    ));
                }
                if let Some(permit) = self.external_effect_permit.take() {
                    permit.initiated();
                }
                self.external_effect_open = false;
                self.validate_live(op)
            }
            _ => self.validate_live(op),
        }
    }

    fn run_mutation(&mut self, name: &str, input: HandlerInput) -> SnapbackResult<MutationOutput> {
        // @ref LLP 0076#surface — while an upstream reader is open, every
        // nested mutation is conservatively treated as progress and admitted
        // at no more than ten commits per second. EOF/cancel removes the
        // cursor before terminal settlement, so completion is not delayed.
        // @ref LLP 0076#author-decisions--2026-07-23 — decision 4: the host
        // rate fence emits the profile-neutral
        // `SNAPBACK_ACTION_PROGRESS_RATE_EXCEEDED`, not the retired
        // fixture-flavored `SNAPBACK_REPLY_*` name.
        // @ref LLP 0076#settlement-and-retry — the single-runner lease: a
        // runner that does not hold the attempt lease cannot commit progress,
        // and late commits against a terminal attempt are fenced by the host.
        crate::stream_attempt::global_stream_attempt_registry()
            .progress_guard(&self.stream_runner)?;
        if !self.response_streams.is_empty() {
            if self
                .last_stream_progress_commit
                .is_some_and(|last| last.elapsed() < Duration::from_millis(100))
            {
                return Err(action_stream_error(
                    "SNAPBACK_ACTION_PROGRESS_RATE_EXCEEDED",
                    "progress",
                    "stream progress exceeds ten authoritative commits per second",
                    json!({ "limitPerSecond": 10, "received": "progress commit too soon" }),
                ));
            }
            self.last_stream_progress_commit = Some(Instant::now());
        }
        let mut snapback = self.lock_live("runMutation")?;
        let authority = self
            .authority
            .inherit_for(InvocationSource::NestedMutation)?;
        let host_identity =
            snapback.covered_host_child_identity(&self.host_operation, name, &input, &authority)?;
        match snapback.stage_nested_mutation(
            name,
            &input,
            authority,
            host_identity.as_ref(),
        )? {
            StagedNestedMutation::InLock(staged) => {
                let snapshot = snapback.authorization_reservation_snapshot()?;
                let ephemeral = snapback.ephemeral_api();
                drop(snapback);
                let reservation = self.reserve_authorization_commit(ephemeral, staged.preflight)?;

                let mut snapback = self.lock_live("runMutation")?;
                if snapback.authorization_reservation_snapshot()? != snapshot {
                    drop(snapback);
                    reservation.cancel();
                    return Err(action_authorization_reservation_stale(name));
                }
                crate::storage::install_managed_authorization_reservation(reservation);
                let outcome = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                    snapback.invoke_host_plan_mutation_guarded(
                        name,
                        staged.input,
                        staged.invocation,
                        host_identity,
                        || self.validate_live("runMutation"),
                        || self.lock_commit_live("runMutation"),
                    )
                }));
                let unused = crate::storage::take_managed_authorization_reservation();
                drop(snapback);
                if let Some(unused) = unused {
                    unused.cancel();
                }
                let output = match outcome {
                    Ok(result) => result,
                    Err(payload) => std::panic::resume_unwind(payload),
                };
                if output.is_ok() {
                    // @ref LLP 0076#settlement-and-retry — a successful
                    // nested commit while an attempt cursor is open counts as
                    // durable progress; retry is prohibited afterwards.
                    crate::stream_attempt::global_stream_attempt_registry()
                        .record_progress_commit(&self.stream_runner);
                }
                output
            }
            StagedNestedMutation::Detached(staged) => {
                let crate::local::DetachedIbexMutation { binding, read } = *staged;
                let mut input = binding.invocation.canonicalize_input(input);
                crate::local::bind_authoritative_client_mutation_identity(
                    &mut input,
                    host_identity.as_ref(),
                );
                let telemetry = snapback.telemetry();
                let correlation = input
                    .correlation
                    .as_ref()
                    .and_then(Value::as_str)
                    .map(str::to_owned);
                let span = telemetry.start_classified_span(
                    crate::telemetry_contract::OperationClassIdV1::FUNCTION_MUTATION,
                    name,
                    correlation.as_deref(),
                    None,
                );
                drop(snapback);
                let mut output = (|| {
                    let module = match &binding.function.runtime {
                        FunctionRuntime::IbexModule(module) => module,
                        _ => unreachable!("detached nested mutation must be an Ibex module"),
                    };
                    let executed = crate::runtime::with_runtime_log_telemetry(
                        telemetry.clone(),
                        correlation,
                        || match read {
                            DetachedMutationRead::Lane(read) => read
                                .execute_detached_ibex_mutation(
                                    module,
                                    input.clone(),
                                    &binding.invocation,
                                    &binding.schema,
                                    self.deadline,
                                ),
                            DetachedMutationRead::Snapshot(db) => {
                                crate::runtime::execute_ibex_mutation_prepared(
                                    module,
                                    input.clone(),
                                    &binding.invocation,
                                    crate::storage::DbRead::Live(db.as_ref()),
                                    None,
                                    Some(self.deadline),
                                )
                            }
                        },
                    )?;

                    // The handler ran exactly once off Local. Reenter only to
                    // preview its immutable buffered effects, then release Local
                    // before the potentially blocking room reservation.
                    let mut snapback = self.lock_live("runMutation")?;
                    let preflight = snapback.preview_detached_nested_authorization_mutation(
                        name,
                        &input,
                        &binding,
                        &executed,
                        host_identity.as_ref(),
                    )?;
                    let snapshot = snapback.authorization_reservation_snapshot()?;
                    let ephemeral = snapback.ephemeral_api();
                    drop(snapback);
                    let reservation = self.reserve_authorization_commit(ephemeral, preflight)?;

                    // Acquire the instance before the independent commit gate. A
                    // wedged writer cannot strand this action worker: lock_live
                    // polls abandonment/deadline without holding either lock. If
                    // this call gets the gate first, the watchdog waits only for
                    // the bounded validation/SQLite commit (ENG-24340).
                    let mut snapback = self.lock_live("runMutation")?;
                    if snapback.authorization_reservation_snapshot()? != snapshot {
                        drop(snapback);
                        reservation.cancel();
                        return Err(action_authorization_reservation_stale(name));
                    }
                    crate::storage::install_managed_authorization_reservation(reservation);
                    let outcome = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                        snapback.commit_detached_ibex_mutation_guarded(
                            name,
                            input,
                            binding,
                            executed,
                            host_identity,
                            || self.validate_live("runMutation"),
                            || self.lock_commit_live("runMutation"),
                        )
                    }));
                    let unused = crate::storage::take_managed_authorization_reservation();
                    drop(snapback);
                    if let Some(unused) = unused {
                        unused.cancel();
                    }
                    match outcome {
                        Ok(result) => result,
                        Err(payload) => std::panic::resume_unwind(payload),
                    }
                })();
                match &mut output {
                    Ok(_) => span.finish(Some(200), None, None),
                    Err(error) => {
                        let severity = error.diagnostic.severity.clone();
                        span.finish_error(Some(500), error, Some(json!({ "severity": severity })))
                    }
                }
                if output.is_ok() {
                    // @ref LLP 0076#settlement-and-retry — a successful
                    // nested commit while an attempt cursor is open counts as
                    // durable progress; retry is prohibited afterwards.
                    crate::stream_attempt::global_stream_attempt_registry()
                        .record_progress_commit(&self.stream_runner);
                }
                output
            }
        }
    }

    fn has_fresh_client(&mut self, principal_id: &str) -> SnapbackResult<bool> {
        if !self.connected_client_predicate_available {
            return Err(SnapbackError::error(
                "SNAPBACK_CONNECTED_CLIENT_PREDICATE_UNAVAILABLE",
                "realtime",
                "realtime.hasFreshClient requires a session-auth application",
            ));
        }
        // @ref LLP 0222#semantics-pinned — false means only that no exact
        // transport witness remains inside the fixed monotonic-time budget.
        Ok(self
            .connected_clients
            .has_fresh_client(principal_id, Instant::now()))
    }

    fn open_response_stream(
        &mut self,
        request: ActionStreamRequest,
    ) -> SnapbackResult<ActionStreamOpened> {
        // @ref LLP 0076#authority-and-lifecycle — stream ownership stays
        // inside this exact detached action host and every operation passes
        // validate_host_call before dispatch.
        self.validate_stream_authority("fetchStream.open")?;
        let _egress = crate::auth::rehearsal::ExternalEgressGate::prepare(
            self.authority.rehearsal_provenance(),
            self.authority.profile(),
            crate::auth::rehearsal::RegisteredEgressChannel::RuntimeFetch,
            crate::auth::rehearsal::RegisteredEgressAdapter::Real,
        )?;
        // @ref LLP 0076#settlement-and-retry — automatically re-dispatched
        // cron/durable invocations are excluded from streamed actions until
        // resumable retry semantics exist: an automatic retry cannot prove
        // the prior runner's upstream request never initiated.
        if self.automatic_retry_invocation {
            return Err(action_stream_error(
                "SNAPBACK_ACTION_STREAM_INVALID",
                "open",
                "automatically retried invocations are excluded from streamed actions",
                json!({ "expected": "a first-dispatch invocation", "received": "an automatic retry dispatch" }),
            ));
        }
        if self.response_streams.len() >= ACTION_STREAM_OPEN_MAX {
            return Err(action_stream_error(
                "SNAPBACK_ACTION_STREAM_LIMIT_EXCEEDED",
                "open",
                "the action already owns the maximum number of open response streams",
                json!({ "limit": ACTION_STREAM_OPEN_MAX, "received": "additional stream" }),
            ));
        }
        if request.url.len() > 4_096
            || !(request.url.starts_with("http://") || request.url.starts_with("https://"))
            || request.url.chars().any(char::is_control)
        {
            return Err(action_stream_error(
                "SNAPBACK_ACTION_STREAM_INVALID",
                "open",
                "ctx.fetchStream requires a bounded absolute HTTP(S) URL",
                json!({ "expected": "absolute http(s) URL <= 4096 bytes", "received": "invalid URL shape" }),
            ));
        }
        let method = request.method.to_ascii_uppercase();
        if !matches!(
            method.as_str(),
            "GET" | "HEAD" | "POST" | "PUT" | "PATCH" | "DELETE"
        ) {
            return Err(action_stream_error(
                "SNAPBACK_ACTION_STREAM_INVALID",
                "open",
                "ctx.fetchStream received an unsupported HTTP method",
                json!({ "expected": "GET|HEAD|POST|PUT|PATCH|DELETE", "received": "unsupported method" }),
            ));
        }
        if request.headers.len() > 64
            || request.headers.iter().any(|(name, value)| {
                name.is_empty()
                    || name.len() > 256
                    || value.len() > 8_192
                    || name.chars().any(char::is_control)
                    || value.contains(['\r', '\n'])
            })
        {
            return Err(action_stream_error(
                "SNAPBACK_ACTION_STREAM_INVALID",
                "open",
                "ctx.fetchStream headers exceeded the safe shape",
                json!({ "expected": "at most 64 bounded single-line headers", "received": "invalid header shape" }),
            ));
        }
        if request
            .idempotency_key
            .as_ref()
            .is_some_and(|key| key.is_empty() || key.len() > 8_192 || key.contains(['\r', '\n']))
        {
            return Err(action_stream_error(
                "SNAPBACK_ACTION_STREAM_INVALID",
                "open",
                "ctx.fetchStream received an invalid idempotency key",
                json!({ "expected": "a non-empty single-line key <= 8192 bytes", "received": "invalid idempotency key shape" }),
            ));
        }
        // @ref LLP 0036#runtime-exposure-d5-d8 — the local profile stages
        // secret VALUES into the invocation (with the staged-value redactor
        // scrubbing every error envelope), so descriptor placement slots have
        // nothing to resolve here: refuse them explicitly rather than
        // silently sending a request the author believes carries a secret.
        if request
            .secret_slots
            .iter()
            .any(|slot| slot.secret.is_some())
        {
            return Err(action_stream_error(
                "SNAPBACK_ACTION_STREAM_INVALID",
                "open",
                "opaque secret descriptors resolve only at a hosted fetch boundary; this profile stages secret values",
                json!({ "expected": "value-mode secret placement (ctx.secrets handles)", "received": "opaque descriptor slot" }),
            ));
        }
        if request
            .body
            .as_ref()
            .is_some_and(|body| body.len() as u64 > ACTION_STREAM_TOTAL_BYTES_MAX)
        {
            return Err(action_stream_error(
                "SNAPBACK_ACTION_STREAM_LIMIT_EXCEEDED",
                "open",
                "ctx.fetchStream request body exceeded the v1 byte limit",
                json!({ "limitBytes": ACTION_STREAM_TOTAL_BYTES_MAX, "received": "oversized body" }),
            ));
        }

        let remaining = self.deadline.saturating_duration_since(Instant::now());
        if remaining.is_zero() {
            return Err(action_deadline_elapsed("fetchStream.open"));
        }
        // Mint the cursor id and bind it as a child record of the named
        // attempt BEFORE the request bytes reach the outbound stack: the
        // write-ahead pre-mark leaves `initiation_possible` standing unless a
        // provably pre-send failure narrows it (LLP 0076 §Settlement).
        let stream_id = crate::ids::mint_time_ordered(crate::ids::Kind::Stream);
        if let Some(attempt_token) = &request.attempt_token {
            crate::stream_attempt::global_stream_attempt_registry().bind_cursor(
                attempt_token,
                &stream_id,
                &self.stream_runner,
            )?;
            // The write-ahead pre-mark MUST be durable before any request
            // byte reaches the outbound stack: a crash from here on is
            // recovered as `initiation_possible`, the conservative reading.
            if let Err(error) = self.flush_stream_attempts_required("fetchStream.open") {
                crate::stream_attempt::global_stream_attempt_registry().close_cursor(&stream_id);
                return Err(error);
            }
        }
        let request_timeout = remaining.min(Duration::from_millis(ACTION_STREAM_IDLE_MS));
        let agent = ureq::AgentBuilder::new()
            .timeout_connect(request_timeout)
            .timeout_read(request_timeout)
            .timeout_write(request_timeout)
            .build();
        let mut outbound = agent
            .request(&method, &request.url)
            .timeout(request_timeout);
        for (name, value) in &request.headers {
            outbound = outbound.set(name, value);
        }
        // @ref LLP 0076#surface — a caller-supplied idempotency key is
        // provider-visible: it is forwarded as the upstream `Idempotency-Key`
        // header unless the author set that header explicitly.
        if let Some(key) = &request.idempotency_key
            && !request
                .headers
                .keys()
                .any(|name| name.eq_ignore_ascii_case("idempotency-key"))
        {
            outbound = outbound.set("Idempotency-Key", key);
        }
        let started = Instant::now();
        let response = match &request.body {
            Some(body) => outbound.send_string(body),
            None => outbound.call(),
        };
        let response = match response {
            Ok(response) | Err(ureq::Error::Status(_, response)) => response,
            Err(ureq::Error::Transport(transport)) => {
                // @ref LLP 0076#settlement-and-retry — classification is by
                // host-provable phase and ambiguity over-approximates: a
                // non-idempotent transport failure that cannot be proven
                // pre-initiation is ambiguous, never silently retried. Only a
                // provable pre-send failure (DNS, connection refused, an
                // unusable URL) narrows the pre-mark to
                // `definitely_not_initiated`; everything else stays at the
                // fail-safe `initiation_possible`.
                let registry = crate::stream_attempt::global_stream_attempt_registry();
                if matches!(
                    transport.kind(),
                    ureq::ErrorKind::Dns
                        | ureq::ErrorKind::ConnectionFailed
                        | ureq::ErrorKind::InvalidUrl
                        | ureq::ErrorKind::UnknownScheme
                ) {
                    registry.cursor_initiation(
                        &stream_id,
                        crate::stream_attempt::StreamInitiationState::DefinitelyNotInitiated,
                    );
                }
                registry.close_cursor(&stream_id);
                self.flush_stream_attempts_trusted();
                // @ref LLP 0076#author-decisions--2026-07-23 — decision 5:
                // safe methods are idempotent by grammar; a bare authored
                // idempotency key no longer confers retry semantics. Until a
                // deployment-pinned provider idempotency declaration exists,
                // every keyed non-GET downgrades to non-idempotent and an
                // unprovable transport failure settles ambiguous.
                let provable_pre_send = matches!(
                    transport.kind(),
                    ureq::ErrorKind::Dns
                        | ureq::ErrorKind::ConnectionFailed
                        | ureq::ErrorKind::InvalidUrl
                        | ureq::ErrorKind::UnknownScheme
                );
                let retry_safe = matches!(method.as_str(), "GET" | "HEAD");
                let timed_out = started.elapsed() >= request_timeout;
                let (code, message) = if timed_out {
                    (
                        "SNAPBACK_ACTION_STREAM_IDLE_TIMEOUT",
                        "the upstream did not produce response metadata within the idle limit",
                    )
                } else if retry_safe || provable_pre_send {
                    (
                        "SNAPBACK_ACTION_STREAM_UPSTREAM_FAILED",
                        "the upstream request failed before response metadata was available",
                    )
                } else {
                    (
                        "SNAPBACK_ACTION_STREAM_UPSTREAM_AMBIGUOUS",
                        "the non-idempotent upstream request lost transport after initiation",
                    )
                };
                return Err(action_stream_error(
                    code,
                    "open",
                    message,
                    json!({ "received": "transport failure", "retrySafe": retry_safe }),
                ));
            }
        };
        self.validate_stream_authority("fetchStream.open")?;
        // Response metadata arrived: the certainty axis advances to its
        // absorbing `response_observed` state. The durable advance is
        // best-effort — a skipped write leaves `initiation_possible`, which
        // is the conservative direction.
        crate::stream_attempt::global_stream_attempt_registry().cursor_initiation(
            &stream_id,
            crate::stream_attempt::StreamInitiationState::ResponseObserved,
        );
        self.flush_stream_attempts_trusted();
        let status = response.status();
        let status_text = response.status_text().to_owned();
        let final_url = response.get_url().to_owned();
        let mut headers = BTreeMap::new();
        for name in response.headers_names().into_iter().take(64) {
            if let Some(value) = response.header(&name) {
                headers.insert(name, value.chars().take(8_192).collect());
            }
        }
        let now = Instant::now();
        // Absolute per-stream wall deadline, with settlement grace reserved
        // ahead of the action watchdog so the timeout can be durably settled
        // before abandonment.
        let watchdog_bounded = self
            .deadline
            .checked_sub(Duration::from_millis(ACTION_STREAM_SETTLE_GRACE_MS))
            .unwrap_or(now);
        let wall_deadline = (now + Duration::from_millis(ACTION_STREAM_WALL_MS))
            .min(watchdog_bounded)
            .max(now);
        let (pull_tx, chunk_rx) = spawn_stream_reader_thread(
            response.into_reader(),
            self.stream_buffered_bytes.clone(),
            self.stream_buffered_peak.clone(),
        );
        self.response_streams.insert(
            stream_id.clone(),
            OpenActionResponseStream {
                pull_tx,
                chunk_rx,
                opened_at: now,
                wall_deadline,
                last_byte_at: now,
                total_bytes: 0,
            },
        );
        Ok(ActionStreamOpened {
            stream_id,
            status,
            status_text,
            url: final_url,
            headers,
        })
    }

    // Buffered host-mediated fetch — `ctx.fetch`'s local implementation
    // (0137 a4-f1 / a5-f1): the same detached execution lane, egress gate,
    // request validation, and value-mode secret profile as the streamed
    // sibling above, minus the cursor machinery. The response value is
    // field-compatible with the workerd coordinator's `hostActionFetch`
    // ({status, ok, url, bodyText}, authored URL echoed) so `ctx.fetch`
    // reads identically on both targets.
    fn host_fetch(
        &mut self,
        request: crate::runtime::HostFetchRequest,
    ) -> SnapbackResult<crate::runtime::HostFetchResponse> {
        self.validate_host_call("host.fetch")?;
        let _egress = crate::auth::rehearsal::ExternalEgressGate::prepare(
            self.authority.rehearsal_provenance(),
            self.authority.profile(),
            crate::auth::rehearsal::RegisteredEgressChannel::RuntimeFetch,
            crate::auth::rehearsal::RegisteredEgressAdapter::Real,
        )?;
        let fetch_error = |code: &str, message: &str| {
            SnapbackError::error(code, "runtime", message).with_details(json!({
                "operation": "fetch",
                "repair": "guide/backend/actions-and-fetch#the-inline-form",
            }))
        };
        if request.url.len() > 4_096
            || !(request.url.starts_with("http://") || request.url.starts_with("https://"))
            || request.url.chars().any(char::is_control)
        {
            return Err(fetch_error(
                "SNAPBACK_HOST_FETCH_INVALID",
                "ctx.fetch requires a bounded absolute HTTP(S) URL",
            ));
        }
        let method = request.method.to_ascii_uppercase();
        if !matches!(
            method.as_str(),
            "GET" | "HEAD" | "POST" | "PUT" | "PATCH" | "DELETE"
        ) {
            return Err(fetch_error(
                "SNAPBACK_HOST_FETCH_INVALID",
                "ctx.fetch received an unsupported HTTP method",
            ));
        }
        if request.headers.len() > 64
            || request.headers.iter().any(|(name, value)| {
                name.is_empty()
                    || name.len() > 256
                    || value.len() > 8_192
                    || name.chars().any(char::is_control)
                    || value.contains(['\r', '\n'])
            })
        {
            return Err(fetch_error(
                "SNAPBACK_HOST_FETCH_INVALID",
                "ctx.fetch headers exceeded the safe shape",
            ));
        }
        // @ref LLP 0036#runtime-exposure-d5-d8 — the local profile stages
        // secret VALUES into the invocation, so descriptor placement slots
        // have nothing to resolve here: refuse them explicitly rather than
        // silently sending a request the author believes carries a secret.
        if request
            .secret_slots
            .iter()
            .any(|slot| slot.secret.is_some())
        {
            return Err(fetch_error(
                "SNAPBACK_HOST_FETCH_SLOT_INVALID",
                "opaque secret descriptors resolve only at a hosted fetch boundary; this profile stages secret values",
            ));
        }
        if request
            .body
            .as_ref()
            .is_some_and(|body| body.len() as u64 > HOST_FETCH_RESPONSE_BYTES_MAX)
        {
            return Err(fetch_error(
                "SNAPBACK_HOST_FETCH_INVALID",
                "ctx.fetch request body exceeded the byte limit",
            ));
        }
        let remaining = self.deadline.saturating_duration_since(Instant::now());
        if remaining.is_zero() {
            return Err(action_deadline_elapsed("fetch"));
        }
        // Same bounds as the workerd leg: the authored timeout (default 15 s)
        // clamped by the action's remaining wall budget.
        let requested_timeout = Duration::from_millis(
            request
                .timeout_ms
                .filter(|timeout| *timeout > 0)
                .unwrap_or(15_000),
        );
        let request_timeout = requested_timeout.min(remaining);
        let agent = ureq::AgentBuilder::new()
            .timeout_connect(request_timeout)
            .timeout_read(request_timeout)
            .timeout_write(request_timeout)
            .build();
        let mut outbound = agent
            .request(&method, &request.url)
            .timeout(request_timeout);
        for (name, value) in &request.headers {
            outbound = outbound.set(name, value);
        }
        let response = match &request.body {
            Some(body) => outbound.send_string(body),
            None => outbound.call(),
        };
        let response = match response {
            Ok(response) | Err(ureq::Error::Status(_, response)) => response,
            Err(ureq::Error::Transport(_transport)) => {
                // Header/body/transport detail is application data; report
                // the phase fact only (the streamed sibling's rule).
                return Err(fetch_error(
                    "SNAPBACK_HOST_FETCH_FAILED",
                    "the upstream request failed before a response was available",
                ));
            }
        };
        self.validate_host_call("host.fetch")?;
        let status = response.status();
        let mut body = Vec::new();
        let mut reader = response
            .into_reader()
            .take(HOST_FETCH_RESPONSE_BYTES_MAX + 1);
        if std::io::Read::read_to_end(&mut reader, &mut body).is_err() {
            return Err(fetch_error(
                "SNAPBACK_HOST_FETCH_FAILED",
                "the upstream response body could not be read",
            ));
        }
        if body.len() as u64 > HOST_FETCH_RESPONSE_BYTES_MAX {
            return Err(fetch_error(
                "SNAPBACK_HOST_FETCH_RESPONSE_TOO_LARGE",
                "the upstream response exceeded the bounded host fetch byte limit",
            ));
        }
        let body_text = String::from_utf8(body).map_err(|_error| {
            fetch_error(
                "SNAPBACK_HOST_FETCH_RESPONSE_INVALID_UTF8",
                "the upstream response body was not valid UTF-8",
            )
        })?;
        Ok(crate::runtime::HostFetchResponse {
            status,
            ok: (200..300).contains(&status),
            url: request.url,
            body_text,
        })
    }

    fn push_send(
        &mut self,
        request: crate::push::PushSendRequestV1,
    ) -> SnapbackResult<crate::push::PushSendReservationResponseV1> {
        self.validate_host_call("push.send")?;
        let _egress = crate::auth::rehearsal::ExternalEgressGate::prepare(
            self.authority.rehearsal_provenance(),
            self.authority.profile(),
            crate::auth::rehearsal::RegisteredEgressChannel::PushProvider,
            crate::auth::rehearsal::RegisteredEgressAdapter::Real,
        )?;
        let trigger_mode = if self.deferred_push_grant.is_some()
            && matches!(self.authority.resolved(), ResolvedAppAuthority::System)
        {
            crate::push::PushTriggerModeV1::Deferred
        } else if matches!(self.authority.resolved(), ResolvedAppAuthority::System) {
            crate::push::PushTriggerModeV1::System
        } else {
            crate::push::PushTriggerModeV1::Immediate
        };
        let provider_base = expo_push_provider_base_url(self.authority.profile())?;
        let endpoint = format!(
            "{}/--/api/v2/push/send",
            provider_base.trim_end_matches('/')
        );
        let now_ms = now_millis();
        let (mut attempt, access_token) = {
            let mut snapback = self.lock_live("push.send.reserve")?;
            let _effect = self
                .authority
                .effect_guard("push send durable reservation")?;
            let database = snapback.auth_database_mut();
            let schema = database.schema().clone();
            let declaration = schema.push_seam.clone().ok_or_else(|| {
                SnapbackError::error(
                    "SNAPBACK_PUSH_SEAM_NOT_DECLARED",
                    "push",
                    "the app schema does not declare the push send seam",
                )
            })?;
            let access_token = self.push_access_token(&declaration)?;
            let attempt = database.push_registry().reserve_send(
                &declaration,
                &schema,
                || self.authority.clone(),
                trigger_mode,
                self.deferred_push_grant.as_ref(),
                &request,
                now_ms,
            )?;
            (attempt, access_token)
        };

        // @ref LLP 0143#d2-the-send-lane — pacing is host-owned and bounded
        //   across attempts, never an application convention or hidden
        //   provider burst. The manifest publishes this exact bound.
        let _pacing = (!attempt.batches.is_empty()).then(|| {
            EXPO_PUSH_SEND_PACER
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner())
        });

        for batch in &attempt.batches {
            let Some(claim) = ({
                let mut snapback = self.lock_live("push.send.claim")?;
                let _effect = self.authority.effect_guard("push batch claim")?;
                snapback
                    .auth_database_mut()
                    .push_registry()
                    .claim_batch(&batch.batch_id, now_millis())?
            }) else {
                continue;
            };

            // Service-token authority is checked before the durable transmit
            // marker. From the marker commit onward every loss of process or
            // response certainty settles (or recovers) as ambiguous.
            {
                let mut snapback = self.lock_live("push.send.preflight")?;
                snapback.persist_service_deadline_if_due(&self.authority)?;
            }
            let permit = self
                .authority
                .begin_service_external_effect(now_millis(), Instant::now())?;
            {
                let mut snapback = self.lock_live("push.send.transmitting")?;
                let _effect = self
                    .authority
                    .effect_guard("push batch transmitting marker")?;
                snapback
                    .auth_database_mut()
                    .push_registry()
                    .mark_batch_transmitting(&claim, now_millis())?;
            }

            let payload = crate::push::expo_send_payload(&claim, &request);
            if let Some(permit) = permit {
                permit.initiated();
            }
            let remaining = self.deadline.saturating_duration_since(Instant::now());
            let settlement = if remaining.is_zero() {
                crate::push::PushBatchSettlementV1::Ambiguous {
                    code: "timeout".into(),
                }
            } else {
                let timeout = remaining.min(Duration::from_secs(15));
                transmit_expo_push_batch(
                    &endpoint,
                    access_token.as_deref(),
                    payload,
                    timeout,
                    Some(self.deadline),
                )
            };
            {
                let mut snapback = self.lock_live("push.send.settle")?;
                let _effect = self.authority.effect_guard("push batch settlement")?;
                snapback.auth_database_mut().push_registry().settle_batch(
                    &claim,
                    &settlement,
                    now_millis(),
                )?;
            }
        }
        let mut snapback = self.lock_live("push.send.result")?;
        let intent_id = attempt.response.intent_id.clone();
        attempt.response.state = snapback
            .auth_database_mut()
            .push_registry()
            .intent_state(&intent_id)?;
        Ok(attempt.response)
    }

    fn read_response_stream(&mut self, stream_id: &str) -> SnapbackResult<ActionStreamChunk> {
        let Some(mut stream) = self.response_streams.remove(stream_id) else {
            // @ref LLP 0076#diagnostics — a read after cancellation returns
            // end-of-stream, not an error; `SNAPBACK_ACTION_STREAM_CANCELLED`
            // stays a reserved internal reason no v1 read path emits.
            if self.closed_response_streams.contains(stream_id) {
                return Ok(ActionStreamChunk {
                    done: true,
                    bytes: Vec::new(),
                    total_bytes: 0,
                    elapsed_ms: 0,
                    delta_ms: 0,
                });
            }
            return Err(action_stream_error(
                "SNAPBACK_ACTION_STREAM_INVALID",
                "read",
                "the response stream id is unknown to this action invocation",
                json!({ "expected": "an open invocation-local stream", "received": "unknown stream id" }),
            ));
        };
        if Instant::now() >= stream.wall_deadline {
            self.close_response_stream_cursor(stream_id);
            return Err(action_stream_error(
                "SNAPBACK_ACTION_STREAM_TIMEOUT",
                "read",
                "the response stream exceeded its wall-clock limit",
                json!({ "limitMs": ACTION_STREAM_WALL_MS, "received": "wall limit elapsed" }),
            ));
        }
        if stream.last_byte_at.elapsed() >= Duration::from_millis(ACTION_STREAM_IDLE_MS) {
            self.close_response_stream_cursor(stream_id);
            return Err(action_stream_error(
                "SNAPBACK_ACTION_STREAM_IDLE_TIMEOUT",
                "read",
                "the response stream exceeded its idle limit",
                json!({ "limitMs": ACTION_STREAM_IDLE_MS, "received": "idle limit elapsed" }),
            ));
        }
        // Direct attempt-to-cursor cancellation signal: a committed terminal
        // settlement on the owning attempt closes this cursor at the next
        // pull boundary — physically dropping the upstream reader — without
        // waiting for the next progress mutation to observe the terminal row.
        if crate::stream_attempt::global_stream_attempt_registry()
            .cursor_attempt_terminal(stream_id)
        {
            let total_bytes = stream.total_bytes;
            let elapsed_ms = stream.opened_at.elapsed().as_millis() as u64;
            drop(stream);
            self.close_response_stream_cursor(stream_id);
            return Ok(ActionStreamChunk {
                done: true,
                bytes: Vec::new(),
                total_bytes,
                elapsed_ms,
                delta_ms: 0,
            });
        }
        // Pre-pull leg of the per-read authority fence.
        if let Err(error) = self.validate_stream_authority("fetchStream.read") {
            drop(stream);
            self.close_response_stream_cursor(stream_id);
            return Err(error);
        }
        let remaining = ACTION_STREAM_TOTAL_BYTES_MAX.saturating_sub(stream.total_bytes);
        let requested = if remaining == 0 {
            1
        } else {
            ACTION_STREAM_CHUNK_BYTES_MAX.min(remaining as usize)
        };
        // Dispatch the pull to the cursor's reader thread. The rendezvous
        // channel holds one request, so a second in-flight pull on the same
        // cursor is structurally impossible; a full channel is a protocol
        // violation, not a queue.
        if stream
            .pull_tx
            .try_send(StreamPullRequest { requested })
            .is_err()
        {
            drop(stream);
            self.close_response_stream_cursor(stream_id);
            return Err(action_stream_error(
                "SNAPBACK_ACTION_STREAM_INVALID",
                "read",
                "the response stream already has a pull in flight",
                json!({ "expected": "one in-flight pull per cursor", "received": "overlapping pull" }),
            ));
        }
        // The absolute wall ceiling bounds THIS pull: recv_timeout fires at
        // the deadline even while the socket read is still blocked, and the
        // dropped stream retires the reader thread within one socket-timeout
        // window. Idle is enforced separately by the socket read timeout.
        let wall_remaining = stream
            .wall_deadline
            .saturating_duration_since(Instant::now())
            .max(Duration::from_millis(1));
        let pulled = match stream.chunk_rx.recv_timeout(wall_remaining) {
            Ok(outcome) => outcome,
            Err(std::sync::mpsc::RecvTimeoutError::Timeout) => {
                drop(stream);
                self.close_response_stream_cursor(stream_id);
                return Err(action_stream_error(
                    "SNAPBACK_ACTION_STREAM_TIMEOUT",
                    "read",
                    "the response stream exceeded its wall-clock limit",
                    json!({ "limitMs": ACTION_STREAM_WALL_MS, "received": "wall limit elapsed mid-read" }),
                ));
            }
            Err(std::sync::mpsc::RecvTimeoutError::Disconnected) => {
                drop(stream);
                self.close_response_stream_cursor(stream_id);
                return Err(action_stream_error(
                    "SNAPBACK_ACTION_STREAM_UPSTREAM_FAILED",
                    "read",
                    "the upstream response stream failed while reading",
                    json!({ "received": "reader thread ended" }),
                ));
            }
        };
        let bytes = match pulled {
            Ok(bytes) => bytes,
            Err(error)
                if matches!(
                    error.kind(),
                    std::io::ErrorKind::TimedOut | std::io::ErrorKind::WouldBlock
                ) =>
            {
                self.close_response_stream_cursor(stream_id);
                return Err(action_stream_error(
                    "SNAPBACK_ACTION_STREAM_IDLE_TIMEOUT",
                    "read",
                    "the upstream produced no response bytes within the idle limit",
                    json!({ "limitMs": ACTION_STREAM_IDLE_MS, "received": "read timeout" }),
                ));
            }
            Err(_) => {
                self.close_response_stream_cursor(stream_id);
                return Err(action_stream_error(
                    "SNAPBACK_ACTION_STREAM_UPSTREAM_FAILED",
                    "read",
                    "the upstream response stream failed while reading",
                    json!({ "received": "transport read failure" }),
                ));
            }
        };
        let read = bytes.len();
        let release_buffered = |counter: &Arc<AtomicU64>| {
            if read > 0 {
                counter.fetch_sub(read as u64, Ordering::SeqCst);
            }
        };
        // Post-pull leg of the per-read authority fence: authority may have
        // been terminalized while this pull was blocked awaiting bytes. Late
        // bytes are discarded — the cursor closes and the authority refusal,
        // not the data, reaches the action.
        if let Err(error) = self.validate_stream_authority("fetchStream.read") {
            release_buffered(&self.stream_buffered_bytes);
            drop(stream);
            self.close_response_stream_cursor(stream_id);
            return Err(error);
        }
        if read == 0 {
            self.close_response_stream_cursor(stream_id);
            return Ok(ActionStreamChunk {
                done: true,
                bytes: Vec::new(),
                total_bytes: stream.total_bytes,
                elapsed_ms: stream.opened_at.elapsed().as_millis() as u64,
                delta_ms: 0,
            });
        }
        if stream.total_bytes.saturating_add(read as u64) > ACTION_STREAM_TOTAL_BYTES_MAX {
            release_buffered(&self.stream_buffered_bytes);
            self.close_response_stream_cursor(stream_id);
            return Err(action_stream_error(
                "SNAPBACK_ACTION_STREAM_LIMIT_EXCEEDED",
                "read",
                "the upstream response exceeded the v1 total-byte limit",
                json!({ "limitBytes": ACTION_STREAM_TOTAL_BYTES_MAX, "received": "oversized response" }),
            ));
        }
        let delta_ms = stream.last_byte_at.elapsed().as_millis() as u64;
        stream.total_bytes += read as u64;
        stream.last_byte_at = Instant::now();
        let total_bytes = stream.total_bytes;
        let elapsed_ms = stream.opened_at.elapsed().as_millis() as u64;
        self.response_streams.insert(stream_id.to_owned(), stream);
        // Handoff complete: the chunk now belongs to the application; the
        // host-materialized accounting releases it.
        release_buffered(&self.stream_buffered_bytes);
        // @ref LLP 0076#author-decisions--2026-07-23 — decision 6: every read
        // result carries host-owned monotonic elapsed milliseconds so
        // authored code can gate progress commits without a wall clock.
        Ok(ActionStreamChunk {
            done: false,
            bytes,
            total_bytes,
            elapsed_ms,
            delta_ms,
        })
    }

    fn cancel_response_stream(&mut self, stream_id: &str) -> SnapbackResult<()> {
        if self.response_streams.remove(stream_id).is_some()
            || self.closed_response_streams.contains(stream_id)
        {
            self.close_response_stream_cursor(stream_id);
            return Ok(());
        }
        Err(action_stream_error(
            "SNAPBACK_ACTION_STREAM_INVALID",
            "cancel",
            "the response stream id is unknown to this action invocation",
            json!({ "expected": "an invocation-local stream", "received": "unknown stream id" }),
        ))
    }

    // @ref LLP 0076#settlement-and-retry — the host-owned StreamAttemptV1
    // record: idempotent start by client key under the single-runner lease.
    // The durable row is consulted first, so a winner settled in a previous
    // process life (or by the startup reconciler) is returned verbatim.
    fn start_stream_attempt(
        &mut self,
        client_key: &str,
    ) -> SnapbackResult<crate::stream_attempt::StreamAttemptStart> {
        self.validate_live("streamAttempt.start")?;
        let registry = crate::stream_attempt::global_stream_attempt_registry();
        let (namespace, persisted) = {
            let snapback = self.lock_live("streamAttempt.start")?;
            let persisted =
                snapback
                    .stream_attempt_record(client_key)?
                    .and_then(|(_, record_json)| {
                        serde_json::from_str::<crate::stream_attempt::PersistedStreamAttempt>(
                            &record_json,
                        )
                        .ok()
                    });
            (snapback.stream_attempt_namespace(), persisted)
        };
        let started = registry.start(
            namespace,
            client_key,
            &self.stream_runner,
            persisted.as_ref(),
        )?;
        // The attempt row itself is durable before the caller can bind
        // cursors or commit progress against it.
        self.flush_stream_attempts_required("streamAttempt.start")?;
        Ok(started)
    }

    fn settle_stream_attempt(
        &mut self,
        attempt_token: &str,
        cause: crate::stream_attempt::StreamAttemptCause,
    ) -> SnapbackResult<crate::stream_attempt::StreamAttemptTerminal> {
        self.validate_live("streamAttempt.settle")?;
        let terminal = crate::stream_attempt::global_stream_attempt_registry().settle(
            attempt_token,
            cause,
            &self.stream_runner,
        )?;
        // The authored settle is a durable terminal fact: persist it before
        // the action observes success.
        self.flush_stream_attempts_required("streamAttempt.settle")?;
        Ok(terminal)
    }

    fn emit_stream_chunk(
        &mut self,
        chunk: Value,
    ) -> SnapbackResult<crate::stream_attempt::StreamChunkEmission> {
        self.validate_stream_authority("stream.emit")?;
        let attempt_token = self.output_stream_attempt.clone().ok_or_else(|| {
            SnapbackError::error(
                "SNAPBACK_STREAM_NOT_DECLARED",
                "runtime",
                "ctx.stream.emit is available only to an action declared with stream: true",
            )
        })?;
        let chunk_bytes = serde_json::to_vec(&chunk).map_err(|_| {
            SnapbackError::error(
                "SNAPBACK_STREAM_CHUNK_INVALID",
                "runtime",
                "the stream chunk is not bounded JSON",
            )
        })?;
        let emission = crate::stream_attempt::global_stream_attempt_registry().emit_chunk(
            &attempt_token,
            chunk_bytes.len(),
            &self.stream_runner,
        )?;
        let scope = Scope::from_pairs([("attemptToken", attempt_token.clone())]);
        let value = serde_json::to_vec(&json!({
            "attemptToken": attempt_token,
            "chunkIndex": emission.chunk_index,
            "chunk": chunk,
        }))
        .map_err(|_| {
            SnapbackError::error(
                "SNAPBACK_STREAM_CHUNK_INVALID",
                "runtime",
                "the stream chunk envelope could not be serialized",
            )
        })?;
        let permit = self
            .ephemeral
            .begin_server_authorized_room_act(crate::ephemeral::STREAM_COLLECTION_NAME, &scope)
            .map_err(Self::ephemeral_error)?;
        let auth = AuthContext::default().with_room_permission("_snapback_stream_server", &scope);
        self.ephemeral
            .publish_with_room_authority(
                crate::ephemeral::PublishRequest {
                    collection: crate::ephemeral::STREAM_COLLECTION_NAME.to_owned(),
                    scope,
                    connection_id: format!("stream:{attempt_token}"),
                    session_id: None,
                    user_id: None,
                    custom_key: Some(format!("{:020}", emission.chunk_index)),
                    value,
                    ttl_ms: Some(30_000),
                    auth,
                },
                now_millis(),
                permit.as_ref(),
            )
            .map_err(Self::ephemeral_error)?;
        self.flush_stream_attempts_required("stream.emit")?;
        Ok(emission)
    }
}

// @ref LLP 0012#diagnostic-schema — stream refusals carry operation, expected
// shape/limit, a value-free received summary, and the guide repair anchor;
// URLs, headers, bodies, and response bytes never enter a default diagnostic.
fn action_stream_error(
    code: &'static str,
    operation: &'static str,
    message: &'static str,
    details: Value,
) -> SnapbackError {
    let mut details = details.as_object().cloned().unwrap_or_default();
    details.insert("operation".to_owned(), json!(operation));
    details.insert(
        "repair".to_owned(),
        json!("guide/backend/actions-and-fetch#stream-a-response"),
    );
    SnapbackError::error(code, "runtime", message).with_details(Value::Object(details))
}

fn action_authorization_reservation_stale(name: &str) -> SnapbackError {
    authorization_reservation_stale(format!(
        "authorization state changed while action-hosted mutation {name} reserved protected rooms; retry the complete mutation with short jitter"
    ))
}

/// A stale reservation commits no application or authorization effect. It is
/// therefore an ordinary retryable conflict, not service unavailability.
///
/// @ref LLP 0059#plan-begin-commit-finalize — reservation revalidation
/// precedes the durable transaction and a stale attempt is abandoned whole.
fn authorization_reservation_stale(message: impl Into<String>) -> SnapbackError {
    SnapbackError::error("SNAPBACK_AUTH_RESERVATION_STALE", "auth", message).with_details(json!({
        "retryable": true,
        "retryStrategy": "short-jitter",
        "effectCommitted": false,
    }))
}

fn action_abandoned(op: &str) -> SnapbackError {
    SnapbackError::error(
        "SNAPBACK_ACTION_TIMEOUT",
        "runtime",
        format!("ctx.{op} rejected: the action exceeded its wall-clock watchdog and was abandoned"),
    )
}

fn action_deadline_elapsed(op: &str) -> SnapbackError {
    SnapbackError::error(
        "SNAPBACK_ACTION_TIMEOUT",
        "runtime",
        format!(
            "ctx.{op} rejected: the action exceeded its wall-clock execution deadline before the host operation could complete"
        ),
    )
}

fn action_generation_conflict(op: &str, staged: u64, current: u64) -> SnapbackError {
    // @ref LLP 0028#execution-the-action-class — the outer detached action and
    // every host call retain the staging-time code/schema/reset authority.
    SnapbackError::error(
        "SNAPBACK_ACTION_GENERATION_CONFLICT",
        "runtime",
        format!(
            "ctx.{op} rejected: app code, schema, or state reset changed while the action was running"
        ),
    )
    .with_details(json!({
        "stagedAppGeneration": staged,
        "currentAppGeneration": current,
    }))
}

/// Linearize watchdog abandonment against the final commit gate, then cancel
/// the exact room reservation currently owned by the detached action. Callers
/// run this on a blocking thread because the bounded SQLite commit window may
/// momentarily own `commit_gate`.
///
/// @ref LLP 0059#authorization-write-handoff — abandonment exact-unmarks an
///   in-flight room ticket before the watchdog publishes its timeout.
fn linearize_detached_action_abandonment(
    commit_gate: &StdMutex<()>,
    abandoned: &AtomicBool,
    active_reservation: &StdMutex<
        Option<Arc<crate::storage::AuthorizationReservationCancellation>>,
    >,
) {
    let _gate = commit_gate
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner);
    abandoned.store(true, Ordering::SeqCst);
    if let Some(cancellation) = active_reservation
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .take()
    {
        cancellation.cancel();
    }
}

/// Run a staged Ibex action on a detached thread under a wall-clock watchdog.
///
/// The action holds no instance lock while it runs; nested Ibex handlers also
/// execute outside it, so a hung fetch or mutation stalls only this action,
/// not writes, cron, or in-memory queries. On timeout Hermes asynchronously
/// breaks the eval and the fresh runtime is destroyed. The abandonment gate
/// rejects any host call that races with that teardown.
/// Mutations the action committed before the timeout remain committed —
/// actions are not transactions (LLP 0028).
async fn run_detached_ibex_action(
    state: &SharedSnapback,
    action: Box<crate::local::DetachedIbexAction>,
    input: HandlerInput,
    metadata: CronRunMetadata,
) -> SnapbackResult<Value> {
    let limiter = detached_action_limiter();
    run_detached_ibex_action_with_admission(
        state,
        action,
        input,
        metadata,
        limiter.semaphore.clone(),
        limiter.limit,
    )
    .await
}

async fn run_detached_ibex_action_with_admission(
    state: &SharedSnapback,
    action: Box<crate::local::DetachedIbexAction>,
    input: HandlerInput,
    metadata: CronRunMetadata,
    admission: Arc<Semaphore>,
    worker_limit: usize,
) -> SnapbackResult<Value> {
    run_detached_ibex_action_with_admission_and_counters(
        state,
        action,
        input,
        metadata,
        admission,
        worker_limit,
        global_detached_action_worker_counters(),
    )
    .await
}

async fn run_detached_ibex_action_with_admission_and_counters(
    state: &SharedSnapback,
    action: Box<crate::local::DetachedIbexAction>,
    input: HandlerInput,
    metadata: CronRunMetadata,
    admission: Arc<Semaphore>,
    worker_limit: usize,
    counters: DetachedActionWorkerCounters,
) -> SnapbackResult<Value> {
    run_detached_ibex_action_with_admission_counters_and_timeout(
        state,
        action,
        input,
        metadata,
        admission,
        worker_limit,
        counters,
        action_watchdog_timeout_ms(),
    )
    .await
}

#[allow(clippy::too_many_arguments)]
async fn run_detached_ibex_action_with_admission_counters_and_timeout(
    state: &SharedSnapback,
    action: Box<crate::local::DetachedIbexAction>,
    input: HandlerInput,
    metadata: CronRunMetadata,
    admission: Arc<Semaphore>,
    worker_limit: usize,
    counters: DetachedActionWorkerCounters,
    timeout_ms: u64,
) -> SnapbackResult<Value> {
    // @ref LLP 0028#execution-the-action-class — detached native work has a
    // hard process-wide admission ceiling. A timed-out native call may retain
    // its permit until it actually exits, but it can never cause unbounded
    // thread growth.
    let worker_permit =
        reserve_detached_action_worker_with_counters(admission, worker_limit, counters)?;
    let started = Instant::now();
    let deadline = started
        .checked_add(Duration::from_millis(timeout_ms))
        .ok_or_else(|| {
            SnapbackError::error(
                "SNAPBACK_ACTION_TIMEOUT_INVALID",
                "runtime",
                "configured action watchdog cannot be represented by the host clock",
            )
        })?;
    // Give Hermes' async-break monitor a small teardown margin before the
    // public watchdog fires. Normal timeout responses therefore come only
    // after the runtime and its OS worker have been destroyed; the outer
    // timer remains the fail-safe for a native host call that cannot unwind.
    let interrupt_cushion_ms = (timeout_ms / 10).clamp(1, 50);
    let execution_deadline = deadline
        .checked_sub(Duration::from_millis(interrupt_cushion_ms))
        .unwrap_or(deadline);
    let abandoned = Arc::new(AtomicBool::new(false));
    let commit_gate = Arc::new(StdMutex::new(()));
    let active_reservation = Arc::new(StdMutex::new(None));
    // @ref LLP 0076#settlement-and-retry — one control-plane identity per
    // invocation: the StreamAttemptV1 lease binds to it, and the trusted
    // terminalizer settles its attempts when it can no longer commit.
    let stream_runner = crate::stream_attempt::StreamRunnerIdentity::new(abandoned.clone());
    let automatic_retry_invocation =
        metadata.attempt > 1 || matches!(metadata.trigger, crate::cron::CronRunTrigger::Recovery);
    let host_operation = HostOperationParentV1::from_action_run(&metadata);
    let (sender, mut receiver) = tokio::sync::oneshot::channel();
    let spawned = spawn_detached_action_worker(
        worker_permit,
        counters,
        {
            let state = state.clone();
            let abandoned = abandoned.clone();
            let commit_gate = commit_gate.clone();
            let active_reservation = active_reservation.clone();
            let stream_runner = stream_runner.clone();
            move || {
                let crate::local::DetachedIbexAction {
                    function_name,
                    function_id,
                    stream,
                    stream_initiator,
                    stream_started,
                    ephemeral,
                    connected_clients,
                    connected_client_predicate_available,
                    telemetry,
                    module,
                    grants,
                    redactor,
                    runtime,
                    invocation,
                    app_generation,
                    app_generation_fence,
                    deferred_push_grant,
                } = *action;
                let push_grants = grants.clone();
                let correlation = input
                    .correlation
                    .as_ref()
                    .and_then(Value::as_str)
                    .map(str::to_owned);
                let span = telemetry.start_classified_span(
                    crate::telemetry_contract::OperationClassIdV1::FUNCTION_ACTION,
                    &function_name,
                    correlation.as_deref(),
                    None,
                );
                let mut host = DetachedActionHost {
                    state,
                    connected_clients,
                    connected_client_predicate_available,
                    abandoned,
                    commit_gate,
                    active_reservation,
                    deadline: execution_deadline,
                    app_generation,
                    app_generation_fence,
                    authority: invocation.authority().clone(),
                    push_grants,
                    deferred_push_grant,
                    external_effect_open: false,
                    external_effect_permit: None,
                    response_streams: BTreeMap::new(),
                    closed_response_streams: BTreeSet::new(),
                    last_stream_progress_commit: None,
                    stream_runner: stream_runner.clone(),
                    output_stream_attempt: None,
                    output_stream_function_id: stream.then_some(function_id),
                    output_stream_initiator: stream_initiator,
                    ephemeral,
                    stream_buffered_bytes: Arc::new(AtomicU64::new(0)),
                    stream_buffered_peak: Arc::new(AtomicU64::new(0)),
                    automatic_retry_invocation,
                    host_operation,
                };
                let input = invocation.canonicalize_input(input);
                let initialized = host.initialize_output_stream();
                if initialized.is_ok()
                    && let Some(stream_started) = stream_started
                    && let Some(attempt_token) = host.output_stream_attempt.clone()
                {
                    let _ = stream_started.send(attempt_token);
                }
                let result = initialized.and_then(|()| {
                    crate::runtime::with_runtime_log_telemetry(
                        telemetry.clone(),
                        correlation,
                        || {
                            runtime.invoke_ibex_action_prepared(
                                &module,
                                input,
                                &invocation,
                                metadata,
                                &mut host,
                                grants,
                                Some(execution_deadline),
                            )
                        },
                    )
                });
                let result = match result {
                    Err(_error) if Instant::now() >= execution_deadline => {
                        Err(action_deadline_elapsed("action.execute"))
                    }
                    other => other,
                };
                // @ref LLP 0028#execution-the-action-class — an action may
                // await native fetch/timer work and return without making
                // another Snapback host call. Linearize completion against the
                // same staging generation so a reload/reset during that await
                // cannot escape as success — and so a spurious settlement-floor
                // diagnostic cannot mask that fence (ENG-24530). ENG-25006
                // closes Ibex's historical erase-before-enqueue fetch window,
                // but this caller-side precedence remains defense in depth:
                // when a reload/reset crossed the async span,
                // SNAPBACK_ACTION_GENERATION_CONFLICT is the precise, stable
                // cause and must still win over a settlement floor. The
                // watchdog is the hard upper bound: validate_live reports
                // abandonment/deadline (SNAPBACK_ACTION_TIMEOUT) ahead of the
                // generation fence, so a genuinely stuck native op keeps timing
                // out and a truly unsettled handler with no generation drift
                // keeps its SNAPBACK_HANDLER_DID_NOT_SETTLE.
                let mut fenced = match result {
                    Ok(value) => host.validate_live("action.complete").map(|()| value),
                    Err(error) if error.diagnostic.code == "SNAPBACK_HANDLER_DID_NOT_SETTLE" => {
                        match host.validate_live("action.complete") {
                            Ok(()) => Err(error),
                            Err(fence) => Err(fence),
                        }
                    }
                    Err(error) => Err(error),
                };
                if host.output_stream_attempt.is_some()
                    && let Ok(value) = &fenced
                {
                    let final_len = match value {
                        Value::String(text) => text.len(),
                        value => serde_json::to_vec(value).map_or(usize::MAX, |bytes| bytes.len()),
                    };
                    if final_len
                        > crate::storage::stream_transcripts::STREAM_TRANSCRIPT_FINAL_MAX_BYTES
                    {
                        fenced = Err(SnapbackError::error(
                            "SNAPBACK_STREAM_FINAL_TOO_LARGE",
                            "runtime",
                            "the streaming action final value exceeds 256 KiB",
                        ));
                    }
                }
                // @ref LLP 0076#settlement-and-retry — the trusted
                // terminalizer's completion leg: whatever the authored path
                // did, every attempt this invocation still holds open gets a
                // durable winner. An attempt the action settled is untouched;
                // an unsettled one maps the invocation outcome onto the five
                // frozen causes (watchdog/deadline → timed_out, fence loss →
                // cancelled, anything else — including an action that simply
                // returned without settling — → failed).
                let terminal_cause = match &fenced {
                    Err(error) if error.diagnostic.code == "SNAPBACK_ACTION_TIMEOUT" => {
                        crate::stream_attempt::StreamAttemptCause::TimedOut
                    }
                    Err(error)
                        if matches!(
                            error.diagnostic.code.as_str(),
                            "SNAPBACK_ACTION_GENERATION_CONFLICT"
                                | "SNAPBACK_AUTH_SCOPED_TOKEN_INVALID"
                                | "SNAPBACK_AUTH_STREAM_RESET"
                        ) =>
                    {
                        crate::stream_attempt::StreamAttemptCause::Cancelled
                    }
                    Ok(_) if host.output_stream_attempt.is_some() => {
                        crate::stream_attempt::StreamAttemptCause::Complete
                    }
                    _ => crate::stream_attempt::StreamAttemptCause::Failed,
                };
                let attempt_registry = crate::stream_attempt::global_stream_attempt_registry();
                if let Some(attempt_token) = host.output_stream_attempt.clone()
                    && let Err(error) = host.settle_stream_attempt(&attempt_token, terminal_cause)
                    && fenced.is_ok()
                {
                    fenced = Err(error);
                }
                if host.output_stream_attempt.is_some()
                    && let Err(error) = host.persist_output_transcript_trusted(&fenced)
                    && fenced.is_ok()
                {
                    fenced = Err(error);
                }
                attempt_registry.terminalize_invocation(&stream_runner, terminal_cause);
                // The worker itself is done: release its attempt references
                // so durably flushed terminals can be reaped (registry
                // retention). Anything terminalize just dirtied is reaped by
                // the flush below instead.
                attempt_registry.release_invocation(&stream_runner);
                host.flush_stream_attempts_trusted();
                let mut result = fenced
                    // This is the earliest common envelope boundary and
                    // carries the staging-time values, so rotation cannot
                    // make an old secret invisible to the scrubber.
                    .map_err(|error| redactor.redact_error(error));
                match &mut result {
                    Ok(_) => span.finish(Some(200), None, None),
                    Err(error) => {
                        let severity = error.diagnostic.severity.clone();
                        span.finish_error(Some(500), error, Some(json!({ "severity": severity })))
                    }
                }
                result
            }
        },
        move |result| {
            // Runtime/host/worker guards are gone before publishing the
            // result, so a returned timeout proves no CPU worker leaked.
            let _ = sender.send(result);
        },
    );
    if let Err(error) = spawned {
        return Err(SnapbackError::error(
            "SNAPBACK_ACTION_THREAD_SPAWN_FAILED",
            "runtime",
            "action execution thread could not be spawned",
        )
        .with_details(json!({ "error": error.to_string() })));
    }
    match tokio::time::timeout(Duration::from_millis(timeout_ms), &mut receiver).await {
        Ok(Ok(result)) => result,
        Ok(Err(_closed)) => {
            // The worker died without publishing a result; its attempts
            // still need a durable winner. The dead worker can no longer
            // consult them, so its references are released as well.
            let attempt_registry = crate::stream_attempt::global_stream_attempt_registry();
            attempt_registry.terminalize_invocation(
                &stream_runner,
                crate::stream_attempt::StreamAttemptCause::Failed,
            );
            attempt_registry.release_invocation(&stream_runner);
            Err(SnapbackError::error(
                "SNAPBACK_ACTION_THREAD_FAILED",
                "runtime",
                "action execution thread terminated without reporting a result",
            ))
        }
        Err(_elapsed) => {
            // Linearize timeout against the bounded commit gate, independent
            // of the global instance lock. A nested handler can be permanently
            // hung, so waiting for that lock here would defeat the watchdog.
            let gate = commit_gate.clone();
            let abandoned_for_timeout = abandoned.clone();
            let active_reservation_for_timeout = active_reservation.clone();
            tokio::task::spawn_blocking(move || {
                // Detached workers return this gate only from their final
                // precommit callback, so the sole possible owner spans an
                // already-built SQLite transaction's identity write + COMMIT,
                // never handler code, plan iteration, instance-lock waiting,
                // or realtime fan-out.
                linearize_detached_action_abandonment(
                    gate.as_ref(),
                    abandoned_for_timeout.as_ref(),
                    active_reservation_for_timeout.as_ref(),
                );
            })
            .await
            .map_err(|error| {
                SnapbackError::error(
                    "SNAPBACK_ACTION_THREAD_FAILED",
                    "runtime",
                    "action watchdog commit gate task failed",
                )
                .with_details(json!({ "error": error.to_string() }))
            })?;
            // @ref LLP 0076#settlement-and-retry — the trusted terminalizer's
            // abandonment leg: abandonment is linearized under the commit
            // gate above, so no progress commit can land after this settle
            // writes the durable winner. The hung worker's own completion
            // settle then loses the compare-and-set and observes this row —
            // which is why this leg terminalizes but does NOT release the
            // invocation's registry references; the worker's own completion
            // leg releases them once it can no longer consult the record.
            crate::stream_attempt::global_stream_attempt_registry().terminalize_invocation(
                &stream_runner,
                crate::stream_attempt::StreamAttemptCause::TimedOut,
            );

            // Hermes' own async-break deadline should already be unwinding
            // the VM. Give that bounded termination path a short grace window
            // before publishing the watchdog response. The action thread
            // sends only after destroying its runtime and decrementing the
            // worker counter, so success here proves there is no live CPU
            // worker left behind by this timeout.
            let worker_terminated = tokio::time::timeout(
                Duration::from_millis(ACTION_INTERRUPT_GRACE_MS),
                &mut receiver,
            )
            .await
            .is_ok();
            Err(SnapbackError::error(
                "SNAPBACK_ACTION_TIMEOUT",
                "runtime",
                format!(
                    "action exceeded the {timeout_ms}ms wall-clock watchdog and was abandoned; \
                     mutations it committed before the timeout remain committed"
                ),
            )
            .with_details(json!({
                "timeoutMs": timeout_ms,
                "workerTerminated": worker_terminated,
            })))
        }
    }
}

/// Execute a bounded HostPlan action without retaining `LocalSnapback` across
/// room-authority quiescence. Each `RunMutation` gets its own exact preview,
/// reservation, and commit; earlier successful steps remain committed if a
/// later step fails, matching the ordinary non-transactional action model.
/// The owned task preserves the historical in-lock behavior that request
/// cancellation cannot abandon the remaining bounded steps halfway through.
///
/// @ref LLP 0059#authorization-write-handoff — action granularity is one
///   exact reservation per `RunMutation`, never one widened outer reservation.
async fn run_managed_host_plan_action(
    state: &SharedSnapback,
    name: String,
    input: HandlerInput,
    metadata: CronRunMetadata,
    prepared: crate::auth::invocation::PreparedInvocation,
) -> SnapbackResult<Value> {
    let state = state.clone();
    tokio::spawn(async move {
        let stage_name = name.clone();
        let action = with_snapback(&state, move |snapback| {
            snapback.stage_managed_host_plan_action(&stage_name, input, metadata, prepared)
        })
        .await?;

        let mut bindings = BTreeMap::new();
        let mut last_result = Value::Null;
        let mut changed_count = 0usize;
        let steps = action.plan.steps.clone();
        let execution = async {
            for step in steps {
                action.validate_generation()?;
                let stage_action = action.clone();
                let stage_step = step.clone();
                let stage_bindings = bindings.clone();
                let committed = with_snapback_staged_authorization_write(
                    &state,
                    None,
                    move |snapback| {
                        snapback.stage_managed_host_plan_action_step(
                            &stage_action,
                            &stage_step,
                            &stage_bindings,
                        )
                    },
                    move |snapback, staged| {
                        snapback.commit_staged_recorded_authorization_mutation(staged)
                    },
                )
                .await;
                let (mutation, _receipt) = match committed {
                    Ok(committed) => committed?,
                    Err(error) => {
                        // A reload/reset may race the stage-to-commit window.
                        // Preserve the action-level generation diagnostic over
                        // the reservation protocol's generic stale carrier.
                        action.validate_generation()?;
                        return Err(error);
                    }
                };
                let output = mutation?;
                changed_count += output.changed_count;
                last_result = output.result;
                let ActionStep::RunMutation { bind_result_as, .. } = step;
                if let Some(binding) = bind_result_as {
                    bindings.insert(binding, last_result.clone());
                }
            }

            match &action.plan.return_value {
                Some(ActionReturnValue::Literal(value)) => Ok(value.clone()),
                Some(ActionReturnValue::Binding(name)) => {
                    bindings.get(name).cloned().ok_or_else(|| {
                        SnapbackError::error(
                            "SNAPBACK_BINDING_MISSING",
                            "runtime",
                            format!("action binding {name} was not available"),
                        )
                    })
                }
                Some(ActionReturnValue::ChangedCount) => Ok(json!(changed_count)),
                Some(ActionReturnValue::LastMutationResult) | None => Ok(last_result),
            }
        }
        .await;
        action.finish(execution)
    })
    .await
    .map_err(|error| {
        SnapbackError::error(
            "SNAPBACK_ACTION_THREAD_FAILED",
            "runtime",
            "managed host-plan action task terminated without reporting a result",
        )
        .with_details(json!({ "error": error.to_string() }))
    })?
}

/// Execute a staged app/admin action and shape the run-result envelope.
/// `metadata_prefix` names the triggering surface (`action` for the app-data
/// route, `admin` for the function runner).
pub(crate) async fn run_staged_app_action(
    state: &SharedSnapback,
    name: &str,
    input: HandlerInput,
    stage: AppActionStage,
    metadata_prefix: &str,
) -> FunctionRunResult {
    let started = Instant::now();
    let metadata = crate::local::manual_action_metadata(metadata_prefix, name);
    let result = match stage.mode {
        StagedAction::HostPlan(prepared) => {
            run_managed_host_plan_action(state, name.to_owned(), input, metadata, prepared).await
        }
        StagedAction::Detached(action) => {
            run_detached_ibex_action(state, action, input, metadata).await
        }
    };
    crate::local::action_run_result(
        name,
        stage.reads,
        stage.writes,
        started.elapsed().as_millis() as u64,
        result,
    )
}

/// One cron tick in the detached flow: claim due runs under the lock, execute
/// each claim off the lock (watchdogged for Ibex actions), finish each claim
/// back under the lock (ENG-23324).
pub(crate) async fn cron_tick_detached(
    state: &SharedSnapback,
    now_ms: u64,
) -> SnapbackResult<Vec<CronRunRecord>> {
    let claims = with_snapback(state, move |snapback| snapback.claim_due_cron_runs(now_ms)).await?;
    // Independent jobs must not head-of-line block one another, but dispatch
    // remains bounded separately from the process-wide worker admission cap.
    // Preserve claim order in the returned test/admin envelope even though
    // execution finishes out of order.
    let mut completed =
        futures_util::stream::iter(claims.into_iter().enumerate().map(|(index, claim)| {
            let state = state.clone();
            async move { (index, execute_cron_claim_detached(&state, claim).await) }
        }))
        .buffer_unordered(configured_cron_dispatch_concurrency(
            std::env::var("SNAPBACK_CRON_DISPATCH_CONCURRENCY")
                .ok()
                .as_deref(),
        ))
        .collect::<Vec<_>>()
        .await;
    completed.sort_by_key(|(index, _)| *index);
    let mut records = Vec::with_capacity(completed.len());
    for (_, result) in completed {
        records.push(result?);
    }
    Ok(records)
}

/// Claim one scheduler tick and hand each run to the process-wide bounded
/// cron dispatcher. This returns after dispatch, not after handler completion,
/// so `overlap: allow` can claim a later due slot while an earlier run is
/// still executing. Saturation becomes a recorded run outcome instead of an
/// unbounded task queue.
async fn dispatch_cron_tick_background(
    state: &SharedSnapback,
    dispatcher: &Arc<Semaphore>,
    dispatcher_limit: usize,
    now_ms: u64,
) -> SnapbackResult<usize> {
    let claims = with_snapback(state, move |snapback| snapback.claim_due_cron_runs(now_ms)).await?;
    let mut dispatched = 0;
    for claim in claims {
        match dispatcher.clone().try_acquire_owned() {
            Ok(permit) => {
                dispatched += 1;
                let state = state.clone();
                tokio::spawn(async move {
                    let _permit = permit;
                    if let Err(error) = execute_cron_claim_detached(&state, claim).await {
                        state.lock().await.record_cron_tick_error(
                            error,
                            crate::local::DiagnosticBoundary::Attached,
                        );
                    }
                });
            }
            Err(_) => {
                let started_wall_ms = now_millis();
                let job_name = claim.job.name.clone();
                let finish = with_snapback(state, move |snapback| {
                    snapback.finish_cron_claim(
                        claim,
                        started_wall_ms,
                        Err(Diagnostic::error(
                            "SNAPBACK_CRON_DISPATCH_CAPACITY_EXCEEDED",
                            "cron",
                            format!(
                                "cron job {job_name} could not start because every bounded dispatcher slot is busy"
                            ),
                        )
                        .with_details(json!({
                            "dispatcherLimit": dispatcher_limit,
                            "availableSlots": 0,
                        }))),
                    )
                })
                .await;
                // Every claim was already persisted as active. A failure to
                // persist this capacity outcome must not abandon later claims
                // in the batch; record it and continue draining ownership.
                if let Err(error) = finish {
                    state
                        .lock()
                        .await
                        .record_cron_tick_error(error, crate::local::DiagnosticBoundary::Attached);
                }
            }
        }
    }
    Ok(dispatched)
}

/// Execute one claimed cron run without holding the global mutex across the
/// action, then finish the claim.
pub(crate) async fn execute_cron_claim_detached(
    state: &SharedSnapback,
    claim: AdmittedCronClaim,
) -> SnapbackResult<CronRunRecord> {
    let started_wall_ms = now_millis();
    let input = crate::local::cron_claim_input(&claim);
    let metadata = claim.metadata.clone();
    let action = claim.job.action.clone();
    let staged = {
        let action = action.clone();
        let admission = claim.admission_lease().clone();
        with_snapback(state, move |snapback| {
            snapback.stage_action_invocation_with_admission(&action, admission)
        })
        .await
    };
    let result = match staged {
        Ok(StagedAction::Detached(action)) => {
            run_detached_ibex_action(state, action, input, metadata).await
        }
        Ok(StagedAction::HostPlan(prepared)) => {
            run_managed_host_plan_action(state, action, input, metadata, prepared).await
        }
        Err(error) => Err(error),
    }
    .map_err(|error| error.diagnostic);
    with_snapback(state, move |snapback| {
        snapback.finish_cron_claim(claim, started_wall_ms, result)
    })
    .await
}

/// One injected-clock jobs drain (LLP 0115 CV-9's deterministic seam; sibling
/// of [`cron_tick_detached`] but set-based per LLP 0121): claim every due job
/// at `now_ms` under the lock, execute each claim off the lock, publish each
/// terminal transition back under the lock, and repeat for cascading enqueues
/// up to `max_waves` bounded waves (LLP 0121 open question 5's drain
/// semantics, decided: bounded waves, never run-to-quiescence). Returns the
/// synchronous drain receipts in claim order.
pub(crate) async fn jobs_drain_detached(
    state: &SharedSnapback,
    now_ms: u64,
    max_waves: usize,
    diagnostic_boundary: crate::local::DiagnosticBoundary,
) -> SnapbackResult<Vec<crate::jobs::JobDrainRecord>> {
    let mut records = Vec::new();
    let waves = max_waves.clamp(1, crate::jobs::JOBS_DRAIN_MAX_WAVES);
    for _ in 0..waves {
        let claims = match with_snapback(state, move |snapback| {
            snapback.claim_due_jobs(
                now_ms,
                crate::jobs::JOBS_CLAIM_BATCH,
                "forced-drain",
                diagnostic_boundary,
            )
        })
        .await
        {
            Ok(claims) => claims,
            Err(error) => {
                state
                    .lock()
                    .await
                    .record_cron_tick_error(error.clone(), diagnostic_boundary);
                return Err(error);
            }
        };
        if claims.is_empty() {
            break;
        }
        let mut completed =
            futures_util::stream::iter(claims.into_iter().enumerate().map(|(index, claim)| {
                let state = state.clone();
                async move { (index, execute_job_claim_detached(&state, claim).await) }
            }))
            .buffer_unordered(configured_cron_dispatch_concurrency(
                std::env::var("SNAPBACK_CRON_DISPATCH_CONCURRENCY")
                    .ok()
                    .as_deref(),
            ))
            .collect::<Vec<_>>()
            .await;
        completed.sort_by_key(|(index, _)| *index);
        for (_, result) in completed {
            match result {
                Ok(record) => records.push(record),
                Err(error) => {
                    state.lock().await.record_cron_tick_error(
                        error.clone(),
                        crate::local::DiagnosticBoundary::Attached,
                    );
                    return Err(error);
                }
            }
        }
    }
    Ok(records)
}

/// Execute one claimed job without holding the global mutex across the
/// action, then publish its terminal outcome — the jobs sibling of
/// [`execute_cron_claim_detached`]. The callee runs with the job's immutable
/// validated args under the same staged action machinery cron uses (LLP 0070
/// v1 host-plan-envelope admission; both action tiers).
pub(crate) async fn execute_job_claim_detached(
    state: &SharedSnapback,
    claim: crate::local::AdmittedJobClaim,
) -> SnapbackResult<crate::jobs::JobDrainRecord> {
    if claim.action == crate::watches::INTERNAL_EVALUATION_ACTION {
        let attempt = claim.attempt;
        let max_attempts = claim.max_attempts;
        let context = claim.watch_context();
        let prepared =
            with_snapback(state, move |snapback| snapback.prepare_watch_job(context)).await;
        let result = match prepared {
            Ok(crate::local::WatchJobExecution::Complete(value)) => Ok(value),
            Ok(crate::local::WatchJobExecution::Action(prepared)) => {
                let crate::local::PreparedWatchAction {
                    watch_id,
                    job_id,
                    ordinal,
                    owner_principal_id,
                    action,
                    input,
                    metadata,
                    staged,
                } = prepared;
                let reaction = match staged {
                    StagedAction::Detached(action) => {
                        run_detached_ibex_action(state, action, input, metadata).await
                    }
                    StagedAction::HostPlan(prepared) => {
                        run_managed_host_plan_action(state, action, input, metadata, prepared).await
                    }
                };
                let now_ms = claim.drain_now_ms;
                with_snapback(state, move |snapback| {
                    snapback.settle_watch_action(
                        watch_id,
                        job_id,
                        ordinal,
                        owner_principal_id,
                        &reaction,
                        attempt,
                        max_attempts,
                        now_ms,
                    )
                })
                .await
            }
            Ok(crate::local::WatchJobExecution::Webhook(prepared)) => {
                let recheck = prepared.clone();
                let delivery = with_snapback(state, move |snapback| {
                    snapback.revalidate_watch_webhook_delivery(&recheck, claim.drain_now_ms)
                })
                .await;
                let outcome = match delivery {
                    Ok(delivery) => {
                        tokio::task::spawn_blocking(move || crate::webhooks::deliver(delivery))
                            .await
                            .unwrap_or(crate::webhooks::DeliveryOutcome::Retryable {
                                code: "SNAPBACK_WEBHOOK_DELIVERY_RETRYABLE",
                                http_status: None,
                            })
                    }
                    Err(error)
                        if matches!(
                            error.diagnostic.code.as_str(),
                            "SNAPBACK_WEBHOOK_TARGET_UNAVAILABLE"
                                | "SNAPBACK_WEBHOOK_SECRET_UNAVAILABLE"
                        ) =>
                    {
                        crate::webhooks::DeliveryOutcome::Retryable {
                            code: if error.diagnostic.code == "SNAPBACK_WEBHOOK_SECRET_UNAVAILABLE"
                            {
                                "SNAPBACK_WEBHOOK_SECRET_UNAVAILABLE"
                            } else {
                                "SNAPBACK_WEBHOOK_TARGET_UNAVAILABLE"
                            },
                            http_status: None,
                        }
                    }
                    Err(error) => crate::webhooks::DeliveryOutcome::Permanent {
                        code: match error.diagnostic.code.as_str() {
                            "SNAPBACK_WATCH_AUTHORITY_DEAD" => "SNAPBACK_WATCH_AUTHORITY_DEAD",
                            "SNAPBACK_WEBHOOK_SSRF_REFUSED" => "SNAPBACK_WEBHOOK_SSRF_REFUSED",
                            _ => "SNAPBACK_WEBHOOK_DELIVERY_INVALID",
                        },
                        http_status: None,
                    },
                };
                with_snapback(state, move |snapback| {
                    snapback.settle_watch_webhook(
                        prepared,
                        outcome,
                        attempt,
                        max_attempts,
                        claim.drain_now_ms,
                    )
                })
                .await
            }
            Err(error) => Err(error),
        }
        .map_err(|error| error.diagnostic);
        return with_snapback(state, move |snapback| {
            snapback.finish_job_claim(claim, result)
        })
        .await;
    }
    let input = LocalSnapback::job_claim_input(&claim);
    let metadata = LocalSnapback::job_claim_metadata(&claim);
    let action = claim.action.clone();
    let deferred_push_grant = claim.push_grant.clone();
    let rehearsal_provenance = claim.rehearsal_provenance.clone();
    let staged = {
        let action = action.clone();
        let admission = claim.admission_lease().clone();
        with_snapback(state, move |snapback| {
            snapback.stage_job_action_invocation_with_admission(
                &action,
                admission,
                deferred_push_grant,
                rehearsal_provenance,
            )
        })
        .await
    };
    let result = match staged {
        Ok(StagedAction::Detached(action)) => {
            run_detached_ibex_action(state, action, input, metadata).await
        }
        Ok(StagedAction::HostPlan(prepared)) => {
            run_managed_host_plan_action(state, action, input, metadata, prepared).await
        }
        Err(error) => Err(error),
    }
    .map_err(|error| error.diagnostic);
    with_snapback(state, move |snapback| {
        snapback.finish_job_claim(claim, result)
    })
    .await
}

/// The autonomous jobs worker: the existing one-second scheduler loop reused
/// as the wakeup over the durable job table (LLP 0121 option 2 case 3 — the
/// ticker is a wakeup; the job/attempt rows stay the only evidence).
/// `SNAPBACK_JOBS_DISABLED` idles it (the sibling of `SNAPBACK_CRON_DISABLED`,
/// deliberately a separate flag: cron and jobs are separate subsystems with
/// separate ledgers), leaving the admin forced drain as the only driver —
/// which is how deterministic acceptance runs.
pub fn spawn_jobs_worker(state: SharedSnapback, autonomy_disabled: bool) -> JoinHandle<()> {
    tokio::spawn(async move {
        if autonomy_disabled {
            return;
        }
        // The durable queue initializes this hint at open and every committed
        // enqueue arms it. An empty instance therefore pays only this atomic
        // load per tick, not a SQLite transaction and file-lock round trip.
        //
        // @ref LLP 0032#phase-3--lifecycle-and-resource-hardening — L5: idle
        // means idle across cron and one-off job schedulers.
        let jobs_active = state.lock().await.jobs_activity_flag();
        let mut ticks = interval(Duration::from_secs(1));
        // First tick resolves immediately. Startup hydration arms the hint
        // when pending/claimed rows survived the last shutdown, so it also
        // doubles as the recovery sweep for a non-empty durable queue.
        loop {
            ticks.tick().await;
            if !jobs_active.load(std::sync::atomic::Ordering::Relaxed) {
                continue;
            }
            // The flag is only a wakeup hint; durable rows remain authority.
            // Refresh under the Local lock so a concurrent enqueue cannot be
            // lost between the count and clearing the flag.
            let pending =
                match with_snapback(&state, |snapback| snapback.refresh_jobs_activity()).await {
                    Ok(pending) => pending,
                    Err(error) => {
                        state.lock().await.record_cron_tick_error(
                            error,
                            crate::local::DiagnosticBoundary::Standalone,
                        );
                        continue;
                    }
                };
            if pending == 0 {
                continue;
            }
            let now = now_millis();
            let _ =
                jobs_drain_detached(&state, now, 1, crate::local::DiagnosticBoundary::Standalone)
                    .await;
        }
    })
}

/// Parse the `SNAPBACK_JOBS_DISABLED` switch with the same vocabulary as
/// [`cron_autonomy_disabled`].
pub fn jobs_autonomy_disabled(value: Option<&str>) -> bool {
    matches!(
        value.map(str::trim).map(str::to_ascii_lowercase).as_deref(),
        Some("1") | Some("true")
    )
}

type ConnectionRetirementSink = Arc<dyn Fn(BoundConnectionTerminalCapture) + Send + Sync + 'static>;

/// Transport-level connection grants (ENG-23442). Connection ids used to be
/// caller-chosen bearerless capabilities: knowledge of an id alone was enough
/// to drain `/outbox/{id}` or attach `/live/{id}/stream` and read another
/// client's queued live results. Connections are now opened through
/// `POST /connection/open`, which returns the connection id paired with a
/// server-minted `connectionToken`; every connection-scoped operation must
/// present that token. A grant normally survives socket close so the kit can
/// reconnect. The registry itself is fixed-cap: unopened/unused grants are
/// evicted first; used grants become evictable only after an idle lease. If
/// every grant is both used and current, admission refuses transiently rather
/// than displacing live authority. Once a used id is retired under pressure,
/// caller-suggested ids stay disabled for this process so stale room/outbox
/// state can never be adopted by a new bearer; the client receives a fresh
/// minted id instead.
///
/// @ref LLP 0031#connection-capability-grants — server-issued grants; the
/// ConnectionAuth policy class marks every route this gate covers.
/// @ref LLP 0053#invalidation-is-an-obligation-not-a-message — the exact-v1
/// offer binds a never-reused issuer and connection generation into the grant.
#[derive(Clone, Default)]
pub struct ConnectionRegistry {
    grants: Arc<std::sync::Mutex<ConnectionRegistryState>>,
    invalidation_issuer:
        Arc<std::sync::Mutex<Option<crate::auth::invalidation::LiveInvalidationIssuer>>>,
    retirement_sink: Arc<std::sync::Mutex<Option<ConnectionRetirementSink>>>,
}

#[derive(Default)]
struct ConnectionRegistryState {
    grants: std::collections::HashMap<String, ConnectionGrantRecord>,
    unused: std::collections::BTreeSet<(u64, String)>,
    used: std::collections::BTreeSet<(u64, String)>,
    anonymous_grants: std::collections::HashMap<String, std::collections::BTreeSet<String>>,
    session_grants: std::collections::HashMap<BoundSessionKey, std::collections::BTreeSet<String>>,
    service_token_grants: std::collections::HashMap<String, std::collections::BTreeSet<String>>,
    anonymous_open_attempts: std::collections::HashMap<String, std::collections::VecDeque<Instant>>,
    unknown_open_attempts: std::collections::HashMap<String, std::collections::VecDeque<Instant>>,
    session_open_attempts:
        std::collections::HashMap<BoundSessionKey, std::collections::VecDeque<Instant>>,
    service_open_attempts: std::collections::HashMap<[u8; 32], std::collections::VecDeque<Instant>>,
    agent_route_attempts:
        std::collections::HashMap<AgentRouteThrottleKey, std::collections::VecDeque<Instant>>,
    external_api_attempts:
        std::collections::HashMap<ExternalApiThrottleKey, std::collections::VecDeque<Instant>>,
    pressure_mint_only: bool,
}

#[derive(Clone, Debug, Eq, Hash, PartialEq)]
struct AgentRouteThrottleKey {
    path: &'static str,
    source: AgentRouteThrottleSource,
}

#[derive(Clone, Debug, Eq, Hash, PartialEq)]
#[allow(dead_code)] // Declared/integration arms are shared vocabulary for the data-plane sibling.
enum AgentRouteThrottleSource {
    Session(String),
    Credential([u8; 32]),
    Declared([u8; 32]),
    Integration(String),
    Malformed,
}

#[derive(Clone, Debug, Eq, Hash, PartialEq)]
struct ExternalApiThrottleKey {
    route_family: &'static str,
    source: ExternalApiThrottleSource,
}

#[derive(Clone, Debug, Eq, Hash, PartialEq)]
enum ExternalApiThrottleSource {
    NetworkFloor([u8; 32]),
    DeclaredCreation([u8; 32]),
    Declared([u8; 32]),
    Integration(String),
    Link(String),
    OverflowNetworkFloor,
    OverflowDeclaredCreation,
    OverflowDeclared,
    OverflowIntegration,
    OverflowLink,
}

impl ExternalApiThrottleSource {
    fn overflow(&self) -> (Self, usize) {
        match self {
            Self::NetworkFloor(_) | Self::OverflowNetworkFloor => (
                Self::OverflowNetworkFloor,
                EXTERNAL_API_ANONYMOUS_FLOOR_LIMIT,
            ),
            Self::DeclaredCreation(_) | Self::OverflowDeclaredCreation => (
                Self::OverflowDeclaredCreation,
                EXTERNAL_API_DECLARED_CREATION_LIMIT,
            ),
            Self::Declared(_) | Self::OverflowDeclared => {
                (Self::OverflowDeclared, EXTERNAL_API_DECLARED_LIMIT)
            }
            Self::Integration(_) | Self::OverflowIntegration => {
                (Self::OverflowIntegration, EXTERNAL_API_INTEGRATION_LIMIT)
            }
            Self::Link(_) | Self::OverflowLink => {
                (Self::OverflowLink, EXTERNAL_API_CAPABILITY_LINK_LIMIT)
            }
        }
    }
}

struct ConnectionGrantRecord {
    grant_id: String,
    token: String,
    last_use_ms: u64,
    used: bool,
    /// Exact socket generation currently performing split teardown. While
    /// present, connection acts and replacement socket registration refuse;
    /// ordinary close still preserves the reusable grant itself.
    socket_teardown: Option<u64>,
    managed_authority: bool,
    authority: BoundGrantAuthority,
    hosted_sender: Option<HostedSenderGrantBinding>,
    authorization_invalidation:
        Option<crate::auth::invalidation::AuthorizationInvalidationConnection>,
    /// The lineage's explicit wire-version binding: `Some(token)` when the
    /// first open carried a known offer, `None` for a legacy (offerless-open)
    /// lineage. Fixed at first open; no re-open changes it.
    ///
    /// @ref LLP 0094#0b3-the-wireversion-open-time-offer — binding is once,
    ///   at open, and immutable for the grant lineage; legacy is implicitly
    ///   v1 for the equality rules but never upgraded in place.
    wire_version: Option<String>,
    ephemeral_authority_protocol: Option<u32>,
    ephemeral_authority_instance: Option<String>,
    /// Immutable lineage fact: true only when the first open crossed a
    /// current authenticated single-instance hosted admission. A required
    /// lineage can never use the local `(None, None)` compatibility case.
    ///
    /// @ref LLP 0094#hosted-ephemeral-per-boundary-contract — hosted
    ///   admission makes protocol 1 plus the exact authority instance
    ///   mandatory on open, reopen, HTTP operations, and socket upgrade.
    hosted_ephemeral_authority_required: bool,
    ephemeral_expiry_protocol: Option<u32>,
}

/// The sender half of a `BoundGrantAuthorityV2` session grant: the custody
/// key's JWK thumbprint plus the durable `sender_replay_epoch` current at
/// issuance. Equality is exact-tuple; the grant invalidates when the epoch
/// advances past its issuance value.
///
/// @ref LLP 0059#boundgrantauthorityv2--sender-bound-grants-amendment-2026-07-23
/// — the registry-side V2 shape (thumbprint + issuance epoch, deadline
/// excluded from identity).
#[derive(Clone, Eq, PartialEq)]
struct HostedSenderGrantBinding {
    jwk_thumbprint: String,
    sender_replay_epoch_at_issuance: u64,
}

impl std::fmt::Debug for HostedSenderGrantBinding {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter.write_str("HostedSenderGrantBinding([REDACTED])")
    }
}

#[derive(Clone, Debug, Eq, Hash, PartialEq)]
struct BoundSessionKey {
    authorization_stream_incarnation: String,
    session_id: String,
    generation: u64,
}

impl From<ConnectionSessionThrottleKey> for BoundSessionKey {
    fn from(value: ConnectionSessionThrottleKey) -> Self {
        Self {
            authorization_stream_incarnation: value.authorization_stream_incarnation,
            session_id: value.session_id,
            generation: value.generation,
        }
    }
}

#[derive(Clone)]
enum BoundGrantAuthority {
    Anonymous {
        authorization_stream_incarnation: String,
        publication: FencedPublication,
    },
    Session {
        authorization_stream_incarnation: String,
        session_id: String,
        user_id: String,
        provider: String,
        generation: u64,
        deadline_ms: u64,
        publication: FencedPublication,
    },
    /// A scoped-token carrier. Durable authority is retained separately from
    /// the exact token and connection grant so routine token churn does not
    /// change queued-work ownership while ending this carrier purges only its
    /// own live effects.
    ///
    /// @ref LLP 0055#grant-backed-live-and-queued-replay — grant-backed live
    ///   uses durable and carrier axes with exact-token terminal propagation.
    ServicePrincipal {
        authorization_stream_incarnation: String,
        authority: ResolvedAppAuthority,
        token_id: String,
        deadline_ms: u64,
        publication: FencedPublication,
        service_publication: ServiceAuthorityPublication,
    },
}

impl std::fmt::Debug for BoundGrantAuthority {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Anonymous {
                authorization_stream_incarnation,
                ..
            } => formatter
                .debug_struct("BoundGrantAuthority::Anonymous")
                .field(
                    "authorization_stream_incarnation",
                    authorization_stream_incarnation,
                )
                .finish(),
            Self::Session {
                authorization_stream_incarnation,
                session_id,
                user_id,
                provider,
                generation,
                deadline_ms,
                ..
            } => formatter
                .debug_struct("BoundGrantAuthority::Session")
                .field(
                    "authorization_stream_incarnation",
                    authorization_stream_incarnation,
                )
                .field("session_id", session_id)
                .field("user_id", user_id)
                .field("provider", provider)
                .field("generation", generation)
                .field("deadline_ms", deadline_ms)
                .finish(),
            Self::ServicePrincipal {
                authorization_stream_incarnation,
                token_id,
                deadline_ms,
                ..
            } => formatter
                .debug_struct("BoundGrantAuthority::ServicePrincipal")
                .field(
                    "authorization_stream_incarnation",
                    authorization_stream_incarnation,
                )
                .field("token_id", token_id)
                .field("deadline_ms", deadline_ms)
                .finish_non_exhaustive(),
        }
    }
}

impl BoundGrantAuthority {
    fn authorization_stream_incarnation(&self) -> &str {
        match self {
            Self::Anonymous {
                authorization_stream_incarnation,
                ..
            }
            | Self::Session {
                authorization_stream_incarnation,
                ..
            }
            | Self::ServicePrincipal {
                authorization_stream_incarnation,
                ..
            } => authorization_stream_incarnation,
        }
    }

    fn publication(&self) -> &FencedPublication {
        match self {
            Self::Anonymous { publication, .. }
            | Self::Session { publication, .. }
            | Self::ServicePrincipal { publication, .. } => publication,
        }
    }

    fn service_publication(&self) -> Option<&ServiceAuthorityPublication> {
        match self {
            Self::ServicePrincipal {
                service_publication,
                ..
            } => Some(service_publication),
            Self::Anonymous { .. } | Self::Session { .. } => None,
        }
    }

    fn try_publish<T>(
        &self,
        epoch_now_ms: u64,
        monotonic_now: Instant,
        publish: impl FnOnce() -> SnapbackResult<T>,
    ) -> SnapbackResult<Option<T>> {
        let nested = self
            .publication()
            .try_publish(epoch_now_ms, monotonic_now, || {
                match self.service_publication() {
                    Some(service) => service.try_publish(epoch_now_ms, monotonic_now, publish),
                    None => publish().map(Some),
                }
            })?;
        Ok(nested.flatten())
    }

    fn effect_fence(&self, grant_id: &str) -> crate::ephemeral::ConnectionEffectFence {
        match self {
            Self::Anonymous {
                authorization_stream_incarnation,
                ..
            } => crate::ephemeral::ConnectionEffectFence::anonymous(
                authorization_stream_incarnation.clone(),
                grant_id.to_owned(),
            ),
            Self::Session {
                authorization_stream_incarnation,
                session_id,
                generation,
                ..
            } => crate::ephemeral::ConnectionEffectFence::session(
                authorization_stream_incarnation.clone(),
                grant_id.to_owned(),
                session_id.clone(),
                *generation,
            ),
            Self::ServicePrincipal {
                authorization_stream_incarnation,
                token_id,
                ..
            } => crate::ephemeral::ConnectionEffectFence::service_principal(
                authorization_stream_incarnation.clone(),
                grant_id.to_owned(),
                token_id.clone(),
            ),
        }
    }

    fn reverse_key(&self) -> GrantReverseKey {
        match self {
            Self::Anonymous {
                authorization_stream_incarnation,
                ..
            } => GrantReverseKey::Anonymous(authorization_stream_incarnation.clone()),
            Self::Session {
                authorization_stream_incarnation,
                session_id,
                generation,
                ..
            } => GrantReverseKey::Session(BoundSessionKey {
                authorization_stream_incarnation: authorization_stream_incarnation.clone(),
                session_id: session_id.clone(),
                generation: *generation,
            }),
            Self::ServicePrincipal { token_id, .. } => {
                GrantReverseKey::ServiceToken(token_id.clone())
            }
        }
    }

    fn same_identity(&self, other: &Self) -> bool {
        match (self, other) {
            (
                Self::Anonymous {
                    authorization_stream_incarnation: left,
                    ..
                },
                Self::Anonymous {
                    authorization_stream_incarnation: right,
                    ..
                },
            ) => left == right,
            (
                Self::Session {
                    authorization_stream_incarnation: left_incarnation,
                    session_id: left_session,
                    user_id: left_user,
                    provider: left_provider,
                    generation: left_generation,
                    ..
                },
                Self::Session {
                    authorization_stream_incarnation: right_incarnation,
                    session_id: right_session,
                    user_id: right_user,
                    provider: right_provider,
                    generation: right_generation,
                    ..
                },
            ) => {
                left_incarnation == right_incarnation
                    && left_session == right_session
                    && left_user == right_user
                    && left_provider == right_provider
                    && left_generation == right_generation
            }
            (
                Self::ServicePrincipal {
                    authorization_stream_incarnation: left_incarnation,
                    authority: left_authority,
                    token_id: left_token,
                    ..
                },
                Self::ServicePrincipal {
                    authorization_stream_incarnation: right_incarnation,
                    authority: right_authority,
                    token_id: right_token,
                    ..
                },
            ) => {
                left_incarnation == right_incarnation
                    && left_authority == right_authority
                    && left_token == right_token
            }
            _ => false,
        }
    }

    fn stale_error_at(&self, epoch_now_ms: u64) -> SnapbackError {
        match self {
            Self::Anonymous { .. } => {
                // Anonymous authority is re-established by a fresh handshake,
                // so clients racing the boot-provision reset window may retry
                // this stream-replacement refusal (issues/20260807-auth-stream-reset-boot-flake.md).
                // @ref LLP 0059#reset-restore-and-stream-publication — refusal stands; the typed hint only marks anonymous re-establishment as safe.
                SnapbackError::error(
                    "SNAPBACK_AUTH_STREAM_RESET",
                    "auth",
                    "the connection authorization stream is no longer current",
                )
                .with_details(json!({
                    "authorityDisposition": "carrier",
                    "retryable": true,
                    "cause": "stream_replaced"
                }))
            }
            Self::Session { publication, .. } => {
                let disposition = publication
                    .session_terminal_reason(epoch_now_ms, Instant::now())
                    .ok()
                    .flatten()
                    .map(session_http_authority_disposition)
                    .unwrap_or(HttpAuthorityDisposition::Carrier);
                session_expired_http("the connection session is no longer current", disposition)
            }
            Self::ServicePrincipal {
                service_publication,
                ..
            } => {
                let disposition =
                    match service_publication.terminal_disposition(epoch_now_ms, Instant::now()) {
                        ServiceAuthorityDisposition::Carrier => HttpAuthorityDisposition::Carrier,
                        ServiceAuthorityDisposition::DurableDelete => {
                            HttpAuthorityDisposition::DurableDelete
                        }
                    };
                scoped_token_invalid_http(
                    "the connection scoped token authority is no longer current",
                    disposition,
                )
            }
        }
    }

    fn terminal_capture(
        &self,
        connection_id: String,
        grant_id: String,
    ) -> BoundConnectionTerminalCapture {
        match self {
            Self::Anonymous {
                authorization_stream_incarnation,
                ..
            } => BoundConnectionTerminalCapture {
                connection_id,
                grant_id,
                authorization_stream_incarnation: authorization_stream_incarnation.clone(),
                session_id: None,
                generation: None,
                service_token_id: None,
                whole_id_cleanup_safe: false,
            },
            Self::Session {
                authorization_stream_incarnation,
                session_id,
                generation,
                ..
            } => BoundConnectionTerminalCapture {
                connection_id,
                grant_id,
                authorization_stream_incarnation: authorization_stream_incarnation.clone(),
                session_id: Some(session_id.clone()),
                generation: Some(*generation),
                service_token_id: None,
                whole_id_cleanup_safe: false,
            },
            Self::ServicePrincipal {
                authorization_stream_incarnation,
                token_id,
                ..
            } => BoundConnectionTerminalCapture {
                connection_id,
                grant_id,
                authorization_stream_incarnation: authorization_stream_incarnation.clone(),
                session_id: None,
                generation: None,
                service_token_id: Some(token_id.clone()),
                whole_id_cleanup_safe: false,
            },
        }
    }
}

enum GrantReverseKey {
    Anonymous(String),
    Session(BoundSessionKey),
    ServiceToken(String),
}

enum ResolvedRoomConnectionAuthority {
    Absent,
    Current {
        auth: Option<AuthContext>,
        effect_fence: crate::ephemeral::ConnectionEffectFence,
    },
    Replaced,
}

#[derive(Clone, Debug)]
struct PreparedConnectionOpenAuthority {
    resolved: ResolvedAppAuthority,
    bound: BoundGrantAuthority,
    managed_authority: bool,
    hosted_sender: Option<HostedSenderGrantBinding>,
}

struct ConnectionOpenAttempt<'a> {
    suggested: Option<String>,
    previous_token: Option<&'a str>,
    allow_suggested: bool,
    prepared: PreparedConnectionOpenAuthority,
    now_ms: u64,
    monotonic_now: Instant,
    auth_invalidation_protocol: Option<u32>,
    /// A validated *known* wire-version offer (the handler refuses unknown
    /// tokens before the registry runs, preserving §0B.3's
    /// classification-before-equality precedence). `None` = offerless.
    wire_version_offer: Option<String>,
    ephemeral_authority_protocol: Option<u32>,
    ephemeral_authority_instance: Option<String>,
    hosted_ephemeral_authority_required: bool,
    ephemeral_expiry_protocol: Option<u32>,
    admission: Option<&'a AdmissionLease>,
}

impl<'a> ConnectionOpenAttempt<'a> {
    fn new(
        suggested: Option<String>,
        previous_token: Option<&'a str>,
        allow_suggested: bool,
        prepared: PreparedConnectionOpenAuthority,
        now_ms: u64,
        monotonic_now: Instant,
        auth_invalidation_protocol: Option<u32>,
    ) -> Self {
        Self {
            suggested,
            previous_token,
            allow_suggested,
            prepared,
            now_ms,
            monotonic_now,
            auth_invalidation_protocol,
            wire_version_offer: None,
            ephemeral_authority_protocol: None,
            ephemeral_authority_instance: None,
            hosted_ephemeral_authority_required: false,
            ephemeral_expiry_protocol: None,
            admission: None,
        }
    }

    fn with_admission(mut self, admission: &'a AdmissionLease) -> Self {
        self.admission = Some(admission);
        self
    }

    /// Attach a validated known wire-version offer (LLP 0094 §0B.3). Callers
    /// that never offer (in-crate embeddings, the bundle mint) stay legacy.
    fn with_wire_version(mut self, wire_version_offer: Option<String>) -> Self {
        self.wire_version_offer = wire_version_offer;
        self
    }

    fn with_ephemeral_authority_protocol(mut self, protocol: Option<u32>) -> Self {
        self.ephemeral_authority_protocol = protocol;
        self
    }

    fn with_ephemeral_authority_instance(mut self, instance: Option<String>) -> Self {
        self.ephemeral_authority_instance = instance;
        self
    }

    fn with_hosted_ephemeral_authority_required(mut self, required: bool) -> Self {
        self.hosted_ephemeral_authority_required = required;
        self
    }

    fn with_ephemeral_expiry_protocol(mut self, protocol: Option<u32>) -> Self {
        self.ephemeral_expiry_protocol = protocol;
        self
    }
}

#[derive(Clone, Debug)]
struct OpenedConnectionGrant {
    grant: ConnectionGrant,
    grant_id: String,
    newly_minted: bool,
}

#[derive(Clone, Debug)]
struct PreparedConnectionAct {
    connection_id: String,
    grant_id: String,
    resolved: ResolvedAppAuthority,
    bound: BoundGrantAuthority,
    authorization_invalidation:
        Option<crate::auth::invalidation::AuthorizationInvalidationConnection>,
    ephemeral_authority_protocol: Option<u32>,
    ephemeral_authority_instance: Option<String>,
    hosted_ephemeral_authority_required: bool,
}

impl PreparedConnectionOpenAuthority {
    fn authenticated_use_key(&self) -> Option<(String, u64)> {
        match &self.bound {
            BoundGrantAuthority::Anonymous { .. }
            | BoundGrantAuthority::ServicePrincipal { .. } => None,
            BoundGrantAuthority::Session {
                session_id,
                generation,
                ..
            } => Some((session_id.clone(), *generation)),
        }
    }
}

impl PreparedConnectionAct {
    fn session_principal_id(&self) -> Option<&str> {
        match &self.bound {
            BoundGrantAuthority::Session { user_id, .. } => Some(user_id.as_str()),
            BoundGrantAuthority::Anonymous { .. }
            | BoundGrantAuthority::ServicePrincipal { .. } => None,
        }
    }

    fn verify_ephemeral_authority_instance(&self, presented: Option<&str>) -> Result<(), ApiError> {
        if self.hosted_ephemeral_authority_required
            && self.ephemeral_authority_protocol
                != Some(crate::ephemeral::EPHEMERAL_AUTHORITY_PROTOCOL_V1)
        {
            return Err(ApiError::from(SnapbackError::error(
                "SNAPBACK_EPHEMERAL_AUTHORITY_UNSUPPORTED",
                "ephemeral",
                "this hosted connection did not negotiate ephemeralAuthorityProtocol 1",
            )));
        }
        match (self.ephemeral_authority_instance.as_deref(), presented) {
            (None, None) if !self.hosted_ephemeral_authority_required => Ok(()),
            (None, _) => Err(ApiError::from(SnapbackError::error(
                "SNAPBACK_EPHEMERAL_AUTHORITY_INSTANCE_REQUIRED",
                "ephemeral",
                "this hosted connection has no current ephemeral authority instance",
            ))),
            (Some(_), None) => Err(ApiError::from(SnapbackError::error(
                "SNAPBACK_EPHEMERAL_AUTHORITY_INSTANCE_REQUIRED",
                "ephemeral",
                "this connection requires its negotiated ephemeral authority instance",
            ))),
            (Some(expected), Some(actual)) if constant_time_str_eq(expected, actual) => Ok(()),
            _ => Err(ApiError::from(SnapbackError::error(
                "SNAPBACK_EPHEMERAL_AUTHORITY_INSTANCE_CHANGED",
                "ephemeral",
                "the presented ephemeral authority instance does not match this connection",
            ))),
        }
    }

    fn ephemeral_authority_instance(&self) -> Option<&str> {
        self.ephemeral_authority_instance.as_deref()
    }

    fn effect_fence(&self) -> crate::ephemeral::ConnectionEffectFence {
        self.bound.effect_fence(&self.grant_id)
    }

    /// Reserve the exact stream/session (and, when applicable, finite-service)
    /// authority before the final registry act. Permit release is atomic-only,
    /// so this owner may cross the Local finalize without carrying any auth
    /// mutex; terminal premark refuses until the owner is dropped.
    fn reserve_authority_work(
        &self,
        epoch_now_ms: u64,
        monotonic_now: Instant,
    ) -> Result<ConnectionAuthorityWorkPermit, ApiError> {
        let publication = self
            .bound
            .publication()
            .try_reserve_work(epoch_now_ms, monotonic_now)
            .map_err(ApiError::from)?
            .ok_or_else(|| ApiError::from(self.bound.stale_error_at(epoch_now_ms)))?;
        let service = self
            .bound
            .service_publication()
            .map(|service| service.begin_authority_work(epoch_now_ms, monotonic_now))
            .transpose()
            .map_err(ApiError::from)?;
        Ok(ConnectionAuthorityWorkPermit {
            _publication: publication,
            _service: service,
        })
    }

    fn authenticated_use_key(&self) -> Option<(String, u64)> {
        match &self.bound {
            BoundGrantAuthority::Anonymous { .. }
            | BoundGrantAuthority::ServicePrincipal { .. } => None,
            BoundGrantAuthority::Session {
                session_id,
                generation,
                ..
            } => Some((session_id.clone(), *generation)),
        }
    }
}

fn record_authenticated_poll_witness(
    runtime: &AppState,
    connection_act: &PreparedConnectionAct,
) -> Result<(), ApiError> {
    let Some(principal_id) = connection_act.session_principal_id() else {
        return Ok(());
    };
    runtime
        .connected_clients
        .register_or_refresh_authenticated_poll(
            principal_id,
            &connection_act.connection_id,
            &connection_act.grant_id,
            Instant::now(),
        )
        .map_err(ApiError::from)
}

#[must_use = "authority work must remain reserved through Local finalization"]
struct ConnectionAuthorityWorkPermit {
    _publication: FencedAuthorityWorkPermit,
    _service: Option<ServiceAuthorityWorkPermit>,
}

impl ConnectionAuthorityWorkPermit {
    /// Complete the Local leg of the exact operation that already reserved
    /// this authority. A pending service terminal may drain this predecessor,
    /// but it cannot make the predecessor reject its own final publication.
    fn with_retained_service_authority<T>(&self, operation: impl FnOnce() -> T) -> T {
        match &self._service {
            Some(service) => service.with_retained_authority(operation),
            None => operation(),
        }
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub(crate) struct BoundConnectionTerminalCapture {
    pub(crate) connection_id: String,
    pub(crate) grant_id: String,
    pub(crate) authorization_stream_incarnation: String,
    pub(crate) session_id: Option<String>,
    pub(crate) generation: Option<u64>,
    pub(crate) service_token_id: Option<String>,
    /// Proof carried from the registry mutation that readable-ID adoption is
    /// permanently disabled before asynchronous whole-connection cleanup.
    whole_id_cleanup_safe: bool,
}

impl BoundConnectionTerminalCapture {
    fn after_mint_only_containment(mut self) -> Self {
        self.whole_id_cleanup_safe = true;
        self
    }

    fn effect_fence(&self) -> crate::ephemeral::ConnectionEffectFence {
        match (&self.session_id, self.generation, &self.service_token_id) {
            (Some(session_id), Some(generation), None) => {
                crate::ephemeral::ConnectionEffectFence::session(
                    self.authorization_stream_incarnation.clone(),
                    self.grant_id.clone(),
                    session_id.clone(),
                    generation,
                )
            }
            (None, None, Some(token_id)) => {
                crate::ephemeral::ConnectionEffectFence::service_principal(
                    self.authorization_stream_incarnation.clone(),
                    self.grant_id.clone(),
                    token_id.clone(),
                )
            }
            (None, None, None) => crate::ephemeral::ConnectionEffectFence::anonymous(
                self.authorization_stream_incarnation.clone(),
                self.grant_id.clone(),
            ),
            _ => unreachable!("terminal capture preserves one complete authority class"),
        }
    }
}

/// Clone-shared server half of item 5 terminal propagation. Registry removal
/// invalidates every future act; notifier terminalization makes already-
/// queued effects non-deliverable and wakes only the exact bound socket. The
/// socket's generation-guarded teardown then performs physical room/outbox
/// cleanup without risking a replacement grant that reused the readable id.
#[derive(Clone)]
pub(crate) struct AuthTerminalLifecycle {
    connections: ConnectionRegistry,
    connected_clients: crate::connected_clients::ConnectedClientRegistry,
    delivery: Arc<crate::ephemeral::DeliveryNotifier>,
    ephemeral: EphemeralApi,
    snapback: SharedSnapback,
}

pub(crate) fn committed_mode_terminal_reason(
    predecessor: &crate::auth::mode::AuthModeStateRecord,
    committed: &crate::auth::mode::AuthModeStateRecord,
) -> Option<crate::live_wire::LiveAuthErrorReason> {
    (predecessor.active == crate::manifest::AuthMode::Sessions
        && (committed.active != crate::manifest::AuthMode::Sessions
            || committed.mode_state != crate::auth::mode::AuthModeStatus::Settled))
        .then_some(if committed.desired == crate::manifest::AuthMode::Dev {
            crate::live_wire::LiveAuthErrorReason::Downgrade
        } else {
            crate::live_wire::LiveAuthErrorReason::ModeTransition
        })
}

/// Registry retirement invokes this while it still owns the exact grant.
/// Registry -> notifier is the established connection-act order. The event is
/// visible before the checked grant is removed, so a wake that observed no
/// event must either finish an earlier act or block on the registry and reach
/// the installed event after retirement.
///
/// @ref LLP 0059#typed-terminal-auth-error — every terminal socket observes
/// its typed event before any post-retirement wake can make it exit.
fn install_bound_terminal_before_retirement(
    delivery: &crate::ephemeral::DeliveryNotifier,
    capture: &BoundConnectionTerminalCapture,
    event: crate::ephemeral::DeliveryTerminalEvent,
) {
    let _ = delivery.terminalize_bound(&capture.connection_id, &capture.grant_id, event);
}

fn purge_connection_capture(
    ephemeral: &EphemeralApi,
    capture: &BoundConnectionTerminalCapture,
    wake_after_purge: bool,
) {
    let effect_fence = capture.effect_fence();
    if wake_after_purge {
        ephemeral.purge_connection_effects(&capture.connection_id, &effect_fence);
    } else {
        ephemeral.purge_connection_effects_silently(&capture.connection_id, &effect_fence);
    }
}

/// Whole-readable-id cleanup is safe only after the registry mutation carried
/// mint-only containment in the capture. It deliberately leaves the notifier
/// registration untouched: auth terminalization retains its typed event there,
/// while pressure/admin retirement removes the exact registration beforehand.
async fn cleanup_mint_only_retired_connection(
    ephemeral: EphemeralApi,
    snapback: SharedSnapback,
    capture: BoundConnectionTerminalCapture,
) {
    debug_assert!(capture.whole_id_cleanup_safe);
    let connection_id = capture.connection_id;
    ephemeral.disconnect_terminal_retired(&connection_id, now_millis());
    let topology_id = connection_id.clone();
    with_snapback(&snapback, move |snapback| {
        snapback.disconnect_topology_for_transport(&topology_id, now_millis())
    })
    .await;
    // A pre-retirement stage may have finalized while Local was queued. The
    // second whole-ID sweep closes activity/rate/room/outbox residue from that
    // winner without touching the exact typed notifier event.
    ephemeral.disconnect_terminal_retired(&connection_id, now_millis());
}

fn spawn_mint_only_retired_connection_cleanup(
    ephemeral: EphemeralApi,
    snapback: SharedSnapback,
    capture: BoundConnectionTerminalCapture,
) -> Option<JoinHandle<()>> {
    if !capture.whole_id_cleanup_safe {
        return None;
    }
    let runtime = tokio::runtime::Handle::try_current().ok()?;
    Some(runtime.spawn(cleanup_mint_only_retired_connection(
        ephemeral, snapback, capture,
    )))
}

/// Complete a registry-retired administrative or idle teardown without ever
/// overlapping the registry, notifier/ephemeral shards, and LocalSnapback.
/// Registry retirement sets mint-only pressure before this future is created,
/// so the readable id cannot be adopted by a successor during whole-id
/// cleanup. The exact-fence sweep after Local closes the last finalize race.
async fn cleanup_retired_connection(runtime: AppState, capture: BoundConnectionTerminalCapture) {
    let connection_id = capture.connection_id.clone();
    debug_assert!(capture.whole_id_cleanup_safe);
    runtime
        .connected_clients
        .remove_grant(&capture.connection_id, &capture.grant_id);
    let delivery = runtime.ephemeral.delivery_notifier();
    let _ = delivery.retire_bound(&connection_id, &capture.grant_id);
    cleanup_mint_only_retired_connection(runtime.ephemeral, runtime.snapback, capture).await;
}

/// Transfer every capture to independent ownership before the caller reaches
/// its first await. A maintenance worker may be cancelled while joining one
/// task, but no later already-retired grant can lose its cleanup owner.
struct RetiredConnectionCleanupTask {
    retry_capture: BoundConnectionTerminalCapture,
    task: JoinHandle<()>,
}

fn spawn_retired_connection_cleanup_batch(
    runtime: &AppState,
    captures: Vec<BoundConnectionTerminalCapture>,
) -> Vec<RetiredConnectionCleanupTask> {
    captures
        .into_iter()
        .map(|capture| RetiredConnectionCleanupTask {
            retry_capture: capture.clone(),
            task: tokio::spawn(cleanup_retired_connection(runtime.clone(), capture)),
        })
        .collect()
}

/// Join every independently owned cleanup without surrendering its fail-closed
/// retry witness. A child panic/cancellation is reported without exposing a
/// connection id, and the exact mint-only capture returns to the maintenance
/// loop for an idempotent retry on its next tick.
///
/// @ref LLP 0032#phase-3--lifecycle-and-resource-hardening — L2 retirement
/// remains owned and mint-only contained across asynchronous cleanup failure.
async fn join_retired_connection_cleanup_batch(
    tasks: Vec<RetiredConnectionCleanupTask>,
    telemetry: &crate::telemetry::Telemetry,
) -> Vec<BoundConnectionTerminalCapture> {
    let mut retry = Vec::new();
    for RetiredConnectionCleanupTask {
        retry_capture,
        task,
    } in tasks
    {
        if let Err(error) = task.await {
            let failure_kind = if error.is_panic() {
                "panic"
            } else if error.is_cancelled() {
                "cancelled"
            } else {
                "unknown"
            };
            eprintln!(
                "SNAPBACK_CONNECTION_CLEANUP_FAILED: retired connection cleanup task {failure_kind}; fail-closed retry retained"
            );
            telemetry.standalone_diagnostic(&crate::diagnostic::Diagnostic::warning(
                "SNAPBACK_CONNECTION_CLEANUP_FAILED",
                "runtime",
                "retired connection cleanup task failed",
            ));
            retry.push(retry_capture);
        }
    }
    retry
}

impl AuthTerminalLifecycle {
    pub(crate) fn new(
        connections: ConnectionRegistry,
        connected_clients: crate::connected_clients::ConnectedClientRegistry,
        ephemeral: &EphemeralApi,
        snapback: SharedSnapback,
    ) -> Self {
        let delivery = ephemeral.delivery_notifier();
        let retirement_delivery = delivery.clone();
        let retirement_ephemeral = ephemeral.clone();
        let retirement_snapback = snapback.clone();
        let retirement_connected_clients = connected_clients.clone();
        connections.install_retirement_sink(move |capture| {
            retirement_connected_clients.remove_grant(&capture.connection_id, &capture.grant_id);
            purge_connection_capture(&retirement_ephemeral, &capture, true);
            let _ = retirement_delivery.retire_bound(&capture.connection_id, &capture.grant_id);
            let _ = spawn_mint_only_retired_connection_cleanup(
                retirement_ephemeral.clone(),
                retirement_snapback.clone(),
                capture,
            );
        });
        Self {
            connections,
            connected_clients,
            delivery,
            ephemeral: ephemeral.clone(),
            snapback,
        }
    }

    pub(crate) fn expiry_sink(&self) -> crate::auth::runtime::AuthExpiryTerminalSink {
        let lifecycle = self.clone();
        crate::auth::runtime::AuthExpiryTerminalSink::new(move |expired| {
            lifecycle.expire_sessions(expired);
        })
    }

    fn expire_sessions(&self, expired: Vec<crate::auth::session_projection::ExpiredSession>) {
        for expired in expired {
            self.terminate_session_generation_for_disposition(
                &expired.authorization_stream_incarnation,
                &expired.session_id,
                expired.generation,
                crate::live_wire::LiveAuthErrorReason::Expired,
                crate::live_wire::LiveAuthorityDisposition::Carrier,
                expired.close_by,
            );
        }
    }

    #[cfg(test)]
    pub(crate) fn terminate_session_generation(
        &self,
        authorization_stream_incarnation: &str,
        session_id: &str,
        generation: u64,
        reason: crate::live_wire::LiveAuthErrorReason,
        close_by: Instant,
    ) {
        self.terminate_session_generation_for_disposition(
            authorization_stream_incarnation,
            session_id,
            generation,
            reason,
            crate::live_wire::LiveAuthorityDisposition::DurableDelete,
            close_by,
        );
    }

    fn terminate_session_generation_for_disposition(
        &self,
        authorization_stream_incarnation: &str,
        session_id: &str,
        generation: u64,
        reason: crate::live_wire::LiveAuthErrorReason,
        authority_disposition: crate::live_wire::LiveAuthorityDisposition,
        close_by: Instant,
    ) {
        let event = crate::ephemeral::DeliveryTerminalEvent {
            code: crate::live_wire::LiveAuthErrorCode::SessionExpired,
            reason,
            authority_disposition,
            close_by,
        };
        let captures = self
            .connections
            .invalidate_session_generation_with_terminal(
                authorization_stream_incarnation,
                session_id,
                generation,
                &self.delivery,
                event,
            );
        self.cleanup_terminalized_captures(captures);
    }

    pub(crate) fn terminate_service_tokens(&self, token_ids: &[String], close_by: Instant) {
        self.terminate_service_tokens_for_reason(
            token_ids,
            crate::live_wire::LiveAuthErrorReason::Revoked,
            crate::live_wire::LiveAuthorityDisposition::DurableDelete,
            close_by,
        );
    }

    fn evict_service_tokens(&self, token_ids: &[String], close_by: Instant) {
        self.terminate_service_tokens_for_reason(
            token_ids,
            crate::live_wire::LiveAuthErrorReason::Revoked,
            crate::live_wire::LiveAuthorityDisposition::Carrier,
            close_by,
        );
    }

    #[cfg(test)]
    fn expire_service_tokens(&self, token_ids: &[String], close_by: Instant) {
        self.terminate_service_tokens_for_reason(
            token_ids,
            crate::live_wire::LiveAuthErrorReason::Expired,
            crate::live_wire::LiveAuthorityDisposition::Carrier,
            close_by,
        );
    }

    fn expire_service_tokens_for_disposition(
        &self,
        token_ids: &[String],
        disposition: ServiceAuthorityDisposition,
        close_by: Instant,
    ) {
        let disposition = match disposition {
            ServiceAuthorityDisposition::Carrier => {
                crate::live_wire::LiveAuthorityDisposition::Carrier
            }
            ServiceAuthorityDisposition::DurableDelete => {
                crate::live_wire::LiveAuthorityDisposition::DurableDelete
            }
        };
        self.terminate_service_tokens_for_reason(
            token_ids,
            crate::live_wire::LiveAuthErrorReason::Expired,
            disposition,
            close_by,
        );
    }

    fn terminate_service_tokens_for_reason(
        &self,
        token_ids: &[String],
        reason: crate::live_wire::LiveAuthErrorReason,
        authority_disposition: crate::live_wire::LiveAuthorityDisposition,
        close_by: Instant,
    ) {
        let event = crate::ephemeral::DeliveryTerminalEvent {
            code: crate::live_wire::LiveAuthErrorCode::ScopedTokenInvalid,
            reason,
            authority_disposition,
            close_by,
        };
        let captures = self.connections.invalidate_service_tokens_with_terminal(
            token_ids,
            &self.delivery,
            event,
        );
        self.cleanup_terminalized_captures(captures);
    }

    pub(crate) fn committed_stream_reset(
        &self,
        reason: crate::live_wire::LiveAuthErrorReason,
        close_by: Instant,
    ) {
        let event = crate::ephemeral::DeliveryTerminalEvent {
            code: crate::live_wire::LiveAuthErrorCode::StreamReset,
            reason,
            authority_disposition: crate::live_wire::LiveAuthorityDisposition::DurableDelete,
            close_by,
        };
        let captures = self
            .connections
            .clear_after_committed_reset_with_terminal(&self.delivery, event);
        self.cleanup_terminalized_captures(captures);
    }

    pub(crate) fn committed_mode_transition(
        &self,
        reason: crate::live_wire::LiveAuthErrorReason,
        close_by: Instant,
    ) {
        let event = crate::ephemeral::DeliveryTerminalEvent {
            code: crate::live_wire::LiveAuthErrorCode::ModePending,
            reason,
            authority_disposition: crate::live_wire::LiveAuthorityDisposition::DurableDelete,
            close_by,
        };
        let captures = self
            .connections
            .clear_after_committed_reset_with_terminal(&self.delivery, event);
        self.cleanup_terminalized_captures(captures);
    }

    /// Complete every terminal phase, including the Local topology purge,
    /// before a committed mode-transition carrier is allowed to reopen its
    /// successor admission epoch. No registry/ephemeral guard crosses the
    /// awaited Local phase.
    async fn committed_mode_transition_before_reopen(
        &self,
        reason: crate::live_wire::LiveAuthErrorReason,
        close_by: Instant,
    ) {
        let event = crate::ephemeral::DeliveryTerminalEvent {
            code: crate::live_wire::LiveAuthErrorCode::ModePending,
            reason,
            authority_disposition: crate::live_wire::LiveAuthorityDisposition::DurableDelete,
            close_by,
        };
        let captures = self
            .connections
            .clear_after_committed_reset_with_terminal(&self.delivery, event);
        for capture in &captures {
            self.connected_clients
                .remove_grant(&capture.connection_id, &capture.grant_id);
            purge_connection_capture(&self.ephemeral, capture, false);
            debug_assert!(capture.whole_id_cleanup_safe);
            self.ephemeral
                .disconnect_terminal_retired(&capture.connection_id, now_millis());
        }
        let connection_ids = captures
            .iter()
            .map(|capture| capture.connection_id.clone())
            .collect::<Vec<_>>();
        with_snapback(&self.snapback, move |local| {
            for connection_id in connection_ids {
                local.disconnect_topology_for_transport(&connection_id, now_millis());
            }
        })
        .await;
        for capture in captures {
            self.ephemeral
                .disconnect_terminal_retired(&capture.connection_id, now_millis());
        }
    }

    fn cleanup_terminalized_captures(&self, captures: Vec<BoundConnectionTerminalCapture>) {
        for capture in captures {
            self.connected_clients
                .remove_grant(&capture.connection_id, &capture.grant_id);
            purge_connection_capture(&self.ephemeral, &capture, false);
            let _ = spawn_mint_only_retired_connection_cleanup(
                self.ephemeral.clone(),
                self.snapback.clone(),
                capture,
            );
        }
    }
}

impl ConnectionRegistryState {
    fn touch(&mut self, connection_id: &str, now_ms: u64) {
        let Some((previous, was_used)) = self
            .grants
            .get(connection_id)
            .map(|record| (record.last_use_ms, record.used))
        else {
            return;
        };
        let index = if was_used {
            &mut self.used
        } else {
            &mut self.unused
        };
        index.remove(&(previous, connection_id.to_owned()));
        if let Some(record) = self.grants.get_mut(connection_id) {
            record.last_use_ms = now_ms;
            record.used = true;
        }
        self.used.insert((now_ms, connection_id.to_owned()));
    }

    fn admit_slot(
        &mut self,
        now_ms: u64,
    ) -> SnapbackResult<Option<BoundConnectionTerminalCapture>> {
        if self.grants.len() < MAX_CONNECTION_GRANTS {
            return Ok(None);
        }
        if let Some((_last_use, connection_id)) = self.unused.pop_first() {
            let record = self
                .remove_grant(&connection_id)
                .expect("unused LRU entry names an installed grant");
            return Ok(Some(
                record
                    .authority
                    .terminal_capture(connection_id, record.grant_id),
            ));
        }
        let expired_before = now_ms.saturating_sub(CONNECTION_GRANT_IDLE_TTL_MS);
        if self
            .used
            .first()
            .is_some_and(|(last_use, _)| *last_use <= expired_before)
            && let Some((_last_use, connection_id)) = self.used.pop_first()
        {
            let record = self
                .remove_grant(&connection_id)
                .expect("used LRU entry names an installed grant");
            self.pressure_mint_only = true;
            return Ok(Some(
                record
                    .authority
                    .terminal_capture(connection_id, record.grant_id)
                    .after_mint_only_containment(),
            ));
        }
        Err(SnapbackError::error(
            "SNAPBACK_CONNECTION_GRANT_LIMIT_EXCEEDED",
            "realtime",
            format!(
                "connection grant limit ({MAX_CONNECTION_GRANTS}) is occupied by active leases; retry after an idle lease expires"
            ),
        ))
    }

    fn insert(&mut self, connection_id: String, record: ConnectionGrantRecord) {
        self.unused
            .insert((record.last_use_ms, connection_id.clone()));
        self.index_grant(&connection_id, &record.authority);
        self.grants.insert(connection_id, record);
    }

    fn index_grant(&mut self, connection_id: &str, authority: &BoundGrantAuthority) {
        match authority.reverse_key() {
            GrantReverseKey::Anonymous(incarnation) => {
                self.anonymous_grants
                    .entry(incarnation)
                    .or_default()
                    .insert(connection_id.to_owned());
            }
            GrantReverseKey::Session(key) => {
                self.session_grants
                    .entry(key)
                    .or_default()
                    .insert(connection_id.to_owned());
            }
            GrantReverseKey::ServiceToken(token_id) => {
                self.service_token_grants
                    .entry(token_id)
                    .or_default()
                    .insert(connection_id.to_owned());
            }
        }
    }

    fn unindex_grant(&mut self, connection_id: &str, authority: &BoundGrantAuthority) {
        match authority.reverse_key() {
            GrantReverseKey::Anonymous(incarnation) => {
                if let Some(ids) = self.anonymous_grants.get_mut(&incarnation) {
                    ids.remove(connection_id);
                    if ids.is_empty() {
                        self.anonymous_grants.remove(&incarnation);
                    }
                }
            }
            GrantReverseKey::Session(key) => {
                if let Some(ids) = self.session_grants.get_mut(&key) {
                    ids.remove(connection_id);
                    if ids.is_empty() {
                        self.session_grants.remove(&key);
                    }
                }
            }
            GrantReverseKey::ServiceToken(token_id) => {
                if let Some(ids) = self.service_token_grants.get_mut(&token_id) {
                    ids.remove(connection_id);
                    if ids.is_empty() {
                        self.service_token_grants.remove(&token_id);
                    }
                }
            }
        }
    }

    fn remove_grant(&mut self, connection_id: &str) -> Option<ConnectionGrantRecord> {
        let record = self.grants.remove(connection_id)?;
        let index = if record.used {
            &mut self.used
        } else {
            &mut self.unused
        };
        index.remove(&(record.last_use_ms, connection_id.to_owned()));
        self.unindex_grant(connection_id, &record.authority);
        Some(record)
    }

    fn consume_bucket(
        bucket: &mut std::collections::VecDeque<Instant>,
        limit: usize,
        window: Duration,
        now: Instant,
    ) -> Result<(), u64> {
        while bucket
            .front()
            .is_some_and(|attempt| now.saturating_duration_since(*attempt) >= window)
        {
            bucket.pop_front();
        }
        if bucket.len() >= limit {
            let remaining = bucket
                .front()
                .and_then(|oldest| {
                    oldest
                        .checked_add(window)
                        .map(|deadline| deadline.saturating_duration_since(now))
                })
                .unwrap_or(window);
            let millis = remaining.as_millis().max(1);
            let seconds = millis.div_ceil(1_000).min(u128::from(u64::MAX)) as u64;
            return Err(seconds.max(1));
        }
        bucket.push_back(now);
        Ok(())
    }

    fn prune_bucket(
        bucket: &mut std::collections::VecDeque<Instant>,
        window: Duration,
        now: Instant,
    ) {
        while bucket
            .front()
            .is_some_and(|attempt| now.saturating_duration_since(*attempt) >= window)
        {
            bucket.pop_front();
        }
    }

    fn consume_anonymous_open(&mut self, incarnation: &str, now: Instant) -> Result<(), u64> {
        Self::consume_bucket(
            self.anonymous_open_attempts
                .entry(incarnation.to_owned())
                .or_default(),
            CONNECTION_OPEN_COARSE_LIMIT,
            CONNECTION_OPEN_WINDOW,
            now,
        )
    }

    fn consume_unknown_open(&mut self, incarnation: &str, now: Instant) -> Result<(), u64> {
        Self::consume_bucket(
            self.unknown_open_attempts
                .entry(incarnation.to_owned())
                .or_default(),
            CONNECTION_OPEN_COARSE_LIMIT,
            CONNECTION_OPEN_WINDOW,
            now,
        )
    }

    fn consume_session_open(&mut self, key: BoundSessionKey, now: Instant) -> Result<(), u64> {
        // Rejected opens can name sessions that never own a grant. Expire
        // their empty buckets independently of grant pressure so this local
        // throttle cannot become an unbounded process-lifetime index.
        self.session_open_attempts.retain(|_, bucket| {
            Self::prune_bucket(bucket, CONNECTION_OPEN_WINDOW, now);
            !bucket.is_empty()
        });
        Self::consume_bucket(
            self.session_open_attempts.entry(key).or_default(),
            CONNECTION_OPEN_SESSION_LIMIT,
            CONNECTION_OPEN_WINDOW,
            now,
        )
    }

    fn consume_service_open(&mut self, token_hash: [u8; 32], now: Instant) -> Result<(), u64> {
        self.service_open_attempts.retain(|_, bucket| {
            Self::prune_bucket(bucket, CONNECTION_OPEN_WINDOW, now);
            !bucket.is_empty()
        });
        Self::consume_bucket(
            self.service_open_attempts.entry(token_hash).or_default(),
            CONNECTION_OPEN_SESSION_LIMIT,
            CONNECTION_OPEN_WINDOW,
            now,
        )
    }

    fn consume_agent_route(
        &mut self,
        path: &'static str,
        mut source: AgentRouteThrottleSource,
        limit: usize,
        now: Instant,
    ) -> Result<(), u64> {
        self.agent_route_attempts.retain(|_, bucket| {
            Self::prune_bucket(bucket, AGENT_ROUTE_THROTTLE_WINDOW, now);
            !bucket.is_empty()
        });
        let mut key = AgentRouteThrottleKey {
            path,
            source: source.clone(),
        };
        if !self.agent_route_attempts.contains_key(&key)
            && self.agent_route_attempts.len() >= AGENT_ROUTE_THROTTLE_SOURCE_CAP
        {
            source = AgentRouteThrottleSource::Malformed;
            key = AgentRouteThrottleKey { path, source };
        }
        Self::consume_bucket(
            self.agent_route_attempts.entry(key).or_default(),
            limit,
            AGENT_ROUTE_THROTTLE_WINDOW,
            now,
        )
    }

    fn consume_external_api(
        &mut self,
        mut source: ExternalApiThrottleSource,
        mut limit: usize,
        now: Instant,
    ) -> Result<(), u64> {
        let mut key = ExternalApiThrottleKey {
            route_family: EXTERNAL_API_ROUTE_FAMILY,
            source: source.clone(),
        };
        if !self.external_api_attempts.contains_key(&key)
            && self.external_api_attempts.len() >= EXTERNAL_API_THROTTLE_KEY_CAP
        {
            self.external_api_attempts.retain(|_, bucket| {
                Self::prune_bucket(bucket, EXTERNAL_API_THROTTLE_WINDOW, now);
                !bucket.is_empty()
            });
            if self.external_api_attempts.len() >= EXTERNAL_API_THROTTLE_KEY_CAP {
                (source, limit) = source.overflow();
                key = ExternalApiThrottleKey {
                    route_family: EXTERNAL_API_ROUTE_FAMILY,
                    source,
                };
            }
        }
        Self::consume_bucket(
            self.external_api_attempts.entry(key).or_default(),
            limit,
            EXTERNAL_API_THROTTLE_WINDOW,
            now,
        )
    }

    #[cfg(test)]
    fn assert_grant_indexes_consistent(&self) {
        assert_eq!(self.grants.len(), self.unused.len() + self.used.len());
        for (connection_id, record) in &self.grants {
            let lru_key = (record.last_use_ms, connection_id.clone());
            assert_eq!(
                (self.unused.contains(&lru_key), self.used.contains(&lru_key)),
                (!record.used, record.used),
                "grant must occur in exactly its declared LRU index"
            );
            match record.authority.reverse_key() {
                GrantReverseKey::Anonymous(incarnation) => assert!(
                    self.anonymous_grants
                        .get(&incarnation)
                        .is_some_and(|ids| ids.contains(connection_id))
                ),
                GrantReverseKey::Session(key) => assert!(
                    self.session_grants
                        .get(&key)
                        .is_some_and(|ids| ids.contains(connection_id))
                ),
                GrantReverseKey::ServiceToken(token_id) => assert!(
                    self.service_token_grants
                        .get(&token_id)
                        .is_some_and(|ids| ids.contains(connection_id))
                ),
            }
        }
        for (incarnation, ids) in &self.anonymous_grants {
            assert!(!ids.is_empty(), "anonymous reverse index has a ghost set");
            for connection_id in ids {
                assert!(matches!(
                    self.grants.get(connection_id).map(|record| &record.authority),
                    Some(BoundGrantAuthority::Anonymous {
                        authorization_stream_incarnation,
                        ..
                    }) if authorization_stream_incarnation == incarnation
                ));
            }
        }
        for (key, ids) in &self.session_grants {
            assert!(!ids.is_empty(), "session reverse index has a ghost set");
            for connection_id in ids {
                assert!(matches!(
                    self.grants.get(connection_id).map(|record| &record.authority),
                    Some(BoundGrantAuthority::Session {
                        authorization_stream_incarnation,
                        session_id,
                        generation,
                        ..
                    }) if authorization_stream_incarnation == &key.authorization_stream_incarnation
                        && session_id == &key.session_id
                        && generation == &key.generation
                ));
            }
        }
        for (token_id, ids) in &self.service_token_grants {
            assert!(
                !ids.is_empty(),
                "service token reverse index has a ghost set"
            );
            for connection_id in ids {
                assert!(matches!(
                    self.grants.get(connection_id).map(|record| &record.authority),
                    Some(BoundGrantAuthority::ServicePrincipal {
                        token_id: bound_token_id,
                        ..
                    }) if bound_token_id == token_id
                ));
            }
        }
    }
}

/// The `POST /connection/open` response: the (possibly adopted) connection id
/// and the bearer the caller must present on every connection-scoped call.
#[derive(Clone, Deserialize, PartialEq, Serialize, schemars::JsonSchema)]
pub struct ConnectionGrant {
    #[serde(rename = "connectionId")]
    pub connection_id: String,
    #[serde(rename = "connectionToken")]
    pub connection_token: String,
    #[serde(
        rename = "authorizationInvalidation",
        default,
        skip_serializing_if = "Option::is_none"
    )]
    pub authorization_invalidation:
        Option<crate::auth::invalidation::AuthorizationInvalidationConnection>,
    /// Bound-wire-version witness (LLP 0094 §0B.3): present on every open and
    /// re-open response of an explicitly bound lineage, never on a legacy
    /// (offerless-open) lineage. Echo present ⇔ explicitly bound.
    ///
    /// @ref LLP 0094#0b3-the-wireversion-open-time-offer — the additive echo
    ///   is the hosted arm's only runtime version witness (§0B.6).
    #[serde(
        rename = "wireVersion",
        default,
        skip_serializing_if = "Option::is_none"
    )]
    pub wire_version: Option<String>,
    /// Echo present iff the client offered the known hosted-ephemeral
    /// authority protocol. Absence never fails durable/local connection use.
    #[serde(
        rename = "ephemeralAuthorityProtocol",
        default,
        skip_serializing_if = "Option::is_none"
    )]
    pub ephemeral_authority_protocol: Option<u32>,
    /// Opaque authority-instance witness. Every negotiated ephemeral frame
    /// repeats this value so clients can fence in-memory state across target
    /// process replacement.
    #[serde(
        rename = "ephemeralAuthorityInstance",
        default,
        skip_serializing_if = "Option::is_none"
    )]
    #[schemars(pattern(r"^eai1\.[A-Za-z0-9_-]{43}$"))]
    pub ephemeral_authority_instance: Option<String>,
    /// Present and true only when this lineage was opened under a current
    /// authenticated hosted single-instance admission. Such a lineage must
    /// repeat protocol 1 on reopen and present its exact instance on every
    /// governed HTTP request or WebSocket upgrade.
    ///
    /// @ref LLP 0094#hosted-ephemeral-per-boundary-contract — absence is the
    ///   legacy-local compatibility case; hosted authority is fail-closed.
    #[serde(
        rename = "hostedEphemeralAuthorityRequired",
        default,
        skip_serializing_if = "is_false"
    )]
    pub hosted_ephemeral_authority_required: bool,
    /// Echo present iff the connection lineage negotiated LLP 0107's
    /// monotonic ephemeral-expiry conversion protocol.
    #[serde(
        rename = "ephemeralExpiryProtocol",
        default,
        skip_serializing_if = "Option::is_none"
    )]
    pub ephemeral_expiry_protocol: Option<u32>,
}

impl std::fmt::Debug for ConnectionGrant {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        // @ref LLP 0039#diagnostics-and-route-registry — bearer capabilities
        // never enter logs or diagnostic/debug projections.
        formatter
            .debug_struct("ConnectionGrant")
            .field("connection_id", &self.connection_id)
            .field("connection_token", &"[REDACTED]")
            .field(
                "authorization_invalidation",
                &self.authorization_invalidation,
            )
            .field("wire_version", &self.wire_version)
            .field(
                "ephemeral_authority_protocol",
                &self.ephemeral_authority_protocol,
            )
            .field(
                "ephemeral_authority_instance",
                &self.ephemeral_authority_instance,
            )
            .field(
                "hosted_ephemeral_authority_required",
                &self.hosted_ephemeral_authority_required,
            )
            .field("ephemeral_expiry_protocol", &self.ephemeral_expiry_protocol)
            .finish()
    }
}

fn is_false(value: &bool) -> bool {
    !*value
}

/// The `POST /connection/open` request. `previousToken` is a bearer secret
/// used only to prove ownership of an existing grant; it is request-only and
/// must never enter diagnostics, receipts, retained client state, or logs.
///
/// @ref LLP 0051#d4-finish-dk-7-the-live-envelope-becomes-schema-governed — the
///   complete non-JS client HTTP surface is Rust-owned and generated.
#[derive(Clone, Default, Deserialize, PartialEq, Serialize, schemars::JsonSchema)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct OpenConnectionRequest {
    #[serde(default, alias = "connection_id")]
    pub connection_id: Option<String>,
    /// A prior grant's bearer. This field is deliberately absent from every
    /// server response and from all receipt/capsule schemas.
    #[serde(default, alias = "previous_token")]
    pub previous_token: Option<String>,
    /// Exact must-understand offer. Missing opens a legacy connection that
    /// cannot admit session-mode auth-scoped live work; a present unknown
    /// value refuses (`SNAPBACK_AUTH_INVALIDATION_PROTOCOL_UNSUPPORTED`).
    ///
    /// @ref LLP 0094#0c5-authinvalidationprotocol-decided-not-inherited — from
    ///   B1 both open-time offer fields follow one matrix: known binds,
    ///   unknown refuses, absent degrades to legacy.
    #[serde(default, alias = "auth_invalidation_protocol")]
    pub auth_invalidation_protocol: Option<u32>,
    /// Exact wire-version offer (LLP 0094 §0B.3): a known token binds the
    /// connection lineage, an unknown token refuses
    /// (`SNAPBACK_WIRE_VERSION_UNSUPPORTED`), absent opens a legacy lineage
    /// implicitly bound to v1 for the socket-equality rule.
    #[serde(default, alias = "wire_version")]
    pub wire_version: Option<String>,
    /// Capability-first hosted ephemeral offer. Known binds, unknown refuses,
    /// and absent degrades without failing durable connection use.
    #[serde(default, alias = "ephemeral_authority_protocol")]
    pub ephemeral_authority_protocol: Option<u32>,
    /// Optional exact offer. Unknown values refuse; absence preserves the
    /// legacy durable surface and makes React presence unavailable.
    #[serde(default, alias = "ephemeral_expiry_protocol")]
    pub ephemeral_expiry_protocol: Option<u32>,
}

impl std::fmt::Debug for OpenConnectionRequest {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter
            .debug_struct("OpenConnectionRequest")
            .field("connection_id", &self.connection_id)
            .field(
                "previous_token",
                &self.previous_token.as_ref().map(|_| "[REDACTED]"),
            )
            .field(
                "auth_invalidation_protocol",
                &self.auth_invalidation_protocol,
            )
            .field("wire_version", &self.wire_version)
            .field(
                "ephemeral_authority_protocol",
                &self.ephemeral_authority_protocol,
            )
            .field("ephemeral_expiry_protocol", &self.ephemeral_expiry_protocol)
            .finish()
    }
}

impl ConnectionRegistry {
    fn ephemeral_expiry_protocol(&self, connection_id: &str) -> Option<u32> {
        self.lock()
            .grants
            .get(connection_id)
            .and_then(|record| record.ephemeral_expiry_protocol)
    }

    fn ephemeral_authority_instance(&self, connection_id: &str) -> Option<String> {
        self.lock()
            .grants
            .get(connection_id)
            .and_then(|record| record.ephemeral_authority_instance.clone())
    }

    fn install_retirement_sink(
        &self,
        sink: impl Fn(BoundConnectionTerminalCapture) + Send + Sync + 'static,
    ) {
        *self
            .retirement_sink
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(Arc::new(sink));
    }

    fn publish_retirement(&self, capture: BoundConnectionTerminalCapture) {
        let sink = self
            .retirement_sink
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .clone();
        if let Some(sink) = sink {
            sink(capture);
        }
    }

    /// Remove the currently installed grant for an administrator-directed
    /// connection teardown. Cleanup is returned to the async handler rather
    /// than sent through the best-effort retirement sink: the handler must
    /// await local topology removal before acknowledging 204.
    fn retire_connection_for_cleanup(
        &self,
        connection_id: &str,
    ) -> Option<BoundConnectionTerminalCapture> {
        let mut state = self.lock();
        let record = state.remove_grant(connection_id)?;
        state.pressure_mint_only = true;
        Some(
            record
                .authority
                .terminal_capture(connection_id.to_owned(), record.grant_id)
                .after_mint_only_containment(),
        )
    }

    /// Atomically retire grants whose exact registry last-use stamp is still
    /// at or before the maintenance cutoff. Any act that wins the registry
    /// first refreshes the stamp and survives this sweep.
    fn retire_idle_for_cleanup(&self, cutoff_ms: u64) -> Vec<BoundConnectionTerminalCapture> {
        let mut state = self.lock();
        let ids = state
            .unused
            .iter()
            .take_while(|(last_use, _)| *last_use <= cutoff_ms)
            .chain(
                state
                    .used
                    .iter()
                    .take_while(|(last_use, _)| *last_use <= cutoff_ms),
            )
            .map(|(_, connection_id)| connection_id.clone())
            .collect::<BTreeSet<_>>();
        let captures = ids
            .into_iter()
            .filter_map(|connection_id| {
                let record = state.remove_grant(&connection_id)?;
                Some(
                    record
                        .authority
                        .terminal_capture(connection_id, record.grant_id)
                        .after_mint_only_containment(),
                )
            })
            .collect::<Vec<_>>();
        if !captures.is_empty() {
            state.pressure_mint_only = true;
        }
        captures
    }

    /// Invalidate every process-local connection capability after the shared
    /// authorization stream rotates at a committed app reset.
    #[cfg(test)]
    pub(crate) fn clear_after_committed_reset(&self) -> Vec<BoundConnectionTerminalCapture> {
        self.clear_after_committed_reset_inner(|_| {})
    }

    fn clear_after_committed_reset_with_terminal(
        &self,
        delivery: &crate::ephemeral::DeliveryNotifier,
        event: crate::ephemeral::DeliveryTerminalEvent,
    ) -> Vec<BoundConnectionTerminalCapture> {
        self.clear_after_committed_reset_inner(|capture| {
            install_bound_terminal_before_retirement(delivery, capture, event);
        })
    }

    fn clear_after_committed_reset_inner(
        &self,
        mut before_remove: impl FnMut(&BoundConnectionTerminalCapture),
    ) -> Vec<BoundConnectionTerminalCapture> {
        let mut state = self.lock();
        let captures = state
            .grants
            .iter()
            .map(|(connection_id, record)| {
                record
                    .authority
                    .terminal_capture(connection_id.clone(), record.grant_id.clone())
                    .after_mint_only_containment()
            })
            .collect::<Vec<_>>();
        for capture in &captures {
            before_remove(capture);
        }
        let retired_any = !captures.is_empty();
        let retain_mint_only_containment = state.pressure_mint_only || retired_any;
        *state = ConnectionRegistryState::default();
        state.pressure_mint_only = retain_mint_only_containment;
        *self
            .invalidation_issuer
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = None;
        captures
    }

    pub(crate) fn install_invalidation_issuer(
        &self,
        issuer: crate::auth::invalidation::LiveInvalidationIssuer,
    ) {
        *self
            .invalidation_issuer
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(issuer);
    }

    pub(crate) fn clear_invalidation_issuer(&self) {
        *self
            .invalidation_issuer
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = None;
    }

    #[cfg(test)]
    fn invalidation_expectation_for_test(&self) -> Option<crate::storage::AuthorizationVersion> {
        self.invalidation_issuer
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .as_ref()
            .map(|issuer| {
                issuer
                    .authorization_expectation()
                    .expect("test issuer expectation")
            })
    }

    /// Remove every grant bound to one exact predecessor session generation.
    /// The reverse index keeps this proportional to the affected authority,
    /// not to the 16,384-entry registry.
    #[cfg(test)]
    pub(crate) fn invalidate_session_generation(
        &self,
        authorization_stream_incarnation: &str,
        session_id: &str,
        generation: u64,
    ) -> Vec<BoundConnectionTerminalCapture> {
        self.invalidate_session_generation_inner(
            authorization_stream_incarnation,
            session_id,
            generation,
            |_| {},
        )
    }

    fn invalidate_session_generation_with_terminal(
        &self,
        authorization_stream_incarnation: &str,
        session_id: &str,
        generation: u64,
        delivery: &crate::ephemeral::DeliveryNotifier,
        event: crate::ephemeral::DeliveryTerminalEvent,
    ) -> Vec<BoundConnectionTerminalCapture> {
        self.invalidate_session_generation_inner(
            authorization_stream_incarnation,
            session_id,
            generation,
            |capture| {
                install_bound_terminal_before_retirement(delivery, capture, event);
            },
        )
    }

    fn invalidate_session_generation_inner(
        &self,
        authorization_stream_incarnation: &str,
        session_id: &str,
        generation: u64,
        mut before_remove: impl FnMut(&BoundConnectionTerminalCapture),
    ) -> Vec<BoundConnectionTerminalCapture> {
        let key = BoundSessionKey {
            authorization_stream_incarnation: authorization_stream_incarnation.to_owned(),
            session_id: session_id.to_owned(),
            generation,
        };
        let mut state = self.lock();
        let ids = state.session_grants.get(&key).cloned().unwrap_or_default();
        let captures = ids
            .iter()
            .filter_map(|connection_id| {
                let record = state.grants.get(connection_id)?;
                Some(
                    record
                        .authority
                        .terminal_capture(connection_id.clone(), record.grant_id.clone())
                        .after_mint_only_containment(),
                )
            })
            .collect::<Vec<_>>();
        for capture in &captures {
            before_remove(capture);
        }
        for connection_id in &ids {
            state
                .remove_grant(connection_id)
                .expect("terminalized session grant remains installed under registry ownership");
        }
        if !ids.is_empty() {
            state.pressure_mint_only = true;
        }
        captures
    }

    /// Remove every connection capability carried by one of the exact scoped
    /// tokens that became terminal in the just-committed credential operation.
    /// The token reverse index keeps cap eviction isolated: another carrier of
    /// the same durable grant is deliberately left installed.
    ///
    /// @ref LLP 0055#ending-authority-revocation-expiry-deactivation — token revocation and cap eviction end
    ///   the carrier axis only; rotation supplies every token from the ended
    ///   credential generation as exact witnesses.
    fn invalidate_service_tokens_with_terminal(
        &self,
        token_ids: &[String],
        delivery: &crate::ephemeral::DeliveryNotifier,
        event: crate::ephemeral::DeliveryTerminalEvent,
    ) -> Vec<BoundConnectionTerminalCapture> {
        self.invalidate_service_tokens_inner(token_ids, |capture| {
            install_bound_terminal_before_retirement(delivery, capture, event);
        })
    }

    fn invalidate_service_tokens_inner(
        &self,
        token_ids: &[String],
        mut before_remove: impl FnMut(&BoundConnectionTerminalCapture),
    ) -> Vec<BoundConnectionTerminalCapture> {
        let mut state = self.lock();
        let ids = token_ids
            .iter()
            .flat_map(|token_id| {
                state
                    .service_token_grants
                    .get(token_id)
                    .into_iter()
                    .flatten()
                    .cloned()
            })
            .collect::<std::collections::BTreeSet<_>>();
        let captures = ids
            .iter()
            .filter_map(|connection_id| {
                let record = state.grants.get(connection_id)?;
                Some(
                    record
                        .authority
                        .terminal_capture(connection_id.clone(), record.grant_id.clone())
                        .after_mint_only_containment(),
                )
            })
            .collect::<Vec<_>>();
        for capture in &captures {
            before_remove(capture);
        }
        for connection_id in &ids {
            state
                .remove_grant(connection_id)
                .expect("terminalized service grant remains installed under registry ownership");
        }
        if !ids.is_empty() {
            state.pressure_mint_only = true;
        }
        captures
    }

    /// Resolve and account for one connection-open credential before the
    /// handler considers id reuse. This is the only production constructor
    /// for `BoundGrantAuthority`.
    fn prepare_open_authority(
        &self,
        coordinator: &AuthCoordinator,
        presented: PresentedSessionBearer<'_>,
        epoch_now_ms: u64,
        monotonic_now: Instant,
    ) -> Result<PreparedConnectionOpenAuthority, ApiError> {
        let incarnation = coordinator
            .authorization_stream_incarnation()
            .map_err(ApiError::from)?;
        match presented {
            PresentedSessionBearer::Absent => {
                self.consume_anonymous_open(&incarnation, monotonic_now)?;
                let prepared = coordinator
                    .prepare_anonymous_connection()
                    .map_err(ApiError::from)?;
                Ok(PreparedConnectionOpenAuthority {
                    resolved: ResolvedAppAuthority::Anonymous,
                    managed_authority: true,
                    hosted_sender: None,
                    bound: BoundGrantAuthority::Anonymous {
                        authorization_stream_incarnation: prepared.authorization_stream_incarnation,
                        publication: prepared.publication,
                    },
                })
            }
            PresentedSessionBearer::Malformed => {
                self.consume_anonymous_open(&incarnation, monotonic_now)?;
                Err(ApiError::from(SnapbackError::error(
                    "SNAPBACK_AUTH_REQUIRED",
                    "auth",
                    "authentication is required",
                )))
            }
            PresentedSessionBearer::Candidate(raw) => {
                // @ref LLP 0077#author-decisions--2026-07-23 — decision 4: both session
                // spellings resolve here; on hosted lanes the sender
                // admission has already proof-gated an `sbs2_` presentation.
                let Ok(bearer) = SessionBearer::parse_any_version(raw) else {
                    self.consume_anonymous_open(&incarnation, monotonic_now)?;
                    return Err(ApiError::from(SnapbackError::error(
                        "SNAPBACK_AUTH_REQUIRED",
                        "auth",
                        "authentication is required",
                    )));
                };
                match coordinator
                    .classify_connection_bearer(&bearer, epoch_now_ms, monotonic_now)
                    .map_err(ApiError::from)?
                {
                    ConnectionBearerResolution::Current(prepared) => {
                        let (resolved, incarnation, deadline_ms, publication) =
                            prepared.into_parts();
                        let ResolvedAppAuthority::Session {
                            user_id,
                            session_id,
                            provider,
                            generation,
                            ..
                        } = &resolved
                        else {
                            unreachable!("connection session preparation is session authority")
                        };
                        self.consume_session_open(
                            BoundSessionKey {
                                authorization_stream_incarnation: incarnation.clone(),
                                session_id: session_id.clone(),
                                generation: *generation,
                            },
                            monotonic_now,
                        )?;
                        Ok(PreparedConnectionOpenAuthority {
                            managed_authority: true,
                            hosted_sender: None,
                            bound: BoundGrantAuthority::Session {
                                authorization_stream_incarnation: incarnation,
                                session_id: session_id.clone(),
                                user_id: user_id.clone(),
                                provider: provider.clone(),
                                generation: *generation,
                                deadline_ms,
                                publication,
                            },
                            resolved,
                        })
                    }
                    ConnectionBearerResolution::Superseded(key) => {
                        self.consume_session_open(key.into(), monotonic_now)?;
                        Err(ApiError::from(SnapbackError::error(
                            "SNAPBACK_AUTH_CREDENTIAL_SUPERSEDED",
                            "auth",
                            "authentication credential has been superseded",
                        )))
                    }
                    ConnectionBearerResolution::Unavailable(key) => {
                        self.consume_session_open(key.into(), monotonic_now)?;
                        Err(ApiError::from(SnapbackError::error(
                            "SNAPBACK_AUTH_REQUIRED",
                            "auth",
                            "authentication is required",
                        )))
                    }
                    ConnectionBearerResolution::Unknown {
                        authorization_stream_incarnation,
                    } => {
                        self.consume_unknown_open(
                            &authorization_stream_incarnation,
                            monotonic_now,
                        )?;
                        Err(ApiError::from(SnapbackError::error(
                            "SNAPBACK_AUTH_REQUIRED",
                            "auth",
                            "authentication is required",
                        )))
                    }
                }
            }
        }
    }

    /// Detached/test embeddings may intentionally run active Dev without the
    /// pre-bind AuthRuntime composition used by the CLI. Keep that legacy
    /// posture anonymous-only while still applying the same coarse throttle;
    /// Sessions mode never enters this seam.
    fn prepare_unmanaged_dev_open(
        &self,
        presented: PresentedSessionBearer<'_>,
        monotonic_now: Instant,
    ) -> Result<PreparedConnectionOpenAuthority, ApiError> {
        let (incarnation, publication) =
            FencedPublication::anonymous_for_unmanaged_dev_connection();
        self.consume_anonymous_open(&incarnation, monotonic_now)?;
        match presented {
            PresentedSessionBearer::Absent => Ok(PreparedConnectionOpenAuthority {
                resolved: ResolvedAppAuthority::Anonymous,
                managed_authority: false,
                hosted_sender: None,
                bound: BoundGrantAuthority::Anonymous {
                    authorization_stream_incarnation: incarnation,
                    publication,
                },
            }),
            PresentedSessionBearer::Malformed | PresentedSessionBearer::Candidate(_) => {
                Err(ApiError::from(SnapbackError::error(
                    "SNAPBACK_AUTH_REQUIRED",
                    "auth",
                    "session credentials are unavailable while auth mode is dev",
                )))
            }
        }
    }

    fn consume_anonymous_open(
        &self,
        incarnation: &str,
        monotonic_now: Instant,
    ) -> Result<(), ApiError> {
        self.lock()
            .consume_anonymous_open(incarnation, monotonic_now)
            .map_err(ApiError::auth_throttled)
    }

    fn consume_unknown_open(
        &self,
        incarnation: &str,
        monotonic_now: Instant,
    ) -> Result<(), ApiError> {
        self.lock()
            .consume_unknown_open(incarnation, monotonic_now)
            .map_err(ApiError::auth_throttled)
    }

    fn consume_session_open(
        &self,
        key: BoundSessionKey,
        monotonic_now: Instant,
    ) -> Result<(), ApiError> {
        self.lock()
            .consume_session_open(key, monotonic_now)
            .map_err(ApiError::auth_throttled)
    }

    fn consume_service_open(
        &self,
        token_hash: [u8; 32],
        monotonic_now: Instant,
    ) -> Result<(), ApiError> {
        self.lock()
            .consume_service_open(token_hash, monotonic_now)
            .map_err(ApiError::auth_throttled)
    }

    fn consume_agent_route(
        &self,
        path: &'static str,
        source: AgentRouteThrottleSource,
        monotonic_now: Instant,
    ) -> Result<(), ApiError> {
        let Some(limit) = agent_route_throttle_limit(path) else {
            return Ok(());
        };
        self.lock()
            .consume_agent_route(path, source, limit, monotonic_now)
            .map_err(ApiError::auth_throttled)
    }

    fn consume_external_api(
        &self,
        source: ExternalApiThrottleSource,
        limit: usize,
        monotonic_now: Instant,
    ) -> Result<(), u64> {
        self.lock()
            .consume_external_api(source, limit, monotonic_now)
    }

    /// Open a grant. A caller-suggested id is adopted only in non-prod
    /// profiles (trusted local: readable ids keep demos, acceptance suites,
    /// and gated-inspect output debuggable) and only while unclaimed — a
    /// suggestion that collides with a live grant gets a minted id instead of
    /// a token rotation, so an existing connection's bearer can never be
    /// displaced by a later caller. Prod always mints: connection ids leaving
    /// the trusted posture are unguessable, never caller-selected.
    ///
    /// Re-open idempotence: a caller presenting the id's CURRENT token gets
    /// the same grant back (any profile — possession of the bearer already
    /// proves ownership). This is what lets a client hold one connection
    /// identity across reconnects and server restarts: after a restart the
    /// registry is empty, so the suggestion is simply adopted afresh.
    fn open_prepared(
        &self,
        attempt: ConnectionOpenAttempt<'_>,
    ) -> SnapbackResult<OpenedConnectionGrant> {
        let ConnectionOpenAttempt {
            suggested,
            previous_token,
            allow_suggested,
            prepared,
            now_ms,
            monotonic_now,
            auth_invalidation_protocol,
            wire_version_offer,
            ephemeral_authority_protocol,
            ephemeral_authority_instance,
            hosted_ephemeral_authority_required,
            ephemeral_expiry_protocol,
            admission,
        } = attempt;
        let PreparedConnectionOpenAuthority {
            resolved: _,
            managed_authority,
            bound,
            hosted_sender,
        } = prepared;
        if hosted_ephemeral_authority_required
            && ephemeral_authority_protocol
                != Some(crate::ephemeral::EPHEMERAL_AUTHORITY_PROTOCOL_V1)
        {
            return Err(SnapbackError::error(
                "SNAPBACK_EPHEMERAL_AUTHORITY_UNSUPPORTED",
                "ephemeral",
                "this hosted target requires ephemeralAuthorityProtocol 1",
            ));
        }
        if hosted_ephemeral_authority_required && ephemeral_authority_instance.is_none() {
            return Err(SnapbackError::error(
                "SNAPBACK_EPHEMERAL_AUTHORITY_INSTANCE_REQUIRED",
                "ephemeral",
                "this hosted target has no current ephemeral authority instance",
            ));
        }
        let publication_bound = bound.clone();
        let stale = bound.stale_error_at(now_ms);
        let mut retirement = None;
        let result = publication_bound.try_publish(now_ms, monotonic_now, || {
            let mut grants = self.lock();
            let _mode_publication = admission
                .map(|admission| admission.effect_guard("connection grant publication"))
                .transpose()?;
            if let (Some(id), Some(previous)) = (suggested.as_ref(), previous_token)
                && grants
                    .grants
                    .get(id)
                    .is_some_and(|existing| constant_time_str_eq(&existing.token, previous))
            {
                if grants
                    .grants
                    .get(id)
                    .is_some_and(|existing| existing.socket_teardown.is_some())
                {
                    return Err(SnapbackError::error(
                        "SNAPBACK_CONNECTION_TEARDOWN_PENDING",
                        "realtime",
                        "the current socket is still completing exact connection teardown",
                    ));
                }
                let same_authority = grants.grants.get(id).is_some_and(|existing| {
                    existing.authority.same_identity(&bound)
                        && existing.hosted_sender == hosted_sender
                });
                if !same_authority {
                    if let Some(record) = grants.remove_grant(id) {
                        retirement = Some(
                            record
                                .authority
                                .terminal_capture(id.clone(), record.grant_id)
                                .after_mint_only_containment(),
                        );
                    }
                    grants.pressure_mint_only = true;
                    return Err(SnapbackError::error(
                        "SNAPBACK_CONNECTION_AUTHORITY_MISMATCH",
                        "auth",
                        "the previous connection token is bound to different authority",
                    ));
                }
                // Re-open matrix (LLP 0094 §0B.3): the binding fixed at first
                // open is immutable for the lineage. The offer reaching here
                // is already classified known, so a present offer that does
                // not equal the lineage's bound version — explicit, or the
                // implicit v1 of a legacy lineage — is exactly a mismatch
                // (never an unknown-token refusal, which the handler owns).
                //
                // @ref LLP 0094#0b3-the-wireversion-open-time-offer — a
                //   changed offer under `previousToken` refuses and leaves
                //   the existing connection, socket, and subscriptions
                //   undisturbed; a confirming offer on a legacy lineage never
                //   upgrades it.
                let lineage_wire_version = grants
                    .grants
                    .get(id)
                    .and_then(|existing| existing.wire_version.clone());
                let lineage_ephemeral_authority_protocol = grants
                    .grants
                    .get(id)
                    .and_then(|existing| existing.ephemeral_authority_protocol);
                let lineage_ephemeral_authority_instance = grants
                    .grants
                    .get(id)
                    .and_then(|existing| existing.ephemeral_authority_instance.clone());
                let lineage_hosted_ephemeral_authority_required = grants
                    .grants
                    .get(id)
                    .is_some_and(|existing| existing.hosted_ephemeral_authority_required);
                let lineage_ephemeral_expiry_protocol = grants
                    .grants
                    .get(id)
                    .and_then(|existing| existing.ephemeral_expiry_protocol);
                if let Some(offer) = wire_version_offer.as_deref() {
                    let bound_version = lineage_wire_version
                        .as_deref()
                        .unwrap_or(crate::wire_version::WIRE_VERSION_V1);
                    if offer != bound_version {
                        return Err(SnapbackError::error(
                            "SNAPBACK_WIRE_VERSION_MISMATCH",
                            "realtime",
                            "the wire-version offer does not equal this connection lineage's bound version; open a fresh connection to change versions",
                        ));
                    }
                }
                if lineage_hosted_ephemeral_authority_required
                    && ephemeral_authority_protocol.is_none()
                {
                    return Err(SnapbackError::error(
                        "SNAPBACK_EPHEMERAL_AUTHORITY_UNSUPPORTED",
                        "ephemeral",
                        "this hosted connection lineage requires ephemeralAuthorityProtocol 1 on every reopen",
                    ));
                }
                if hosted_ephemeral_authority_required
                    != lineage_hosted_ephemeral_authority_required
                {
                    return Err(SnapbackError::error(
                        "SNAPBACK_EPHEMERAL_AUTHORITY_INSTANCE_CHANGED",
                        "ephemeral",
                        "the hosted ephemeral authority requirement changed; open a fresh connection",
                    ));
                }
                if let Some(offer) = ephemeral_authority_protocol {
                    let Some(bound) = lineage_ephemeral_authority_protocol else {
                        return Err(SnapbackError::error(
                            "SNAPBACK_EPHEMERAL_AUTHORITY_PROTOCOL_MISMATCH",
                            "ephemeral",
                            "a legacy connection lineage cannot be upgraded in place",
                        ));
                    };
                    if offer != bound {
                        return Err(SnapbackError::error(
                            "SNAPBACK_EPHEMERAL_AUTHORITY_PROTOCOL_MISMATCH",
                            "ephemeral",
                            "the ephemeral authority offer does not equal this lineage",
                        ));
                    }
                    if ephemeral_authority_instance != lineage_ephemeral_authority_instance {
                        return Err(SnapbackError::error(
                            "SNAPBACK_EPHEMERAL_AUTHORITY_INSTANCE_CHANGED",
                            "ephemeral",
                            "the hosted ephemeral authority changed; open a fresh connection",
                        ));
                    }
                }
                if let Some(offer) = ephemeral_expiry_protocol {
                    let Some(bound) = lineage_ephemeral_expiry_protocol else {
                        return Err(SnapbackError::error(
                            "SNAPBACK_EPHEMERAL_EXPIRY_PROTOCOL_MISMATCH",
                            "ephemeral",
                            "a legacy connection lineage cannot be upgraded to an expiry protocol in place",
                        ));
                    };
                    if offer != bound {
                        return Err(SnapbackError::error(
                            "SNAPBACK_EPHEMERAL_EXPIRY_PROTOCOL_MISMATCH",
                            "ephemeral",
                            "the ephemeral expiry offer does not equal this lineage",
                        ));
                    }
                }
                let existing = grants
                    .grants
                    .get_mut(id)
                    .expect("exact previous grant remains installed");
                existing.authority = bound.clone();
                existing.managed_authority = managed_authority;
                existing.hosted_sender = hosted_sender.clone();
                let grant_id = existing.grant_id.clone();
                let connection_token = existing.token.clone();
                let authorization_invalidation = existing.authorization_invalidation.clone();
                grants.touch(id, now_ms);
                return Ok(OpenedConnectionGrant {
                    grant: ConnectionGrant {
                        connection_id: id.clone(),
                        connection_token,
                        authorization_invalidation,
                        // Echo ⇔ explicit binding: a legacy lineage's
                        // confirming re-open offer produces no echo.
                        wire_version: lineage_wire_version,
                        ephemeral_authority_protocol:
                            lineage_ephemeral_authority_protocol,
                        ephemeral_authority_instance:
                            lineage_ephemeral_authority_instance,
                        hosted_ephemeral_authority_required:
                            lineage_hosted_ephemeral_authority_required,
                        ephemeral_expiry_protocol:
                            lineage_ephemeral_expiry_protocol,
                    },
                    grant_id,
                    newly_minted: false,
                });
            }
            retirement = grants.admit_slot(now_ms)?;
            let connection_id = match suggested {
                Some(id)
                    if allow_suggested
                        && !grants.pressure_mint_only
                        && valid_suggested_connection_id(&id)
                        && !grants.grants.contains_key(&id) =>
                {
                    id
                }
                _ => loop {
                    let minted = crate::ids::mint_time_ordered(crate::ids::Kind::Connection);
                    if !grants.grants.contains_key(&minted) {
                        break minted;
                    }
                },
            };
            let grant_id = Uuid::now_v7().to_string();
            // @ref LLP 0077#author-decisions--2026-07-23 — decision 4: sender-bound
            // connection-open mints the structurally distinct `sct2_` grant
            // spelling a v1 verifier cannot accept.
            let connection_token = if hosted_sender.is_some() {
                format!("sct2_{}", Uuid::new_v4().simple())
            } else {
                format!("sct_{}", Uuid::new_v4().simple())
            };
            let authorization_invalidation = if auth_invalidation_protocol
                == Some(crate::auth::invalidation::AUTH_INVALIDATION_PROTOCOL_VERSION)
            {
                self.invalidation_issuer
                    .lock()
                    .unwrap_or_else(std::sync::PoisonError::into_inner)
                    .clone()
                    .map(|issuer| {
                        let issuer_retirement = issuer.authenticate_prior_issuer_retirement()?;
                        Ok::<_, SnapbackError>(
                            crate::auth::invalidation::AuthorizationInvalidationConnection {
                                protocol_version:
                                    crate::auth::invalidation::AUTH_INVALIDATION_PROTOCOL_VERSION,
                                issuer_id: issuer.authenticated().issuer_id.clone(),
                                connection_generation: issuer.reserve_connection_generation()?,
                                authorization: issuer.authorization_expectation()?,
                                version_stream: issuer.version_stream()?,
                                issuer_retirement,
                            },
                        )
                    })
                    .transpose()?
            } else {
                None
            };
            grants.insert(
                connection_id.clone(),
                ConnectionGrantRecord {
                    grant_id: grant_id.clone(),
                    token: connection_token.clone(),
                    authority: bound,
                    hosted_sender,
                    managed_authority,
                    last_use_ms: now_ms,
                    used: false,
                    socket_teardown: None,
                    authorization_invalidation: authorization_invalidation.clone(),
                    wire_version: wire_version_offer.clone(),
                    ephemeral_authority_protocol,
                    ephemeral_authority_instance: ephemeral_authority_instance.clone(),
                    hosted_ephemeral_authority_required,
                    ephemeral_expiry_protocol,
                },
            );
            Ok(OpenedConnectionGrant {
                grant: ConnectionGrant {
                    connection_id,
                    connection_token,
                    authorization_invalidation,
                    wire_version: wire_version_offer.clone(),
                    ephemeral_authority_protocol,
                    ephemeral_authority_instance,
                    hosted_ephemeral_authority_required,
                    ephemeral_expiry_protocol,
                },
                grant_id,
                newly_minted: true,
            })
        });
        if let Some(capture) = retirement {
            // Never call into outbox/room/notifier state while the registry or
            // leaf publication locks are held. The exact-act cut above makes
            // the remove→purge interval non-deliverable.
            self.publish_retirement(capture);
        }
        result?.ok_or(stale)
    }

    /// Retract a fresh grant whose bearer has not been published because the
    /// qualifying-use or final response fence failed. Exact grant identity
    /// prevents cleanup from deleting a replacement that reused the wire id.
    fn discard_unpublished_open(&self, opened: &OpenedConnectionGrant) {
        if !opened.newly_minted {
            return;
        }
        let capture = {
            let mut state = self.lock();
            if state
                .grants
                .get(&opened.grant.connection_id)
                .is_some_and(|record| record.grant_id == opened.grant_id)
            {
                state
                    .remove_grant(&opened.grant.connection_id)
                    .map(|record| {
                        record
                            .authority
                            .terminal_capture(opened.grant.connection_id.clone(), record.grant_id)
                    })
            } else {
                None
            }
        };
        if let Some(capture) = capture {
            self.publish_retirement(capture);
        }
    }

    /// Remove a pending-registration grant for reaping, yielding a
    /// whole-id-cleanup-safe terminal capture (the connection existed only
    /// for the reaped bundle, so whole-id teardown is exact). The caller
    /// publishes the capture so the retirement sink disarms demand and
    /// purges topology.
    fn retire_bundle_connection(
        &self,
        connection_id: &str,
        grant_id: &str,
    ) -> Option<BoundConnectionTerminalCapture> {
        let mut state = self.lock();
        if state
            .grants
            .get(connection_id)
            .is_none_or(|record| record.grant_id != grant_id)
        {
            return None;
        }
        let record = state.remove_grant(connection_id)?;
        Some(
            record
                .authority
                .terminal_capture(connection_id.to_owned(), record.grant_id)
                .after_mint_only_containment(),
        )
    }

    /// Rotate a pending-registration grant's secret in place (LLP 0031 dated
    /// amendment: a lost-response retry returns the registration set under a
    /// freshly rotated connection-grant secret bound to the same connection
    /// identity; re-returning a possibly-exposed secret verbatim is refused).
    fn rotate_grant_token(&self, connection_id: &str, grant_id: &str) -> SnapbackResult<String> {
        let mut state = self.lock();
        let record = state
            .grants
            .get_mut(connection_id)
            .filter(|record| record.grant_id == grant_id)
            .ok_or_else(|| {
                SnapbackError::error(
                    "SNAPBACK_CONNECTION_TOKEN_INVALID",
                    "realtime",
                    "the pending connection grant is no longer installed",
                )
            })?;
        // @ref LLP 0077#author-decisions--2026-07-23 — decision 4: a rotated grant
        // secret keeps its lane's spelling; sender-bound lanes stay `sct2_`.
        let token = if record.hosted_sender.is_some() {
            format!("sct2_{}", Uuid::new_v4().simple())
        } else {
            format!("sct_{}", Uuid::new_v4().simple())
        };
        record.token = token.clone();
        Ok(token)
    }

    /// The effect fence and invalidation connection for an installed grant —
    /// the register-mode supersede path re-derives the pending connection's
    /// registration identity from the registry record.
    fn bundle_register_identity(
        &self,
        connection_id: &str,
        grant_id: &str,
    ) -> Option<(
        crate::ephemeral::ConnectionEffectFence,
        Option<crate::auth::invalidation::AuthorizationInvalidationConnection>,
    )> {
        let state = self.lock();
        let record = state
            .grants
            .get(connection_id)
            .filter(|record| record.grant_id == grant_id)?;
        Some((
            record.authority.effect_fence(grant_id),
            record.authorization_invalidation.clone(),
        ))
    }

    /// Refresh the grant's mutable cached lease after authenticated-use
    /// publication. The immutable authority identity and grant id must still
    /// match at the session fence cut.
    fn refresh_open_deadline(
        &self,
        opened: &OpenedConnectionGrant,
        prepared: &PreparedConnectionOpenAuthority,
        deadline_ms: u64,
        epoch_now_ms: u64,
        monotonic_now: Instant,
    ) -> SnapbackResult<()> {
        let stale = prepared.bound.stale_error_at(epoch_now_ms);
        prepared
            .bound
            .publication()
            .try_publish(epoch_now_ms, monotonic_now, || {
                let mut state = self.lock();
                let Some(record) = state.grants.get_mut(&opened.grant.connection_id) else {
                    return Ok(false);
                };
                if record.grant_id != opened.grant_id
                    || !record.authority.same_identity(&prepared.bound)
                {
                    return Ok(false);
                }
                if let BoundGrantAuthority::Session {
                    deadline_ms: cached,
                    ..
                } = &mut record.authority
                {
                    *cached = deadline_ms;
                }
                Ok(true)
            })?
            .filter(|updated| *updated)
            .map(|_| ())
            .ok_or(stale)
    }

    fn refresh_act_deadline(
        &self,
        prepared: &PreparedConnectionAct,
        deadline_ms: u64,
        epoch_now_ms: u64,
        monotonic_now: Instant,
    ) -> SnapbackResult<()> {
        let stale = prepared.bound.stale_error_at(epoch_now_ms);
        prepared
            .bound
            .publication()
            .try_publish(epoch_now_ms, monotonic_now, || {
                let mut state = self.lock();
                let Some(record) = state.grants.get_mut(&prepared.connection_id) else {
                    return Ok(false);
                };
                if record.grant_id != prepared.grant_id
                    || !record.authority.same_identity(&prepared.bound)
                {
                    return Ok(false);
                }
                if let BoundGrantAuthority::Session {
                    deadline_ms: cached,
                    ..
                } = &mut record.authority
                {
                    *cached = deadline_ms;
                }
                Ok(true)
            })?
            .filter(|updated| *updated)
            .map(|_| ())
            .ok_or(stale)
    }

    /// Legacy Rust embedding seam used by dev/test harnesses that construct
    /// grants before installing an auth coordinator. The record is marked
    /// unmanaged and sessions-mode middleware refuses it; production HTTP
    /// opens exclusively through projection-backed `open_prepared`.
    #[doc(hidden)]
    pub fn open(
        &self,
        suggested: Option<String>,
        previous_token: Option<&str>,
        allow_suggested: bool,
    ) -> SnapbackResult<ConnectionGrant> {
        let (incarnation, publication) =
            FencedPublication::anonymous_for_unmanaged_dev_connection();
        self.open_prepared(ConnectionOpenAttempt::new(
            suggested,
            previous_token,
            allow_suggested,
            PreparedConnectionOpenAuthority {
                resolved: ResolvedAppAuthority::Anonymous,
                managed_authority: false,
                hosted_sender: None,
                bound: BoundGrantAuthority::Anonymous {
                    authorization_stream_incarnation: incarnation,
                    publication,
                },
            },
            now_millis(),
            Instant::now(),
            None,
        ))
        .map(|opened| opened.grant)
    }

    fn resolve_room_connection_authority(
        &self,
        connection_id: &str,
        expected_effect_fence: Option<&crate::ephemeral::ConnectionEffectFence>,
        coordinator: Option<&AuthCoordinator>,
        epoch_now_ms: u64,
        monotonic_now: Instant,
    ) -> SnapbackResult<ResolvedRoomConnectionAuthority> {
        let (grant_id, managed_authority, bound) = {
            let state = self.lock();
            let Some(record) = state.grants.get(connection_id) else {
                return Ok(ResolvedRoomConnectionAuthority::Absent);
            };
            (
                record.grant_id.clone(),
                record.managed_authority,
                record.authority.clone(),
            )
        };
        if matches!(bound, BoundGrantAuthority::ServicePrincipal { .. }) {
            return Err(SnapbackError::error(
                "SNAPBACK_AUTH_POLICY_UNAVAILABLE",
                "auth",
                "grant-backed live and ephemeral operations are unavailable until the agent live fence is ready",
            )
            .with_details(json!({ "capability": "grantBackedLive" })));
        }
        let effect_fence = bound.effect_fence(&grant_id);
        if expected_effect_fence.is_some_and(|expected| expected != &effect_fence) {
            return Ok(ResolvedRoomConnectionAuthority::Replaced);
        }
        let resolved = if !managed_authority {
            None
        } else {
            match &bound {
                BoundGrantAuthority::Anonymous { .. } => Some(ResolvedAppAuthority::Anonymous),
                BoundGrantAuthority::ServicePrincipal { .. } => {
                    unreachable!("service-principal room authority refused above")
                }
                BoundGrantAuthority::Session {
                    authorization_stream_incarnation,
                    session_id,
                    user_id,
                    provider,
                    generation,
                    ..
                } => match coordinator {
                    Some(coordinator) => {
                        let resolution = coordinator.resolve_bound_connection_session(
                            authorization_stream_incarnation,
                            session_id,
                            user_id,
                            provider,
                            *generation,
                            epoch_now_ms,
                            monotonic_now,
                        )?;
                        match resolution {
                            BoundSessionResolution::Current(resolved) => Some(resolved),
                            BoundSessionResolution::Terminal { .. }
                            | BoundSessionResolution::Unavailable => None,
                        }
                    }
                    None => None,
                },
            }
        };
        let current = bound
            .publication()
            .try_publish(epoch_now_ms, monotonic_now, || {
                Ok(self.lock().grants.get(connection_id).is_some_and(|record| {
                    record.grant_id == grant_id
                        && record.socket_teardown.is_none()
                        && record.authority.effect_fence(&record.grant_id) == effect_fence
                }))
            })?;
        if current != Some(true) {
            return Ok(ResolvedRoomConnectionAuthority::Replaced);
        }
        Ok(ResolvedRoomConnectionAuthority::Current {
            auth: resolved.as_ref().map(ephemeral_auth_from_authority),
            effect_fence,
        })
    }

    /// Verify a presented token for one connection-scoped operation. Unknown
    /// connections and token mismatches share one diagnostic code so the gate
    /// is not an existence oracle for the connection-id namespace.
    fn prepare_act(
        &self,
        connection_id: &str,
        presented: Option<&str>,
        coordinator: Option<&AuthCoordinator>,
        allow_unmanaged_dev: bool,
        epoch_now_ms: u64,
        monotonic_now: Instant,
    ) -> Result<PreparedConnectionAct, ApiError> {
        let Some(presented) = presented else {
            return Err(connection_auth_error(
                "SNAPBACK_CONNECTION_TOKEN_REQUIRED",
                "connection-scoped operations require the connection token issued by POST /connection/open",
                connection_id,
            ));
        };
        let (
            grant_id,
            bound,
            authorization_invalidation,
            ephemeral_authority_protocol,
            ephemeral_authority_instance,
            hosted_ephemeral_authority_required,
        ) = {
            let grants = self.lock();
            let Some(record) = grants
                .grants
                .get(connection_id)
                .filter(|expected| constant_time_str_eq(&expected.token, presented))
            else {
                return Err(connection_auth_error(
                    "SNAPBACK_CONNECTION_TOKEN_INVALID",
                    "connection is not open on this server or the token does not match",
                    connection_id,
                ));
            };
            if record.socket_teardown.is_some() {
                return Err(connection_teardown_pending(connection_id));
            }
            if !record.managed_authority && !allow_unmanaged_dev {
                return Err(connection_auth_error(
                    "SNAPBACK_CONNECTION_TOKEN_INVALID",
                    "connection authority is unavailable in sessions mode",
                    connection_id,
                ));
            }
            (
                record.grant_id.clone(),
                record.authority.clone(),
                record.authorization_invalidation.clone(),
                record.ephemeral_authority_protocol,
                record.ephemeral_authority_instance.clone(),
                record.hosted_ephemeral_authority_required,
            )
        };
        let resolved = match &bound {
            BoundGrantAuthority::Anonymous { .. } => ResolvedAppAuthority::Anonymous,
            BoundGrantAuthority::ServicePrincipal {
                authority,
                service_publication,
                ..
            } => {
                match service_publication
                    .resolve_act(epoch_now_ms, monotonic_now)
                    .map_err(ApiError::from)?
                {
                    ServiceAuthorityActResolution::Current(_) => {}
                    ServiceAuthorityActResolution::Terminal(disposition) => {
                        let disposition = match disposition {
                            ServiceAuthorityDisposition::Carrier => {
                                HttpAuthorityDisposition::Carrier
                            }
                            ServiceAuthorityDisposition::DurableDelete => {
                                HttpAuthorityDisposition::DurableDelete
                            }
                        };
                        return Err(ApiError::from(scoped_token_invalid_http(
                            "the connection scoped token authority is no longer current",
                            disposition,
                        )));
                    }
                    ServiceAuthorityActResolution::Unavailable => {
                        return Err(ApiError::from(SnapbackError::error(
                            "SNAPBACK_AUTH_POLICY_UNAVAILABLE",
                            "auth",
                            "finite service authority termination is unresolved",
                        )));
                    }
                }
                authority.clone()
            }
            BoundGrantAuthority::Session {
                authorization_stream_incarnation,
                session_id,
                user_id,
                provider,
                generation,
                ..
            } => {
                let coordinator = coordinator.ok_or_else(|| {
                    ApiError::from(SnapbackError::error(
                        "SNAPBACK_AUTH_PROJECTION_UNAVAILABLE",
                        "auth",
                        "authentication projection is unavailable",
                    ))
                })?;
                match coordinator
                    .resolve_bound_connection_session(
                        authorization_stream_incarnation,
                        session_id,
                        user_id,
                        provider,
                        *generation,
                        epoch_now_ms,
                        monotonic_now,
                    )
                    .map_err(ApiError::from)?
                {
                    BoundSessionResolution::Current(resolved) => resolved,
                    BoundSessionResolution::Terminal { reason } => {
                        return Err(ApiError::from(session_expired_http(
                            "the connection session is no longer current",
                            session_http_authority_disposition(reason),
                        )));
                    }
                    BoundSessionResolution::Unavailable => {
                        return Err(ApiError::from(bound.stale_error_at(epoch_now_ms)));
                    }
                }
            }
        };
        Ok(PreparedConnectionAct {
            connection_id: connection_id.to_owned(),
            grant_id,
            resolved,
            bound,
            authorization_invalidation,
            ephemeral_authority_protocol,
            ephemeral_authority_instance,
            hosted_ephemeral_authority_required,
        })
    }

    #[cfg(test)]
    pub fn verify(&self, connection_id: &str, presented: Option<&str>) -> Result<(), ApiError> {
        let prepared = self.prepare_act(
            connection_id,
            presented,
            None,
            true,
            now_millis(),
            Instant::now(),
        )?;
        prepared.try_act(self, now_millis(), Instant::now(), || Ok(()))
    }

    fn authenticate_presented_bearer(&self, presented: Option<&str>) -> Result<(), ApiError> {
        let Some(presented) = presented else {
            return Err(connection_auth_error(
                "SNAPBACK_CONNECTION_TOKEN_REQUIRED",
                "connection-scoped operations require the connection token issued by POST /connection/open",
                "",
            ));
        };
        let grants = self.lock();
        // Do not replace this with Iterator::any: it short-circuits and leaks
        // which registry entry matched through request timing.
        // @ref LLP 0039#session-transport-and-connection-binding — grant
        // verification uses constant-time comparison under the small registry lock.
        #[allow(clippy::unnecessary_fold)]
        let valid = grants.grants.values().fold(false, |valid, record| {
            constant_time_str_eq(&record.token, presented) || valid
        });
        if valid {
            Ok(())
        } else {
            Err(connection_auth_error(
                "SNAPBACK_CONNECTION_TOKEN_INVALID",
                "connection token is not open on this server",
                "",
            ))
        }
    }

    fn hosted_sender_for_presented_grant(
        &self,
        presented: Option<&str>,
    ) -> Option<HostedSenderGrantBinding> {
        let presented = presented?;
        self.lock().grants.values().fold(None, |binding, record| {
            if constant_time_str_eq(&record.token, presented) {
                record.hosted_sender.clone()
            } else {
                binding
            }
        })
    }

    /// Renew an already-authenticated WebSocket lease on frame traffic. The
    /// upgrade verified the bearer once; subsequent frames do not carry it,
    /// but they are still proof that this exact authorized socket is active.
    #[cfg(test)]
    fn touch_verified_socket(&self, connection_id: &str) -> bool {
        let prepared = {
            let state = self.lock();
            let Some(record) = state.grants.get(connection_id) else {
                return false;
            };
            PreparedConnectionAct {
                connection_id: connection_id.to_owned(),
                grant_id: record.grant_id.clone(),
                resolved: ResolvedAppAuthority::Anonymous,
                bound: record.authority.clone(),
                authorization_invalidation: record.authorization_invalidation.clone(),
                ephemeral_authority_protocol: record.ephemeral_authority_protocol,
                ephemeral_authority_instance: record.ephemeral_authority_instance.clone(),
                hosted_ephemeral_authority_required: record.hosted_ephemeral_authority_required,
            }
        };
        prepared
            .try_act(self, now_millis(), Instant::now(), || Ok(()))
            .is_ok()
    }

    fn lock(&self) -> RankedMutexGuard<'_, ConnectionRegistryState> {
        ranked_mutex_lock_unpoisoned(&self.grants, AUTH_LOCK_RANK_CONNECTION_REGISTRY)
    }
}

impl PreparedConnectionAct {
    pub(crate) fn terminal_capture(&self) -> BoundConnectionTerminalCapture {
        self.bound
            .terminal_capture(self.connection_id.clone(), self.grant_id.clone())
    }

    /// Convert the current socket registration into a split-teardown claim
    /// while the exact grant is temporarily suspended. Registry then notifier
    /// is the same order used by connection acts; no lock escapes this call.
    /// A stale socket generation returns `None` and owns no cleanup.
    fn begin_socket_teardown(
        &self,
        registry: &ConnectionRegistry,
        notifier: &Arc<crate::ephemeral::DeliveryNotifier>,
        generation: u64,
    ) -> Option<BoundSocketTeardown> {
        let mut state = registry.lock();
        let grant_is_current = state.grants.get(&self.connection_id).is_some_and(|record| {
            record.grant_id == self.grant_id && record.socket_teardown.is_none()
        });
        let delivery = notifier.begin_teardown(&self.connection_id, generation)?;
        if grant_is_current {
            state
                .grants
                .get_mut(&self.connection_id)
                .expect("the registry guard preserves the checked grant")
                .socket_teardown = Some(generation);
        }
        Some(BoundSocketTeardown {
            registry: registry.clone(),
            connection_id: self.connection_id.clone(),
            grant_id: self.grant_id.clone(),
            generation,
            suspended_current_grant: grant_is_current,
            delivery: Some(delivery),
            finished: false,
        })
    }

    fn try_act<T>(
        &self,
        registry: &ConnectionRegistry,
        epoch_now_ms: u64,
        monotonic_now: Instant,
        act: impl FnOnce() -> Result<T, ApiError>,
    ) -> Result<T, ApiError> {
        let mut outcome = None;
        // Publication → registry is the canonical order also used by open and
        // retirement. Keep the registry guard through the bounded synchronous
        // act so removal cannot linearize between exact-grant validation and
        // an outbox acknowledgement or writer `try_send`.
        let published = self
            .bound
            .try_publish(epoch_now_ms, monotonic_now, || {
                let mut state = registry.lock();
                let current = state.grants.get(&self.connection_id).is_some_and(|record| {
                    record.grant_id == self.grant_id && record.socket_teardown.is_none()
                });
                if !current {
                    return Err(SnapbackError::error(
                        "SNAPBACK_CONNECTION_TOKEN_INVALID",
                        "realtime",
                        "the connection grant is no longer current",
                    ));
                }
                state.touch(&self.connection_id, epoch_now_ms);
                outcome = Some(act());
                Ok(())
            })
            .map_err(ApiError::from)?;
        if published.is_none() {
            return Err(ApiError::from(self.bound.stale_error_at(epoch_now_ms)));
        }
        outcome.expect("a successful fenced connection act records its outcome")
    }
}

/// Lock-free ownership of one ordinary socket-close cleanup. The reusable
/// connection grant remains installed but refuses acts until `finish`; the
/// notifier claim independently prevents a same-id socket registration.
#[must_use = "socket teardown ownership must move into cleanup and finish explicitly"]
struct BoundSocketTeardown {
    registry: ConnectionRegistry,
    connection_id: String,
    grant_id: String,
    generation: u64,
    suspended_current_grant: bool,
    delivery: Option<crate::ephemeral::DeliveryTeardownClaim>,
    finished: bool,
}

impl BoundSocketTeardown {
    fn suspended_current_grant(&self) -> bool {
        self.suspended_current_grant
    }

    fn finish(mut self) {
        self.release();
    }

    fn release(&mut self) {
        if self.finished {
            return;
        }
        let mut state = self.registry.lock();
        if let Some(record) = state.grants.get_mut(&self.connection_id)
            && record.grant_id == self.grant_id
            && record.socket_teardown == Some(self.generation)
        {
            record.socket_teardown = None;
        }
        if let Some(delivery) = self.delivery.take() {
            // Registry -> notifier is the canonical connection publication
            // order; neither lock overlaps LocalSnapback or ephemeral rooms.
            delivery.finish();
        }
        self.finished = true;
    }
}

impl Drop for BoundSocketTeardown {
    fn drop(&mut self) {
        // Fail closed on a cleanup-task panic. Ordinary cancellation cannot
        // reach this owner because teardown moves it into an independently
        // spawned task before awaiting completion.
    }
}

fn connection_auth_error(code: &str, message: &str, connection_id: &str) -> ApiError {
    ApiError(
        SnapbackError::new(
            Diagnostic::error(code, "realtime", message)
                .with_details(json!({ "connection_id": connection_id })),
        ),
        None,
        None,
        None,
        None,
    )
}

fn connection_teardown_pending(connection_id: &str) -> ApiError {
    ApiError::from(
        SnapbackError::error(
            "SNAPBACK_CONNECTION_TEARDOWN_PENDING",
            "realtime",
            "the current socket is still completing exact connection teardown",
        )
        .with_details(json!({ "connection_id": connection_id })),
    )
}

fn live_finalize_task_failed() -> ApiError {
    ApiError::from(SnapbackError::error(
        "SNAPBACK_LIVE_FINALIZE_FAILED",
        "realtime",
        "the owned live-effect finalization task did not complete",
    ))
}

/// Constant-time token comparison (length is public: tokens are fixed-form).
pub(crate) fn constant_time_str_eq(a: &str, b: &str) -> bool {
    let (a, b) = (a.as_bytes(), b.as_bytes());
    if a.len() != b.len() {
        return false;
    }
    a.iter().zip(b).fold(0u8, |acc, (x, y)| acc | (x ^ y)) == 0
}

/// The connection-token transports: the header for HTTP callers, the query
/// parameter and `snapback.connection-token.<token>` subprotocol for WebSocket
/// upgrades (a browser `WebSocket` cannot set request headers).
const CONNECTION_TOKEN_HEADER: &str = "x-snapback-connection-token";
const CONNECTION_TOKEN_SUBPROTOCOL_PREFIX: &str = "snapback.connection-token.";
const EPHEMERAL_AUTHORITY_INSTANCE_HEADER: &str = "x-snapback-ephemeral-authority-instance";
const EPHEMERAL_AUTHORITY_INSTANCE_SUBPROTOCOL_PREFIX: &str =
    "snapback.ephemeral-authority-instance.";
const SENDER_PROOF_SUBPROTOCOL_PREFIX: &str = "snapback.sender-proof.";
/// The negotiated live-stream subprotocol. The kit always offers this
/// alongside the token subprotocol so the server has a legal echo (a browser
/// fails the connection when it offered subprotocols and the server selected
/// none). Byte-identical to the wire-version token (LLP 0094 §0B.1): the
/// socket offer IS the wire-version offer.
const LIVE_STREAM_SUBPROTOCOL: &str = crate::wire_version::WIRE_VERSION_V1;
const MAX_LIVE_SOCKET_FRAME_BYTES: usize = 64 * 1_024;
const MAX_CONNECTION_GRANTS: usize = 16_384;
const CONNECTION_GRANT_IDLE_TTL_MS: u64 = CONNECTION_IDLE_TTL_MS;
const CONNECTION_OPEN_SESSION_LIMIT: usize = 60;
const CONNECTION_OPEN_COARSE_LIMIT: usize = 240;
const CONNECTION_OPEN_WINDOW: Duration = Duration::from_secs(60);
const AGENT_ROUTE_THROTTLE_WINDOW: Duration = Duration::from_secs(60);
const AGENT_ROUTE_THROTTLE_SOURCE_CAP: usize = 4_096;
const EXTERNAL_API_ROUTE_FAMILY: &str = "api.v1";
const EXTERNAL_API_THROTTLE_WINDOW: Duration = Duration::from_secs(60);
const EXTERNAL_API_THROTTLE_KEY_CAP: usize = 20_000;
/// @ref LLP 0071#declared-tier — every external lane first consumes the same
/// low-cardinality network floor, so minted declared ids cannot multiply it.
const EXTERNAL_API_ANONYMOUS_FLOOR_LIMIT: usize = 60;
/// @ref LLP 0071#bounded-pre-auth-ledger — new high-cardinality ledger rows
/// require a distinct low-cardinality network-evidence creation admission.
const EXTERNAL_API_DECLARED_CREATION_LIMIT: usize = 10;
/// @ref LLP 0071#declared-tier — stable cooperative identification receives
/// a larger per-id budget while retaining the anonymous network floor.
const EXTERNAL_API_DECLARED_LIMIT: usize = 240;
const EXTERNAL_API_INTEGRATION_LIMIT: usize = 600;
/// @ref LLP 0204#d94--shareable-capability-links — a resolved link receives
/// one attributable budget which composes with, and never replaces, the
/// anonymous network floor charged before secret lookup.
const EXTERNAL_API_CAPABILITY_LINK_LIMIT: usize = 240;
const EXTERNAL_API_BLESSED_MULTIPLIER: usize = 4;

/// Each agent-management route owns a distinct closed budget. Equal limits do
/// not share accounting: the canonical route path is the bucket key.
///
/// @ref LLP 0055#routes-and-credential-classes — every route has its own
/// throttle budget, independent of its credential class.
fn agent_route_throttle_limit(path: &str) -> Option<usize> {
    match path {
        "/auth/oauth/register" => Some(10),
        "/auth/oauth/authorize" => Some(60),
        "/auth/oauth/token" => Some(120),
        "/auth/oauth/revoke" => Some(120),
        "/auth/agents/register" => Some(10),
        "/auth/agent-invitations" => Some(10),
        "/auth/pairing-codes" => Some(20),
        "/auth/agents/pair" => Some(60),
        "/auth/grant-requests" => Some(120),
        "/auth/grant-requests/{id}/approve" => Some(60),
        "/auth/grant-requests/{id}/deny" => Some(60),
        "/auth/grants" => Some(120),
        "/auth/grants/by-actor/{actor_id}" => Some(60),
        "/auth/grants/{id}" => Some(60),
        "/effects" => Some(120),
        "/effects/{id}/approve" | "/effects/{id}/deny" => Some(60),
        "/auth/agents/rotate" => Some(10),
        // LLP 0062's process-per-command agent lane mints one short-lived
        // carrier per invocation. Six hundred credential-and-grant-bound
        // attempts per minute admits realistic agent bursts without making
        // the unauthenticated source bucket an authority amplifier.
        "/auth/agents/token" => Some(600),
        "/auth/agents/token/release" => Some(240),
        "/auth/agents/revoke-self" => Some(20),
        _ => None,
    }
}

fn agent_body_throttle_source(body: Option<&Value>) -> AgentRouteThrottleSource {
    let object = body.and_then(Value::as_object);
    let credential = object
        .and_then(|body| body.get("credential"))
        .and_then(Value::as_str)
        .and_then(|credential| AgentCredential::parse(credential).ok());
    if let Some(credential) = credential {
        return AgentRouteThrottleSource::Credential(*credential.token_hash().as_bytes());
    }
    let token = object
        .and_then(|body| body.get("token"))
        .and_then(Value::as_str)
        .and_then(|token| ScopedToken::parse(token).ok());
    match token {
        Some(token) => AgentRouteThrottleSource::Credential(*token.token_hash().as_bytes()),
        None => AgentRouteThrottleSource::Malformed,
    }
}

fn valid_suggested_connection_id(value: &str) -> bool {
    let bytes = value.as_bytes();
    !bytes.is_empty()
        && bytes.len() <= crate::ephemeral::MAX_EPHEMERAL_CONNECTION_ID_BYTES
        && bytes[0].is_ascii_alphanumeric()
        && bytes[1..]
            .iter()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'.' | b'_' | b':' | b'-'))
}

fn header_connection_token(headers: &HeaderMap) -> Option<String> {
    headers
        .get(CONNECTION_TOKEN_HEADER)
        .and_then(|value| value.to_str().ok())
        .map(str::to_owned)
}

fn header_secret_read_lease(headers: &HeaderMap) -> Option<&str> {
    headers
        .get(SECRET_READ_LEASE_HEADER)
        .and_then(|value| value.to_str().ok())
        .map(str::trim)
        .filter(|value| !value.is_empty())
}

fn single_header_value<'a>(headers: &'a HeaderMap, name: &str) -> Option<&'a str> {
    let mut values = headers.get_all(name).iter();
    let value = values.next()?.to_str().ok()?;
    values.next().is_none().then_some(value)
}

const SNAPBACK_CLIENT_ID_HEADER: &str = "snapback-client-id";
const SNAPBACK_CLIENT_ID_STATUS_HEADER: &str = "snapback-client-id-status";
const NETWORK_EVIDENCE_ROTATION_MS: u64 = 24 * 60 * 60 * 1_000;

#[derive(Clone, Debug)]
struct NormalizedDeclaredClientId {
    value: String,
    digest: [u8; 32],
}

#[derive(Clone, Debug)]
struct ExternalClientIdContext {
    declared: Option<NormalizedDeclaredClientId>,
    status: Arc<StdMutex<Option<&'static str>>>,
}

/// Bearer-free result of the capability-link request-secret resolver. The
/// raw path token is intentionally discarded before the request reaches a
/// handler; every subsequent diagnostic, receipt, and span uses the
/// registered route template plus this non-secret durable id.
///
/// @ref LLP 0031#capability-link-mint-and-serve-family — secret URL
/// placeholders are normalized to the registered template at ingress.
#[derive(Clone, Debug)]
struct ResolvedCapabilityLink(crate::storage::capability_links::CapabilityLinkRecord);

fn capability_link_token_from_path(spec: RouteSpec, path: &str) -> Option<&str> {
    match spec.path {
        "/capability-links/{token}" => path.strip_prefix("/capability-links/"),
        "/capability-links/{token}/invoke" => path
            .strip_prefix("/capability-links/")
            .and_then(|path| path.strip_suffix("/invoke")),
        _ => None,
    }
    .filter(|token| !token.is_empty() && !token.contains('/'))
}

fn capability_link_unavailable_error() -> ApiError {
    SnapbackError::error(
        "SNAPBACK_CAPABILITY_LINK_UNAVAILABLE",
        "capability-links",
        "the capability link is unavailable",
    )
    .into()
}

impl ExternalClientIdContext {
    fn ignored(status: &'static str) -> Self {
        Self {
            declared: None,
            status: Arc::new(StdMutex::new(Some(status))),
        }
    }

    fn accepted(declared: NormalizedDeclaredClientId) -> Self {
        Self {
            declared: Some(declared),
            status: Arc::new(StdMutex::new(Some("accepted"))),
        }
    }

    fn absent() -> Self {
        Self {
            declared: None,
            status: Arc::new(StdMutex::new(None)),
        }
    }

    fn set_status(&self, status: &'static str) {
        *self
            .status
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(status);
    }

    fn status(&self) -> Option<&'static str> {
        *self
            .status
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
    }
}

fn declared_client_id_context(
    spec: RouteSpec,
    headers: &HeaderMap,
) -> Option<ExternalClientIdContext> {
    if !external_api_route(spec) {
        return None;
    }
    let mut values = headers.get_all(SNAPBACK_CLIENT_ID_HEADER).iter();
    let Some(_) = values.next() else {
        return Some(ExternalClientIdContext::absent());
    };
    if values.next().is_some() {
        return Some(ExternalClientIdContext::ignored("ignored-duplicate"));
    }
    let Some(raw) = single_header_value(headers, SNAPBACK_CLIENT_ID_HEADER) else {
        return Some(ExternalClientIdContext::ignored("ignored-invalid-encoding"));
    };
    match normalize_declared_client_id(raw) {
        Ok(declared) => Some(ExternalClientIdContext::accepted(declared)),
        Err(status) => Some(ExternalClientIdContext::ignored(status)),
    }
}

fn normalize_declared_client_id(raw: &str) -> Result<NormalizedDeclaredClientId, &'static str> {
    let normalized = raw.nfkc().collect::<String>().trim().to_lowercase();
    if normalized.chars().count() < 16 {
        return Err("ignored-too-short");
    }
    if normalized.len() > crate::storage::declared_clients::DECLARED_CLIENT_MAX_ID_BYTES {
        return Err("ignored-too-long");
    }
    if normalized.chars().any(char::is_control) {
        return Err("ignored-invalid-characters");
    }
    if !declared_id_contains_email(&normalized) {
        return Err("ignored-no-email");
    }
    use sha2::Digest as _;
    let mut hasher = sha2::Sha256::new();
    hasher.update(b"snapback:declared-client-id:v1\n");
    hasher.update(normalized.as_bytes());
    let digest: [u8; 32] = hasher.finalize().into();
    Ok(NormalizedDeclaredClientId {
        value: normalized,
        digest,
    })
}

fn declared_client_caller_key(normalized_id: &str) -> String {
    use base64::Engine as _;
    use sha2::Digest as _;
    let mut hasher = sha2::Sha256::new();
    hasher.update(b"snapback:declared-client-id:v1\n");
    hasher.update(normalized_id.as_bytes());
    base64::engine::general_purpose::URL_SAFE_NO_PAD.encode(hasher.finalize())
}

fn declared_id_contains_email(value: &str) -> bool {
    static EMAIL: OnceLock<regex::Regex> = OnceLock::new();
    EMAIL
        .get_or_init(|| {
            regex::Regex::new(
                r#"(?i)[a-z0-9.!#$%&'*+?^_`{|}~-]+@[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)+"#,
            )
            .expect("declared-id email profile regex is valid")
        })
        .find_iter(value)
        .any(|candidate| {
            let email = candidate.as_str();
            let Some((local, domain)) = email.split_once('@') else {
                return false;
            };
            !local.is_empty()
                && local.len() <= 64
                && !local.starts_with('.')
                && !local.ends_with('.')
                && !local.contains("..")
                && domain.len() <= 253
                && domain.split('.').all(|label| {
                    !label.is_empty()
                        && label.len() <= 63
                        && label.as_bytes()[0].is_ascii_alphanumeric()
                        && label.as_bytes()[label.len() - 1].is_ascii_alphanumeric()
                })
        })
}

fn external_api_network_evidence(source: Option<std::net::IpAddr>, now_ms: u64) -> ([u8; 32], u64) {
    let generation = now_ms / NETWORK_EVIDENCE_ROTATION_MS;
    let grouped = source
        .map(|source| {
            crate::auth::throttle::AuthenticationThrottleDimensions::for_ip(
                EXTERNAL_API_ROUTE_FAMILY,
                source,
                None,
                None,
            )
            .effective_source
        })
        .unwrap_or_else(|| "unattributed".to_owned());
    use sha2::Digest as _;
    let mut hasher = sha2::Sha256::new();
    hasher.update(b"snapback:external-api-network-evidence:v1\n");
    hasher.update(generation.to_le_bytes());
    hasher.update(grouped.as_bytes());
    (hasher.finalize().into(), generation)
}

fn subprotocol_connection_token(headers: &HeaderMap) -> Option<String> {
    headers
        .get_all(header::SEC_WEBSOCKET_PROTOCOL)
        .iter()
        .filter_map(|value| value.to_str().ok())
        .flat_map(|value| value.split(','))
        .map(str::trim)
        .find_map(|proto| proto.strip_prefix(CONNECTION_TOKEN_SUBPROTOCOL_PREFIX))
        .map(str::to_owned)
}

fn presented_ephemeral_authority_instance(headers: &HeaderMap) -> Option<String> {
    headers
        .get(EPHEMERAL_AUTHORITY_INSTANCE_HEADER)
        .and_then(|value| value.to_str().ok())
        .map(str::to_owned)
        .or_else(|| {
            headers
                .get_all(header::SEC_WEBSOCKET_PROTOCOL)
                .iter()
                .filter_map(|value| value.to_str().ok())
                .flat_map(|value| value.split(','))
                .map(str::trim)
                .find_map(|protocol| {
                    protocol.strip_prefix(EPHEMERAL_AUTHORITY_INSTANCE_SUBPROTOCOL_PREFIX)
                })
                .map(str::to_owned)
        })
}

fn connection_token_for_request(
    effective: EffectiveRoutePolicy,
    request: &Request<Body>,
) -> Option<String> {
    connection_grant_carrier(effective, request.headers(), request.uri())
        .map(|presented| presented.token)
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum ConnectionGrantCarrierKind {
    HttpHeader,
    WebSocketSubprotocol,
    DevQuery,
}

struct PresentedConnectionGrant {
    token: String,
    kind: ConnectionGrantCarrierKind,
}

fn connection_grant_carrier(
    effective: EffectiveRoutePolicy,
    headers: &HeaderMap,
    uri: &axum::http::Uri,
) -> Option<PresentedConnectionGrant> {
    let header = || {
        header_connection_token(headers).map(|token| PresentedConnectionGrant {
            token,
            kind: ConnectionGrantCarrierKind::HttpHeader,
        })
    };
    match effective.credential_resolution {
        CredentialResolution::ConnectionGrantHeader => header(),
        CredentialResolution::ConnectionGrantHeaderOrWebSocketSubprotocol => {
            header().or_else(|| {
                subprotocol_connection_token(headers).map(|token| PresentedConnectionGrant {
                    token,
                    kind: ConnectionGrantCarrierKind::WebSocketSubprotocol,
                })
            })
        }
        CredentialResolution::ConnectionGrantHeaderOrDevQuery => header().or_else(|| {
            uri.query().and_then(|query| {
                query.split('&').find_map(|pair| {
                    pair.strip_prefix("connection_token=")
                        .filter(|value| !value.is_empty())
                        .map(|token| PresentedConnectionGrant {
                            token: token.to_owned(),
                            kind: ConnectionGrantCarrierKind::DevQuery,
                        })
                })
            })
        }),
        // Route validation rejects ConnectionAuth entries whose credential
        // axis does not name an HTTP connection carrier.
        _ => None,
    }
}

fn connection_id_from_request_path(path: &str) -> Option<&str> {
    path.strip_prefix("/live/")
        .and_then(|path| path.strip_suffix("/stream"))
        .or_else(|| path.strip_prefix("/outbox/"))
}

/// `POST /connection/open` — the connection handshake (ENG-23442). Public by
/// design: it GRANTS a capability rather than exercising one, exactly like
/// `/app/ensure`. The profile decides whether a caller-suggested id may be
/// adopted (non-prod only).
async fn open_connection(
    State(runtime): State<AppState>,
    Extension(_authority): Extension<PreparedAuthority>,
    Extension(prepared): Extension<PreparedConnectionOpenAuthority>,
    Extension(admission): Extension<AdmissionLease>,
    headers: HeaderMap,
    body: Result<Bytes, BytesRejection>,
) -> Result<Json<ConnectionGrant>, ApiError> {
    let body = parse_optional_json::<OpenConnectionRequest>(&headers, body)?;
    let (
        suggested,
        previous_token,
        auth_invalidation_protocol,
        wire_version,
        ephemeral_authority_protocol,
        ephemeral_expiry_protocol,
    ) = body
        .map(|body| {
            (
                body.connection_id,
                body.previous_token,
                body.auth_invalidation_protocol,
                body.wire_version,
                body.ephemeral_authority_protocol,
                body.ephemeral_expiry_protocol,
            )
        })
        .unwrap_or_default();
    // @ref LLP 0094#0c5-authinvalidationprotocol-decided-not-inherited — an
    // unknown offer refuses instead of silently degrading to legacy; absent
    // keeps degrading (both open-time offer fields follow one matrix).
    if auth_invalidation_protocol.is_some_and(|offered| {
        offered != crate::auth::invalidation::AUTH_INVALIDATION_PROTOCOL_VERSION
    }) {
        return Err(ApiError::from(SnapbackError::error(
            "SNAPBACK_AUTH_INVALIDATION_PROTOCOL_UNSUPPORTED",
            "auth",
            "this server understands authInvalidationProtocol 1 only; omit the field to open a legacy connection",
        )));
    }
    if ephemeral_authority_protocol
        .is_some_and(|offered| offered != crate::ephemeral::EPHEMERAL_AUTHORITY_PROTOCOL_V1)
    {
        return Err(ApiError::from(SnapbackError::error(
            "SNAPBACK_EPHEMERAL_AUTHORITY_UNSUPPORTED",
            "ephemeral",
            "this server understands ephemeralAuthorityProtocol 1 only; omit the field to keep hosted ephemeral unavailable",
        )));
    }
    let hosted_serving = runtime.hosted_serving_handle();
    let hosted_ephemeral_authority_instance = if let Some(hosted) = hosted_serving.as_ref() {
        hosted.hosted_target_authority_instance_at(
            now_millis(),
            prepared.bound.authorization_stream_incarnation(),
            runtime.server_startup_nonce(),
        )?
    } else {
        None
    };
    let hosted_ephemeral_authority_required = hosted_ephemeral_authority_instance.is_some();
    if hosted_ephemeral_authority_required && ephemeral_authority_protocol.is_none() {
        return Err(ApiError::from(SnapbackError::error(
            "SNAPBACK_EPHEMERAL_AUTHORITY_UNSUPPORTED",
            "ephemeral",
            "this hosted target requires ephemeralAuthorityProtocol 1",
        ))
        .with_ephemeral_authority_instance(hosted_ephemeral_authority_instance.as_deref()));
    }
    // @ref LLP 0107#closed-presence-state — this is a must-understand,
    // lineage-bound offer; unknown values never silently downgrade.
    if ephemeral_expiry_protocol
        .is_some_and(|offered| offered != crate::ephemeral::EPHEMERAL_EXPIRY_PROTOCOL_V1)
    {
        return Err(ApiError::from(SnapbackError::error(
            "SNAPBACK_EPHEMERAL_EXPIRY_UNSUPPORTED",
            "ephemeral",
            "this server understands ephemeralExpiryProtocol 1 only; omit the field to keep durable operations available without React presence",
        )));
    }
    // @ref LLP 0094#0b3-the-wireversion-open-time-offer — known binds, unknown
    // refuses (a v2 client must never be interpreted under v1), absent opens
    // a legacy connection implicitly bound to v1.
    let wire_version = match crate::wire_version::classify_open_offer(
        wire_version.as_deref(),
        crate::wire_version::SUPPORTED_WIRE_VERSIONS,
    ) {
        crate::wire_version::OpenWireVersionOffer::Absent => None,
        crate::wire_version::OpenWireVersionOffer::Known(token) => Some(token.to_owned()),
        crate::wire_version::OpenWireVersionOffer::Unknown => {
            return Err(ApiError::from(SnapbackError::error(
                "SNAPBACK_WIRE_VERSION_UNSUPPORTED",
                "realtime",
                "the offered wireVersion is not supported by this server; supported versions: snapback.v1",
            )));
        }
    };
    let allow_suggested = runtime.server.profile.allows_provisioning();
    let use_key = prepared.authenticated_use_key();
    let opened = {
        let (epoch_now_ms, monotonic_now) = auth_runtime_now(&runtime);
        let ephemeral_authority_instance = if ephemeral_authority_protocol.is_some() {
            if hosted_serving.is_some() {
                Some(hosted_ephemeral_authority_instance.clone().ok_or_else(|| {
                    ApiError::from(SnapbackError::error(
                        "SNAPBACK_HOSTED_ADMISSION_V2_MISSING",
                        "auth-deployment",
                        "hosted ephemeral authority requires a current routed-Machine admission",
                    ))
                })?)
            } else {
                use base64::Engine as _;
                let mut digest = sha2::Sha256::new();
                use sha2::Digest as _;
                digest.update(b"snapback:ephemeral-authority-instance:local:v1\n");
                digest.update(runtime.server_startup_nonce().as_bytes());
                Some(format!(
                    "eai1.{}",
                    base64::engine::general_purpose::URL_SAFE_NO_PAD.encode(digest.finalize())
                ))
            }
        } else {
            None
        };
        runtime
            .connections
            .open_prepared(
                ConnectionOpenAttempt::new(
                    suggested,
                    previous_token.as_deref(),
                    allow_suggested,
                    prepared.clone(),
                    epoch_now_ms,
                    monotonic_now,
                    auth_invalidation_protocol,
                )
                .with_wire_version(wire_version)
                .with_ephemeral_authority_protocol(ephemeral_authority_protocol)
                .with_ephemeral_authority_instance(ephemeral_authority_instance)
                .with_hosted_ephemeral_authority_required(hosted_ephemeral_authority_required)
                .with_ephemeral_expiry_protocol(ephemeral_expiry_protocol)
                .with_admission(&admission),
            )
            .map_err(|error| {
                ApiError::from(error).with_ephemeral_authority_instance(
                    hosted_ephemeral_authority_instance.as_deref(),
                )
            })?
    };
    let deadline = match record_connection_authenticated_use(&runtime, use_key, &admission).await {
        Ok(deadline) => deadline,
        Err(error) => {
            runtime.connections.discard_unpublished_open(&opened);
            return Err(error);
        }
    };
    if let Some(deadline_ms) = deadline {
        let (epoch_now_ms, monotonic_now) = auth_runtime_now(&runtime);
        if let Err(error) = runtime.connections.refresh_open_deadline(
            &opened,
            &prepared,
            deadline_ms,
            epoch_now_ms,
            monotonic_now,
        ) {
            runtime.connections.discard_unpublished_open(&opened);
            return Err(ApiError::from(error));
        }
    }
    // Establish reaper-visible continuity before the first drain. Reaping
    // removes this marker before room/outbox teardown, so an old grant cannot
    // make an extinct drain look like a healthy empty queue.
    runtime
        .ephemeral
        .touch_connection(&opened.grant.connection_id);
    if opened.grant.authorization_invalidation.is_some() {
        let projection_connection = opened.grant.connection_id.clone();
        let projection_admission = admission.clone();
        with_snapback(&runtime.snapback, move |snapback| {
            snapback.reproject_authorization_invalidations(
                &projection_connection,
                &projection_admission,
            )
        })
        .await?;
    }
    Ok(Json(opened.grant))
}

/// The path class of a route or a multiplexed operation.
///
/// @ref LLP 0031#route-classification — every operation is app-data or system.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum RouteClass {
    /// An operation an app client may call; lives at the server root.
    AppData,
    /// Public, read-only system presentation under a reserved namespace: the
    /// console shell/assets and the build-bound served guide.
    SystemStatic,
    /// A system API operation under `/_snapback/api/*`; admin-gated.
    SystemApi,
}

/// The authorization policy a route carries. `AppAuth` means the handler may
/// enforce the app-supplied `ctx.auth` — not that the transport authenticates
/// the caller (in local v0 it does not; see LLP 0031 §The invariant).
/// `ConnectionAuth` strengthens that: the transport requires the
/// server-issued per-connection token from `POST /connection/open` (the
/// handler may still additionally enforce `ctx.auth`).
///
/// @ref LLP 0031#connection-capability-grants — ConnectionAuth marks every
/// route that exercises a connection-scoped capability.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum RoutePolicy {
    Public,
    AppAuth,
    ConnectionAuth,
    SessionAuth,
    AdminRead,
    AdminWrite,
    AdminSecretRead,
}

/// The credential carrier a route resolves. This is deliberately independent
/// from [`RoutePolicy`]: an `AdminWrite` path plus an
/// `ImpersonationCapability` effect, for example, needs two distinct carriers.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum CredentialResolution {
    None,
    /// A closed email-code challenge body proves authority only to exchange
    /// that challenge for a fresh credential; it is never a caller identity.
    ChallengeProof,
    PasswordCredentialBody,
    PasswordRecoveryCodeBody,
    CreationInvitationBody,
    AgentCredentialBody,
    AgentFamilySecretBody,
    /// An exact scoped token carried in a closed destroy-only request body.
    /// Unlike ordinary app-data bearer resolution, this accepts an already
    /// released token so a lost successful response is safely retryable.
    ScopedTokenReleaseBody,
    /// A bearer accepted only by the opaque revoke-only family alarm.
    FamilyAlarmBearer,
    /// A signed asset-delivery URL's token query parameter — the entire
    /// credential on the signed serve lane. Validated against the instance
    /// signing keys, its own expiry, and the asset's current lifecycle
    /// generation; no session, body, or header authority participates
    /// (LLP 0044 §Delivery profiles, `private-signed`).
    SignedUrlToken,
    LegacyBodyAuth,
    ConnectionGrantHeader,
    ConnectionGrantHeaderOrWebSocketSubprotocol,
    ConnectionGrantHeaderOrDevQuery,
    BoundConnectionGrant,
    AdminCredential,
    /// Exact `sbrc_` capability carried only by a registered local rehearsal
    /// operation. Resolution remains operation-specific so it cannot become a
    /// general Authorization bearer.
    RehearsalCapability,
    OptionalSessionBearer,
    OptionalSessionOrScopedToken,
    RequiredSessionBearer,
    RequiredSessionOrScopedToken,
    /// Exact secret URL bearer resolved only on the two registered
    /// capability-link token paths. It never becomes a session or principal.
    CapabilityLinkBearer,
    AdminSecretReadLease,
    OperationSpecific,
}

/// The server-side authority installed for an invocation after credential
/// resolution. No client-provided structure is a `ResolvedCaller`.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum InvocationAuthority {
    None,
    ClientAsserted,
    ResolvedCaller,
    ConnectionBound,
    DevImpersonation,
    Operator,
    AnonymousAdminBypass,
    System,
}

/// Whether an ingress accepts the legacy body `auth` shape. Session-mode
/// overlays turn every applicable `Allowed` entry into `Rejected`; omission is
/// different from a body that was accepted and ignored.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum LegacyBodyPolicy {
    NotApplicable,
    Allowed,
    Rejected,
}

/// An additional effect gate composed with the path policy.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum EffectPolicy {
    None,
    Provisioning,
    FunctionKind,
    OperationSpecific,
    SecretReadMintProof,
    ImpersonationCapability,
    AgentDestroyCapability,
    /// Exact effect and quota come from the resolved rehearsal grant.
    RehearsalGrant,
    Unavailable,
}

/// What a successful response is allowed to carry. The middleware applies
/// no-store to every non-public class; field-level typed projections remain the
/// stronger protection for public payloads.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum ResponseSensitivity {
    StaticPublic,
    PublicProjection,
    /// A public typed response whose contents must never be cached. This is
    /// distinct from operator/application data: request-code and family-alarm
    /// reveal no protected row, but caching either protocol response is still
    /// invalid.
    PublicNoStore,
    /// Declared-public application data (LLP 0031 dated LLP 0090 amendment):
    /// arbitrary app query rows whose anonymous emission is authorized by the
    /// query's own codegen-compiled served-manifest facts, re-checked
    /// server-side. Governs the bundle/Channel A lanes only. Operator-plane
    /// logging posture stays that of application data (bodies excluded);
    /// cache posture is `no-store` in v1 (the middleware's non-public arm).
    DeclaredPublicApplicationData,
    /// Arbitrary app-derived output from one closed anonymous external
    /// projection. Selection never grants function authority; the handler
    /// re-checks exposure, anonymous authorization, and composed admission.
    ExternalAnonymousApplicationData,
    ApplicationData,
    ConnectionSecret,
    OperatorMetadata,
    SensitiveApplicationData,
    CredentialSecret,
}

/// Auth mode used only to evaluate route metadata. Item 4 owns the persisted,
/// staged runtime mode and will feed it into this already-closed evaluator.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum PolicyAuthMode {
    Dev,
    Sessions,
}

impl From<EnsureAppMode> for PolicyAuthMode {
    fn from(mode: EnsureAppMode) -> Self {
        match mode {
            EnsureAppMode::Dev => Self::Dev,
            EnsureAppMode::Sessions => Self::Sessions,
        }
    }
}

impl From<crate::manifest::AuthMode> for PolicyAuthMode {
    fn from(mode: crate::manifest::AuthMode) -> Self {
        match mode {
            crate::manifest::AuthMode::Dev => Self::Dev,
            crate::manifest::AuthMode::Sessions => Self::Sessions,
        }
    }
}

/// Active and desired auth-policy facts consumed by pre-effect gates. Item 2
/// supplies this explicit seam so an active-dev server cannot treat a request
/// or already-staged desired-sessions posture as Public provisioning. Item 4
/// replaces the constructor default with persisted pre-bind resolution.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct PolicyAuthPosture {
    pub active: PolicyAuthMode,
    pub desired: PolicyAuthMode,
}

impl PolicyAuthPosture {
    pub const fn settled(mode: PolicyAuthMode) -> Self {
        Self {
            active: mode,
            desired: mode,
        }
    }

    fn settled_at(self, mode: PolicyAuthMode) -> bool {
        self.active == mode && self.desired == mode
    }
}

/// Per-axis changes that become effective in session mode. `None` means the
/// dev value remains in force; this makes mode-dependent behavior explicit
/// without multiplying route literals.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct SessionModeOverlay {
    pub path_policy: Option<RoutePolicy>,
    pub credential_resolution: Option<CredentialResolution>,
    pub invocation_authority: Option<InvocationAuthority>,
    pub legacy_body_policy: Option<LegacyBodyPolicy>,
    pub effect_policy: Option<EffectPolicy>,
    pub response_sensitivity: Option<ResponseSensitivity>,
}

impl SessionModeOverlay {
    pub const NONE: Self = Self {
        path_policy: None,
        credential_resolution: None,
        invocation_authority: None,
        legacy_body_policy: None,
        effect_policy: None,
        response_sensitivity: None,
    };

    pub const fn app_session() -> Self {
        Self {
            // Ordinary app invocation paths are optional-user at the route
            // boundary. A function's closed authRequirement may strengthen
            // that to required at the shared invocation gate (item 4).
            path_policy: Some(RoutePolicy::Public),
            credential_resolution: Some(CredentialResolution::OptionalSessionBearer),
            invocation_authority: Some(InvocationAuthority::ResolvedCaller),
            legacy_body_policy: Some(LegacyBodyPolicy::Rejected),
            effect_policy: None,
            response_sensitivity: None,
        }
    }

    pub const fn app_function_session() -> Self {
        Self {
            path_policy: Some(RoutePolicy::Public),
            credential_resolution: Some(CredentialResolution::OptionalSessionOrScopedToken),
            invocation_authority: Some(InvocationAuthority::ResolvedCaller),
            legacy_body_policy: Some(LegacyBodyPolicy::Rejected),
            effect_policy: None,
            response_sensitivity: None,
        }
    }

    pub const fn stream_initiator_session() -> Self {
        Self {
            path_policy: Some(RoutePolicy::SessionAuth),
            credential_resolution: Some(CredentialResolution::RequiredSessionOrScopedToken),
            invocation_authority: Some(InvocationAuthority::ResolvedCaller),
            legacy_body_policy: Some(LegacyBodyPolicy::Rejected),
            effect_policy: None,
            response_sensitivity: None,
        }
    }

    pub const fn connection_bound() -> Self {
        Self {
            path_policy: None,
            credential_resolution: None,
            invocation_authority: Some(InvocationAuthority::ConnectionBound),
            legacy_body_policy: Some(LegacyBodyPolicy::Rejected),
            effect_policy: None,
            response_sensitivity: None,
        }
    }

    pub const fn secret_read() -> Self {
        Self {
            path_policy: Some(RoutePolicy::AdminSecretRead),
            credential_resolution: Some(CredentialResolution::AdminSecretReadLease),
            invocation_authority: None,
            legacy_body_policy: None,
            effect_policy: None,
            response_sensitivity: None,
        }
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct EffectiveRoutePolicy {
    pub path_policy: RoutePolicy,
    pub credential_resolution: CredentialResolution,
    pub invocation_authority: InvocationAuthority,
    pub legacy_body_policy: LegacyBodyPolicy,
    pub effect_policy: EffectPolicy,
    pub response_sensitivity: ResponseSensitivity,
    /// The closed LLP 0044 delivery-route predicate, carried into response
    /// controls so no other public/static route inherits cross-origin embed
    /// permission from its sensitivity class alone.
    pub cross_origin_embeddable: bool,
}

/// A declared route in the registry. `policy` is retained as a source
/// compatible spelling of `path_policy`; constructors set both and the router
/// refuses registrations where they differ.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct RouteSpec {
    pub method: &'static str,
    pub path: &'static str,
    pub class: RouteClass,
    pub path_policy: RoutePolicy,
    pub policy: RoutePolicy,
    pub credential_resolution: CredentialResolution,
    pub invocation_authority: InvocationAuthority,
    pub legacy_body_policy: LegacyBodyPolicy,
    pub effect_policy: EffectPolicy,
    pub response_sensitivity: ResponseSensitivity,
    pub session_overlay: SessionModeOverlay,
}

impl RouteSpec {
    // Keeping the independent policy axes explicit is the point of this
    // constructor; hiding them in an untyped options bag would recreate the
    // registry drift ENG-24594 closes.
    #[allow(clippy::too_many_arguments)]
    pub const fn new(
        method: &'static str,
        path: &'static str,
        class: RouteClass,
        path_policy: RoutePolicy,
        credential_resolution: CredentialResolution,
        invocation_authority: InvocationAuthority,
        legacy_body_policy: LegacyBodyPolicy,
        response_sensitivity: ResponseSensitivity,
    ) -> Self {
        Self {
            method,
            path,
            class,
            path_policy,
            policy: path_policy,
            credential_resolution,
            invocation_authority,
            legacy_body_policy,
            effect_policy: EffectPolicy::None,
            response_sensitivity,
            session_overlay: SessionModeOverlay::NONE,
        }
    }

    pub const fn with_effect(mut self, effect_policy: EffectPolicy) -> Self {
        self.effect_policy = effect_policy;
        self
    }

    pub const fn with_invocation_authority(
        mut self,
        invocation_authority: InvocationAuthority,
    ) -> Self {
        self.invocation_authority = invocation_authority;
        self
    }

    pub const fn with_session_overlay(mut self, session_overlay: SessionModeOverlay) -> Self {
        self.session_overlay = session_overlay;
        self
    }

    /// Methods structurally installed for this path. Axum's `get` includes
    /// HEAD, and the registry builder attaches one inert CORS preflight to
    /// every known path; no middleware manufactures methods for unknown paths.
    pub fn accepts_http_method(&self, method: &str) -> bool {
        method == self.method || method == "OPTIONS" || (self.method == "GET" && method == "HEAD")
    }

    pub fn effective_for(self, mode: PolicyAuthMode) -> EffectiveRoutePolicy {
        let mut effective = EffectiveRoutePolicy {
            path_policy: self.path_policy,
            credential_resolution: self.credential_resolution,
            invocation_authority: self.invocation_authority,
            legacy_body_policy: self.legacy_body_policy,
            effect_policy: self.effect_policy,
            response_sensitivity: self.response_sensitivity,
            cross_origin_embeddable: pasteable_delivery_route(self),
        };
        if matches!(mode, PolicyAuthMode::Sessions) {
            let overlay = self.session_overlay;
            effective.path_policy = overlay.path_policy.unwrap_or(effective.path_policy);
            effective.credential_resolution = overlay
                .credential_resolution
                .unwrap_or(effective.credential_resolution);
            effective.invocation_authority = overlay
                .invocation_authority
                .unwrap_or(effective.invocation_authority);
            effective.legacy_body_policy = overlay
                .legacy_body_policy
                .unwrap_or(effective.legacy_body_policy);
            effective.effect_policy = overlay.effect_policy.unwrap_or(effective.effect_policy);
            effective.response_sensitivity = overlay
                .response_sensitivity
                .unwrap_or(effective.response_sensitivity);
        }
        effective
    }

    /// Validate the complete route-policy tuple in both modes. Registration
    /// turns an error into a startup panic; exposing the result lets the
    /// acceptance suite prove malformed tuples are rejected without building
    /// a deliberately broken router.
    pub fn validate(&self) -> Result<(), String> {
        let fail = |message: &str| {
            Err(format!(
                "invalid policy for {} {}: {message}",
                self.method, self.path
            ))
        };
        if self.path_policy != self.policy {
            return fail("path-policy aliases diverged");
        }
        match self.class {
            RouteClass::AppData if self.path.starts_with("/_snapback/") => {
                return fail("app-data route escaped the root namespace");
            }
            RouteClass::SystemStatic => {
                // The llms.txt convention pins this one system-static guide
                // projection to the served root.
                let approved_projection = (self.path.starts_with("/_snapback/admin")
                    && self.response_sensitivity == ResponseSensitivity::StaticPublic)
                    || ((self.path.starts_with("/_snapback/guide") || self.path == "/llms.txt")
                        && self.response_sensitivity == ResponseSensitivity::PublicProjection);
                if !approved_projection
                    || self.path_policy != RoutePolicy::Public
                    || self.credential_resolution != CredentialResolution::None
                    || self.invocation_authority != InvocationAuthority::None
                    || self.legacy_body_policy != LegacyBodyPolicy::NotApplicable
                    || self.effect_policy != EffectPolicy::None
                    || self.session_overlay != SessionModeOverlay::NONE
                {
                    return fail(
                        "system-static entries must be inert public console assets or guide projections",
                    );
                }
            }
            RouteClass::SystemApi => {
                if !self.path.starts_with("/_snapback/api/") {
                    return fail("system API escaped the reserved namespace");
                }
                if !matches!(
                    self.path_policy,
                    RoutePolicy::AdminRead
                        | RoutePolicy::AdminWrite
                        | RoutePolicy::AdminSecretRead
                        | RoutePolicy::SessionAuth
                ) && !(self.path_policy == RoutePolicy::Public
                    && self.credential_resolution == CredentialResolution::RehearsalCapability
                    && self.effect_policy == EffectPolicy::RehearsalGrant)
                {
                    return fail("system API has a non-system path policy");
                }
            }
            RouteClass::AppData => {}
        }

        let valid_base_carrier = match self.path_policy {
            RoutePolicy::Public => matches!(
                self.credential_resolution,
                CredentialResolution::None
                    | CredentialResolution::ChallengeProof
                    | CredentialResolution::PasswordCredentialBody
                    | CredentialResolution::PasswordRecoveryCodeBody
                    | CredentialResolution::CreationInvitationBody
                    | CredentialResolution::AgentCredentialBody
                    | CredentialResolution::AgentFamilySecretBody
                    | CredentialResolution::ScopedTokenReleaseBody
                    | CredentialResolution::FamilyAlarmBearer
                    | CredentialResolution::SignedUrlToken
                    | CredentialResolution::RehearsalCapability
                    | CredentialResolution::CapabilityLinkBearer
                    | CredentialResolution::OperationSpecific
            ),
            RoutePolicy::AppAuth => {
                self.credential_resolution == CredentialResolution::LegacyBodyAuth
            }
            RoutePolicy::ConnectionAuth => matches!(
                self.credential_resolution,
                CredentialResolution::ConnectionGrantHeader
                    | CredentialResolution::ConnectionGrantHeaderOrWebSocketSubprotocol
                    | CredentialResolution::ConnectionGrantHeaderOrDevQuery
                    | CredentialResolution::BoundConnectionGrant
            ),
            RoutePolicy::SessionAuth => matches!(
                self.credential_resolution,
                CredentialResolution::RequiredSessionBearer
                    | CredentialResolution::RequiredSessionOrScopedToken
            ),
            RoutePolicy::AdminRead | RoutePolicy::AdminWrite => {
                self.credential_resolution == CredentialResolution::AdminCredential
            }
            RoutePolicy::AdminSecretRead => {
                self.credential_resolution == CredentialResolution::AdminSecretReadLease
            }
        };
        if !valid_base_carrier {
            return fail("path policy and credential carrier are incompatible");
        }

        if self.path_policy == RoutePolicy::AppAuth
            && (self.invocation_authority != InvocationAuthority::ClientAsserted
                || self.legacy_body_policy != LegacyBodyPolicy::Allowed)
        {
            return fail("AppAuth must explicitly resolve allowed dev body authority");
        }
        if self.legacy_body_policy == LegacyBodyPolicy::Allowed
            && self.invocation_authority != InvocationAuthority::ClientAsserted
        {
            return fail("allowed legacy body auth must install client-asserted authority");
        }
        if self.legacy_body_policy == LegacyBodyPolicy::Rejected
            && self.invocation_authority == InvocationAuthority::ClientAsserted
        {
            return fail("rejected legacy body auth cannot install client authority");
        }
        if self.path_policy == RoutePolicy::SessionAuth
            && self.invocation_authority != InvocationAuthority::ResolvedCaller
        {
            return fail("SessionAuth must install a server-resolved caller");
        }
        if self.method != "OPERATION"
            && self.credential_resolution == CredentialResolution::OperationSpecific
            && self.effect_policy != EffectPolicy::OperationSpecific
        {
            return fail("operation-specific credentials require an operation-specific gate");
        }
        if self.credential_resolution == CredentialResolution::ChallengeProof
            && (self.path_policy != RoutePolicy::Public
                || self.invocation_authority != InvocationAuthority::None
                || self.response_sensitivity != ResponseSensitivity::CredentialSecret)
        {
            return fail(
                "challenge proof must be public, install no caller, and return only a credential-secret response",
            );
        }
        if matches!(
            self.credential_resolution,
            CredentialResolution::PasswordCredentialBody
                | CredentialResolution::PasswordRecoveryCodeBody
        ) && (self.path_policy != RoutePolicy::Public
            || self.invocation_authority != InvocationAuthority::None
            || self.response_sensitivity != ResponseSensitivity::CredentialSecret)
        {
            return fail(
                "password credential bodies must be public, install no caller, and return only a credential-secret response",
            );
        }
        if self.credential_resolution == CredentialResolution::RehearsalCapability
            && (self.method != "OPERATION"
                || self.path_policy != RoutePolicy::Public
                || self.invocation_authority != InvocationAuthority::Operator
                || self.effect_policy != EffectPolicy::RehearsalGrant
                || self.response_sensitivity != ResponseSensitivity::CredentialSecret)
        {
            return fail(
                "rehearsal capability must be an operator operation with an exact grant effect and credential-secret response",
            );
        }
        if self.credential_resolution == CredentialResolution::CapabilityLinkBearer
            && (self.path_policy != RoutePolicy::Public
                || self.invocation_authority != InvocationAuthority::None
                || !matches!(
                    (self.method, self.path, self.response_sensitivity),
                    (
                        "GET",
                        "/capability-links/{token}",
                        ResponseSensitivity::PublicNoStore
                    ) | (
                        "POST",
                        "/capability-links/{token}/invoke",
                        ResponseSensitivity::ExternalAnonymousApplicationData
                    )
                ))
        {
            return fail(
                "capability-link bearers are closed to the inert landing and anonymous invoke rows",
            );
        }
        if self.response_sensitivity == ResponseSensitivity::ExternalAnonymousApplicationData
            && !(self.method == "POST"
                && self.path == "/capability-links/{token}/invoke"
                && self.credential_resolution == CredentialResolution::CapabilityLinkBearer)
        {
            return fail("external anonymous application data is closed to capability-link invoke");
        }
        if self.credential_resolution == CredentialResolution::AgentCredentialBody
            && (self.path_policy != RoutePolicy::Public
                || self.invocation_authority != InvocationAuthority::None
                || self.response_sensitivity != ResponseSensitivity::CredentialSecret)
        {
            return fail(
                "agent credential body must be public, install no caller, and return only a credential-secret response",
            );
        }
        if self.credential_resolution == CredentialResolution::CreationInvitationBody
            && (self.path_policy != RoutePolicy::Public
                || self.invocation_authority != InvocationAuthority::None
                || self.response_sensitivity != ResponseSensitivity::CredentialSecret)
        {
            return fail(
                "creation invitation body must be public, install no caller, and return only a credential-secret response",
            );
        }
        if self.credential_resolution == CredentialResolution::AgentFamilySecretBody
            && (self.path_policy != RoutePolicy::Public
                || self.invocation_authority != InvocationAuthority::None
                || self.response_sensitivity != ResponseSensitivity::PublicNoStore)
        {
            return fail(
                "agent family secret body must be public, install no caller, and return an opaque no-store response",
            );
        }
        if self.credential_resolution == CredentialResolution::ScopedTokenReleaseBody
            && (self.path_policy != RoutePolicy::Public
                || self.invocation_authority != InvocationAuthority::None
                || self.response_sensitivity != ResponseSensitivity::PublicNoStore)
        {
            return fail(
                "scoped-token release body must be public, install no caller, and return an opaque no-store response",
            );
        }
        if self.credential_resolution == CredentialResolution::FamilyAlarmBearer
            && (self.path_policy != RoutePolicy::Public
                || self.invocation_authority != InvocationAuthority::None
                || self.response_sensitivity != ResponseSensitivity::PublicNoStore)
        {
            return fail(
                "family-alarm bearer must be public, install no caller, and return an opaque no-store response",
            );
        }
        if self.effect_policy == EffectPolicy::ImpersonationCapability
            && self.path_policy != RoutePolicy::AdminWrite
        {
            return fail("impersonation capability must compose with AdminWrite");
        }
        if self.effect_policy == EffectPolicy::AgentDestroyCapability
            && self.path_policy != RoutePolicy::AdminWrite
        {
            return fail("agent destroy capability must compose with AdminWrite");
        }
        if self.effect_policy == EffectPolicy::SecretReadMintProof
            && (self.path_policy != RoutePolicy::AdminWrite
                || self.response_sensitivity != ResponseSensitivity::CredentialSecret)
        {
            return fail(
                "secret-read mint proof must compose with AdminWrite and CredentialSecret",
            );
        }

        // A wholly anonymous public route may issue a freshly minted
        // connection capability, but it may not expose app/identity rows or a
        // general credential response without a typed proof/resolution seam.
        if self.path_policy == RoutePolicy::Public
            && self.credential_resolution == CredentialResolution::None
            && self.invocation_authority == InvocationAuthority::None
            && matches!(
                self.response_sensitivity,
                ResponseSensitivity::ApplicationData
                    | ResponseSensitivity::SensitiveApplicationData
                    | ResponseSensitivity::CredentialSecret
            )
        {
            return fail("anonymous public route has an unsafe response classification");
        }

        let sessions = self.effective_for(PolicyAuthMode::Sessions);
        if self.path_policy == RoutePolicy::AppAuth
            && ((!matches!(
                (sessions.path_policy, sessions.credential_resolution),
                (
                    RoutePolicy::Public,
                    CredentialResolution::OptionalSessionBearer
                        | CredentialResolution::OptionalSessionOrScopedToken
                ) | (
                    RoutePolicy::SessionAuth,
                    CredentialResolution::RequiredSessionOrScopedToken
                )
            )) || sessions.invocation_authority != InvocationAuthority::ResolvedCaller
                || sessions.legacy_body_policy != LegacyBodyPolicy::Rejected)
        {
            return fail("AppAuth has an incomplete sessions overlay");
        }
        if self.legacy_body_policy == LegacyBodyPolicy::Allowed
            && (sessions.legacy_body_policy != LegacyBodyPolicy::Rejected
                || sessions.invocation_authority == InvocationAuthority::ClientAsserted)
        {
            return fail("client-asserted body authority remains live in sessions");
        }
        if self.credential_resolution == CredentialResolution::ConnectionGrantHeaderOrDevQuery
            && sessions.credential_resolution != CredentialResolution::ConnectionGrantHeader
        {
            return fail("dev query credential fallback remains live in sessions");
        }
        if self.path_policy == RoutePolicy::ConnectionAuth
            && sessions.invocation_authority != InvocationAuthority::ConnectionBound
        {
            return fail("ConnectionAuth lacks bound authority in sessions");
        }
        if sessions.path_policy == RoutePolicy::SessionAuth
            && (sessions.invocation_authority != InvocationAuthority::ResolvedCaller
                || sessions.legacy_body_policy == LegacyBodyPolicy::Allowed)
        {
            return fail("SessionAuth effective policy is incomplete");
        }
        if sessions.effect_policy == EffectPolicy::ImpersonationCapability
            && sessions.path_policy != RoutePolicy::AdminWrite
        {
            return fail("sessions impersonation capability lost its AdminWrite gate");
        }
        if self.path_policy == RoutePolicy::AdminRead
            && self.response_sensitivity == ResponseSensitivity::SensitiveApplicationData
            && !matches!(
                self.effect_policy,
                EffectPolicy::FunctionKind | EffectPolicy::OperationSpecific
            )
            && (sessions.path_policy != RoutePolicy::AdminSecretRead
                || sessions.credential_resolution != CredentialResolution::AdminSecretReadLease)
        {
            return fail("sensitive AdminRead route lacks its sessions secret-read gate");
        }
        let valid_sessions_carrier = match sessions.path_policy {
            RoutePolicy::Public => matches!(
                sessions.credential_resolution,
                CredentialResolution::None
                    | CredentialResolution::ChallengeProof
                    | CredentialResolution::PasswordCredentialBody
                    | CredentialResolution::PasswordRecoveryCodeBody
                    | CredentialResolution::CreationInvitationBody
                    | CredentialResolution::AgentCredentialBody
                    | CredentialResolution::AgentFamilySecretBody
                    | CredentialResolution::ScopedTokenReleaseBody
                    | CredentialResolution::FamilyAlarmBearer
                    | CredentialResolution::OptionalSessionBearer
                    | CredentialResolution::OptionalSessionOrScopedToken
                    // The signed-URL token is authority-complete on its own;
                    // sessions mode changes nothing about the lane.
                    | CredentialResolution::SignedUrlToken
                    | CredentialResolution::RehearsalCapability
                    | CredentialResolution::CapabilityLinkBearer
                    | CredentialResolution::OperationSpecific
            ),
            RoutePolicy::AppAuth => false,
            RoutePolicy::ConnectionAuth => matches!(
                sessions.credential_resolution,
                CredentialResolution::ConnectionGrantHeader
                    | CredentialResolution::ConnectionGrantHeaderOrWebSocketSubprotocol
                    | CredentialResolution::BoundConnectionGrant
            ),
            RoutePolicy::SessionAuth => matches!(
                sessions.credential_resolution,
                CredentialResolution::RequiredSessionBearer
                    | CredentialResolution::RequiredSessionOrScopedToken
            ),
            RoutePolicy::AdminRead | RoutePolicy::AdminWrite => {
                sessions.credential_resolution == CredentialResolution::AdminCredential
            }
            RoutePolicy::AdminSecretRead => {
                sessions.credential_resolution == CredentialResolution::AdminSecretReadLease
            }
        };
        if !valid_sessions_carrier {
            return fail("sessions path policy and credential carrier are incompatible");
        }
        if sessions.legacy_body_policy == LegacyBodyPolicy::Allowed
            || sessions.invocation_authority == InvocationAuthority::ClientAsserted
        {
            return fail("sessions effective policy retains client-asserted authority");
        }
        Ok(())
    }

    fn assert_valid(self) {
        if let Err(error) = self.validate() {
            panic!("{error}");
        }
    }
}

/// One installed route: metadata and its axum handler travel together. The
/// application router and the public registry are both projections of these
/// values, so a runtime route cannot exist without policy metadata.
pub(crate) struct RegisteredRoute {
    pub spec: RouteSpec,
    pub method_router: MethodRouter<AppState>,
}

impl RegisteredRoute {
    pub(crate) fn new(spec: RouteSpec, method_router: MethodRouter<AppState>) -> Self {
        spec.assert_valid();
        Self {
            spec,
            method_router,
        }
    }
}

const fn public_route(
    method: &'static str,
    path: &'static str,
    sensitivity: ResponseSensitivity,
) -> RouteSpec {
    RouteSpec::new(
        method,
        path,
        RouteClass::AppData,
        RoutePolicy::Public,
        CredentialResolution::None,
        InvocationAuthority::None,
        LegacyBodyPolicy::NotApplicable,
        sensitivity,
    )
}

const fn app_auth_route(method: &'static str, path: &'static str) -> RouteSpec {
    RouteSpec::new(
        method,
        path,
        RouteClass::AppData,
        RoutePolicy::AppAuth,
        CredentialResolution::LegacyBodyAuth,
        InvocationAuthority::ClientAsserted,
        LegacyBodyPolicy::Allowed,
        ResponseSensitivity::ApplicationData,
    )
    .with_session_overlay(SessionModeOverlay::app_session())
}

const fn app_function_route(method: &'static str, path: &'static str) -> RouteSpec {
    RouteSpec::new(
        method,
        path,
        RouteClass::AppData,
        RoutePolicy::AppAuth,
        CredentialResolution::LegacyBodyAuth,
        InvocationAuthority::ClientAsserted,
        LegacyBodyPolicy::Allowed,
        ResponseSensitivity::ApplicationData,
    )
    .with_session_overlay(SessionModeOverlay::app_function_session())
}

const fn connection_route(
    method: &'static str,
    path: &'static str,
    credential_resolution: CredentialResolution,
    body_auth: bool,
    sensitivity: ResponseSensitivity,
) -> RouteSpec {
    let overlay = if body_auth {
        SessionModeOverlay::connection_bound()
    } else {
        SessionModeOverlay {
            path_policy: None,
            credential_resolution: None,
            invocation_authority: Some(InvocationAuthority::ConnectionBound),
            legacy_body_policy: None,
            effect_policy: None,
            response_sensitivity: None,
        }
    };
    RouteSpec::new(
        method,
        path,
        RouteClass::AppData,
        RoutePolicy::ConnectionAuth,
        credential_resolution,
        if body_auth {
            InvocationAuthority::ClientAsserted
        } else {
            InvocationAuthority::None
        },
        if body_auth {
            LegacyBodyPolicy::Allowed
        } else {
            LegacyBodyPolicy::NotApplicable
        },
        sensitivity,
    )
    .with_session_overlay(overlay)
}

pub(crate) const fn system_api_route(
    method: &'static str,
    path: &'static str,
    policy: RoutePolicy,
    sensitivity: ResponseSensitivity,
) -> RouteSpec {
    RouteSpec::new(
        method,
        path,
        RouteClass::SystemApi,
        policy,
        CredentialResolution::AdminCredential,
        InvocationAuthority::Operator,
        LegacyBodyPolicy::NotApplicable,
        sensitivity,
    )
}

pub(crate) const fn system_static_route(method: &'static str, path: &'static str) -> RouteSpec {
    RouteSpec::new(
        method,
        path,
        RouteClass::SystemStatic,
        RoutePolicy::Public,
        CredentialResolution::None,
        InvocationAuthority::None,
        LegacyBodyPolicy::NotApplicable,
        ResponseSensitivity::StaticPublic,
    )
}

const fn served_guide_route(path: &'static str) -> RouteSpec {
    RouteSpec::new(
        "GET",
        path,
        RouteClass::SystemStatic,
        RoutePolicy::Public,
        CredentialResolution::None,
        InvocationAuthority::None,
        LegacyBodyPolicy::NotApplicable,
        ResponseSensitivity::PublicProjection,
    )
}

pub const GUIDE_CONTENT_HASH_HEADER: &str = "x-snapback-guide-content-sha256";
pub const GUIDE_BUILD_COMMIT_HEADER: &str = "x-snapback-server-build-commit";
pub const HTTP_ROUTES_PATH: &str = "/_snapback/guide/http.routes.v1.json";
const HTTP_ROUTES_V1: &[u8] = include_bytes!("../schemas/http.routes.v1.json");

// @ref LLP 0186#w2--context-injection-surface-owned-here — the convention
// endpoint gives agent probes a size-labeled index into the build-bound guide.
// The budgeted capability/surface pair is the one-request entry tier; generated
// section flats are the next tier; the whole-corpus export stays last.
// @ref LLP 0194#design — exact API discovery names both the compact human
// index and canonical machine registry instead of hiding them in the flat file.
// @ref LLP 0184#4-agent-discovery-and-setup — every cold-agent funnel names
// both authority postures and the explicit control-server setup preview.
const LLMS_TXT: &str = r#"# Snapback

> Snapback is a local-first app backend. This server embeds its own authoring guide.

## Read first — one-request entry tier

- [Capability index](/_snapback/guide/capabilities.md) — about 50 KiB; capability-complete and budgeted.
- [Surface map](/_snapback/guide/surface-map.md) — about 12 KiB; route and host-operation map within a 16 KiB budget.
- [Guide index](/_snapback/guide) — choose a specific page when you know the topic.

## Section projections — choose only what you need

- [Getting started](/_snapback/guide/guide-flat.getting-started.generated.md) — about 45 KiB.
- [Backend](/_snapback/guide/guide-flat.backend.generated.md) — about 275 KiB.
- [Realtime](/_snapback/guide/guide-flat.realtime.generated.md) — about 40 KiB.
- [Clients](/_snapback/guide/guide-flat.clients.generated.md) — about 200 KiB.
- [Auth](/_snapback/guide/guide-flat.auth.generated.md) — about 85 KiB.
- [Operating](/_snapback/guide/guide-flat.operating.generated.md) — about 150 KiB.
- [Deploying](/_snapback/guide/guide-flat.deploying.generated.md) — about 45 KiB.
- [Protocol](/_snapback/guide/guide-flat.protocol.generated.md) — about 8 KiB.
- [Recipes](/_snapback/guide/guide-flat.recipes.generated.md) — about 80 KiB.
- [Sync](/_snapback/guide/guide-flat.sync.generated.md) — about 50 KiB.
- [Testing](/_snapback/guide/guide-flat.testing.generated.md) — about 40 KiB.
- [Guide metadata](/_snapback/guide/guide-flat.meta.generated.md) — about 120 KiB.
- [Generated reference](/_snapback/guide/guide-flat.reference.generated.md) — about 1.4 MiB; prefer the API reference index or exact lookup below.

## Exact and machine-readable lookup

- [HTTP route/schema catalog](/_snapback/guide/http.routes.v1.json) — build-bound route policies joined to committed request and response schemas.
- [API reference index](/_snapback/guide/reference/index.md) — compact package and module map.
- [API symbol registry](/_snapback/guide/reference/registry.json) — build-bound exact signatures and stable identities.
- [Diagnostic code registry](/_snapback/guide/reference/diagnostics.md) — every production SNAPBACK_* code with source and HTTP routing.
- [Diagnostic registry JSON](/_snapback/guide/reference/diagnostics-registry.json) — exact build-bound diagnostic lookup data.

## Bulk export

- [Complete guide, single file](/_snapback/guide/flat.md) — about 2.5 MiB and growing; use only when you want the whole corpus, and prefer the entry or section tiers for context-limited readers.

## Operate it

`snapback mcp` serves read-only Guide resources; `snapback mcp-control` adds typed control tools with local admin authority.
Preview control setup with `snapback agent setup --print <client> --server mcp-control`.
"#;

fn guide_bound_response(body: &'static [u8], content_type: &'static str) -> Response {
    let mut response = Response::new(Body::from(body));
    let headers = response.headers_mut();
    headers.insert(header::CONTENT_TYPE, HeaderValue::from_static(content_type));
    headers.insert(
        HeaderName::from_static(GUIDE_CONTENT_HASH_HEADER),
        HeaderValue::from_static(crate::guide::GUIDE_CONTENT_SHA256),
    );
    headers.insert(
        HeaderName::from_static(GUIDE_BUILD_COMMIT_HEADER),
        HeaderValue::from_static(option_env!("SNAPBACK_BUILD_GIT_COMMIT").unwrap_or("unknown")),
    );
    response
}

fn embedded_guide_response(file: &'static crate::guide::EmbeddedGuideFile) -> Response {
    guide_bound_response(file.bytes, file.content_type)
}

fn embedded_guide_path(path: &str) -> Response {
    crate::guide::file(path)
        .map(embedded_guide_response)
        .unwrap_or_else(|| StatusCode::NOT_FOUND.into_response())
}

/// The served-guide root is an alias for the embedded `guide/index.md` bytes.
///
/// @ref LLP 0061#4-distribution-and-discovery — served-guide §4a:
/// checkout-independent, build-bound access to the authoring corpus.
async fn served_guide_index() -> Response {
    embedded_guide_path(crate::guide::INDEX_PATH)
}

async fn served_guide_flat() -> Response {
    embedded_guide_path(crate::guide::FLAT_PATH)
}

async fn served_guide_page(Path(path): Path<String>) -> Response {
    embedded_guide_path(&path)
}

async fn served_llms_txt() -> Response {
    guide_bound_response(LLMS_TXT.as_bytes(), "text/markdown; charset=utf-8")
}

async fn served_http_routes() -> Response {
    let mut response = Response::new(Body::from(HTTP_ROUTES_V1));
    response.headers_mut().insert(
        header::CONTENT_TYPE,
        HeaderValue::from_static("application/json; charset=utf-8"),
    );
    response.headers_mut().insert(
        HeaderName::from_static(GUIDE_BUILD_COMMIT_HEADER),
        HeaderValue::from_static(option_env!("SNAPBACK_BUILD_GIT_COMMIT").unwrap_or("unknown")),
    );
    response
}

/// The app-data route registrations. Each handler literal appears only here;
/// `app()` installs these entries and `route_registry()` projects their specs.
