fn all_route_registrations() -> Vec<RegisteredRoute> {
    core_route_registrations()
        .into_iter()
        .chain(system_route_registrations())
        .chain(crate::admin::admin_route_registrations())
        .collect()
}

fn apply_registered_response_controls(
    effective: EffectiveRoutePolicy,
    mut response: Response,
) -> Response {
    // @ref LLP 0060#c2-defenses-that-do-not-change-the-boundary — observable
    // browser defenses for Snapback-owned pages, without claiming that these
    // headers make an app-origin-readable bearer XSS-proof.
    let headers = response.headers_mut();
    headers.insert(
        header::X_CONTENT_TYPE_OPTIONS,
        HeaderValue::from_static("nosniff"),
    );
    headers.insert(
        HeaderName::from_static("referrer-policy"),
        HeaderValue::from_static("no-referrer"),
    );
    headers.insert(
        HeaderName::from_static("permissions-policy"),
        HeaderValue::from_static(
            "camera=(), microphone=(), geolocation=(), payment=(), usb=(), serial=()",
        ),
    );
    headers.insert(
        HeaderName::from_static("x-frame-options"),
        HeaderValue::from_static("DENY"),
    );
    headers.insert(
        HeaderName::from_static("x-permitted-cross-domain-policies"),
        HeaderValue::from_static("none"),
    );
    if effective.response_sensitivity == ResponseSensitivity::StaticPublic {
        // The setup page has one embedded script. The built Exact shell has
        // build-specific inline bootstrap/manifest blocks and installs its own
        // exact-byte hashes in the handler. Never overwrite that narrower
        // response-specific policy with the setup fallback.
        let csp = HeaderName::from_static("content-security-policy");
        if !headers.contains_key(&csp) {
            headers.insert(
                csp,
                static_public_content_security_policy([SETUP_SCRIPT_SHA256]),
            );
        }
        headers.insert(
            HeaderName::from_static("cross-origin-opener-policy"),
            HeaderValue::from_static("same-origin"),
        );
    }
    if effective.cross_origin_embeddable {
        // @ref LLP 0044#delivery-profiles — these two closed delivery lanes
        // are expressly consumable by cross-origin `<img src>` and CDN pulls;
        // the URL is their entire authority.
        headers.insert(
            HeaderName::from_static("cross-origin-resource-policy"),
            HeaderValue::from_static("cross-origin"),
        );
    } else if effective.response_sensitivity == ResponseSensitivity::StaticPublic {
        headers.insert(
            HeaderName::from_static("cross-origin-resource-policy"),
            HeaderValue::from_static("same-origin"),
        );
    }
    if !matches!(
        effective.response_sensitivity,
        ResponseSensitivity::StaticPublic | ResponseSensitivity::PublicProjection
    ) {
        headers.insert(
            header::CACHE_CONTROL,
            HeaderValue::from_static("no-store, private"),
        );
    }
    response
}

const SETUP_SCRIPT_SHA256: &str = "hI3cw8Q0uOFE0WNfpu7y4/wmpx3phunwNAiXR31Qg+Y=";

/// Construct the one restrictive policy shared by Snapback-owned documents,
/// admitting only same-origin external scripts and explicitly hashed inline
/// bytes supplied by the concrete response handler.
pub(crate) fn static_public_content_security_policy<'a>(
    inline_script_sha256: impl IntoIterator<Item = &'a str>,
) -> HeaderValue {
    let mut value = String::from(
        "default-src 'none'; base-uri 'none'; object-src 'none'; frame-ancestors 'none'; form-action 'self'; script-src 'self'",
    );
    for digest in inline_script_sha256 {
        value.push_str(" 'sha256-");
        value.push_str(digest);
        value.push('\'');
    }
    value.push_str(
        "; style-src 'self' 'unsafe-inline'; img-src 'self' data:; font-src 'self'; connect-src 'self'; manifest-src 'self'; worker-src 'self'; require-trusted-types-for 'script'; trusted-types snapback",
    );
    HeaderValue::try_from(value).expect("base64 SHA-256 digests form a valid CSP header")
}

const POLICY_BODY_PEEK_LIMIT: usize = 2 * 1024 * 1024;
/// Host-op inputs may legitimately carry a declared-chunk-sized byte payload
/// as base64 (`asset.put`, `asset.ensureSeedFixture`), which the generic peek
/// bound would refuse before the operation ever ran. The host-ops lane peeks
/// under this envelope instead — sized to the declared chunk capability fact
/// in base64 plus headroom — and only after the route's coarse admin
/// authorization has already accepted the caller.
const POLICY_BODY_PEEK_LIMIT_HOST_OPS: usize =
    (crate::assets::ASSET_MAX_CHUNK_BYTES as usize * 4).div_ceil(3) + 64 * 1024;

/// Find a legacy authority field without mistaking ordinary app arguments
/// (which may legitimately contain columns named `user_id`) for transport
/// authority. `auth` is forbidden wherever a legacy wrapper placed it;
/// sibling owner fields are forbidden only on the transport object itself.
pub fn legacy_body_auth_field(value: &Value) -> Option<&str> {
    const FORBIDDEN: &[&str] = &[
        "auth",
        "principal",
        "user_id",
        "userId",
        "session_id",
        "sessionId",
        "custom_key",
        "customKey",
        "auth_fingerprint",
        "authFingerprint",
    ];
    fn envelope_auth(value: &Value) -> Option<&str> {
        let fields = value.as_object()?;
        for name in FORBIDDEN.iter().copied() {
            if fields.contains_key(name) {
                return Some(name);
            }
        }
        // Recurse only through the closed legacy transport wrappers. App
        // values in args/scope/value/correlation and permission-epoch maps
        // are opaque domain data even when a key happens to be `user_id`.
        ["request", "input", "ctx_ledger", "ctxLedger"]
            .into_iter()
            .filter_map(|name| fields.get(name))
            .find_map(envelope_auth)
    }

    envelope_auth(value)
}

fn body_auth_unsupported(field: &str) -> ApiError {
    SnapbackError::error(
        "SNAPBACK_AUTH_BODY_AUTH_UNSUPPORTED",
        "auth",
        "client-provided identity fields are not accepted when session authority is server-resolved",
    )
    .with_details(json!({ "field": field }))
    .into()
}

async fn peek_policy_json_body(
    request: Request<Body>,
    limit: usize,
) -> Result<(Request<Body>, Option<Value>), ApiError> {
    let (parts, body) = request.into_parts();
    let bytes = to_bytes(body, limit).await.map_err(|error| {
        SnapbackError::error(
            "SNAPBACK_VALUE_TOO_LARGE",
            "server",
            "request body exceeded the policy-gate inspection limit",
        )
        .with_details(json!({
            "limitBytes": limit,
            "error": error.to_string(),
        }))
    })?;
    let value = if bytes.is_empty() {
        None
    } else {
        serde_json::from_slice(&bytes).ok()
    };
    Ok((Request::from_parts(parts, Body::from(bytes)), value))
}

/// Monotonic deadline for ingesting the body of a request that holds a
/// managed admission root. It is deliberately strictly below the auth-mode
/// quiescence deadline so every admitted finite HTTP request leaves the epoch
/// before staging's drain barrier can expire.
// @ref LLP 0058#admitted-body-ingestion — exact 20000 ms bound, strictly
// below the 30000 ms quiescence deadline (ENG-24988).
const ADMITTED_BODY_INGEST_DEADLINE_MS: u64 = 20_000;
const _: () = assert!(
    ADMITTED_BODY_INGEST_DEADLINE_MS < crate::auth::admission::AUTH_MODE_QUIESCENCE_TIMEOUT_MS
);

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum AdmittedBodyTripReason {
    /// The monotonic ingest deadline elapsed before the body finished.
    DeadlineExceeded,
    /// The admitted epoch stopped accepting (staging closed or retired it)
    /// while the body was still arriving.
    AdmissionClosed,
}

/// Shared record of whether guarded ingestion actually surfaced a refusal.
/// The middleware consults it to publish the canonical diagnostic instead of
/// whatever shape error a downstream extractor derived from the cut body.
#[derive(Default)]
struct AdmittedBodyTrip(OnceLock<AdmittedBodyTripReason>);

impl AdmittedBodyTrip {
    fn reason(&self) -> Option<AdmittedBodyTripReason> {
        self.0.get().copied()
    }

    fn record(&self, reason: AdmittedBodyTripReason) -> AdmittedBodyTripReason {
        let _ = self.0.set(reason);
        self.reason().expect("admitted body trip was just recorded")
    }
}

fn admitted_body_trip_error(reason: AdmittedBodyTripReason) -> SnapbackError {
    match reason {
        AdmittedBodyTripReason::DeadlineExceeded => SnapbackError::error(
            "SNAPBACK_REQUEST_BODY_TIMEOUT",
            "server",
            "request body was not received within the admitted ingest deadline",
        )
        .with_details(json!({ "deadlineMs": ADMITTED_BODY_INGEST_DEADLINE_MS })),
        AdmittedBodyTripReason::AdmissionClosed => SnapbackError::error(
            "SNAPBACK_AUTH_MODE_PENDING",
            "auth",
            "request body ingestion was cancelled because app-data admission closed for an auth-mode transition",
        ),
    }
}

/// Request-body wrapper for invocations holding a managed admission root.
///
/// Body bytes arrive at a rate the remote client controls, so an unterminated
/// chunked upload would otherwise retain its admission root indefinitely and
/// force every auth-mode activation into `SNAPBACK_AUTH_MODE_QUIESCENCE_TIMEOUT`.
/// This guard bounds ingestion with a monotonic deadline strictly below the
/// quiescence deadline and cancels the read as soon as the admitted epoch
/// stops accepting, releasing the lease without waiting for the client.
///
/// @ref LLP 0058#admitted-body-ingestion — admitted ingestion is finite and
/// epoch-close aware; size-bound refusals keep their own diagnostic.
struct AdmittedBodyGuard {
    inner: Body,
    trip: Arc<AdmittedBodyTrip>,
    deadline: std::pin::Pin<Box<tokio::time::Sleep>>,
    epoch_close: std::pin::Pin<Box<dyn std::future::Future<Output = ()> + Send + 'static>>,
}

impl AdmittedBodyGuard {
    fn wrap(
        request: Request<Body>,
        admission: &AdmissionLease,
        controller: AuthAdmissionController,
    ) -> (Request<Body>, Arc<AdmittedBodyTrip>) {
        let trip = Arc::new(AdmittedBodyTrip::default());
        let admitted_epoch = admission.admission_epoch();
        // The watch owns only the controller handle, never a lease clone, so
        // the guard cannot extend the in-flight lifetime it exists to bound.
        let epoch_close = Box::pin(async move {
            let mut snapshot = controller.snapshot();
            while snapshot.admission_epoch == admitted_epoch && snapshot.accepting {
                snapshot = controller.changed(snapshot).await;
            }
        });
        let (parts, body) = request.into_parts();
        let guard = Self {
            inner: body,
            trip: trip.clone(),
            deadline: Box::pin(tokio::time::sleep(tokio::time::Duration::from_millis(
                ADMITTED_BODY_INGEST_DEADLINE_MS,
            ))),
            epoch_close,
        };
        (Request::from_parts(parts, Body::new(guard)), trip)
    }

    fn trip_frame(
        &self,
        reason: AdmittedBodyTripReason,
    ) -> std::task::Poll<Option<Result<http_body::Frame<Bytes>, axum::Error>>> {
        std::task::Poll::Ready(Some(Err(axum::Error::new(admitted_body_trip_error(
            reason,
        )))))
    }
}

impl HttpBody for AdmittedBodyGuard {
    type Data = Bytes;
    type Error = axum::Error;

    fn poll_frame(
        self: std::pin::Pin<&mut Self>,
        context: &mut std::task::Context<'_>,
    ) -> std::task::Poll<Option<Result<http_body::Frame<Self::Data>, Self::Error>>> {
        let this = self.get_mut();
        // A tripped guard is terminal even if the consumer keeps polling.
        if let Some(reason) = this.trip.reason() {
            return this.trip_frame(reason);
        }
        // Frames that already arrived always win the race; the guard only
        // decides what happens while the network has nothing to deliver.
        if let std::task::Poll::Ready(frame) =
            std::pin::Pin::new(&mut this.inner).poll_frame(context)
        {
            return std::task::Poll::Ready(frame);
        }
        if this.epoch_close.as_mut().poll(context).is_ready() {
            let reason = this.trip.record(AdmittedBodyTripReason::AdmissionClosed);
            return this.trip_frame(reason);
        }
        if this.deadline.as_mut().poll(context).is_ready() {
            let reason = this.trip.record(AdmittedBodyTripReason::DeadlineExceeded);
            return this.trip_frame(reason);
        }
        std::task::Poll::Pending
    }

    fn is_end_stream(&self) -> bool {
        self.trip.reason().is_none() && self.inner.is_end_stream()
    }

    fn size_hint(&self) -> http_body::SizeHint {
        self.inner.size_hint()
    }
}

enum HttpOperationSelection {
    Selected(OperationSpec),
    UnknownHost,
    Indeterminate,
}

fn ensure_operation_from_body(body: Option<&Value>) -> Option<OperationSpec> {
    let fields = body?.as_object()?;
    let operation = match fields.get("intent") {
        None => "app.ensure.legacy",
        Some(Value::String(intent)) if intent == "attest" => "app.ensure.attest",
        Some(Value::String(intent)) if intent == "provision" => "app.ensure.provision",
        Some(_) => return None,
    };
    operation_by_name(operation)
}

fn ensure_requested_mode(body: Option<&Value>) -> Option<PolicyAuthMode> {
    match body?.as_object()?.get("requestedMode")?.as_str()? {
        "dev" => Some(PolicyAuthMode::Dev),
        "sessions" => Some(PolicyAuthMode::Sessions),
        _ => None,
    }
}

/// Evaluate the ensure branch against all three mode facts before a loaded
/// artifact hash is inspected. Explicit provisioning is always AdminWrite, so
/// it remains the correction/re-stage branch for any posture. Legacy is only
/// the settled v0-dev compatibility form; Public attestation requires a
/// settled posture matching its requested mode.
fn authorize_ensure_posture(
    operation: OperationSpec,
    body: Option<&Value>,
    posture: PolicyAuthPosture,
) -> Result<(), ApiError> {
    if operation.operation != "app.ensure.provision" && posture.active != posture.desired {
        return Err(SnapbackError::error(
            "SNAPBACK_AUTH_MODE_PENDING",
            "auth",
            "app.ensure intent is unavailable while desired auth mode differs from active auth mode",
        )
        .into());
    }
    let allowed = match operation.operation {
        "app.ensure.provision" => true,
        "app.ensure.legacy" => posture.settled_at(PolicyAuthMode::Dev),
        "app.ensure.attest" => {
            posture.active == posture.desired
                && ensure_requested_mode(body).is_none_or(|requested| posture.settled_at(requested))
        }
        _ => true,
    };
    if allowed {
        return Ok(());
    }
    Err(SnapbackError::error(
        "SNAPBACK_AUTH_POLICY_UNAVAILABLE",
        "auth",
        "app.ensure intent is unavailable for the requested, active, and desired auth-mode posture",
    )
    .into())
}

async fn select_http_operation(
    spec: RouteSpec,
    runtime: &AppState,
    request_path: &str,
    body: Option<&Value>,
) -> HttpOperationSelection {
    match spec.effect_policy {
        EffectPolicy::FunctionKind => {
            let Some(name) = request_path
                .strip_prefix("/_snapback/api/functions/")
                .and_then(|path| path.strip_suffix("/run"))
            else {
                return HttpOperationSelection::Indeterminate;
            };
            let name = name.to_owned();
            let kind = with_snapback(&runtime.snapback, move |snapback| {
                snapback.function_kind(&name)
            })
            .await;
            HttpOperationSelection::Selected(direct_runner_operation_spec(kind.as_ref()))
        }
        EffectPolicy::OperationSpecific if spec.path == "/app/ensure" => {
            ensure_operation_from_body(body)
                .map(HttpOperationSelection::Selected)
                .unwrap_or(HttpOperationSelection::Indeterminate)
        }
        EffectPolicy::OperationSpecific if spec.path == "/_snapback/api/host-ops" => {
            let Some(fields) = body.and_then(Value::as_object) else {
                return HttpOperationSelection::Indeterminate;
            };
            let Some(operation) = fields.get("operation").and_then(Value::as_str) else {
                return HttpOperationSelection::Indeterminate;
            };
            if runtime.server.profile == crate::contract_types::ServerProfile::Prod
                && operation.starts_with("auth.rehearsal.")
            {
                return host_ops_operation_spec(operation, None, false)
                    .map(HttpOperationSelection::Selected)
                    .unwrap_or(HttpOperationSelection::UnknownHost);
            }
            let function = fields.get("function").and_then(Value::as_str);
            let kind = if let Some(function) = function {
                let function = function.to_owned();
                with_snapback(&runtime.snapback, move |snapback| {
                    snapback.function_kind(&function)
                })
                .await
            } else {
                None
            };
            let impersonated = fields
                .get("userId")
                .or_else(|| fields.get("user_id"))
                .is_some_and(|value| !value.is_null())
                || fields
                    .get("input")
                    .and_then(Value::as_object)
                    .and_then(|input| input.get("authority"))
                    .and_then(Value::as_object)
                    .and_then(|authority| authority.get("mode"))
                    .and_then(Value::as_str)
                    == Some("devUser");
            match host_ops_operation_spec(operation, kind.as_ref(), impersonated) {
                Some(spec) => HttpOperationSelection::Selected(spec),
                None => HttpOperationSelection::UnknownHost,
            }
        }
        EffectPolicy::OperationSpecific if spec.path == "/auth/oauth/register" => {
            HttpOperationSelection::Selected(
                operation_by_name("oauth.dynamic-register")
                    .expect("OAuth dynamic registration operation is registered"),
            )
        }
        EffectPolicy::OperationSpecific if spec.path == "/auth/oauth/token" => {
            HttpOperationSelection::Selected(
                operation_by_name("oauth.token-exchange")
                    .expect("OAuth token exchange operation is registered"),
            )
        }
        EffectPolicy::OperationSpecific if spec.path == "/auth/oauth/revoke" => {
            HttpOperationSelection::Selected(
                operation_by_name("oauth.revoke")
                    .expect("OAuth revocation operation is registered"),
            )
        }
        _ => HttpOperationSelection::Indeterminate,
    }
}

fn auth_transition_pending(runtime: &AppState) -> bool {
    let state = runtime.auth_mode_state();
    let posture = runtime.policy_auth_posture();
    state.active != state.desired
        || state.mode_state != crate::auth::mode::AuthModeStatus::Settled
        || state.app_data_availability != crate::auth::mode::AppDataAvailability::Available
        || posture.active != posture.desired
}

fn authorize_deferred_operation_preflight(
    runtime: &AppState,
    headers: &HeaderMap,
    allow_public_rehearsal_class: bool,
) -> Result<(), ApiError> {
    match runtime.active_policy_auth_mode() {
        PolicyAuthMode::Dev => {
            crate::admin::authorize_for_mode(&runtime.server, headers, false, PolicyAuthMode::Dev)
        }
        PolicyAuthMode::Sessions => {
            let admin = crate::admin::authorize_for_mode(
                &runtime.server,
                headers,
                true,
                PolicyAuthMode::Sessions,
            );
            if admin.is_ok()
                || authorize_secret_read(&runtime.secret_reads, headers).is_ok()
                || allow_public_rehearsal_class
            {
                Ok(())
            } else {
                // One stable outer denial avoids turning the preflight into
                // an oracle for lease validity or operation kind.
                admin
            }
        }
    }
}

fn settled_function_load_mode(runtime: &AppState) -> SnapbackResult<AuthMode> {
    if auth_transition_pending(runtime) {
        return Err(SnapbackError::error(
            "SNAPBACK_AUTH_MODE_PENDING",
            "auth",
            "functions.load is unavailable until auth mode is settled and app data is available",
        ));
    }
    Ok(runtime.auth_mode_state().active)
}

fn auth_diagnostic_app_route(path: &str) -> bool {
    matches!(path, "/" | "/health" | "/auth/session")
}

/// Central app-data availability fence. System/operator routes retain their
/// own registered policies; the one pending recovery branch is selected and
/// authorized later by the `/app/ensure` operation gate.
// @ref LLP 0060#d1-plaintext-listener-fence — repeat the startup transport
// refusal for embedded/router composition without claiming proxy/TLS posture.
/// The fixed 404 a hosted deployment serves for every `/_snapback/*` route.
///
/// Deliberately body-free and identical for every operator path: a response
/// that varied by route would let an unauthenticated caller enumerate the
/// operator surface it is not allowed to reach.
///
/// @ref LLP 0060#c2-defenses-that-do-not-change-the-boundary — the first
/// hosted profile chooses `operatorSurface: "disabled"`, and CORS is not
/// enabled on this path.
fn hosted_operator_surface_disabled_response() -> Response {
    let mut response = Response::new(axum::body::Body::empty());
    *response.status_mut() = StatusCode::NOT_FOUND;
    response
}

fn auth_app_data_refusal(spec: RouteSpec, runtime: &AppState) -> Option<SnapbackError> {
    if spec.class != RouteClass::AppData {
        return None;
    }
    // @ref LLP 0060#d5-hosted-readiness-is-conjunctive — the local target
    // cannot turn operator flags or proxy topology into hosted edge authority.
    // CLI composition refuses pre-bind; this repeats the refusal for embedded
    // routers while leaving diagnostic health/identity reachable.
    if runtime.server.auth_deployment == crate::auth::deployment::AuthDeploymentTarget::Hosted
        && !matches!(spec.path, "/" | "/health")
    {
        let Some(authority) = runtime
            .hosted_serving
            .as_ref()
            .and_then(|handle| handle.current())
        else {
            return Some(crate::auth::deployment::deployment_unsupported(
                crate::auth::deployment::HostedAuthCapabilities::local_target(),
            ));
        };
        if let Err(error) = authority.admission_epoch_at(now_millis()) {
            return Some(error);
        }
    }
    // Health is the sole request-path diagnostic that may remain reachable on
    // an already-composed insecure listener. Apply the shared transport fence
    // before the `/` and bootstrap-handshake diagnostic exemptions so neither
    // active nor merely desired sessions can consume a bearer over plaintext.
    if spec.path == "/health" {
        return None;
    }
    if runtime.server.auth_deployment != crate::auth::deployment::AuthDeploymentTarget::Hosted {
        let mode_state = runtime.auth_mode_state();
        let policy_posture = runtime.policy_auth_posture();
        let transport_active = if mode_state.active == crate::manifest::AuthMode::Sessions
            || policy_posture.active == PolicyAuthMode::Sessions
        {
            crate::manifest::AuthMode::Sessions
        } else {
            crate::manifest::AuthMode::Dev
        };
        let transport_desired = if mode_state.desired == crate::manifest::AuthMode::Sessions
            || policy_posture.desired == PolicyAuthMode::Sessions
        {
            crate::manifest::AuthMode::Sessions
        } else {
            crate::manifest::AuthMode::Dev
        };
        let session_transport = transport_active == crate::manifest::AuthMode::Sessions
            || transport_desired == crate::manifest::AuthMode::Sessions;
        let listener_loopback = match runtime.server.listener_transport_loopback() {
            Some(loopback) => loopback,
            None if session_transport => {
                return Some(SnapbackError::error(
                    "SNAPBACK_AUTH_TRANSPORT_INSECURE",
                    "auth",
                    "desired or active sessions require listener-owned loopback or TLS transport evidence; select the intended environment with SNAPBACK_PROFILE",
                )
                .with_details(json!({
                    "profileEnvVar": "SNAPBACK_PROFILE",
                    "requiredTransport": "loopback or TLS",
                })));
            }
            None => runtime.server.loopback,
        };
        if let Err(error) = crate::admin::validate_plaintext_auth_transport(
            listener_loopback,
            runtime.server.profile,
            transport_active,
            transport_desired,
            runtime.allow_insecure_dev_auth,
        ) {
            return Some(error);
        }
    }
    if auth_diagnostic_app_route(spec.path) {
        return None;
    }
    if auth_transition_pending(runtime) && spec.path != "/app/ensure" {
        return Some(SnapbackError::error(
            "SNAPBACK_AUTH_MODE_PENDING",
            "auth",
            "ordinary app data is unavailable while the auth-mode transition is pending",
        ));
    }
    let policy_mode = runtime.active_policy_auth_mode();
    if spec.path != "/app/ensure"
        && policy_mode == PolicyAuthMode::Dev
        && matches!(runtime.server.profile, ServerProfile::Prod)
    {
        return Some(SnapbackError::error(
            "SNAPBACK_AUTH_POLICY_UNAVAILABLE",
            "auth",
            "production profile refuses app data while auth mode is dev",
        ));
    }
    None
}

/// The bare public artifact routes whose whole contract is that anything can
/// fetch them without negotiating (LLP 0062 §5's "bare, credential-free,
/// non-redirecting path"). The app-api discovery and envelope routes are the
/// engine's *first* contact with a server — it cannot offer an auth-client
/// protocol before it has learned the app exists, and neither route reads or
/// mints authority. Same structural-properties-AND-closed-path-set rule as
/// the pasteable delivery lanes below: a future public route does not inherit
/// the exemption by shape alone.
fn bare_public_artifact_route(spec: RouteSpec) -> bool {
    spec.class == RouteClass::AppData
        && spec.policy == RoutePolicy::Public
        && spec.invocation_authority == InvocationAuthority::None
        && spec.credential_resolution == CredentialResolution::None
        && matches!(
            spec.path,
            "/app-api/current"
                | "/app-api/openapi.json"
                | "/app-api/agent-skill"
                | "/app-api/envelope/{sha256}"
                | "/.well-known/oauth-authorization-server"
                | "/.well-known/oauth-protected-resource"
        )
}

/// The pasteable asset-delivery lanes (LLP 0044 §Delivery profiles, dated
/// note 2026-07-31, author-approved). On these two routes the URL itself is
/// the entire authority — the public alias serves static-public bytes with
/// no credential, and the signed lane's query token is the credential —
/// while the auth-client protocol offer exists to version invalidation-
/// capable protocol clients. Plain `<img src>`, CDN pulls, and pasted
/// share links cannot send custom headers and negotiate nothing, so
/// requiring the offer here defeats the profiles' declared purpose without
/// protecting anything. The predicate asserts the structural properties
/// AND the closed path set: a future public route does not inherit the
/// exemption by shape alone.
fn pasteable_delivery_route(spec: RouteSpec) -> bool {
    spec.class == RouteClass::AppData
        && spec.policy == RoutePolicy::Public
        && spec.invocation_authority == InvocationAuthority::None
        && matches!(
            spec.credential_resolution,
            CredentialResolution::SignedUrlToken | CredentialResolution::None
        )
        && matches!(
            spec.path,
            "/assets/signed/{id}/{variant}" | "/assets/public/{id}/{variant}"
        )
}

/// A capability-link URL must remain usable when pasted into an ordinary
/// browser or opened by a preview crawler. The bearer path is its complete
/// credential, and the closed resolver plus invocation gate provide the
/// relevant versioned boundary; requiring a custom auth-client header would
/// make the commissioned share-link surface unusable.
///
/// @ref LLP 0031#capability-link-mint-and-serve-family — both public bearer rows are closed
/// to their registered templates and install no caller authority.
fn pasteable_capability_link_route(spec: RouteSpec) -> bool {
    spec.class == RouteClass::AppData
        && spec.policy == RoutePolicy::Public
        && spec.invocation_authority == InvocationAuthority::None
        && spec.credential_resolution == CredentialResolution::CapabilityLinkBearer
        && matches!(
            (spec.method, spec.path),
            ("GET", "/capability-links/{token}") | ("POST", "/capability-links/{token}/invoke")
        )
}

fn session_online_protocol_refusal(
    spec: RouteSpec,
    runtime: &AppState,
    headers: &HeaderMap,
) -> Option<SnapbackError> {
    if spec.class != RouteClass::AppData
        || auth_diagnostic_app_route(spec.path)
        || spec.path == "/app/ensure"
        // MCP versions its own carrier and every finite invocation beneath
        // this route is still prepared by the registered authority gate.
        // @ref LLP 0204#d3--surface-2-the-mcp-server
        || spec.path == "/mcp"
        || pasteable_delivery_route(spec)
        || pasteable_capability_link_route(spec)
        || bare_public_artifact_route(spec)
        || runtime.auth_mode_state().active != crate::manifest::AuthMode::Sessions
    {
        return None;
    }
    if !runtime.auth_program_readiness().session_activation_ready {
        return Some(
            SnapbackError::error(
                "SNAPBACK_AUTH_POLICY_UNAVAILABLE",
                "auth",
                "session-mode online request/response is not enabled by this process",
            )
            .with_details(json!({ "capability": "onlineRequestResponse" })),
        );
    }
    // Browser WebSockets cannot set the ordinary protocol headers, so the
    // live-stream upgrade carries the same closed offers as subprotocols.
    // Keep every non-upgrade route on the HTTP-only parser: a forged
    // Sec-WebSocket-Protocol header must not become a second HTTP grammar.
    // @ref LLP 0058#bootstrap-handshake — every online boundary repeats its
    // exact protocol offer on the carrier available to that boundary.
    let offers = if spec.path == "/live/{connection_id}/stream" {
        AuthClientProtocolOffers::from_headers(headers)
    } else {
        AuthClientProtocolOffers::from_http_headers(headers)
    };
    if offers.auth_client != Some(AUTH_PROTOCOL_V1) {
        // Name the repair, not just the violation. A caller told only that an
        // offer is missing otherwise goes looking at the process instead of at
        // their own headers.
        return Some(
            SnapbackError::error(
                "SNAPBACK_AUTH_PROFILE_CLIENT_UNSUPPORTED",
                "auth",
                "add the request header `x-snapback-auth-client-protocol: 1`: this request \
                 does not offer the exact supported auth-client protocol (on a WebSocket \
                 upgrade, offer the `snapback.auth-client.1` subprotocol instead; a \
                 non-session SnapbackClient passes both `authClientProtocol: 1` and \
                 `custody: 'anonymous-public'`)",
            )
            .with_details(json!({
                "capability": "onlineRequestResponse",
                "minimumAuthClientProtocol": AUTH_PROTOCOL_V1,
            })),
        );
    }
    None
}

fn live_function_name(spec: RouteSpec, path: &str) -> Option<&str> {
    let suffix = match spec.path {
        "/live/{name}/subscribe" => "/subscribe",
        "/live/{name}/resume" => "/resume",
        "/live/{name}/unsubscribe" => "/unsubscribe",
        _ => return None,
    };
    let name = path.strip_prefix("/live/")?.strip_suffix(suffix)?;
    (!name.is_empty() && !name.contains('/')).then_some(name)
}

/// Item 5 deliberately enables finite session work before LLP 0053's
/// invalidation protocol lands. The exception is narrow: only a manifest-
/// proved authority-independent durable live function, or an unprotected
/// ephemeral room, may cross the live gate in that interval.
///
/// @ref LLP 0058#live-and-replay-admission-before-later-items — refuse
///   auth-scoped live before query/materialization until invalidation exists.
async fn session_live_protocol_refusal(
    spec: RouteSpec,
    runtime: &AppState,
    headers: &HeaderMap,
    path: &str,
    body: Option<&Value>,
) -> Option<SnapbackError> {
    if runtime.auth_mode_state().active != crate::manifest::AuthMode::Sessions {
        return None;
    }

    let auth_scoped = if let Some(function) = live_function_name(spec, path) {
        let function = function.to_owned();
        !with_snapback(&runtime.snapback, move |snapback| {
            snapback.function_is_authority_independent(&function)
        })
        .await
    } else if spec.path == "/ephemeral/subscribe" {
        body.and_then(Value::as_object)
            .and_then(|body| body.get("collection"))
            .and_then(Value::as_str)
            .and_then(|collection| {
                runtime
                    .ephemeral
                    .subscription_requires_permission(collection)
            })
            .unwrap_or(false)
    } else {
        false
    };
    if !auth_scoped {
        return None;
    }

    if !runtime.auth_program_readiness().authorization_invalidation {
        return Some(
            SnapbackError::error(
                "SNAPBACK_AUTH_INVALIDATION_UNAVAILABLE",
                "auth",
                "auth-scoped live work is unavailable until authorization invalidation is ready",
            )
            .with_details(json!({ "capability": "authScopedLive" })),
        );
    }
    if AuthClientProtocolOffers::from_http_headers(headers).auth_invalidation
        != Some(AUTH_PROTOCOL_V1)
    {
        return Some(
            SnapbackError::error(
                "SNAPBACK_AUTH_INVALIDATION_CLIENT_UNSUPPORTED",
                "auth",
                "add the request header `x-snapback-auth-invalidation-protocol: 1` \
                 (or configure SnapbackClient with `authInvalidationProtocol: 1`): \
                 auth-scoped live work requires the exact authorization-invalidation protocol",
            )
            .with_details(json!({
                "capability": "authScopedLive",
                "minimumAuthInvalidationProtocol": AUTH_PROTOCOL_V1,
            })),
        );
    }
    None
}

fn registered_invocation_source(spec: RouteSpec) -> Option<InvocationSource> {
    match spec.path {
        "/capability-links" | "/capability-links/{id}" => {
            Some(InvocationSource::CapabilityLinkManagement)
        }
        "/capability-links/{token}/invoke" => Some(InvocationSource::HttpCapabilityLink),
        "/effects" | "/effects/{id}/approve" | "/effects/{id}/deny" => {
            Some(InvocationSource::EffectManagement)
        }
        "/watches"
        | "/watches/{id}"
        | "/watches/{id}/suspend"
        | "/watches/{id}/resume"
        | "/watches/{id}/renew" => Some(InvocationSource::WatchManagement),
        "/auth/session" => Some(InvocationSource::BootstrapHandshake),
        "/auth/refresh" | "/auth/password/change" | "/auth/recovery/rotate" => {
            Some(InvocationSource::AuthRefresh)
        }
        "/auth/logout" => Some(InvocationSource::AuthLogout),
        "/push/tokens/register" | "/push/tokens/unregister" => {
            Some(InvocationSource::PushTokenRegistry)
        }
        "/auth/step-up/request"
        | "/auth/oauth/authorize"
        | "/auth/agent-invitations"
        | "/auth/pairing-codes"
        | "/auth/grant-requests"
        | "/auth/grant-requests/{id}/approve"
        | "/auth/grant-requests/{id}/deny"
        | "/auth/grants"
        | "/auth/grants/by-actor/{actor_id}"
        | "/auth/grants/{id}" => Some(InvocationSource::AgentGrantManagement),
        "/query/{name}" | "/api/v1/query/{name}" => Some(InvocationSource::HttpQuery),
        "/mcp" => Some(InvocationSource::HttpMcp),
        // Attempt creation runs the generated upload-intent authorizer — a
        // Query-kind admission (LLP 0044 §Upload sessions).
        // Create and finalize both run the generated authorizer (finalize
        // through witness re-validation), so both are query-shaped.
        "/assets/attempts" | "/assets/attempts/{id}/finalize" => Some(InvocationSource::HttpQuery),
        "/assets/attempts/{id}" | "/assets/attempts/{id}/cancel" | "/assets/tus/{id}" => {
            Some(InvocationSource::AssetTransfer)
        }
        // Metadata reads, byte delivery, and owner deletion all decide
        // through the declared read-access policy / owner authority
        // (LLP 0044 §Asset read authorization) — query-shaped admission.
        "/assets/records/{id}"
        | "/assets/records/{id}/bytes/{variant}"
        | "/assets/records/{id}/signed-url" => Some(InvocationSource::HttpQuery),
        "/query/{name}/authorized-lease" => Some(InvocationSource::HttpQuery),
        // Bundle entries are evaluated exactly like HTTP queries; register
        // mode re-prepares LiveInitialQuery authorities per entry inside the
        // local cut (LLP 0092 §0D.5).
        "/app/bundle" => Some(InvocationSource::HttpQuery),
        "/mutation/{name}" | "/api/v1/mutation/{name}" => Some(InvocationSource::HttpMutation),
        "/action/{name}" | "/api/v1/action/{name}" => Some(InvocationSource::HttpAction),
        "/api/v1/run" => Some(InvocationSource::HttpRun),
        "/api/v1/ask" => Some(InvocationSource::HttpAsk),
        "/streams/{attempt_token}" => Some(InvocationSource::HttpQuery),
        "/streams/{attempt_token}/cancel" => Some(InvocationSource::HttpAction),
        "/client-mutations/acknowledge" | "/client-mutations/identity-range" => {
            Some(InvocationSource::MutationSettlementAcknowledgement)
        }
        "/operations/explain" => Some(InvocationSource::HttpQuery),
        "/live/authorization-invalidation/acknowledge"
        | "/live/authorization-invalidation/manual-retry" => {
            Some(InvocationSource::InvalidationAcknowledgement)
        }
        "/connection/open" => Some(InvocationSource::ConnectionOpen),
        "/live/{name}/subscribe" => Some(InvocationSource::LiveInitialQuery),
        "/live/{name}/resume" => Some(InvocationSource::LiveResume),
        "/live/{name}/unsubscribe" => Some(InvocationSource::LiveUnsubscribe),
        "/live/{connection_id}/stream" => Some(InvocationSource::LiveStream),
        "/outbox/{connection_id}" => Some(InvocationSource::OutboxDrain),
        "/ephemeral/collections/ensure" => Some(InvocationSource::EphemeralRegister),
        "/ephemeral/publish" => Some(InvocationSource::EphemeralPublish),
        "/ephemeral/subscribe" => Some(InvocationSource::EphemeralSubscribe),
        "/ephemeral/delete" => Some(InvocationSource::EphemeralDelete),
        "/_snapback/api/functions/{name}/run" => Some(InvocationSource::DirectAdminRunner),
        "/_snapback/api/storage/protected-erasure" => {
            Some(InvocationSource::ProtectedRecordErasure)
        }
        "/_snapback/api/storage/operation-coverage/activate" => {
            Some(InvocationSource::OperationCoverageActivation)
        }
        _ => None,
    }
}

fn selected_invocation_source(
    spec: RouteSpec,
    operation: Option<OperationSpec>,
) -> Option<InvocationSource> {
    registered_invocation_source(spec).or_else(|| {
        let operation = operation?.operation;
        if operation.starts_with("host_ops.function.run.") {
            Some(InvocationSource::HostOperationFunctionRun)
        } else if operation.starts_with("host_ops.function.explain") {
            Some(InvocationSource::HostOperationMutationDryRun)
        } else {
            None
        }
    })
}

/// Mutation-class authority preparation is part of the writer's route to its
/// commit turn. Making that Local acquisition visible to the scheduler keeps a
/// queued evaluation from winning between credential preparation and staging.
///
/// @ref LLP 0200#25-cancellation-fairness-and-bounded-staleness — evaluation
/// turns yield at their boundary while mutation-class writer work is pending.
fn mutation_writer_invocation_source(source: InvocationSource) -> bool {
    matches!(
        source,
        InvocationSource::HttpMutation
            | InvocationSource::LocalMutation
            | InvocationSource::AssetCallback
            | InvocationSource::NestedMutation
    )
}

fn invocation_authority_value(source: InvocationSource, body: Option<&Value>) -> Option<&Value> {
    // `MutationRequest` flattens `HandlerInput`; query/action inputs and all
    // authority-only DTOs are rooted at the request object. Durable live
    // subscribe is the one wrapper whose handler authority lives in `input`.
    let body = body?;
    if source == InvocationSource::LiveInitialQuery {
        body.as_object()?.get("input")
    } else {
        Some(body)
    }
}

fn invocation_wire_authority(
    source: InvocationSource,
    authority_value: Option<&Value>,
) -> WireAuthorityFields {
    let Some(value) = authority_value else {
        return WireAuthorityFields::default();
    };
    match source {
        InvocationSource::LiveInitialQuery
        | InvocationSource::LiveResume
        | InvocationSource::LiveUnsubscribe => WireAuthorityFields::inspect_live_owner(value),
        InvocationSource::EphemeralRegister
        | InvocationSource::EphemeralPublish
        | InvocationSource::EphemeralSubscribe
        | InvocationSource::EphemeralDelete => WireAuthorityFields::inspect_ephemeral(value),
        _ => WireAuthorityFields::inspect_handler(value),
    }
}

fn dev_body_authority(value: Option<&Value>) -> ResolvedAppAuthority {
    let auth = value
        .and_then(Value::as_object)
        .and_then(|object| object.get("auth"))
        .cloned()
        .and_then(|auth| serde_json::from_value::<AuthInput>(auth).ok())
        .unwrap_or_default();
    ResolvedAppAuthority::dev_from_auth(&auth)
}

fn dev_host_operation_authority(value: Option<&Value>) -> ResolvedAppAuthority {
    value
        .and_then(Value::as_object)
        .and_then(|object| object.get("userId").or_else(|| object.get("user_id")))
        .and_then(Value::as_str)
        .map_or(ResolvedAppAuthority::Anonymous, |user_id| {
            ResolvedAppAuthority::DevImpersonation {
                user_id: user_id.to_owned(),
                roles: Vec::new(),
                local_dev_only: true,
            }
        })
}

fn queued_replay_requested(source: InvocationSource, body: Option<&Value>) -> bool {
    match source {
        // @ref LLP 0096#81-the-acknowledge-routes-demand-the-authreplay-offer-coupling —
        // invalidation acks are item-6-owned; only mutation settlement is
        // descriptor-bound, so `InvalidationAcknowledgement` falls through to
        // the `false` arm.
        InvocationSource::MutationSettlementAcknowledgement => true,
        InvocationSource::HttpMutation => body.and_then(Value::as_object).is_some_and(|object| {
            object.contains_key("clientMutationId")
                || object.contains_key("client_mutation_id")
                || object.contains_key("acknowledgedClientMutationIds")
                || object.contains_key("acknowledged_client_mutation_ids")
        }),
        _ => false,
    }
}

async fn prepare_registered_route_authority(
    source: Option<InvocationSource>,
    effective: EffectiveRoutePolicy,
    runtime: &AppState,
    admission: Option<&AdmissionLease>,
    headers: &HeaderMap,
    body: Option<&Value>,
    resolved_connection_authority: Option<&ResolvedAppAuthority>,
) -> Result<Option<PreparedAuthority>, ApiError> {
    let Some(source) = source else {
        return Ok(None);
    };
    let Some(admission) = admission else {
        debug_assert_eq!(source, InvocationSource::BootstrapHandshake);
        return Ok(None);
    };
    let handler_value = invocation_authority_value(source, body);
    let wire = invocation_wire_authority(source, handler_value);
    let mode_state = runtime.auth_mode_state();
    let active_mode = mode_state.active;
    if active_mode == crate::manifest::AuthMode::Sessions && queued_replay_requested(source, body) {
        let offered = AuthClientProtocolOffers::from_http_headers(headers).authority_descriptor;
        if !runtime.auth_program_readiness().authority_descriptor {
            return Err(SnapbackError::error(
                "SNAPBACK_AUTH_POLICY_UNAVAILABLE",
                "auth",
                "queued replay is unavailable in this process",
            )
            .with_details(json!({ "capability": "queuedReplay" }))
            .into());
        }
        if offered != Some(AUTH_PROTOCOL_V1) {
            return Err(SnapbackError::error(
                "SNAPBACK_AUTH_PROFILE_CLIENT_UNSUPPORTED",
                "auth",
                "queued replay requires the exact authority-descriptor protocol offer",
            )
            .with_details(json!({
                "capability": "queuedReplay",
                "minimumAuthorityDescriptorProtocol": AUTH_PROTOCOL_V1,
            }))
            .into());
        }
    }
    let (resolved, fenced_publication, service_publication) =
        if let Some(resolved) = resolved_connection_authority {
            // Connection open/acts already carry the exact bound publication
            // fence. The caller installs that fence after the shared invocation
            // gate has projected this resolved authority.
            (resolved.clone(), None, None)
        } else {
            match active_mode {
                crate::manifest::AuthMode::Dev => {
                    if source == InvocationSource::BootstrapHandshake
                        && headers.contains_key(header::AUTHORIZATION)
                    {
                        return Err(SnapbackError::error(
                            "SNAPBACK_AUTH_REQUIRED",
                            "auth",
                            "session credentials are unavailable while auth mode is dev",
                        )
                        .into());
                    }
                    if matches!(
                        source,
                        InvocationSource::HostOperationFunctionRun
                            | InvocationSource::HostOperationMutationDryRun
                    ) {
                        (dev_host_operation_authority(handler_value), None, None)
                    } else if effective.invocation_authority == InvocationAuthority::ClientAsserted
                        || source == InvocationSource::DirectAdminRunner
                    {
                        (dev_body_authority(handler_value), None, None)
                    } else {
                        (ResolvedAppAuthority::Anonymous, None, None)
                    }
                }
                crate::manifest::AuthMode::Sessions => {
                    let coordinator = installed_auth_coordinator(runtime)?;
                    if matches!(
                        source,
                        InvocationSource::DirectAdminRunner
                            | InvocationSource::HostOperationFunctionRun
                            | InvocationSource::HostOperationMutationDryRun
                            | InvocationSource::ProtectedRecordErasure
                            | InvocationSource::OperationCoverageActivation
                    ) {
                        (
                            ResolvedAppAuthority::AdminBypass {
                                reason: "administrative application invocation".to_owned(),
                            },
                            Some(
                                coordinator
                                    .prepare_anonymous_publication()
                                    .map_err(ApiError::from)?,
                            ),
                            None,
                        )
                    } else if matches!(
                        effective.credential_resolution,
                        CredentialResolution::OptionalSessionBearer
                            | CredentialResolution::OptionalSessionOrScopedToken
                            | CredentialResolution::RequiredSessionBearer
                            | CredentialResolution::RequiredSessionOrScopedToken
                    ) && (effective.credential_resolution
                        == CredentialResolution::RequiredSessionBearer
                        || effective.credential_resolution
                            == CredentialResolution::RequiredSessionOrScopedToken
                        || headers.contains_key(header::AUTHORIZATION))
                    {
                        // Invalid and duplicate Authorization values remain
                        // presented-invalid credentials. Finite request resolution
                        // is projection-only and never falls through to provider or
                        // SQLite.
                        let bearer = auth_bearer(headers).unwrap_or_default().to_owned();
                        let provider = installed_auth_provider(runtime)?;
                        let now_ms = provider.now_ms();
                        let service_monotonic_now = provider.monotonic_now();
                        if matches!(
                            effective.credential_resolution,
                            CredentialResolution::OptionalSessionOrScopedToken
                                | CredentialResolution::RequiredSessionOrScopedToken
                        ) && classify_credential(&bearer) == Some(CredentialClass::ScopedToken)
                        {
                            dispatch_credential_class(&bearer, CredentialClass::ScopedToken)
                                .map_err(|error| ApiError::from(error.into_snapback_error()))?;
                            let token = ScopedToken::parse(&bearer)
                                .map_err(|_| ApiError::from(scoped_token_invalid_carrier()))?;
                            // Bind the durable service-token lookup to the
                            // authorization stream that admitted it. A reset
                            // which starts after this capture makes the final
                            // publication stale; a reset which wins first
                            // refuses the capture before SQLite is consulted.
                            //
                            // @ref LLP 0059#reset-restore-and-stream-publication — a
                            //   predecessor durable result must never bind to
                            //   the successor stream published by reset.
                            let stream_publication = coordinator
                                .prepare_anonymous_publication()
                                .map_err(ApiError::from)?;
                            #[cfg(test)]
                            pause_test_finite_authority_request(
                                headers
                                    .get(TEST_FINITE_AUTHORITY_PAUSE_HEADER)
                                    .and_then(|value| value.to_str().ok()),
                                TestFiniteAuthorityPausePoint::AfterScopedTokenStreamCapture,
                                None,
                            )
                            .await;
                            let service_fences = runtime.service_authority_fences.clone();
                            let service_clock = provider.clone();
                            let _writer_turn_guard = runtime
                                .live_fanout_coalescer
                                .as_ref()
                                .filter(|_| mutation_writer_invocation_source(source))
                                .map(|coalescer| coalescer.writer_turn_guard());
                            let (resolved, service_publication) =
                                with_snapback(&runtime.snapback, move |snapback| {
                                    let resolved = snapback
                                        .auth_database_mut()
                                        .resolve_scoped_token(&token, now_ms)?;
                                    let publication = service_fences
                                        .register(
                                            resolved.service_authority_witness(),
                                            now_ms,
                                            service_monotonic_now,
                                        )?
                                        .with_provider_clock(service_clock);
                                    Ok::<_, SnapbackError>((resolved, publication))
                                })
                                .await?;
                            #[cfg(test)]
                            pause_test_finite_authority_request(
                                headers
                                    .get(TEST_FINITE_AUTHORITY_PAUSE_HEADER)
                                    .and_then(|value| value.to_str().ok()),
                                TestFiniteAuthorityPausePoint::AfterScopedTokenDurableResolve,
                                None,
                            )
                            .await;
                            (
                                ResolvedAppAuthority::from_scoped_token(resolved),
                                Some(stream_publication),
                                Some(service_publication),
                            )
                        } else {
                            // @ref LLP 0077#author-decisions--2026-07-23 — decision 4: both
                            // session spellings reach the resolver; on hosted
                            // lanes the sender admission (proof + spelling
                            // checks) has already run before this gate.
                            if classify_credential(&bearer).is_some_and(|class| {
                                !matches!(
                                    class,
                                    CredentialClass::Session | CredentialClass::SenderSession
                                )
                            }) {
                                dispatch_credential_class(&bearer, CredentialClass::Session)
                                    .map_err(|error| ApiError::from(error.into_snapback_error()))?;
                                unreachable!("wrong-class dispatch always refuses");
                            }
                            let prepared = if matches!(
                                source,
                                InvocationSource::AuthRefresh | InvocationSource::AuthLogout
                            ) {
                                coordinator.resolve_family_bearer(
                                    &bearer,
                                    now_ms,
                                    provider.monotonic_now(),
                                )
                            } else {
                                coordinator.resolve_required_bearer(
                                    &bearer,
                                    now_ms,
                                    provider.monotonic_now(),
                                )
                            }
                            .map_err(ApiError::from)?;
                            let (resolved, publication) = prepared.into_parts();
                            (resolved, Some(publication), None)
                        }
                    } else {
                        (
                            ResolvedAppAuthority::Anonymous,
                            Some(
                                coordinator
                                    .prepare_anonymous_publication()
                                    .map_err(ApiError::from)?,
                            ),
                            None,
                        )
                    }
                }
            }
        };
    let authority = InvocationGate::prepare_admitted_authority(
        source,
        active_mode,
        runtime.server.profile,
        admission.clone(),
        &wire,
        resolved,
    )
    .map_err(ApiError::from)?;
    let authority = match fenced_publication {
        Some(publication) => authority.with_fenced_publication(publication),
        None if source == InvocationSource::BootstrapHandshake => authority
            .with_authorization_stream_incarnation(
                installed_auth_coordinator(runtime)?
                    .authorization_stream_incarnation()
                    .map_err(ApiError::from)?,
            ),
        None => authority,
    };
    let authority = match service_publication {
        Some(publication) => authority.with_service_publication(publication),
        None => authority,
    };
    Ok(Some(
        authority
            .with_rehearsal_authority_registry(runtime.auth_rehearsal_live_grants.clone())
            .map_err(ApiError::from)?,
    ))
}

async fn record_successful_finite_session_use(
    runtime: &AppState,
    authority: &PreparedAuthority,
) -> Result<(), ApiError> {
    let ResolvedAppAuthority::Session {
        session_id,
        generation,
        ..
    } = authority.resolved()
    else {
        return Ok(());
    };
    let provider = installed_auth_provider(runtime)?;
    let coordinator = installed_auth_coordinator(runtime)?;
    let provider_admission = provider.admit().await;
    let session_id = session_id.clone();
    let expected_generation = *generation;
    let now_ms = provider.now_ms();
    let effect_authority = authority.clone();
    let outcome = with_snapback(&runtime.snapback, move |snapback| {
        let _effect = effect_authority
            .effect_guard("authenticated-use expiry transaction")
            .map_err(ProviderError::from)?;
        provider_admission.record_authenticated_use(
            snapback.auth_database_mut(),
            &session_id,
            expected_generation,
            now_ms,
        )
    })
    .await
    .map_err(map_provider_error)?;
    coordinator
        .finalize_authenticated_use(
            match authority.resolved() {
                ResolvedAppAuthority::Session { session_id, .. } => session_id,
                _ => unreachable!("checked session authority"),
            },
            expected_generation,
            outcome,
            now_ms,
            provider.monotonic_now(),
        )
        .map_err(ApiError::from)?;
    Ok(())
}

fn deferred_secret_read_scope(
    spec: RouteSpec,
    request_path: &str,
    body: Option<&Value>,
) -> Option<SecretReadScope> {
    match spec.effect_policy {
        EffectPolicy::FunctionKind => request_path
            .strip_prefix("/_snapback/api/functions/")
            .and_then(|path| path.strip_suffix("/run"))
            .map(|name| SecretReadScope::FunctionRun(name.to_owned())),
        EffectPolicy::OperationSpecific if spec.path == "/_snapback/api/host-ops" => {
            let fields = body?.as_object()?;
            let operation = fields.get("operation")?.as_str()?;
            let function = fields.get("function")?.as_str()?.to_owned();
            match operation {
                "function.run" => Some(SecretReadScope::FunctionRun(function)),
                "function.explain" => Some(SecretReadScope::FunctionExplain(function)),
                _ => None,
            }
        }
        _ => None,
    }
}

fn route_uses_managed_admission(spec: RouteSpec) -> bool {
    (spec.class == RouteClass::AppData && !matches!(spec.path, "/" | "/health" | "/app/ensure"))
        || matches!(
            spec.path,
            "/_snapback/api/functions/{name}/run"
                | "/_snapback/api/functions/load"
                | "/_snapback/api/host-ops"
                | "/_snapback/api/app/reset"
                | "/_snapback/api/app/seed/ensure-v1"
                | "/_snapback/api/app/seed/preview-v1"
                | "/_snapback/api/app/seed/reset-install-v1"
                | "/_snapback/api/app/seed/clear-v1"
                | "/_snapback/api/storage/protected-erasure"
                | "/_snapback/api/storage/operation-coverage/activate"
                | "/_snapback/api/auth/mailbox"
                | "/_snapback/api/admin-secret-read/mint"
                | "/_snapback/api/auth/integrations"
                | "/_snapback/api/auth/integrations/{id}/retire"
                | "/_snapback/api/auth/integrations/{id}/suspend"
                | "/_snapback/api/auth/integrations/{id}/resume"
                | "/_snapback/api/auth/declared-clients"
                | "/_snapback/api/auth/declared-clients/bless"
                | "/_snapback/api/auth/declared-clients/suspend"
                | "/_snapback/api/auth/declared-clients/resume"
                | "/_snapback/api/auth/declared-clients/delete"
        )
}

fn acquire_registered_route_admission(
    spec: RouteSpec,
    runtime: &AppState,
) -> Result<Option<AdmissionLease>, ApiError> {
    if !route_uses_managed_admission(spec) {
        return Ok(None);
    }
    let controller = runtime.auth_admission_controller();
    let active_mode = runtime.auth_mode_state().active;
    let admission = if spec.path == "/auth/session" {
        controller.admit_diagnostic_for_mode(active_mode)
    } else {
        controller.admit_for_mode(active_mode)
    };
    admission.map(Some).map_err(ApiError::from)
}

fn finish_registered_response(
    effective: EffectiveRoutePolicy,
    response: Response,
    admission: Option<&AdmissionLease>,
    authority: Option<&PreparedAuthority>,
) -> Response {
    let mut response = if let Some(admission) = admission {
        let controlled = apply_registered_response_controls(effective, response);
        let committed_outcome = controlled
            .extensions()
            .get::<CommittedAuthOutcome>()
            .cloned();
        let committed_response_class =
            committed_outcome
                .as_ref()
                .and_then(|_| match controlled.status() {
                    StatusCode::OK => Some(CommittedAuthResponseClass::CredentialSecret),
                    StatusCode::NO_CONTENT => Some(CommittedAuthResponseClass::LogoutNoContent),
                    StatusCode::ACCEPTED => Some(CommittedAuthResponseClass::FamilyAlarmAccepted),
                    _ => None,
                });
        // Keep the server's canonical publication order aligned with exact
        // connection acts: stream/session leaf first, then the independent
        // mode-admission cut. Taking mode admission first deadlocks against a
        // concurrent connection handler that already owns the shared stream
        // fence and reaches its query/publication admission guard.
        //
        // @ref LLP 0059#locking-and-linearization — finite leaf validation
        // precedes the one bounded publication handoff.
        let publish_under_mode = || {
            let _mode_publication = admission.effect_guard("HTTP response publication")?;
            Ok(controlled)
        };
        let published = match committed_outcome {
            Some(outcome) => match committed_response_class {
                Some(response_class) => outcome.try_publish(
                    response_class,
                    now_millis(),
                    Instant::now(),
                    publish_under_mode,
                ),
                None => match admission.effect_guard("HTTP response publication") {
                    Ok(_mode_publication) => Err(SnapbackError::error(
                        "SNAPBACK_AUTH_PROJECTION_UNAVAILABLE",
                        "auth",
                        "committed auth outcome was attached to an unsupported response",
                    )),
                    Err(error) => Err(error),
                },
            },
            None => match authority {
                Some(authority) => {
                    authority.try_publish_fenced(now_millis(), Instant::now(), publish_under_mode)
                }
                None => publish_under_mode().map(Some),
            },
        };
        match published {
            Ok(Some(response)) => response,
            Ok(None) => {
                let error = match authority {
                    Some(authority) => stale_prepared_authority(authority, now_millis()),
                    None => SnapbackError::error(
                        "SNAPBACK_AUTH_POLICY_UNAVAILABLE",
                        "auth",
                        "the authorization stream changed before response publication",
                    ),
                };
                apply_registered_response_controls(effective, ApiError::from(error).into_response())
            }
            Err(error) => {
                apply_registered_response_controls(effective, ApiError::from(error).into_response())
            }
        }
    } else {
        apply_registered_response_controls(effective, response)
    };
    if let Some(admission) = admission {
        // Clones share one root token, so retaining both the bare route lease
        // and any prepared authority does not inflate the in-flight count.
        response.extensions_mut().insert(admission.clone());
    }
    if let Some(authority) = authority {
        response.extensions_mut().insert(authority.clone());
    }
    let publication_authority = response
        .extensions_mut()
        .remove::<RetainedRealtimeAuthority>();
    if let Some(admission) = admission {
        let (parts, body) = response.into_parts();
        let body = Body::new(RetainedAdmissionBody {
            inner: body,
            _admission: admission.clone(),
            _authority: authority.cloned(),
            _publication_authority: publication_authority,
            realtime_handoff_committed: false,
            realtime_handoff_failed: false,
        });
        Response::from_parts(parts, body)
    } else {
        debug_assert!(publication_authority.is_none());
        response
    }
}

/// Response extensions may be discarded after the headers are encoded. Keep
/// the counted root (and exact authority when present) inside the body itself
/// so transition quiescence covers every frame through end/error/drop.
struct RetainedAdmissionBody {
    inner: Body,
    _admission: AdmissionLease,
    _authority: Option<PreparedAuthority>,
    _publication_authority: Option<RetainedRealtimeAuthority>,
    realtime_handoff_committed: bool,
    realtime_handoff_failed: bool,
}

/// Response extensions can be discarded after header encoding. The Arc makes
/// the extension cloneable while keeping the exact durable/room publication
/// permits alive until the wrapped HTTP body reaches its final transport sink
/// (or is dropped).
#[derive(Clone)]
struct RetainedRealtimeAuthority {
    _permits: Arc<Vec<RealtimePublicationPermit>>,
    outbox_leases: Arc<Vec<crate::ephemeral::OutboxDrainLease>>,
    connection_handoff: Option<RetainedConnectionHandoff>,
}

#[derive(Clone)]
struct RetainedConnectionHandoff {
    connections: ConnectionRegistry,
    ephemeral: EphemeralApi,
    connection_act: PreparedConnectionAct,
    auth_provider: Option<Arc<AuthProvider>>,
}

impl RetainedRealtimeAuthority {
    fn acknowledge_outbox_leases(&self, admission: &AdmissionLease) -> bool {
        match self.connection_handoff.as_ref() {
            None => admission
                .effect_guard("HTTP response body frame publication")
                .is_ok_and(|_publication| {
                    crate::ephemeral::OutboxDrainLease::acknowledge_all(&self.outbox_leases)
                }),
            Some(handoff) => {
                // @ref LLP 0059#act-time-validation — the exact leaf/grant
                // check and leased HTTP ownership acceptance share one final
                // publication -> registry -> outbox cut.
                // Connection routes install the same stream/session
                // publication handle in PreparedAuthority and this exact act.
                // Use it once (non-reentrant) to make leaf validation,
                // grant-current validation, and batch acknowledgement one
                // publication → registry → outbox cut.
                let (epoch_now_ms, monotonic_now) = handoff.auth_provider.as_ref().map_or_else(
                    || (now_millis(), Instant::now()),
                    |provider| (provider.now_ms(), provider.monotonic_now()),
                );
                handoff
                    .connection_act
                    .try_act(&handoff.connections, epoch_now_ms, monotonic_now, || {
                        let _publication = admission
                            .effect_guard("HTTP response body frame publication")
                            .map_err(ApiError::from)?;
                        Ok(handoff.ephemeral.acknowledge_outbox_handoff_bound(
                            &handoff.connection_act.connection_id,
                            &handoff.connection_act.effect_fence(),
                            &self.outbox_leases,
                        ))
                    })
                    .unwrap_or(false)
            }
        }
    }
}

fn retain_room_authority(mut response: Response, permit: Option<RoomAuthorityPermit>) -> Response {
    if let Some(permit) = permit {
        retain_realtime_authority_in(&mut response, vec![RealtimePublicationPermit::Room(permit)]);
    }
    response
}

fn retain_realtime_authority_in(response: &mut Response, permits: Vec<RealtimePublicationPermit>) {
    retain_realtime_handoff_in(response, permits, Vec::new(), None);
}

fn retain_realtime_handoff_in(
    response: &mut Response,
    permits: Vec<RealtimePublicationPermit>,
    outbox_leases: Vec<crate::ephemeral::OutboxDrainLease>,
    connection_handoff: Option<RetainedConnectionHandoff>,
) {
    if !permits.is_empty() || !outbox_leases.is_empty() || connection_handoff.is_some() {
        response.extensions_mut().insert(RetainedRealtimeAuthority {
            _permits: Arc::new(permits),
            outbox_leases: Arc::new(outbox_leases),
            connection_handoff,
        });
    }
}

impl HttpBody for RetainedAdmissionBody {
    type Data = Bytes;
    type Error = axum::Error;

    fn poll_frame(
        self: std::pin::Pin<&mut Self>,
        context: &mut std::task::Context<'_>,
    ) -> std::task::Poll<Option<Result<http_body::Frame<Self::Data>, Self::Error>>> {
        let this = self.get_mut();
        if this.realtime_handoff_failed {
            return std::task::Poll::Ready(None);
        }
        // Authority was validated exactly once when the complete response was
        // transferred into this body. Network flushing happens later without
        // rechecking the leaf; only the mode-admission root remains live per
        // frame so a retired mode cannot keep producing bytes.
        // Poll into a local first. No byte is yielded until the complete leased
        // set validates and is acknowledged at this response-body ownership
        // boundary. Pending/error/drop leaves every frame physically queued.
        let frame = std::pin::Pin::new(&mut this.inner).poll_frame(context);
        if !this.realtime_handoff_committed {
            match &frame {
                std::task::Poll::Ready(Some(Ok(_))) => {
                    let committed = this._publication_authority.as_ref().map_or_else(
                        || {
                            this._admission
                                .effect_guard("HTTP response body frame publication")
                                .is_ok()
                        },
                        |authority| authority.acknowledge_outbox_leases(&this._admission),
                    );
                    if !committed {
                        this.realtime_handoff_failed = true;
                        this._publication_authority = None;
                        return std::task::Poll::Ready(None);
                    }
                    this.realtime_handoff_committed = true;
                }
                std::task::Poll::Ready(Some(Err(_))) | std::task::Poll::Ready(None) => {
                    this.realtime_handoff_failed = true;
                    this._publication_authority = None;
                }
                std::task::Poll::Pending => {}
            }
        } else if this
            ._admission
            .effect_guard("HTTP response body frame publication")
            .is_err()
        {
            // EOF is terminal even if the consumer retains the Body object.
            // Release every leased frame/publication permit at the failed
            // mode-root cut instead of parking the globally active batch
            // until object destruction.
            this.realtime_handoff_failed = true;
            this._publication_authority = None;
            return std::task::Poll::Ready(None);
        }
        frame
    }

    fn is_end_stream(&self) -> bool {
        self.realtime_handoff_failed || self.inner.is_end_stream()
    }

    fn size_hint(&self) -> http_body::SizeHint {
        self.inner.size_hint()
    }
}

fn stale_prepared_authority(authority: &PreparedAuthority, epoch_now_ms: u64) -> SnapbackError {
    match authority.resolved() {
        ResolvedAppAuthority::Session { .. } => {
            let disposition = authority
                .session_terminal_reason(epoch_now_ms, Instant::now())
                .ok()
                .flatten()
                .map(session_http_authority_disposition)
                .unwrap_or(HttpAuthorityDisposition::Carrier);
            session_expired_http("authentication session is no longer current", disposition)
        }
        ResolvedAppAuthority::ServicePrincipal { .. } => {
            let disposition =
                match authority.service_terminal_disposition(epoch_now_ms, Instant::now()) {
                    Some(ServiceAuthorityDisposition::DurableDelete) => {
                        HttpAuthorityDisposition::DurableDelete
                    }
                    Some(ServiceAuthorityDisposition::Carrier) | None => {
                        HttpAuthorityDisposition::Carrier
                    }
                };
            scoped_token_invalid_http(
                "scoped agent token authority is no longer current",
                disposition,
            )
        }
        _ => {
            // Anonymous-class authority is re-established by a fresh
            // handshake, so clients racing the boot-provision reset window
            // may retry this refusal (issues/20260807-auth-stream-reset-boot-flake.md).
            // @ref LLP 0059#reset-restore-and-stream-publication — refusal stands; the typed hint only marks anonymous re-establishment as safe.
            SnapbackError::error(
                "SNAPBACK_AUTH_STREAM_RESET",
                "auth",
                "the authorization stream is no longer current",
            )
            .with_details(json!({
                "authorityDisposition": "carrier",
                "retryable": true,
                "cause": "stream_replaced"
            }))
        }
    }
}

#[cfg(test)]
const TEST_FINITE_AUTHORITY_PAUSE_HEADER: &str = "x-snapback-test-finite-authority-pause";

#[cfg(test)]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum TestFiniteAuthorityPausePoint {
    BeforeHandler,
    BeforeResponsePublication,
    AfterScopedTokenStreamCapture,
    AfterScopedTokenDurableResolve,
    AfterSessionTerminalOwnedSpawn,
    AfterServiceTerminalOwnedSpawn,
}

#[cfg(test)]
#[derive(Clone)]
struct TestFiniteAuthorityPauseEntry {
    point: TestFiniteAuthorityPausePoint,
    reached: Arc<tokio::sync::Barrier>,
    release: Arc<tokio::sync::Barrier>,
    response_status: Arc<StdMutex<Option<StatusCode>>>,
}

#[cfg(test)]
struct TestFiniteAuthorityPause {
    id: String,
    reached: Arc<tokio::sync::Barrier>,
    release: Arc<tokio::sync::Barrier>,
    response_status: Arc<StdMutex<Option<StatusCode>>>,
}

#[cfg(test)]
static TEST_FINITE_AUTHORITY_PAUSES: OnceLock<
    StdMutex<std::collections::HashMap<String, TestFiniteAuthorityPauseEntry>>,
> = OnceLock::new();

#[cfg(test)]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum TestLiveServiceTerminalFailure {
    Planning,
    Gate,
    Transaction,
    OwnedTaskPanic,
}

#[cfg(test)]
static TEST_LIVE_SERVICE_TERMINAL_FAILURES: OnceLock<
    StdMutex<
        std::collections::HashMap<
            String,
            std::collections::VecDeque<TestLiveServiceTerminalFailure>,
        >,
    >,
> = OnceLock::new();

#[cfg(test)]
fn test_live_service_terminal_failures() -> &'static StdMutex<
    std::collections::HashMap<String, std::collections::VecDeque<TestLiveServiceTerminalFailure>>,
> {
    TEST_LIVE_SERVICE_TERMINAL_FAILURES
        .get_or_init(|| StdMutex::new(std::collections::HashMap::new()))
}

#[cfg(test)]
fn inject_test_live_service_terminal_failure(
    token_id: &str,
    failure: TestLiveServiceTerminalFailure,
) {
    test_live_service_terminal_failures()
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .entry(token_id.to_owned())
        .or_default()
        .push_back(failure);
}

#[cfg(test)]
fn take_test_live_service_terminal_failure(
    token_id: &str,
    expected: TestLiveServiceTerminalFailure,
) -> bool {
    let mut failures = test_live_service_terminal_failures()
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner);
    if failures.get(token_id).and_then(|queued| queued.front()) != Some(&expected) {
        return false;
    }
    let queued = failures
        .get_mut(token_id)
        .expect("the checked live-service failure queue exists");
    assert_eq!(queued.pop_front(), Some(expected));
    if queued.is_empty() {
        failures.remove(token_id);
    }
    true
}

#[cfg(test)]
fn test_live_service_terminal_failures_drained(token_id: &str) -> bool {
    !test_live_service_terminal_failures()
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .contains_key(token_id)
}

#[cfg(test)]
fn injected_live_service_terminal_failure(stage: &str) -> SnapbackError {
    SnapbackError::error(
        "SNAPBACK_TEST_LIVE_SERVICE_TERMINAL_FAILURE",
        "auth",
        format!("injected live service terminal {stage} failure"),
    )
}

#[cfg(test)]
fn test_finite_authority_pauses()
-> &'static StdMutex<std::collections::HashMap<String, TestFiniteAuthorityPauseEntry>> {
    TEST_FINITE_AUTHORITY_PAUSES.get_or_init(|| StdMutex::new(std::collections::HashMap::new()))
}

#[cfg(test)]
fn install_test_finite_authority_pause(
    point: TestFiniteAuthorityPausePoint,
) -> TestFiniteAuthorityPause {
    let id = format!("finite-authority-{}", Uuid::now_v7().simple());
    let reached = Arc::new(tokio::sync::Barrier::new(2));
    let release = Arc::new(tokio::sync::Barrier::new(2));
    let response_status = Arc::new(StdMutex::new(None));
    let entry = TestFiniteAuthorityPauseEntry {
        point,
        reached: reached.clone(),
        release: release.clone(),
        response_status: response_status.clone(),
    };
    let replaced = test_finite_authority_pauses()
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .insert(id.clone(), entry);
    assert!(replaced.is_none(), "finite-authority pause id was reused");
    TestFiniteAuthorityPause {
        id,
        reached,
        release,
        response_status,
    }
}

#[cfg(test)]
impl TestFiniteAuthorityPause {
    fn id(&self) -> &str {
        &self.id
    }

    async fn wait_until_reached(&self) {
        self.reached.wait().await;
    }

    async fn release(&self) {
        self.release.wait().await;
    }

    fn response_status(&self) -> Option<StatusCode> {
        *self
            .response_status
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
    }
}

#[cfg(test)]
impl Drop for TestFiniteAuthorityPause {
    fn drop(&mut self) {
        test_finite_authority_pauses()
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .remove(&self.id);
    }
}

#[cfg(test)]
async fn pause_test_finite_authority_request(
    pause_id: Option<&str>,
    point: TestFiniteAuthorityPausePoint,
    response_status: Option<StatusCode>,
) {
    let Some(pause_id) = pause_id else {
        return;
    };
    let entry = {
        let mut pauses = test_finite_authority_pauses()
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        if pauses
            .get(pause_id)
            .is_some_and(|entry| entry.point == point)
        {
            pauses.remove(pause_id)
        } else {
            None
        }
    };
    if let Some(entry) = entry {
        *entry
            .response_status
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = response_status;
        entry.reached.wait().await;
        entry.release.wait().await;
    }
}

const SENDER_PROOF_HEADER: &str = "dpop";
const SENDER_NONCE_HEADER: &str = "dpop-nonce";
const SENDER_NONCE_TTL_SECONDS: u64 = 120;

#[derive(Clone, Default)]
struct SenderNonceResponse(Arc<OnceLock<HeaderValue>>);

impl SenderNonceResponse {
    fn install(&self, nonce: &str) -> Result<(), SnapbackError> {
        let value = HeaderValue::from_str(nonce).map_err(|_| {
            SnapbackError::error(
                "SNAPBACK_AUTH_SENDER_PROOF_INVALID",
                "auth",
                "sender proof nonce is invalid",
            )
        })?;
        self.0.set(value).map_err(|_| {
            SnapbackError::error(
                "SNAPBACK_AUTH_SENDER_PROOF_INVALID",
                "auth",
                "sender proof nonce was published more than once",
            )
        })
    }

    fn value(&self) -> Option<&HeaderValue> {
        self.0.get()
    }
}

fn sender_proof_header(headers: &HeaderMap) -> Result<Option<&str>, SnapbackError> {
    let mut values = headers.get_all(SENDER_PROOF_HEADER).iter();
    let Some(value) = values.next() else {
        return Ok(None);
    };
    if values.next().is_some() || value.as_bytes().len() > 8 * 1024 {
        return Err(SnapbackError::error(
            "SNAPBACK_AUTH_SENDER_PROOF_INVALID",
            "auth",
            "sender proof is invalid",
        ));
    }
    value.to_str().map(Some).map_err(|_| {
        SnapbackError::error(
            "SNAPBACK_AUTH_SENDER_PROOF_INVALID",
            "auth",
            "sender proof is invalid",
        )
    })
}

fn sender_proof_subprotocol(headers: &HeaderMap) -> Result<Option<String>, SnapbackError> {
    let mut proof = None;
    for value in headers.get_all(header::SEC_WEBSOCKET_PROTOCOL) {
        let value = value.to_str().map_err(|_| {
            SnapbackError::error(
                "SNAPBACK_AUTH_SENDER_PROOF_INVALID",
                "auth",
                "sender proof is invalid",
            )
        })?;
        for protocol in value.split(',').map(str::trim) {
            let Some(candidate) = protocol.strip_prefix(SENDER_PROOF_SUBPROTOCOL_PREFIX) else {
                continue;
            };
            if candidate.is_empty() || candidate.len() > 8 * 1024 || proof.is_some() {
                return Err(SnapbackError::error(
                    "SNAPBACK_AUTH_SENDER_PROOF_INVALID",
                    "auth",
                    "sender proof is invalid",
                ));
            }
            proof = Some(candidate.to_owned());
        }
    }
    Ok(proof)
}

/// The `{name}` segment of a generated function-invocation route, extracted
/// from the raw request path. Hosted admission consults this only after
/// `canonical_external_uri` has rejected `%`-encoding, backslashes, doubled
/// slashes, and dot segments, so the raw segment cannot spell one function
/// name for the middleware and a different one for the handler's decoded
/// `Path` extractor.
fn function_invocation_route_name(spec: RouteSpec, path: &str) -> Option<&str> {
    let name = match spec.path {
        "/query/{name}" => path.strip_prefix("/query/")?,
        "/api/v1/query/{name}" => path.strip_prefix("/api/v1/query/")?,
        "/query/{name}/authorized-lease" => path
            .strip_prefix("/query/")?
            .strip_suffix("/authorized-lease")?,
        "/mutation/{name}" => path.strip_prefix("/mutation/")?,
        "/api/v1/mutation/{name}" => path.strip_prefix("/api/v1/mutation/")?,
        "/action/{name}" => path.strip_prefix("/action/")?,
        "/api/v1/action/{name}" => path.strip_prefix("/api/v1/action/")?,
        _ => return None,
    };
    (!name.is_empty() && !name.contains('/')).then_some(name)
}

/// Whether the published function manifest proves this function-invocation
/// request can never legitimately serve a caller with no session carrier at
/// all, hoisting the function-level `authRequirement` into route policy for
/// the hosted absent-carrier decision (LLP 0077 D-1).
///
/// Fails closed on ambiguity: only a name the published manifest statically
/// declares `public` or `optional-user` may admit an absent carrier. An
/// unknown name — which no caller, anonymous or authenticated, can ever
/// invoke successfully — refuses identically to an `authenticated` one, so
/// the pre-body refusal is not a function-existence oracle.
///
/// @ref LLP 0077#http-binding — an unproven sender must never cause body
/// ingestion; the route-level policy alone cannot see function requirements.
fn hosted_function_route_requires_session_carrier(
    spec: RouteSpec,
    path: &str,
    runtime: &AppState,
) -> bool {
    let Some(name) = function_invocation_route_name(spec, path) else {
        return false;
    };
    !matches!(
        runtime.read.published_function_auth_requirement(name),
        Some(AuthRequirement::Public | AuthRequirement::OptionalUser)
    )
}

fn hosted_route_may_present_session(spec: RouteSpec, effective: EffectiveRoutePolicy) -> bool {
    spec.path != "/auth/family-alarm"
        && (matches!(
            effective.credential_resolution,
            CredentialResolution::OptionalSessionBearer
                | CredentialResolution::OptionalSessionOrScopedToken
                | CredentialResolution::RequiredSessionBearer
                | CredentialResolution::RequiredSessionOrScopedToken
        ) || spec.path == "/connection/open")
}

fn sender_admission_response(
    rejection: crate::auth::sender_proof::SenderAdmissionRejection,
    nonce_response: &SenderNonceResponse,
) -> Response {
    use crate::auth::sender_proof::SenderAdmissionRejectionKind;
    if let Some(challenge) = rejection.challenge()
        && let Err(error) = nonce_response.install(challenge.expose_for_transport())
    {
        return ApiError::from(error).into_response();
    }
    // @ref LLP 0077#issuance-refresh-and-recovery — a committed logout whose
    // response was lost: the tombstone-resolved signed request receives the
    // terminal durableDelete outcome (LLP 0057's SESSION_EXPIRED shape) so
    // the stranded client can safely delete custody; no nonce accompanies it.
    if rejection.kind == SenderAdmissionRejectionKind::TerminalDurableDelete {
        let mut response = ApiError::from(
            SnapbackError::error(
                "SNAPBACK_AUTH_SESSION_EXPIRED",
                "auth",
                "authentication session is expired",
            )
            .with_details(json!({ "authorityDisposition": "durableDelete" })),
        )
        .into_response();
        *response.status_mut() = StatusCode::UNAUTHORIZED;
        return response;
    }
    let (code, status) = match rejection.kind {
        SenderAdmissionRejectionKind::Required => (
            "SNAPBACK_AUTH_SENDER_PROOF_REQUIRED",
            StatusCode::UNAUTHORIZED,
        ),
        SenderAdmissionRejectionKind::Invalid => (
            "SNAPBACK_AUTH_SENDER_PROOF_INVALID",
            StatusCode::UNAUTHORIZED,
        ),
        SenderAdmissionRejectionKind::Replayed => (
            "SNAPBACK_AUTH_SENDER_PROOF_REPLAYED",
            StatusCode::UNAUTHORIZED,
        ),
        SenderAdmissionRejectionKind::Unavailable => (
            "SNAPBACK_AUTH_SENDER_PROOF_AUTHORITY_UNAVAILABLE",
            StatusCode::SERVICE_UNAVAILABLE,
        ),
        SenderAdmissionRejectionKind::TerminalDurableDelete => {
            unreachable!("the terminal durable-delete outcome returns above")
        }
    };
    let mut response = ApiError::from(SnapbackError::error(
        code,
        "auth",
        "sender-constrained request admission failed",
    ))
    .into_response();
    *response.status_mut() = status;
    response
}

#[allow(clippy::too_many_arguments)] // Keep every throttle dimension explicit at the fail-closed charge boundary.
async fn charge_hosted_sender_attempt(
    runtime: &AppState,
    throttle: crate::auth::deployment::HostedAuthenticationThrottle,
    source: std::net::IpAddr,
    subject: Option<String>,
    access_token: Option<String>,
    bound_family: Option<String>,
    allow_superseded_grace: bool,
    now_ms: u64,
) -> Result<(), Response> {
    let result = with_snapback(&runtime.snapback, move |snapback| {
        snapback
            .auth_database_mut()
            .charge_sender_authentication_attempt(
                &throttle,
                source,
                subject,
                access_token.as_deref(),
                bound_family.as_deref(),
                allow_superseded_grace,
                now_ms,
            )
    })
    .await;
    match result {
        Ok(decision) if decision.admitted => Ok(()),
        Ok(decision) => Err(ApiError::auth_budget_throttled(decision).into_response()),
        Err(_) => {
            let mut response = ApiError::from(SnapbackError::error(
                "SNAPBACK_AUTH_THROTTLE_UNAVAILABLE",
                "auth",
                "shared authentication throttle is unavailable",
            ))
            .into_response();
            *response.status_mut() = StatusCode::SERVICE_UNAVAILABLE;
            Err(response)
        }
    }
}

fn require_hosted_effective_source(
    effective_source: Option<std::net::IpAddr>,
) -> Result<std::net::IpAddr, Response> {
    match effective_source {
        Some(source) => Ok(source),
        #[cfg(test)]
        None => Ok("127.0.0.1"
            .parse()
            .expect("test-only hosted effective source is canonical")),
        #[cfg(not(test))]
        None => {
            let mut response = ApiError::from(SnapbackError::error(
                "SNAPBACK_AUTH_EFFECTIVE_SOURCE_UNAVAILABLE",
                "auth",
                "hosted effective source authority is unavailable",
            ))
            .into_response();
            *response.status_mut() = StatusCode::SERVICE_UNAVAILABLE;
            Err(response)
        }
    }
}

fn hosted_body_auth_throttle_subject(path: &str, body: Option<&Value>) -> Option<String> {
    let field = match path {
        "/auth/request-code" => "email",
        "/auth/exchange" => "challengeId",
        _ => return None,
    };
    let value = body?.get(field)?.as_str()?.trim();
    if value.is_empty() || value.len() > 512 {
        None
    } else if path == "/auth/request-code" {
        Some(value.to_lowercase())
    } else {
        Some(value.to_owned())
    }
}

async fn charge_hosted_body_auth_attempt(
    spec: RouteSpec,
    runtime: &AppState,
    effective_source: Option<std::net::IpAddr>,
    subject: Option<String>,
) -> Result<(), Response> {
    if !matches!(spec.path, "/auth/request-code" | "/auth/exchange") {
        return Ok(());
    }
    let Some(hosted) = runtime
        .hosted_serving
        .as_ref()
        .and_then(|handle| handle.current())
    else {
        return Ok(());
    };
    let now_ms = installed_auth_provider(runtime)
        .map(|provider| provider.now_ms())
        .unwrap_or_else(|_| now_millis());
    let throttle = hosted
        .authentication_throttle_at(now_ms)
        .map_err(|error| ApiError::from(error).into_response())?;
    let source = require_hosted_effective_source(effective_source)?;
    charge_hosted_sender_attempt(
        runtime, throttle, source, subject, None, None, false, now_ms,
    )
    .await
}

/// Verify a hosted browser session proof before body ingestion or ordinary
/// session projection resolution. Known non-browser credential classes retain
/// their independent authentication path.
///
/// @ref LLP 0077#http-binding — canonical target authority comes only from
/// the provider-authenticated hosted target, and the SQLite replay/nonce cut
/// completes before any body poll.
#[allow(clippy::too_many_arguments)] // Admission inputs stay explicit until verification has produced a binding.
async fn admit_hosted_sender_request(
    spec: RouteSpec,
    effective: EffectiveRoutePolicy,
    runtime: &AppState,
    method: Method,
    request_uri: axum::http::Uri,
    headers: HeaderMap,
    nonce_response: SenderNonceResponse,
    effective_source: Option<std::net::IpAddr>,
) -> Result<Option<HostedSenderGrantBinding>, Response> {
    let Some(hosted) = runtime
        .hosted_serving
        .as_ref()
        .and_then(|handle| handle.current())
    else {
        return Ok(None);
    };
    let now_ms = installed_auth_provider(runtime)
        .map(|provider| provider.now_ms())
        .unwrap_or_else(|_| now_millis());
    // Serving-admission validity still gates every hosted request; the
    // short-lived serving epoch itself is deliberately NOT recorded anywhere
    // in sender state (the durable `sender_replay_epoch` is the namespace).
    if let Err(error) = hosted.admission_epoch_at(now_ms) {
        return Err(ApiError::from(error).into_response());
    }
    let authentication_throttle = match hosted.authentication_throttle_at(now_ms) {
        Ok(throttle) => throttle,
        Err(error) => return Err(ApiError::from(error).into_response()),
    };
    let effective_source = require_hosted_effective_source(effective_source)?;
    // The capability URL has no hosted sender-proof carrier. Return before
    // constructing a canonical external URI so the raw request-secret path
    // cannot enter sender-proof diagnostics or receipts.
    if effective.credential_resolution == CredentialResolution::CapabilityLinkBearer {
        return Ok(None);
    }
    let canonical_external_uri = match hosted.canonical_external_uri(&request_uri, now_ms) {
        Ok(uri) => uri,
        Err(error) => return Err(ApiError::from(error).into_response()),
    };
    let method = method.as_str().to_owned();

    // @ref LLP 0077#websocket-and-connection-binding — every use of a
    // sender-bound connection grant is proof-gated over the grant token,
    // independent of whether HTTP or WebSocket subprotocol carries it.
    if effective.path_policy == RoutePolicy::ConnectionAuth
        && let Some(presented) = connection_grant_carrier(effective, &headers, &request_uri)
    {
        let connection_token = presented.token;
        let Some(binding) = runtime
            .connections
            .hosted_sender_for_presented_grant(Some(&connection_token))
        else {
            return Ok(None);
        };
        // @ref LLP 0077#author-decisions--2026-07-23 — decision 4: the sender grant
        // lane requires the versioned `sct2_` spelling. Exact-token equality
        // already implies it for grants this process minted; the structural
        // check is the verifier half of the downgrade defense and holds even
        // if a future adapter restores grant state minted elsewhere.
        if classify_credential(&connection_token) != Some(CredentialClass::SenderConnectionToken) {
            return Err(ApiError::from(SnapbackError::error(
                "SNAPBACK_CONNECTION_TOKEN_INVALID",
                "realtime",
                "sender-bound connection grants require the v2 token spelling",
            ))
            .into_response());
        }
        let thumbprint = binding.jwk_thumbprint.clone();
        charge_hosted_sender_attempt(
            runtime,
            authentication_throttle,
            effective_source,
            None,
            None,
            Some(thumbprint.clone()),
            false,
            now_ms,
        )
        .await?;
        // The issuance-epoch invalidation is checked inside the storage
        // admit against the durable namespace (decision 6: exact-tuple
        // equality; the grant closes when `sender_replay_epoch` advances
        // past its issuance value).
        let issuance_sender_replay_epoch = binding.sender_replay_epoch_at_issuance;
        let proof = match presented.kind {
            ConnectionGrantCarrierKind::HttpHeader => {
                sender_proof_header(&headers).map(|proof| proof.map(str::to_owned))
            }
            ConnectionGrantCarrierKind::WebSocketSubprotocol => sender_proof_subprotocol(&headers),
            ConnectionGrantCarrierKind::DevQuery => Ok(None),
        };
        let proof = match proof {
            Ok(proof) => proof,
            Err(error) => return Err(ApiError::from(error).into_response()),
        };
        let result = with_snapback(&runtime.snapback, move |snapback| {
            let mut authority = snapback.auth_database_mut().sender_proof_authority();
            let sender_replay_epoch = authority
                .sender_replay_epoch()
                .map_err(|_| sender_authority_unavailable_rejection())?;
            admit_sender_constrained_bound_request(
                &mut authority,
                sender_replay_epoch,
                &method,
                &canonical_external_uri,
                &connection_token,
                proof.as_deref(),
                &thumbprint,
                now_ms / 1_000,
                SENDER_NONCE_TTL_SECONDS,
                None,
                None,
                Some(issuance_sender_replay_epoch),
            )
        })
        .await;
        return match result {
            Ok(admission) => nonce_response
                .install(admission.next_nonce_for_transport())
                .map(|()| Some(binding))
                .map_err(|error| ApiError::from(error).into_response()),
            Err(rejection) => Err(sender_admission_response(rejection, &nonce_response)),
        };
    }

    if !hosted_route_may_present_session(spec, effective) {
        return Ok(None);
    }
    let presented = presented_session_bearer(&headers);
    // @ref LLP 0077#http-binding — D-1: the function-level closed
    // `authRequirement` is hoisted into the route-policy decision here, so an
    // absent carrier on a route that can never legitimately serve an
    // anonymous caller refuses before any body poll instead of deferring to
    // the post-parse function-authority gate.
    let requires_session_carrier =
        matches!(
            effective.credential_resolution,
            CredentialResolution::RequiredSessionBearer
                | CredentialResolution::RequiredSessionOrScopedToken
        ) || hosted_function_route_requires_session_carrier(spec, request_uri.path(), runtime);
    let bearer = match presented {
        PresentedSessionBearer::Absent if !requires_session_carrier => {
            if spec.path == "/connection/open" {
                charge_hosted_sender_attempt(
                    runtime,
                    authentication_throttle,
                    effective_source,
                    None,
                    None,
                    None,
                    false,
                    now_ms,
                )
                .await?;
            }
            return Ok(None);
        }
        PresentedSessionBearer::Candidate(candidate)
            // @ref LLP 0077#author-decisions--2026-07-23 — decision 4: both session
            // spellings enter sender admission (`sbs2_` is the sender-bound
            // class the hosted exchange mints; the legacy `sbs_` spelling is
            // refused inside the admit when its family is sender-bound).
            // Every other credential class stays on its own lane.
            if classify_credential(candidate).is_some_and(|class| {
                !matches!(
                    class,
                    CredentialClass::Session | CredentialClass::SenderSession
                )
            }) =>
        {
            if spec.path == "/connection/open" {
                charge_hosted_sender_attempt(
                    runtime,
                    authentication_throttle,
                    effective_source,
                    None,
                    None,
                    None,
                    false,
                    now_ms,
                )
                .await?;
            }
            return Ok(None);
        }
        PresentedSessionBearer::Candidate(candidate) => candidate.to_owned(),
        PresentedSessionBearer::Absent => {
            charge_hosted_sender_attempt(
                runtime,
                authentication_throttle,
                effective_source,
                None,
                None,
                None,
                spec.path != "/connection/open",
                now_ms,
            )
            .await?;
            let mut response = ApiError::from(SnapbackError::error(
                "SNAPBACK_AUTH_REQUIRED",
                "auth",
                "authentication is required",
            ))
            .into_response();
            *response.status_mut() = StatusCode::UNAUTHORIZED;
            return Err(response);
        }
        PresentedSessionBearer::Malformed => String::new(),
    };
    charge_hosted_sender_attempt(
        runtime,
        authentication_throttle,
        effective_source,
        None,
        Some(bearer.clone()),
        None,
        spec.path != "/connection/open",
        now_ms,
    )
    .await?;
    let proof = match sender_proof_header(&headers) {
        Ok(proof) => proof.map(str::to_owned),
        Err(error) => return Err(ApiError::from(error).into_response()),
    };
    // @ref LLP 0077#author-decisions--2026-07-23 — decision 3: carriers that
    // resolve to no live bound family receive a deterministic keyed cover
    // nonce, so challenge issuance cannot become a family-existence oracle.
    let cover_key = match hosted.sender_cover_key_at(now_ms) {
        Ok(key) => key,
        Err(error) => return Err(ApiError::from(error).into_response()),
    };
    let result = with_snapback(&runtime.snapback, move |snapback| {
        let mut authority = snapback.auth_database_mut().sender_proof_authority();
        let sender_replay_epoch = authority
            .sender_replay_epoch()
            .map_err(|_| sender_authority_unavailable_rejection())?;
        admit_sender_constrained_request(
            &mut authority,
            sender_replay_epoch,
            &method,
            &canonical_external_uri,
            &bearer,
            proof.as_deref(),
            now_ms / 1_000,
            SENDER_NONCE_TTL_SECONDS,
            spec.path != "/connection/open",
            None,
            None,
            Some(&cover_key),
        )
    })
    .await;
    match result {
        Ok(admission) => {
            let binding = HostedSenderGrantBinding {
                jwk_thumbprint: admission.verified.jwk_thumbprint.clone(),
                sender_replay_epoch_at_issuance: admission.sender_replay_epoch,
            };
            nonce_response
                .install(admission.next_nonce_for_transport())
                .map(|()| Some(binding))
                .map_err(|error| ApiError::from(error).into_response())
        }
        Err(rejection) => Err(sender_admission_response(rejection, &nonce_response)),
    }
}

async fn enforce_registered_route_policy(
    spec: RouteSpec,
    runtime: AppState,
    request: Request<Body>,
    next: Next,
) -> Response {
    let client_id_context = declared_client_id_context(spec, request.headers());
    let mut response = enforce_registered_route_policy_inner(
        spec,
        runtime,
        request,
        next,
        client_id_context.clone(),
    )
    .await;
    if let Some(status) = client_id_context.and_then(|context| context.status()) {
        response.headers_mut().insert(
            HeaderName::from_static(SNAPBACK_CLIENT_ID_STATUS_HEADER),
            HeaderValue::from_static(status),
        );
    }
    response
}

async fn enforce_registered_route_policy_inner(
    spec: RouteSpec,
    runtime: AppState,
    mut request: Request<Body>,
    next: Next,
    client_id_context: Option<ExternalClientIdContext>,
) -> Response {
    #[cfg(test)]
    let test_finite_authority_pause_id = request
        .headers()
        .get(TEST_FINITE_AUTHORITY_PAUSE_HEADER)
        .and_then(|value| value.to_str().ok())
        .map(str::to_owned);
    let policy_mode = runtime.active_policy_auth_mode();
    let effective = spec.effective_for(policy_mode);
    if request.method() == Method::OPTIONS {
        request.extensions_mut().insert(spec);
        request.extensions_mut().insert(effective);
        return apply_registered_response_controls(effective, next.run(request).await);
    }
    // @ref LLP 0098#81-first-served-origin-run--2026-07-25 — enforce the
    // operator-surface disablement the admission *attests*. Verifying that a
    // snapshot says `operatorSurface: disabled` while the routes stay reachable
    // is an attested fact with no enforcing code behind it, which is worse than
    // an unverifiable assertion because it looks verified. LLP 0060 C2 defines
    // the disabled surface as a fixed 404 on the public application origin, so
    // that is what a hosted deployment serves — before any handler, and
    // identically for pages and API routes so the response cannot distinguish
    // a present route from an absent one.
    if runtime.hosted_serving.is_some()
        && matches!(spec.class, RouteClass::SystemStatic | RouteClass::SystemApi)
    {
        return apply_registered_response_controls(
            effective,
            hosted_operator_surface_disabled_response(),
        );
    }
    // @ref LLP 0204#d8--authority-acquisition-the-ceremony-and-the-facade — the first OAuth facade is local-only and hosted serving refuses the whole family without enumeration.
    if (runtime.hosted_serving.is_some()
        || runtime.server.auth_deployment == crate::auth::deployment::AuthDeploymentTarget::Hosted)
        && matches!(
            spec.path,
            "/.well-known/oauth-authorization-server"
                | "/.well-known/oauth-protected-resource"
                | "/auth/oauth/register"
                | "/auth/oauth/authorize"
                | "/auth/oauth/token"
                | "/auth/oauth/revoke"
        )
    {
        return apply_registered_response_controls(
            effective,
            hosted_operator_surface_disabled_response(),
        );
    }
    // Streamable HTTP MCP requires Origin validation before credentials,
    // admission, or request-body processing so a DNS-rebinding attempt cannot
    // use any of those layers as an oracle.
    // @ref LLP 0204#d3--surface-2-the-mcp-server — `/mcp` is stateless but
    // remains bound to the declared external API origin set.
    if spec.path == "/mcp"
        && let Err(error) = remote_mcp::require_mcp_origin(&runtime, request.headers()).await
    {
        return apply_registered_response_controls(effective, error.into_response());
    }
    if let Some(error) = auth_app_data_refusal(spec, &runtime) {
        return apply_registered_response_controls(
            effective,
            ApiError::from(error).into_response(),
        );
    }
    if spec.path != "/connection/open"
        && let Some(error) = session_online_protocol_refusal(spec, &runtime, request.headers())
    {
        return apply_registered_response_controls(
            effective,
            ApiError::from(error).into_response(),
        );
    }
    // Count initial master exchanges before the ordinary AdminWrite gate so
    // wrong and missing master values cannot turn this endpoint into an
    // unbounded token oracle. Derived-credential renewals have their own
    // credential registry bounds and do not consume this lane.
    let master_exchange_attempt = spec.path == "/_snapback/api/console/credential"
        && (!request
            .headers()
            .contains_key("x-snapback-console-credential")
            || request.headers().contains_key("x-snapback-admin-token")
            || request.headers().contains_key(header::AUTHORIZATION));
    if master_exchange_attempt
        && let Err(error) = runtime.server.console_credentials.admit_master_exchange()
    {
        return apply_registered_response_controls(
            effective,
            ApiError::from(error).into_response(),
        );
    }
    // Provider paths are intentionally absent in active dev mode. Perform
    // this refusal before credential or body handling so a disabled provider
    // cannot become an oracle for bearer/body shape. `/auth/session`, added by
    // item 4, is the sole bootstrap-handshake exception.
    if policy_mode == PolicyAuthMode::Dev
        && spec.path.starts_with("/auth/")
        && spec.path != "/auth/session"
    {
        // @ref LLP 0055#registration — the sessions-only registration surface
        // has one stable policy-unavailable refusal when the app is in dev;
        // it must not be confused with a malformed or disabled agents policy.
        let (code, message) = if spec.path == "/auth/agents/register" {
            (
                "SNAPBACK_AUTH_POLICY_UNAVAILABLE",
                "agent credential routes require active sessions mode",
            )
        } else {
            (
                "SNAPBACK_AUTH_MODE_DEV",
                "the session provider is unavailable while auth mode is dev",
            )
        };
        return apply_registered_response_controls(
            effective,
            ApiError::from(SnapbackError::error(code, "auth", message)).into_response(),
        );
    }
    // Capability-link tokens are the complete credential on their two closed
    // paths. Reject an Authorization credential before secret lookup so a
    // session/service bearer can never be reinterpreted as link authority.
    // The refusal intentionally matches every unavailable link outcome.
    if effective.credential_resolution == CredentialResolution::CapabilityLinkBearer
        && request.headers().contains_key(header::AUTHORIZATION)
    {
        return apply_registered_response_controls(
            effective,
            capability_link_unavailable_error().into_response(),
        );
    }
    let sender_nonce_response = request
        .extensions()
        .get::<SenderNonceResponse>()
        .cloned()
        .unwrap_or_default();
    // @ref LLP 0098#6-effective-source-under-this-topology — on a hosted
    // deployment the immediate peer is ALWAYS the in-namespace terminator, so
    // using it as the effective source would collapse LLP 0060 D3's five-bucket
    // set onto one bucket and make per-source throttling a fiction. The
    // derivation is the enforcing code behind the attested
    // `effectiveSource: trusted`; a local target keeps the raw peer.
    let peer_ip = request
        .extensions()
        .get::<ConnectInfo<std::net::SocketAddr>>()
        .map(|ConnectInfo(address)| address.ip());
    let hosted_effective_source = if runtime.hosted_serving.is_some() {
        let forwarded = {
            let values = request
                .headers()
                .get_all(crate::auth::effective_source::FORWARDED_HEADER)
                .iter()
                .collect::<Vec<_>>();
            // Two headers are a conflict, and a conflict fails closed rather
            // than letting a caller pick which one the origin believes.
            match values.as_slice() {
                [single] => single.to_str().ok().map(str::to_owned),
                _ => None,
            }
        };
        match crate::auth::effective_source::derive_effective_source(peer_ip, forwarded.as_deref())
        {
            Ok(source) => Some(source),
            Err(error) => {
                return apply_registered_response_controls(
                    effective,
                    ApiError::from(error).into_response(),
                );
            }
        }
    } else {
        peer_ip
    };
    let external_network_evidence = external_api_route(spec).then(|| {
        let now_ms = now_millis();
        let (digest, generation) = external_api_network_evidence(hosted_effective_source, now_ms);
        (digest, generation, now_ms)
    });
    if let Some((network_digest, _, _)) = external_network_evidence
        && let Err(retry_after) = runtime.connections.consume_external_api(
            ExternalApiThrottleSource::NetworkFloor(network_digest),
            EXTERNAL_API_ANONYMOUS_FLOOR_LIMIT,
            Instant::now(),
        )
    {
        return finish_registered_response(
            effective,
            external_api_throttle_error(
                "SNAPBACK_API_NETWORK_FLOOR_EXCEEDED",
                "network-floor",
                "the external anonymous network floor is exhausted",
                retry_after,
            )
            .into_response(),
            None,
            None,
        );
    }
    let mut route_admission = match acquire_registered_route_admission(spec, &runtime) {
        Ok(admission) => admission,
        Err(error) => {
            return apply_registered_response_controls(effective, error.into_response());
        }
    };
    let resolved_capability_link =
        if effective.credential_resolution == CredentialResolution::CapabilityLinkBearer {
            let Some(token) = capability_link_token_from_path(spec, request.uri().path()) else {
                return finish_registered_response(
                    effective,
                    capability_link_unavailable_error().into_response(),
                    route_admission.as_ref(),
                    None,
                );
            };
            if !crate::storage::capability_links::token_has_closed_shape(token) {
                return finish_registered_response(
                    effective,
                    capability_link_unavailable_error().into_response(),
                    route_admission.as_ref(),
                    None,
                );
            }
            let token = token.to_owned();
            let resolved = with_snapback(&runtime.snapback, move |snapback| {
                snapback
                    .auth_database_mut()
                    .resolve_capability_link(&token, now_millis())
            })
            .await;
            match resolved {
                Ok(record) => Some(ResolvedCapabilityLink(record)),
                Err(error) => {
                    return finish_registered_response(
                        effective,
                        ApiError::from(error).into_response(),
                        route_admission.as_ref(),
                        None,
                    );
                }
            }
        } else {
            None
        };
    let hosted_sender_admission = match admit_hosted_sender_request(
        spec,
        effective,
        &runtime,
        request.method().clone(),
        request.uri().clone(),
        request.headers().clone(),
        sender_nonce_response,
        hosted_effective_source,
    )
    .await
    {
        Ok(binding) => binding,
        Err(response) => {
            return finish_registered_response(effective, response, route_admission.as_ref(), None);
        }
    };
    if let Some(binding) = hosted_sender_admission {
        request.extensions_mut().insert(binding);
    }
    // @ref LLP 0058#admitted-body-ingestion — the moment a request owns a
    // managed admission root, its remaining body ingestion must be finite and
    // epoch-close aware. Wrapping here covers both the policy-gate peek below
    // and handler-side extraction on routes whose body is not inspected.
    let mut admitted_body_trip = None;
    if let Some(admission) = route_admission.as_ref() {
        let (guarded, trip) =
            AdmittedBodyGuard::wrap(request, admission, runtime.auth_admission_controller());
        request = guarded;
        admitted_body_trip = Some(trip);
    }
    let registered_source = registered_invocation_source(spec);
    // SessionAuth resolution is deliberately deferred until after the
    // admitted-body legacy-authority check below. On a hosted sender route the
    // proof cut has already completed, but LLP 0058's forbidden-field
    // precedence still wins within post-admission processing.
    let mut early_prepared_authority = None;
    // @ref LLP 0031#enforcement — authenticate every connection carrier
    // before bounded JSON inspection. Body-carried connection ids get a
    // second exact id↔bearer check after decoding; an attacker-controlled
    // body never gets parsed merely to discover which bearer it claims.
    let mut presented_connection_token = None;
    let mut prepared_connection_act = None;
    let presented_ephemeral_authority_instance =
        presented_ephemeral_authority_instance(request.headers());
    if effective.path_policy == RoutePolicy::ConnectionAuth {
        let presented = connection_token_for_request(effective, &request);
        let (epoch_now_ms, monotonic_now) = auth_runtime_now(&runtime);
        let verified: Result<Option<PreparedConnectionAct>, ApiError> =
            match connection_id_from_request_path(request.uri().path()) {
                Some(connection_id) => runtime
                    .connections
                    .prepare_act(
                        connection_id,
                        presented.as_deref(),
                        runtime.auth_coordinator.as_deref(),
                        runtime.auth_mode_state().active == AuthMode::Dev,
                        epoch_now_ms,
                        monotonic_now,
                    )
                    .map(Some),
                None => runtime
                    .connections
                    .authenticate_presented_bearer(presented.as_deref())
                    .map(|()| None),
            };
        let verified = verified.and_then(|prepared| {
            if let Some(prepared) = prepared.as_ref() {
                prepared
                    .verify_ephemeral_authority_instance(
                        presented_ephemeral_authority_instance.as_deref(),
                    )
                    .map_err(|error| {
                        error.with_ephemeral_authority_instance(
                            prepared.ephemeral_authority_instance(),
                        )
                    })?;
            }
            Ok(prepared)
        });
        match verified {
            Ok(prepared) => prepared_connection_act = prepared,
            Err(error) => {
                return finish_registered_response(
                    effective,
                    error.into_response(),
                    route_admission.as_ref(),
                    None,
                );
            }
        }
        presented_connection_token = presented;
    }

    let operation_deferred = matches!(
        effective.effect_policy,
        EffectPolicy::FunctionKind | EffectPolicy::OperationSpecific
    );
    let connection_id_in_body = effective.path_policy == RoutePolicy::ConnectionAuth
        && connection_id_from_request_path(request.uri().path()).is_none();
    // The TUS PATCH body is an opaque `application/offset+octet-stream`
    // chunk: never policy-inspectable JSON and never a transport-auth
    // carrier — authority resolves from headers and session lineage, and the
    // peek's JSON parse of chunk bytes always yielded `None`. Inspecting it
    // had exactly one effect: the peek bound capped real chunks at 2 MiB and
    // made the declared `ASSET_MAX_CHUNK_BYTES` capability fact unreachable
    // (found by the LLP 0139 bakeoff's first real 120 MB upload). The
    // exemption is method-and-path exact — the JSON-shaped AssetTransfer
    // siblings (attempt inspect/cancel, TUS HEAD/DELETE) keep body
    // inspection — and ingest stays bounded in the handler by the chunk
    // fact, refused as the classified media-bounds 413.
    let opaque_transfer_body = spec.path == "/assets/tus/{id}" && spec.method == "PATCH";
    let inspect_body = !opaque_transfer_body
        && (effective.legacy_body_policy == LegacyBodyPolicy::Rejected
            || connection_id_in_body
            || operation_deferred
            || matches!(spec.path, "/auth/request-code" | "/auth/exchange")
            || agent_route_throttle_limit(spec.path).is_some()
            || registered_source.is_some_and(|source| {
                !matches!(
                    source,
                    InvocationSource::AuthRefresh | InvocationSource::AuthLogout
                )
            })
            || effective.effect_policy == EffectPolicy::SecretReadMintProof);
    let connection_open_bearer = (spec.path == "/connection/open")
        .then(|| OwnedPresentedSessionBearer::from_headers(request.headers()));
    let mut policy_body = None;
    if inspect_body {
        let policy_peek_limit = if spec.path == "/_snapback/api/host-ops" {
            POLICY_BODY_PEEK_LIMIT_HOST_OPS
        } else {
            POLICY_BODY_PEEK_LIMIT
        };
        let malformed_deferred_preflight = (operation_deferred
            && matches!(
                spec.path,
                "/_snapback/api/functions/{name}/run" | "/_snapback/api/host-ops"
            ))
        .then(|| authorize_deferred_operation_preflight(&runtime, request.headers(), false));
        match peek_policy_json_body(request, policy_peek_limit).await {
            Ok((rebuilt, body)) => {
                request = rebuilt;
                policy_body = body;
            }
            Err(error) => {
                if let Some(Err(preflight)) = malformed_deferred_preflight {
                    return finish_registered_response(
                        effective,
                        preflight.into_response(),
                        route_admission.as_ref(),
                        None,
                    );
                }
                // A guarded ingest refusal outranks the peek's size-bound
                // shape error: the buffering was cut by the ingest deadline or
                // an epoch close, not by the request exceeding the limit. The
                // size-bound diagnostic is untouched when the guard did not
                // trip (LLP 0058#admitted-body-ingestion).
                let error = match admitted_body_trip.as_ref().and_then(|trip| trip.reason()) {
                    Some(reason) => ApiError::from(admitted_body_trip_error(reason)),
                    None => error,
                };
                if let Err(response) =
                    charge_hosted_body_auth_attempt(spec, &runtime, hosted_effective_source, None)
                        .await
                {
                    return finish_registered_response(
                        effective,
                        response,
                        route_admission.as_ref(),
                        None,
                    );
                }
                // Request-shape parsing is ordered before credential
                // classification, but rejected attempts still consume their
                // exact closed source bucket. Only a throttle replaces the
                // already-selected shape error; every other credential result
                // stays private on this rejected request.
                if let Some(presented) = connection_open_bearer.as_ref() {
                    let (_, monotonic_now) = auth_runtime_now(&runtime);
                    if let Err(accounting_error) = account_connection_open_attempt(
                        &runtime,
                        presented.as_presented(),
                        monotonic_now,
                    ) && accounting_error.0.diagnostic.code == "SNAPBACK_AUTH_THROTTLED"
                    {
                        return finish_registered_response(
                            effective,
                            accounting_error.into_response(),
                            route_admission.as_ref(),
                            None,
                        );
                    }
                }
                if agent_route_throttle_limit(spec.path).is_some()
                    && early_prepared_authority.is_none()
                    && let Err(accounting_error) = runtime.connections.consume_agent_route(
                        spec.path,
                        AgentRouteThrottleSource::Malformed,
                        Instant::now(),
                    )
                    && accounting_error.0.diagnostic.code == "SNAPBACK_AUTH_THROTTLED"
                {
                    return finish_registered_response(
                        effective,
                        accounting_error.into_response(),
                        route_admission.as_ref(),
                        None,
                    );
                }
                return finish_registered_response(
                    effective,
                    error.into_response(),
                    route_admission.as_ref(),
                    None,
                );
            }
        }
    }
    // @ref LLP 0031#enforcement — direct-runner and host-op branches retain
    // their coarse authority floor before function-kind lookup. The one exact
    // public exception is the declared `auth.rehearsal.exercise` operation:
    // its bounded operation selector may pass without inspecting any carrier,
    // then the selected handler resolves all rehearsal authority. This keeps
    // absent, malformed, expired, and unknown carriers non-enumerating.
    // @ref LLP 0213#prefix-class-refusal
    if operation_deferred
        && matches!(
            spec.path,
            "/_snapback/api/functions/{name}/run" | "/_snapback/api/host-ops"
        )
    {
        let selected_name = policy_body
            .as_ref()
            .and_then(Value::as_object)
            .and_then(|fields| fields.get("operation"))
            .and_then(Value::as_str);
        let public_rehearsal_class = spec.path == "/_snapback/api/host-ops"
            && selected_name.is_some_and(|operation| {
                operation == "auth.rehearsal.exercise"
                    || (runtime.server.profile == crate::contract_types::ServerProfile::Prod
                        && operation.starts_with("auth.rehearsal."))
            });
        if let Err(error) = authorize_deferred_operation_preflight(
            &runtime,
            request.headers(),
            public_rehearsal_class,
        ) {
            return finish_registered_response(
                effective,
                error.into_response(),
                route_admission.as_ref(),
                None,
            );
        }
    }
    if let Err(response) = charge_hosted_body_auth_attempt(
        spec,
        &runtime,
        hosted_effective_source,
        hosted_body_auth_throttle_subject(spec.path, policy_body.as_ref()),
    )
    .await
    {
        return finish_registered_response(effective, response, route_admission.as_ref(), None);
    }
    if effective.legacy_body_policy == LegacyBodyPolicy::Rejected
        && let Some(field) = policy_body.as_ref().and_then(legacy_body_auth_field)
    {
        // A forbidden-field refusal precedes ordinary credential resolution
        // (LLP 0077's route-scoped LLP 0058 reorder), but a rejected
        // connection-open attempt still consumes its exact closed source
        // bucket; only a throttle replaces the already-selected shape error,
        // and every other credential result stays private on this rejected
        // request (LLP 0058's accounting invariant is preserved across the
        // reorder).
        if spec.path == "/connection/open"
            && let Some(presented) = connection_open_bearer.as_ref()
        {
            let (_, monotonic_now) = auth_runtime_now(&runtime);
            if let Err(accounting_error) =
                account_connection_open_attempt(&runtime, presented.as_presented(), monotonic_now)
                && accounting_error.0.diagnostic.code == "SNAPBACK_AUTH_THROTTLED"
            {
                return finish_registered_response(
                    effective,
                    accounting_error.into_response(),
                    route_admission.as_ref(),
                    None,
                );
            }
        }
        return finish_registered_response(
            effective,
            body_auth_unsupported(field).into_response(),
            route_admission.as_ref(),
            None,
        );
    }
    // The external surface enablement check precedes the handler's closed
    // run-request decode. LLP 0058's forbidden body-authority check above is
    // transport security, not run-request shape, and keeps its global
    // precedence over every sessions-mode application refusal.
    if matches!(spec.path, "/api/v1/run" | "/api/v1/ask") {
        let api_enabled = with_snapback(&runtime.snapback, |snapback| {
            snapback.external_api_enabled()
        })
        .await;
        if !api_enabled {
            if let Some(context) = client_id_context.as_ref()
                && context.declared.is_some()
            {
                context.set_status("ignored-api-disabled");
            }
            return finish_registered_response(
                effective,
                ApiError::from(SnapbackError::error(
                    "SNAPBACK_API_NOT_ENABLED",
                    "api",
                    "the application has not enabled its external API surface",
                ))
                .into_response(),
                route_admission.as_ref(),
                None,
            );
        }
    }
    // @ref LLP 0077#http-binding — sender admission gates body access first;
    // then forbidden wire authority wins before ordinary SessionAuth
    // projection. Retain that exact projection through final publication.
    if effective.path_policy == RoutePolicy::SessionAuth {
        let Some(source) = registered_source else {
            return finish_registered_response(
                effective,
                ApiError::from(SnapbackError::error(
                    "SNAPBACK_AUTH_POLICY_UNAVAILABLE",
                    "auth",
                    "a SessionAuth route has no registered invocation source",
                ))
                .into_response(),
                route_admission.as_ref(),
                None,
            );
        };
        early_prepared_authority = match prepare_registered_route_authority(
            Some(source),
            effective,
            &runtime,
            route_admission.as_ref(),
            request.headers(),
            policy_body.as_ref(),
            None,
        )
        .await
        {
            Ok(Some(authority)) => Some(authority),
            Ok(None) => {
                return finish_registered_response(
                    effective,
                    ApiError::from(SnapbackError::error(
                        "SNAPBACK_AUTH_POLICY_UNAVAILABLE",
                        "auth",
                        "a SessionAuth route did not produce prepared authority",
                    ))
                    .into_response(),
                    route_admission.as_ref(),
                    None,
                );
            }
            Err(error) => {
                return finish_registered_response(
                    effective,
                    error.into_response(),
                    route_admission.as_ref(),
                    None,
                );
            }
        };
    }
    // Session-owned management routes account against the resolved effective
    // user after forbidden-field inspection but before handler evaluation.
    if let Some(authority) = early_prepared_authority.as_ref()
        && agent_route_throttle_limit(spec.path).is_some()
    {
        let ResolvedAppAuthority::Session { user_id, .. } = authority.resolved() else {
            unreachable!("session-owned agent route resolved non-session authority")
        };
        if let Err(error) = runtime.connections.consume_agent_route(
            spec.path,
            AgentRouteThrottleSource::Session(user_id.clone()),
            Instant::now(),
        ) {
            return finish_registered_response(
                effective,
                error.into_response(),
                route_admission.as_ref(),
                None,
            );
        }
    }
    // Body-credential routes key valid attempts by the one-way bearer hash.
    // Invalid shapes and the bounded overflow of distinct presented hashes
    // share a coarse malformed bucket, preventing an attacker from growing
    // the process-local key set without limit.
    if agent_route_throttle_limit(spec.path).is_some() && early_prepared_authority.is_none() {
        let source = agent_body_throttle_source(policy_body.as_ref());
        if let Err(error) =
            runtime
                .connections
                .consume_agent_route(spec.path, source, Instant::now())
        {
            return finish_registered_response(
                effective,
                error.into_response(),
                route_admission.as_ref(),
                None,
            );
        }
    }
    let connection_open_protocol_error = connection_open_bearer
        .as_ref()
        .and_then(|_| session_online_protocol_refusal(spec, &runtime, request.headers()));
    let prepared_connection_open = if let Some(presented) = connection_open_bearer.as_ref() {
        if connection_open_protocol_error.is_some() {
            let (_, monotonic_now) = auth_runtime_now(&runtime);
            if let Err(accounting_error) =
                account_connection_open_attempt(&runtime, presented.as_presented(), monotonic_now)
                && accounting_error.0.diagnostic.code == "SNAPBACK_AUTH_THROTTLED"
            {
                return finish_registered_response(
                    effective,
                    accounting_error.into_response(),
                    route_admission.as_ref(),
                    None,
                );
            }
            None
        } else {
            let (epoch_now_ms, monotonic_now) = auth_runtime_now(&runtime);
            #[cfg(test)]
            let scoped_token_pause_id = test_finite_authority_pause_id.as_deref();
            #[cfg(not(test))]
            let scoped_token_pause_id = None;
            match prepare_connection_open_authority_with_scoped_token(
                &runtime,
                presented.as_presented(),
                epoch_now_ms,
                monotonic_now,
                scoped_token_pause_id,
            )
            .await
            {
                Ok(mut prepared) => {
                    prepared.hosted_sender = request
                        .extensions()
                        .get::<HostedSenderGrantBinding>()
                        .cloned();
                    Some(prepared)
                }
                Err(error) => {
                    return finish_registered_response(
                        effective,
                        error.into_response(),
                        route_admission.as_ref(),
                        None,
                    );
                }
            }
        }
    } else {
        None
    };
    if let Some(protocol_error) = connection_open_protocol_error {
        return finish_registered_response(
            effective,
            ApiError::from(protocol_error).into_response(),
            route_admission.as_ref(),
            None,
        );
    }
    if let Some(error) = session_live_protocol_refusal(
        spec,
        &runtime,
        request.headers(),
        request.uri().path(),
        policy_body.as_ref(),
    )
    .await
    {
        return finish_registered_response(
            effective,
            ApiError::from(error).into_response(),
            route_admission.as_ref(),
            None,
        );
    }
    // A lease-only caller must prove the statically named function scope
    // before kind lookup. This makes an existing and an unknown function
    // indistinguishable to an under-scoped lease while preserving the normal
    // AdminWrite path for mutation/action callers.
    if operation_deferred
        && policy_mode == PolicyAuthMode::Sessions
        && crate::admin::authorize_for_mode(&runtime.server, request.headers(), true, policy_mode)
            .is_err()
        && let Some(scope) =
            deferred_secret_read_scope(spec, request.uri().path(), policy_body.as_ref())
        && let Err(error) = crate::admin::preflight_secret_read(
            &runtime.secret_reads,
            request.headers(),
            std::collections::BTreeSet::from([scope]),
        )
    {
        return finish_registered_response(
            effective,
            error.into_response(),
            route_admission.as_ref(),
            None,
        );
    }

    let mut selected_operation = None;
    let operation_authorization = if operation_deferred {
        match select_http_operation(spec, &runtime, request.uri().path(), policy_body.as_ref())
            .await
        {
            HttpOperationSelection::Selected(operation) => {
                let operation_policy = operation.effective_for(policy_mode);
                selected_operation = Some((operation, operation_policy));
                if runtime.server.profile == crate::contract_types::ServerProfile::Prod
                    && operation.operation.starts_with("host_ops.auth.rehearsal.")
                {
                    // The typed handler emits the one profile refusal. This
                    // deliberate authorization bypass exists only in prod,
                    // where the rehearsal operation class is itself
                    // forbidden before every credential or body-detail check.
                    // @ref LLP 0213#prefix-class-refusal
                    Ok(())
                } else if operation_policy.legacy_body_policy == LegacyBodyPolicy::Rejected
                    && let Some(field) = policy_body.as_ref().and_then(legacy_body_auth_field)
                {
                    Err(body_auth_unsupported(field))
                } else if operation.transport == OperationTransport::EnsureApp {
                    authorize_ensure_posture(
                        operation,
                        policy_body.as_ref(),
                        runtime.policy_auth_posture(),
                    )
                    .and_then(|()| {
                        authorize_operation_spec(
                            &runtime.server,
                            request.headers(),
                            operation,
                            policy_mode,
                        )
                    })
                } else {
                    authorize_operation_path_spec_with_secret_reads(
                        &runtime.server,
                        request.headers(),
                        operation,
                        policy_mode,
                        &runtime.secret_reads,
                    )
                }
            }
            HttpOperationSelection::UnknownHost => {
                match crate::admin::authorize_for_mode(
                    &runtime.server,
                    request.headers(),
                    true,
                    policy_mode,
                ) {
                    Ok(()) => Err(SnapbackError::new(crate::host_ops::host_op_diagnostic(
                        "SNAPBACK_HOST_OP_UNKNOWN",
                        policy_body
                            .as_ref()
                            .and_then(|body| body.get("operation"))
                            .and_then(Value::as_str)
                            .unwrap_or_default(),
                        "unknown or unregistered host operation",
                    ))
                    .into()),
                    Err(error) => Err(error),
                }
            }
            // A malformed/partial operation body is still authenticated at
            // the strongest possible branch before the typed extractor emits
            // its shape diagnostic.
            HttpOperationSelection::Indeterminate => crate::admin::authorize_for_mode(
                &runtime.server,
                request.headers(),
                true,
                policy_mode,
            ),
        }
    } else {
        Ok(())
    };
    let selected_policy = selected_operation
        .map(|(_, operation_policy)| operation_policy)
        .unwrap_or(effective);
    let production_rehearsal_operation = runtime.server.profile
        == crate::contract_types::ServerProfile::Prod
        && selected_operation.is_some_and(|(operation, _)| {
            operation.operation.starts_with("host_ops.auth.rehearsal.")
        });
    let response_policy = if selected_operation.is_some()
        && !matches!(
            effective.response_sensitivity,
            ResponseSensitivity::StaticPublic | ResponseSensitivity::PublicProjection
        ) {
        EffectiveRoutePolicy {
            response_sensitivity: effective.response_sensitivity,
            ..selected_policy
        }
    } else {
        selected_policy
    };
    let authorization = if selected_policy.effect_policy == EffectPolicy::Unavailable {
        let error = if selected_operation
            .is_some_and(|(operation, _)| operation.operation == "host_ops.auth.mintSession")
        {
            auth_mint_session_mode_unavailable(&runtime)
        } else {
            SnapbackError::error(
                "SNAPBACK_AUTH_POLICY_UNAVAILABLE",
                "auth",
                "this operation is unavailable under the active auth policy",
            )
        };
        Err(error.into())
    } else if operation_deferred {
        operation_authorization
    } else {
        match effective.path_policy {
            RoutePolicy::AdminRead => crate::admin::authorize_for_mode(
                &runtime.server,
                request.headers(),
                false,
                policy_mode,
            ),
            RoutePolicy::AdminWrite => crate::admin::authorize_for_mode(
                &runtime.server,
                request.headers(),
                true,
                policy_mode,
            ),
            RoutePolicy::AdminSecretRead => {
                authorize_secret_read(&runtime.secret_reads, request.headers())
            }
            // The projection-backed credential resolver below is the
            // SessionAuth enforcement point. No admin/public policy may
            // substitute for its required bearer.
            RoutePolicy::SessionAuth => Ok(()),
            RoutePolicy::Public | RoutePolicy::AppAuth | RoutePolicy::ConnectionAuth => Ok(()),
        }
    };
    if let Err(error) = authorization {
        return finish_registered_response(
            response_policy,
            error.into_response(),
            route_admission.as_ref(),
            None,
        );
    }
    let owns_auth_transition = policy_mode == PolicyAuthMode::Sessions
        && (spec.path == "/_snapback/api/functions/load"
            || selected_operation
                .is_some_and(|(operation, _)| operation.operation == "host_ops.functions.load"));
    if owns_auth_transition {
        // Both legacy function-load ingresses are transition owners, like
        // `/app/ensure`. Authentication (and host-operation selection, when
        // applicable) has completed; release the middleware root before
        // entering the handler so the transition never waits on its own
        // response lease.
        // @ref LLP 0058#complete-candidate-pair-preflight — sessions-mode
        // legacy load carriers are one-half provisioning, never raw swaps.
        route_admission.take();
    }
    if selected_policy.effect_policy == EffectPolicy::ImpersonationCapability
        && !production_rehearsal_operation
    {
        if !runtime.server.profile.allows_provisioning() {
            let diagnostic = crate::admin::operation_profile_diagnostic(
                runtime.server.profile,
                "auth impersonation",
                crate::admin::OperationProfileRequirement::NonProd,
            )
            .expect("prod is the only profile that forbids impersonation");
            return finish_registered_response(
                response_policy,
                ApiError::from(SnapbackError::new(diagnostic)).into_response(),
                route_admission.as_ref(),
                None,
            );
        }
        let verified = runtime
            .impersonation_capabilities
            .as_ref()
            .ok_or_else(crate::admin_impersonation::impersonation_required)
            .and_then(|registry| {
                let _effect = route_admission
                    .as_ref()
                    .expect("impersonation app routes are managed")
                    .effect_guard("impersonation capability claim")?;
                registry.authorize(single_header_value(
                    request.headers(),
                    crate::admin_impersonation::IMPERSONATION_CAPABILITY_HEADER,
                ))
            });
        match verified {
            Ok(verified) => {
                request.extensions_mut().insert(verified);
            }
            Err(error) => {
                return finish_registered_response(
                    response_policy,
                    ApiError::from(error).into_response(),
                    route_admission.as_ref(),
                    None,
                );
            }
        }
    }
    if selected_policy.effect_policy == EffectPolicy::AgentDestroyCapability
        && runtime.server.profile == crate::contract_types::ServerProfile::Prod
    {
        let verified = runtime
            .agent_destroy_capabilities
            .as_ref()
            .ok_or_else(crate::admin_agent_destroy::agent_destroy_capability_required)
            .and_then(|registry| {
                let _effect = route_admission
                    .as_ref()
                    .expect("agent-destroy routes are managed")
                    .effect_guard("agent destroy capability claim")?;
                registry.authorize(single_header_value(
                    request.headers(),
                    crate::admin_agent_destroy::AGENT_DESTROY_CAPABILITY_HEADER,
                ))
            });
        match verified {
            Ok(verified) => {
                request.extensions_mut().insert(verified);
            }
            Err(error) => {
                return finish_registered_response(
                    response_policy,
                    ApiError::from(error).into_response(),
                    route_admission.as_ref(),
                    None,
                );
            }
        }
    }
    if selected_policy.effect_policy == EffectPolicy::SecretReadMintProof {
        let Some(bridge) = runtime.secret_read_mint.as_ref() else {
            return finish_registered_response(
                response_policy,
                ApiError::from(crate::admin_secret_read::mint_proof_required()).into_response(),
                route_admission.as_ref(),
                None,
            );
        };
        let envelope = policy_body
            .as_ref()
            .cloned()
            .ok_or_else(crate::admin_secret_read::mint_proof_invalid)
            .and_then(|body| {
                serde_json::from_value::<SecretReadMintEnvelope>(body)
                    .map_err(|_| crate::admin_secret_read::mint_proof_invalid())
            });
        let verified = match envelope.and_then(|envelope| {
            let _effect = route_admission
                .as_ref()
                .expect("secret-read mint app routes are managed")
                .effect_guard("secret-read mint proof claim")?;
            bridge.verify_and_claim(&envelope)
        }) {
            Ok(verified) => verified,
            Err(error) => {
                return finish_registered_response(
                    response_policy,
                    ApiError::from(error).into_response(),
                    route_admission.as_ref(),
                    None,
                );
            }
        };
        request.extensions_mut().insert(verified);
    }
    if effective.path_policy == RoutePolicy::ConnectionAuth {
        let body_connection_id = policy_body
            .as_ref()
            .and_then(Value::as_object)
            .and_then(|body| {
                body.get("connection_id")
                    .or_else(|| body.get("connectionId"))
            })
            .and_then(Value::as_str);
        let (epoch_now_ms, monotonic_now) = auth_runtime_now(&runtime);
        let verified = match body_connection_id {
            Some(connection_id) if connection_id_in_body => runtime.connections.prepare_act(
                connection_id,
                presented_connection_token.as_deref(),
                runtime.auth_coordinator.as_deref(),
                runtime.auth_mode_state().active == AuthMode::Dev,
                epoch_now_ms,
                monotonic_now,
            ),
            _ if connection_id_in_body && policy_body.is_none() => Err(
                ApiError::request_json_invalid("connection request body was empty or malformed"),
            ),
            _ => prepared_connection_act.clone().ok_or_else(|| {
                connection_auth_error(
                    "SNAPBACK_CONNECTION_TOKEN_INVALID",
                    "connection request does not identify its authenticated grant",
                    "",
                )
            }),
        };
        let verified = verified.and_then(|prepared| {
            prepared
                .verify_ephemeral_authority_instance(
                    presented_ephemeral_authority_instance.as_deref(),
                )
                .map_err(|error| {
                    error.with_ephemeral_authority_instance(prepared.ephemeral_authority_instance())
                })?;
            Ok(prepared)
        });
        match verified {
            Ok(prepared) => prepared_connection_act = Some(prepared),
            Err(error) => {
                return finish_registered_response(
                    response_policy,
                    error.into_response(),
                    route_admission.as_ref(),
                    None,
                );
            }
        }
    }

    // Every successfully authenticated connection-scoped HTTP act is a
    // client-originated poll-lane signal. The WebSocket upgrade is excluded:
    // its exact generation is registered only after the upgrade succeeds, so
    // a known socket close cannot leave an upgrade-request witness behind.
    //
    // @ref LLP 0222#open-questions — the real headless client uses HTTP poll;
    // semanticsVersion 2 therefore widens the witness transport explicitly.
    if spec.path != "/live/{connection_id}/stream"
        && let Some(prepared) = prepared_connection_act.as_ref()
        && let Err(error) = record_authenticated_poll_witness(&runtime, prepared)
    {
        return finish_registered_response(
            response_policy,
            error.into_response(),
            route_admission.as_ref(),
            None,
        );
    }

    let invocation_source =
        selected_invocation_source(spec, selected_operation.map(|(operation, _)| operation));
    let resolved_connection_authority = if policy_mode == PolicyAuthMode::Sessions {
        prepared_connection_act
            .as_ref()
            .map(|prepared| &prepared.resolved)
            .or_else(|| {
                prepared_connection_open
                    .as_ref()
                    .map(|prepared| &prepared.resolved)
            })
    } else {
        None
    };
    let prepared_authority = if let Some(authority) = early_prepared_authority {
        Some(authority)
    } else {
        match prepare_registered_route_authority(
            invocation_source,
            selected_policy,
            &runtime,
            route_admission.as_ref(),
            request.headers(),
            policy_body.as_ref(),
            resolved_connection_authority,
        )
        .await
        {
            Ok(authority) => authority,
            Err(error) => {
                return finish_registered_response(
                    response_policy,
                    error.into_response(),
                    route_admission.as_ref(),
                    None,
                );
            }
        }
    };
    let mut prepared_authority = prepared_authority.map(|authority| {
        let bound = prepared_connection_act
            .as_ref()
            .map(|prepared| &prepared.bound)
            .or_else(|| {
                prepared_connection_open
                    .as_ref()
                    .map(|prepared| &prepared.bound)
            });
        let authority = match bound {
            Some(bound) => authority.with_fenced_publication(bound.publication().clone()),
            None => authority,
        };
        match bound.and_then(BoundGrantAuthority::service_publication) {
            Some(publication) => authority.with_service_publication(publication.clone()),
            None => authority,
        }
    });
    if let (Some(authority), Some((network_digest, network_generation, now_ms))) =
        (prepared_authority.as_ref(), external_network_evidence)
    {
        let attribution = match admit_external_api_lane(
            &runtime,
            client_id_context.as_ref(),
            authority,
            resolved_capability_link.as_ref(),
            network_digest,
            network_generation,
            now_ms,
        )
        .await
        {
            Ok(attribution) => attribution,
            Err(error) => {
                let response = error.into_response();
                let response = if spec.path == "/mcp" {
                    remote_mcp::pre_dispatch_tool_refusal(policy_body.as_ref(), response).await
                } else {
                    response
                };
                return finish_registered_response(
                    response_policy,
                    response,
                    route_admission.as_ref(),
                    Some(authority),
                );
            }
        };
        prepared_authority =
            prepared_authority.map(|authority| authority.with_caller_attribution(attribution));
    } else if let Some(authority) = prepared_authority.as_ref() {
        let attribution =
            match telemetry_caller_attribution_for_authority(&runtime, authority).await {
                Ok(attribution) => attribution,
                Err(error) => {
                    return finish_registered_response(
                        response_policy,
                        error.into_response(),
                        route_admission.as_ref(),
                        Some(authority),
                    );
                }
            };
        prepared_authority =
            prepared_authority.map(|authority| authority.with_caller_attribution(attribution));
    }
    if let Some(authority) = prepared_authority.as_ref() {
        request.extensions_mut().insert(authority.clone());
    }
    if let Some(link) = resolved_capability_link {
        request.extensions_mut().insert(link);
    }
    if let Some(admission) = route_admission.as_ref() {
        request.extensions_mut().insert(admission.clone());
    }
    if let Some(prepared) = prepared_connection_act.as_ref() {
        request.extensions_mut().insert(prepared.clone());
    }
    if let Some(prepared) = prepared_connection_open.as_ref() {
        request.extensions_mut().insert(prepared.clone());
    }
    request.extensions_mut().insert(spec);
    if let Some((operation, operation_policy)) = selected_operation {
        request.extensions_mut().insert(operation);
        request.extensions_mut().insert(operation_policy);
    } else {
        request.extensions_mut().insert(effective);
    }
    #[cfg(test)]
    pause_test_finite_authority_request(
        test_finite_authority_pause_id.as_deref(),
        TestFiniteAuthorityPausePoint::BeforeHandler,
        None,
    )
    .await;
    let mut response = next.run(request).await;
    #[cfg(test)]
    pause_test_finite_authority_request(
        test_finite_authority_pause_id.as_deref(),
        TestFiniteAuthorityPausePoint::BeforeResponsePublication,
        Some(response.status()),
    )
    .await;
    // Routes whose body is consumed by the handler (not the policy peek) see
    // the guard's refusal as an extractor error of arbitrary shape. Publish
    // the canonical ingest diagnostic instead; a tripped guard proves the
    // handler could not have observed a complete request body.
    if let Some(reason) = admitted_body_trip.as_ref().and_then(|trip| trip.reason()) {
        response = ApiError::from(admitted_body_trip_error(reason)).into_response();
    }
    if response.status().is_success()
        && matches!(
            invocation_source,
            Some(
                InvocationSource::HttpQuery
                    | InvocationSource::HttpMutation
                    | InvocationSource::HttpAction
                    | InvocationSource::HttpRun
                    | InvocationSource::HttpAsk
                    | InvocationSource::HttpMcp
            )
        )
        && let Some(authority) = prepared_authority.as_ref()
        && let Err(error) = record_successful_finite_session_use(&runtime, authority).await
    {
        response = error.into_response();
    }
    if let Some(authority) = prepared_authority.as_ref()
        && matches!(
            authority.resolved(),
            ResolvedAppAuthority::ServicePrincipal { .. }
        )
        && let Err(error) =
            persist_expired_service_authority_owned(&runtime, authority.clone()).await
    {
        response = ApiError::from(error).into_response();
    }
    let mut response = finish_registered_response(
        response_policy,
        response,
        route_admission.as_ref(),
        prepared_authority.as_ref(),
    );
    if network_profile_refusal_lane(spec).is_some()
        && !runtime.network_profiles.is_normal()
        && response
            .extensions()
            .get::<NetworkProfileObservation>()
            .is_none()
        && (!matches!(spec.path, "/action/{name}" | "/api/v1/action/{name}")
            || response.status().is_success())
    {
        response
            .extensions_mut()
            .insert(NetworkProfileHandlerResponse);
    }
    response
}

const AUTH_REQUEST_BODY_LIMIT: usize = 4 * 1024;
const AUTH_EXCHANGE_BODY_LIMIT: usize = 16 * 1024;

fn auth_request_invalid() -> ApiError {
    SnapbackError::error(
        "SNAPBACK_AUTH_REQUEST_INVALID",
        "auth",
        "authentication request is invalid",
    )
    .into()
}

fn sender_issuance_invalid() -> ApiError {
    SnapbackError::error(
        "SNAPBACK_AUTH_SENDER_PROOF_INVALID",
        "auth",
        "sender-constrained issuance proof is invalid",
    )
    .into()
}

fn prepare_sender_issuance(
    runtime: &AppState,
    request: &ExchangeRequest,
    request_uri: &axum::http::Uri,
    now_ms: u64,
) -> Result<Option<SenderIssuanceCommitment>, ApiError> {
    let Some(hosted) = runtime
        .hosted_serving
        .as_ref()
        .and_then(|handle| handle.current())
    else {
        if request.sender_constraint.is_some() {
            return Err(sender_issuance_invalid());
        }
        return Ok(None);
    };
    let constraint = request
        .sender_constraint
        .as_ref()
        .ok_or_else(sender_issuance_invalid)?;
    if constraint.protocol != SENDER_ISSUANCE_PROTOCOL {
        return Err(sender_issuance_invalid());
    }
    hosted.admission_epoch_at(now_ms).map_err(ApiError::from)?;
    let canonical_exchange_uri = hosted
        .canonical_external_uri(request_uri, now_ms)
        .map_err(ApiError::from)?;
    let verified = verify_sender_issuance_proof(
        constraint.proof.as_str(),
        &SenderIssuanceExpectation {
            challenge_id: &request.challenge_id,
            canonical_exchange_uri: &canonical_exchange_uri,
            public_jwk: &constraint.public_jwk,
            server_unix_seconds: now_ms / 1_000,
        },
    )
    .map_err(|_| sender_issuance_invalid())?;
    SenderIssuanceCommitment::new(verified, now_ms / 1_000, SENDER_NONCE_TTL_SECONDS)
        .map(Some)
        .map_err(|_| sender_issuance_invalid())
}

fn auth_provider_unavailable() -> ApiError {
    auth_provider_unavailable_error().into()
}

fn auth_provider_unavailable_error() -> SnapbackError {
    SnapbackError::error(
        "SNAPBACK_AUTH_PROVIDER_UNAVAILABLE",
        "auth",
        "authentication provider is unavailable",
    )
}

fn map_provider_error(error: ProviderError) -> ApiError {
    error.into_snapback_error().into()
}

fn installed_auth_provider(runtime: &AppState) -> Result<Arc<AuthProvider>, ApiError> {
    runtime
        .auth_provider
        .clone()
        .ok_or_else(auth_provider_unavailable)
}

