fn parse_agent_credential(input: &SecretInput) -> Result<AgentCredential, ApiError> {
    dispatch_credential_class(input.as_str(), CredentialClass::AgentCredential)
        .map_err(|error| ApiError::from(error.into_snapback_error()))?;
    AgentCredential::parse(input.as_str()).map_err(|_| {
        ApiError::from(SnapbackError::error(
            "SNAPBACK_AUTH_AGENT_CREDENTIAL_INVALID",
            "auth",
            "agent credential is invalid",
        ))
    })
}

fn parse_creation_invitation(input: &SecretInput) -> Result<CreationInvitation, ApiError> {
    dispatch_credential_class(input.as_str(), CredentialClass::CreationInvitation)
        .map_err(|error| ApiError::from(error.into_snapback_error()))?;
    CreationInvitation::parse(input.as_str()).map_err(|_| {
        ApiError::from(SnapbackError::error(
            "SNAPBACK_AUTH_AGENT_INVITATION_INVALID",
            "auth",
            "agent creation invitation is invalid",
        ))
    })
}

fn parse_pairing_code(input: &SecretInput) -> Result<PairingCode, ApiError> {
    dispatch_credential_class(input.as_str(), CredentialClass::PairingCode)
        .map_err(|error| ApiError::from(error.into_snapback_error()))?;
    PairingCode::parse(input.as_str()).map_err(|_| {
        ApiError::from(SnapbackError::error(
            "SNAPBACK_AUTH_GRANT_INVALID",
            "auth",
            "agent grant is invalid",
        ))
    })
}

fn reject_agent_route_authorization_header(headers: &HeaderMap) -> Result<(), ApiError> {
    if !headers.contains_key(header::AUTHORIZATION) {
        return Ok(());
    }
    Err(auth_request_invalid())
}

fn require_agent_routes_available(runtime: &AppState) -> Result<Arc<AuthProvider>, ApiError> {
    if runtime.auth_mode_state().active != AuthMode::Sessions {
        return Err(SnapbackError::error(
            "SNAPBACK_AUTH_POLICY_UNAVAILABLE",
            "auth",
            "agent credential routes require active sessions mode",
        )
        .into());
    }
    installed_auth_provider(runtime)
}

async fn require_agent_registration_mode(
    runtime: &AppState,
) -> Result<(Arc<AuthProvider>, AgentsManifest), ApiError> {
    let provider = require_agent_routes_available(runtime)?;
    let policy = with_snapback(&runtime.snapback, |snapback| {
        snapback
            .auth_database_mut()
            .schema()
            .effective_agents_manifest()
    })
    .await;
    Ok((provider, policy))
}

fn require_grant_session(authority: &PreparedAuthority) -> Result<(String, String), ApiError> {
    require_provider_session_authority(authority, InvocationSource::AgentGrantManagement)?;
    let ResolvedAppAuthority::Session {
        user_id,
        session_id,
        ..
    } = authority.resolved()
    else {
        unreachable!("grant-management source requires session authority");
    };
    Ok((user_id.clone(), session_id.clone()))
}

fn grant_step_up_binding(
    authority: &PreparedAuthority,
    request_id: String,
) -> Result<StepUpBinding, ApiError> {
    require_provider_session_authority(authority, InvocationSource::AgentGrantManagement)?;
    let ResolvedAppAuthority::Session {
        user_id,
        session_id,
        generation,
        authority_instance_id,
        ..
    } = authority.resolved()
    else {
        unreachable!("grant-management source requires session authority");
    };
    Ok(StepUpBinding::grant_approval(
        user_id.clone(),
        session_id.clone(),
        *generation,
        authority_instance_id.clone(),
        request_id,
    ))
}

fn agent_invitation_step_up_binding(
    authority: &PreparedAuthority,
) -> Result<StepUpBinding, ApiError> {
    require_provider_session_authority(authority, InvocationSource::AgentGrantManagement)?;
    let ResolvedAppAuthority::Session {
        user_id,
        session_id,
        generation,
        authority_instance_id,
        ..
    } = authority.resolved()
    else {
        unreachable!("grant-management source requires session authority");
    };
    Ok(StepUpBinding::agent_invitation(
        user_id.clone(),
        session_id.clone(),
        *generation,
        authority_instance_id.clone(),
    ))
}

fn effect_step_up_binding(
    authority: &PreparedAuthority,
    effect_id: String,
) -> Result<StepUpBinding, ApiError> {
    authority
        .validate_admission("effect approval step-up binding")
        .map_err(ApiError::from)?;
    if !matches!(
        authority.source(),
        InvocationSource::AgentGrantManagement | InvocationSource::EffectManagement
    ) || authority.active_mode() != AuthMode::Sessions
    {
        return Err(SnapbackError::error(
            "SNAPBACK_INVOCATION_SOURCE_INVALID",
            "auth",
            "effect step-up requires exact session authority",
        )
        .into());
    }
    let ResolvedAppAuthority::Session {
        user_id,
        session_id,
        generation,
        authority_instance_id,
        ..
    } = authority.resolved()
    else {
        return Err(SnapbackError::error(
            "SNAPBACK_INVOCATION_SOURCE_INVALID",
            "auth",
            "effect step-up requires a session principal",
        )
        .into());
    };
    Ok(StepUpBinding::effect_approval(
        user_id.clone(),
        session_id.clone(),
        *generation,
        authority_instance_id.clone(),
        effect_id,
    ))
}

fn password_set_step_up_binding(
    authority: &PreparedAuthority,
    identity_id: String,
    source: InvocationSource,
) -> Result<StepUpBinding, ApiError> {
    require_provider_session_authority(authority, source)?;
    let ResolvedAppAuthority::Session {
        user_id,
        session_id,
        generation,
        authority_instance_id,
        ..
    } = authority.resolved()
    else {
        unreachable!("password-set source requires session authority");
    };
    Ok(StepUpBinding::password_set(
        user_id.clone(),
        session_id.clone(),
        *generation,
        authority_instance_id.clone(),
        identity_id,
    ))
}

/// Fresh-authentication requests derive their human address from the exact
/// live session. The wire chooses only a closed operation and target; it can
/// neither redirect delivery nor mint an unbound proof.
///
/// @ref LLP 0055#re-credentialing-recovery-and-the-production-profile-invariant — step-up is operation/target bound,
/// five-minute, single-use, and capture-only outside production until LLP 0045.
async fn auth_step_up_request(
    State(runtime): State<AppState>,
    Extension(authority): Extension<PreparedAuthority>,
    headers: HeaderMap,
    body: Result<Bytes, BytesRejection>,
) -> Result<Json<RequestCodeResponse>, ApiError> {
    let provider = require_agent_routes_available(&runtime)?;
    let request: StepUpRequest = parse_auth_json(&headers, body)?;
    let binding = match request {
        StepUpRequest::GrantApproval { request_id } => {
            grant_step_up_binding(&authority, request_id)?
        }
        StepUpRequest::AgentInvitation {} => agent_invitation_step_up_binding(&authority)?,
        StepUpRequest::EffectApproval { effect_id } => {
            effect_step_up_binding(&authority, effect_id)?
        }
        StepUpRequest::PasswordSet { identity_id } => {
            password_set_step_up_binding(
                &authority,
                identity_id,
                InvocationSource::AgentGrantManagement,
            )?
        }
    };
    let admission = provider.admit().await;
    let now_ms = provider.now_ms();
    let lookup_binding = binding.clone();
    let (admission, address) = with_snapback(&runtime.snapback, move |snapback| {
        let address =
            admission.step_up_address(snapback.auth_database_mut(), &lookup_binding, now_ms);
        (admission, address)
    })
    .await;
    let address = address.map_err(map_provider_error)?;
    let admission = admission
        .for_address(address)
        .await
        .map_err(map_provider_error)?;
    let effect_authority = authority.clone();
    let response = with_snapback(&runtime.snapback, move |snapback| {
        let _effect = effect_authority
            .effect_guard("step-up challenge transaction")
            .map_err(ProviderError::from)?;
        admission.request_step_up(snapback.auth_database_mut(), &binding)
    })
    .await
    .map_err(map_provider_error)?;
    Ok(Json(response))
}

/// Mint a user-owned single-use creation invitation. Proof verification and
/// invitation insertion share the storage transaction; the bearer itself is
/// never sufficient.
///
/// @ref LLP 0055#registration — only `invitedBy: users` enables this route,
/// with ten live invitations per user.
async fn auth_agent_invitation(
    State(runtime): State<AppState>,
    Extension(authority): Extension<PreparedAuthority>,
    headers: HeaderMap,
    body: Result<Bytes, BytesRejection>,
) -> Result<Json<AgentInvitationSecretResponse>, ApiError> {
    let (user_id, _) = require_grant_session(&authority)?;
    let (provider, policy) = require_agent_registration_mode(&runtime).await?;
    if policy.mode != AgentsMode::Invited || policy.invited_by != crate::manifest::InvitedBy::Users
    {
        return Err(SnapbackError::error(
            "SNAPBACK_AUTH_AGENT_INVITATIONS_DISABLED",
            "auth",
            "user-minted agent invitations are not enabled by the active schema manifest",
        )
        .into());
    }
    let request: AgentInvitationRequest = parse_auth_json(&headers, body)?;
    let step_up = request
        .step_up
        .ok_or_else(|| ApiError::from(crate::auth::crypto::step_up_required_error()))?;
    let binding = agent_invitation_step_up_binding(&authority)?;
    let admission = provider.admit().await;
    let challenge_id = step_up.challenge_id.clone();
    let (admission, coordination) = with_snapback(&runtime.snapback, move |snapback| {
        let coordination =
            admission.step_up_coordination(snapback.auth_database_mut(), &challenge_id);
        (admission, coordination)
    })
    .await;
    let coordination = coordination.map_err(map_provider_error)?;
    let proof = admission
        .for_step_up(coordination, binding, step_up.code.as_str())
        .await
        .map_err(map_provider_error)?;
    let effect_authority = authority.clone();
    let effect_provider = provider.clone();
    let profile = runtime.server.profile;
    let invitation = with_snapback(&runtime.snapback, move |snapback| {
        let _effect = effect_authority.effect_guard("agent invitation mint transaction")?;
        snapback.auth_database_mut().mint_agent_invitation(
            &user_id,
            profile,
            proof.proof(),
            effect_provider.now_ms(),
            effect_provider.agent_random_source(),
        )
    })
    .await?;
    Ok(Json(AgentInvitationSecretResponse {
        invitation_id: invitation.invitation_id,
        expires_at_ms: invitation.expires_at_ms,
        invitation: invitation.secret,
    }))
}

