/// Deliberately explicit selector for destructive exactly-once-ledger
/// recovery. An empty object is rejected: an operator must name one resolved
/// auth context or affirm that every retained settlement should be removed.
#[derive(Debug, Default, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct ClientMutationPurgeBody {
    #[serde(default)]
    auth: Option<AuthInput>,
    #[serde(default)]
    all: bool,
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
struct ClientMutationPurgeResponse {
    purged: u64,
}

async fn purge_client_mutation_settlements(
    State(state): State<SharedSnapback>,
    State(ctx): State<Arc<ServerContext>>,
    headers: HeaderMap,
    input: Result<Json<ClientMutationPurgeBody>, JsonRejection>,
) -> Result<Json<ClientMutationPurgeResponse>, ApiError> {
    crate::admin::authorize(&ctx, &headers, true)?;
    let Json(body) = input.map_err(ApiError::from_json_rejection)?;
    let auth = match (body.auth, body.all) {
        (Some(auth), false) => Some(auth),
        (None, true) => None,
        _ => {
            return Err(SnapbackError::error(
                "SNAPBACK_CLIENT_MUTATION_PURGE_SELECTOR_INVALID",
                "sync",
                "choose exactly one purge selector: auth or all=true",
            )
            .into());
        }
    };
    let purged = with_snapback(&state, move |snapback| {
        snapback.purge_client_mutation_settlements(auth.as_ref())
    })
    .await?;
    Ok(Json(ClientMutationPurgeResponse { purged }))
}

fn parse_optional_json<T: serde::de::DeserializeOwned>(
    headers: &HeaderMap,
    body: Result<Bytes, BytesRejection>,
) -> Result<Option<T>, ApiError> {
    let body = body.map_err(|error| ApiError::request_json_invalid(error.to_string()))?;
    if body.is_empty() {
        return Ok(None);
    }
    let is_json = headers
        .get(header::CONTENT_TYPE)
        .and_then(|value| value.to_str().ok())
        .and_then(|value| value.split(';').next())
        .is_some_and(|value| value.trim().eq_ignore_ascii_case("application/json"));
    if !is_json {
        return Err(ApiError::request_json_invalid(
            "nonempty request body requires Content-Type: application/json",
        ));
    }
    let value: Value = serde_json::from_slice(&body)
        .map_err(|error| ApiError::request_json_invalid(error.to_string()))?;
    if !value.is_object() {
        return Err(ApiError::request_json_invalid(
            "request body must be a JSON object",
        ));
    }
    // Deserialize the original bytes so serde's typed visitor still observes
    // duplicate object keys. Converting the intermediate Value into T would
    // collapse duplicates first and silently let the last destructive/reset
    // or capability field win.
    serde_json::from_slice(&body)
        .map(Some)
        .map_err(|error| ApiError::request_json_invalid(error.to_string()))
}

/// Release one fully prepared HTTP response at its absolute deadline. The
/// caller has already dropped invocation/instance authorities; this function
/// owns only response bytes and the immutable profile snapshot.
///
/// HTTP profile deadlines are per request, not per TCP connection. Snapback's
/// supported HTTP/1.1 clients issue one in-flight request per connection; HTTP
/// pipelining is not a supported observation surface, so no cross-request
/// monotone clamp is applied here.
///
/// @ref LLP 0167#observation-semantics--what-a-delay-means — physical waiting
///   is an egress concern and never extends commit or invocation authority.
async fn release_network_profiled_response(
    mut response: Response,
    prepared: Option<crate::network_profile::PreparedNetworkEgress>,
) -> Response {
    let Some(prepared) = prepared else {
        return response;
    };
    let wait = prepared
        .release_at()
        .saturating_duration_since(Instant::now());
    if !wait.is_zero() {
        tokio::time::sleep(wait).await;
    }
    let marker = HeaderValue::from_str(&prepared.snapshot().profile.name)
        .expect("validated network profile names are response-header safe");
    response.headers_mut().insert(
        HeaderName::from_static(crate::network_profile::NETWORK_PROFILE_HEADER),
        marker,
    );
    response
        .extensions_mut()
        .insert(NetworkProfileObservation(prepared.snapshot().clone()));
    response
}

fn prepare_mutation_network_egress(
    profiles: &crate::network_profile::NetworkProfileState,
    basis: crate::network_profile::MutationEgressBasis,
    result_ready_at: Instant,
) -> Option<crate::network_profile::PreparedNetworkEgress> {
    match basis {
        crate::network_profile::MutationEgressBasis::ResultReady => profiles.admit_result(
            crate::network_profile::NetworkEgressLane::MutationAck,
            result_ready_at,
        ),
        crate::network_profile::MutationEgressBasis::NormalCommit => None,
        crate::network_profile::MutationEgressBasis::ProfiledCommit(group) => {
            Some(group.for_lane(crate::network_profile::NetworkEgressLane::MutationAck))
        }
    }
}

fn external_api_route(spec: RouteSpec) -> bool {
    matches!(
        spec.path,
        "/api/v1/query/{name}"
            | "/api/v1/mutation/{name}"
            | "/api/v1/action/{name}"
            | "/api/v1/run"
            | "/api/v1/ask"
            | "/mcp"
            | "/capability-links/{token}/invoke"
    )
}

const RUN_PROGRAM_MAX_BYTES: usize = 1024 * 1024;

#[derive(Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct ExternalRunRequest {
    program: String,
    envelope_digest: String,
    #[serde(default)]
    args: serde_json::Map<String, Value>,
}

async fn current_target_capability_manifest(
    runtime: &AppState,
) -> crate::manifest::CapabilityManifest {
    with_snapback(&runtime.snapback, |snapback| {
        snapback.current_capability_manifest()
    })
    .await
}

/// The single executor-promotion seam. A target that fails the evidence gate
/// returns that gate's typed refusal. Even a future target whose manifest
/// passes remains refused here until an author-gated landing replaces this
/// match arm with the complete checker/executor; there is no partial executor
/// behind today's unevidenced profiles.
fn run_code_capability_refusal(manifest: &crate::manifest::CapabilityManifest) -> SnapbackError {
    match crate::manifest::untrusted_code_profile_evidenced(manifest) {
        Err(error) => error,
        Ok(()) => SnapbackError::error(
            "SNAPBACK_API_RUN_UNTRUSTED_CODE_UNSUPPORTED",
            "api",
            "this target's untrusted-code executor has not been author-promoted",
        )
        .with_details(json!({
            "targetProfileId": manifest.target_profile_id,
            "capabilityGap": "hosted_untrusted_code",
            "gapDeclared": false,
            "unevidencedLimits": [],
            "executorPromoted": false,
        })),
    }
}

/// `POST /api/v1/run` validates the real wire contract, then stops at the
/// target evidence gate. The caller authority is intentionally extracted even
/// though no executor ships: the future injected client must remain bound to
/// this prepared grant and route every nested call through ordinary admission.
///
/// @ref LLP 0204#d6--code-mode-unified — submissions are bounded and digest
///   bound; programs have no ambient authority.
/// @ref LLP 0047#capability-manifest — execution is refused unless every
///   required target limit is evidenced as enforced.
async fn invoke_run(
    State(runtime): State<AppState>,
    Extension(_authority): Extension<PreparedAuthority>,
    input: Result<Json<ExternalRunRequest>, JsonRejection>,
) -> Response {
    let Json(request) = match input.map_err(ApiError::from_json_rejection) {
        Ok(request) => request,
        Err(error) => return error.into_response(),
    };
    let ExternalRunRequest {
        program,
        envelope_digest,
        args: _args,
    } = request;
    let program_bytes = program.len();
    if program_bytes > RUN_PROGRAM_MAX_BYTES {
        return ApiError::from(
            SnapbackError::error(
                "SNAPBACK_API_RUN_PROGRAM_TOO_LARGE",
                "api",
                "the submitted code-mode program exceeds the 1 MiB limit",
            )
            .with_details(json!({
                "maximumBytes": RUN_PROGRAM_MAX_BYTES,
                "actualBytes": program_bytes,
            })),
        )
        .into_response();
    }
    let (current_digest, _) = match current_app_api_envelope(&runtime).await {
        Ok(envelope) => envelope,
        Err(error) => return error.into_response(),
    };
    if envelope_digest != current_digest {
        return ApiError::from(
            SnapbackError::error(
                "SNAPBACK_API_RUN_ENVELOPE_STALE",
                "api",
                "the submitted code-mode program targets a stale API envelope",
            )
            .with_details(json!({ "currentEnvelopeDigest": current_digest })),
        )
        .into_response();
    }
    let manifest = current_target_capability_manifest(&runtime).await;
    ApiError::from(run_code_capability_refusal(&manifest)).into_response()
}

const ASK_TASK_MAX_BYTES: usize = 64 * 1024;
