/// `/query/{name}` runs on the lock-free read lane when the instance is
/// file-backed: a pooled WAL reader inside a pinned read transaction, so
/// queries proceed during long writes. In-memory instances (no WAL) keep the
/// serialized write-lane path.
///
/// @ref LLP 0032#phase-3--lifecycle-and-resource-hardening — L6.
async fn invoke_query(
    State(runtime): State<AppState>,
    State(state): State<SharedSnapback>,
    State(read): State<crate::local::ReadLane>,
    Extension(authority): Extension<PreparedAuthority>,
    Extension(route): Extension<RouteSpec>,
    Path(name): Path<String>,
    input: Result<Json<FiniteQueryRequest>, JsonRejection>,
) -> Response {
    let network_profiles = runtime.network_profiles.clone();
    let result: Result<Json<FunctionResponse<FiniteQueryOutput>>, ApiError> = async move {
        let attribution = authority.function_attribution();
        let Json(request) = input
            .map_err(ApiError::from_json_rejection)
            .map_err(|error| error.with_attribution(attribution.clone()))?;
        validate_external_api_request(
            &state,
            route,
            &name,
            request.request.expected_generation.is_some(),
        )
        .await
        .map_err(|error| error.with_attribution(attribution.clone()))?;
        let input = request.request.input;
        let expected_generation = request.request.expected_generation;
        let completeness_namespace = request.completeness_namespace;
        let prior_completeness_proofs = request.prior_completeness_proofs;
        let proof_requested =
            completeness_namespace.is_some() || !prior_completeness_proofs.is_empty();
        // Only finite service authority needs the SQLite-owned terminal cut.
        // Anonymous and session queries are fenced by their process publication
        // handles and must stay off the global write lane so WAL reads remain
        // concurrent with long mutations.
        // @ref LLP 0059#finite-service-authority-fence — service witnesses
        // serialize with terminal writers; unrelated authority classes do not.
        if matches!(
            authority.resolved(),
            ResolvedAppAuthority::ServicePrincipal { .. }
        ) {
            persist_expired_service_authority_owned(&runtime, authority.clone())
                .await
                .map_err(ApiError::from)
                .map_err(|error| error.with_attribution(attribution.clone()))?;
            let authority_to_validate = authority.clone();
            with_snapback(&state, move |snapback| {
                snapback.validate_prepared_service_authority(&authority_to_validate)
            })
            .await
            .map_err(ApiError::from)
            .map_err(|error| error.with_attribution(attribution.clone()))?;
        }
        let (output, facts) = if proof_requested {
            with_snapback(&state, move |snapback| {
                let output = snapback.invoke_finite_query_prepared_generation(
                    &name,
                    input,
                    authority.clone(),
                    expected_generation.as_ref(),
                    completeness_namespace.as_ref(),
                    &prior_completeness_proofs,
                )?;
                authority.validate_admission("finite query generation facts")?;
                let facts = snapback.function_invocation_facts(authority.active_mode())?;
                Ok((output, facts))
            })
            .await
        } else if read.available() {
            with_read_lane(&read, move |lane| {
                lane.invoke_query_prepared_generation_with_facts(
                    &name,
                    input,
                    authority,
                    expected_generation.as_ref(),
                )
            })
            .await
            .map(|(output, facts)| (FiniteQueryOutput::without_proof(output), facts))
        } else {
            with_snapback(&state, move |snapback| {
                let invocation = snapback.invoke_query_with_dependencies_prepared_generation(
                    &name,
                    input,
                    authority.clone(),
                    expected_generation.as_ref(),
                )?;
                authority.validate_admission("query generation facts")?;
                let facts = snapback.function_invocation_facts(authority.active_mode())?;
                Ok((FiniteQueryOutput::without_proof(invocation.output), facts))
            })
            .await
        }
        .map_err(ApiError::from)
        .map_err(|error| error.with_attribution(attribution.clone()))?;
        Ok(Json(FunctionResponse::with_facts(
            output,
            attribution,
            facts,
        )))
    }
    .await;
    // The async invocation future (and therefore PreparedAuthority) is gone
    // before result-readiness is stamped or any timer begins.
    let response = result.into_response();
    let prepared = network_profiles.admit_result(
        crate::network_profile::NetworkEgressLane::QueryResponse,
        Instant::now(),
    );
    release_network_profiled_response(response, prepared).await
}

/// Replay-tuple identities for credential families that do not carry LLP
/// 0077's hosted sender binding. Hosted requests replace this projection with
/// the verified JWK thumbprint and durable sender replay epoch below.
fn bundle_authority_key(resolved: &ResolvedAppAuthority) -> String {
    match resolved {
        ResolvedAppAuthority::Anonymous => "anonymous".to_owned(),
        ResolvedAppAuthority::DevImpersonation { user_id, .. } => format!("dev:{user_id}"),
        ResolvedAppAuthority::Session { user_id, .. } => format!("session:{user_id}"),
        ResolvedAppAuthority::RevalidatedPrincipal { user_id, .. } => {
            format!("watch:{user_id}")
        }
        ResolvedAppAuthority::ServicePrincipal { actor_user_id, .. } => {
            format!("service:{actor_user_id}")
        }
        ResolvedAppAuthority::AdminBypass { .. } => "admin".to_owned(),
        ResolvedAppAuthority::System => "system".to_owned(),
    }
}

fn bundle_sender_identity(resolved: &ResolvedAppAuthority) -> (String, u64) {
    match resolved {
        ResolvedAppAuthority::Anonymous => ("anonymous".to_owned(), 0),
        ResolvedAppAuthority::DevImpersonation { user_id, .. } => (format!("dev:{user_id}"), 0),
        ResolvedAppAuthority::Session {
            session_id,
            authority_instance_id,
            generation,
            ..
        } => (
            format!("session:{authority_instance_id}:{session_id}"),
            *generation,
        ),
        ResolvedAppAuthority::RevalidatedPrincipal {
            authority_instance_id,
            ..
        } => (format!("watch:{authority_instance_id}"), 0),
        ResolvedAppAuthority::ServicePrincipal {
            credential_id,
            token_id,
            credential_generation,
            ..
        } => (
            format!("service:{credential_id}:{token_id}"),
            *credential_generation,
        ),
        ResolvedAppAuthority::AdminBypass { reason } => (format!("admin:{reason}"), 0),
        ResolvedAppAuthority::System => ("system".to_owned(), 0),
    }
}

/// Reap a pending-registration connection: registry removal with terminal
/// capture, which the retirement sink turns into full ephemeral + local
/// topology teardown — demand disarmed, capacity released, grant invalidated
/// (LLP 0092 §0D.4).
fn bundle_reap_connection(runtime: &AppState, connection_id: String, grant_id: String) {
    if let Some(capture) = runtime
        .connections
        .retire_bundle_connection(&connection_id, &grant_id)
    {
        runtime.connections.publish_retirement(capture);
    }
}

fn bundle_refusal(code: &'static str, message: &str) -> ApiError {
    ApiError::from(SnapbackError::error(code, "realtime", message.to_owned()))
}

/// The attach-grace window (LLP 0092 §0D.4: 30 s default, a server policy
/// knob — overridable so acceptance suites can exercise reaping without a
/// 30-second wait).
fn bundle_attach_grace_ms() -> u64 {
    std::env::var("SNAPBACK_BUNDLE_ATTACH_GRACE_MS")
        .ok()
        .and_then(|value| value.parse().ok())
        .unwrap_or(crate::bundle::BUNDLE_ATTACH_GRACE_MS)
}

/// Reap every pending-registration owner past its attach deadline. The
/// maintenance worker calls this every tick; it is public so the acceptance
/// suite can drive the sweep deterministically. Returns the number reaped.
pub fn sweep_pending_bundle_owners(runtime: &AppState) -> usize {
    let now = now_millis();
    let reaped = runtime.bundle_pending.sweep(now);
    let count = reaped.len();
    for (connection_id, grant_id) in reaped {
        bundle_reap_connection(runtime, connection_id, grant_id);
    }
    count
}

/// `POST /app/bundle` — the snapshot bundle endpoint (LLP 0090 D1.2 rollout
/// step 2; the contract is LLP 0092 §0D). Read mode evaluates a manifest
/// entry's queries at one commit cut and creates no server state; register
/// mode additionally arms the pending-registration owner of the LLP 0031
/// dated amendment — the one sanctioned socketless-demand exception.
async fn app_bundle(
    State(runtime): State<AppState>,
    State(state): State<SharedSnapback>,
    Extension(authority): Extension<PreparedAuthority>,
    sender_binding: Option<Extension<HostedSenderGrantBinding>>,
    headers: HeaderMap,
    input: Result<Json<crate::bundle::BundleRequest>, JsonRejection>,
) -> Result<Json<crate::bundle::BundleResponse>, ApiError> {
    use crate::bundle::{self, BundleMode, RegisterAdmission, code};
    let Json(request) = input.map_err(ApiError::from_json_rejection)?;
    let mode = bundle::validate_mode(request.mode.as_deref(), request.idempotency_key.as_deref())
        .map_err(|code| {
        bundle_refusal(code, "bundle mode/idempotency-key combination refused")
    })?;
    if request.auth_invalidation_protocol.is_some_and(|offered| {
        offered != crate::auth::invalidation::AUTH_INVALIDATION_PROTOCOL_VERSION
    }) {
        return Err(ApiError::from(SnapbackError::error(
            "SNAPBACK_AUTH_INVALIDATION_PROTOCOL_UNSUPPORTED",
            "auth",
            "this server understands authInvalidationProtocol 1 only; omit the field to register a legacy connection",
        )));
    }
    if mode == BundleMode::Read
        && (request.auth_invalidation_protocol.is_some()
            || !request.authorization_namespaces.is_empty())
    {
        return Err(bundle_refusal(
            code::MODE_INVALID,
            "read mode cannot negotiate a connection or authorization namespaces",
        ));
    }
    if !request.authorization_namespaces.is_empty()
        && request.auth_invalidation_protocol
            != Some(crate::auth::invalidation::AUTH_INVALIDATION_PROTOCOL_VERSION)
    {
        return Err(bundle_refusal(
            code::MODE_INVALID,
            "authorizationNamespaces require authInvalidationProtocol 1",
        ));
    }
    if mode == BundleMode::Register
        && authority.active_mode() == AuthMode::Sessions
        && request.auth_invalidation_protocol
            != Some(crate::auth::invalidation::AUTH_INVALIDATION_PROTOCOL_VERSION)
    {
        return Err(ApiError::from(SnapbackError::error(
            "SNAPBACK_AUTH_INVALIDATION_CLIENT_UNSUPPORTED",
            "auth",
            "sessions-mode register bundles require authInvalidationProtocol 1",
        )));
    }
    let (epoch_now_ms, monotonic_now) = auth_runtime_now(&runtime);
    let authority_key = bundle_authority_key(authority.resolved());
    runtime
        .bundle_pending
        .admit_rate(&authority_key, epoch_now_ms)
        .map_err(|code| bundle_refusal(code, "per-authority bundle request rate exceeded"))?;
    // Route resolution (LLP 0092 §0C.1, ENG-25448 landed): while a route
    // manifest is served it is the only source of entries and the inline
    // `devManifestEntry` dev/test form refuses by design; without one the
    // inline form is required. Anonymous reads additionally require every
    // named query to carry the codegen-compiled `publicInline` fact in the
    // served functions manifest (§0D.1's NOT_PUBLIC gate — the fact check is
    // server-side, never the route-manifest author's word).
    let anonymous_read =
        mode == BundleMode::Read && matches!(authority.resolved(), ResolvedAppAuthority::Anonymous);
    let entry = {
        let route = request.route.clone();
        let dev_entry = request.dev_manifest_entry.clone();
        with_snapback(&state, move |snapback| {
            let entry = snapback.resolve_bundle_route(&route, dev_entry.as_ref())?;
            if anonymous_read && !snapback.bundle_entry_public_inline(&entry) {
                return Err(SnapbackError::error(
                    code::NOT_PUBLIC,
                    "realtime",
                    "anonymous bundle reads require a publicInline-class route".to_owned(),
                ));
            }
            Ok(entry)
        })
        .await
        .map_err(ApiError::from)?
    };
    let mixed_children = if mode == BundleMode::Register
        && (request.format_version.is_some()
            || request.profile.is_some()
            || request.plan_hash.is_some()
            || entry.mixed_group_eligible)
    {
        let entry_for_admission = entry.clone();
        let format_version = request.format_version;
        let profile = request.profile.clone();
        let plan_hash = request.plan_hash.clone();
        Some(
            with_snapback(&state, move |snapback| {
                bundle::admit_mixed_profile_v2(
                    &entry_for_admission,
                    format_version,
                    profile.as_deref(),
                    plan_hash.as_deref(),
                    |name| snapback.function(name).ok().cloned(),
                )
                .map_err(|code| {
                    SnapbackError::error(
                        code,
                        "realtime",
                        "mixed bundle plan identity refused".to_owned(),
                    )
                })
            })
            .await
            .map_err(ApiError::from)?,
        )
    } else {
        if request.format_version.is_some()
            || request.profile.is_some()
            || request.plan_hash.is_some()
        {
            return Err(bundle_refusal(
                code::MODE_INVALID,
                "formatVersion/profile/planHash are reserved for mixed register bundles",
            ));
        }
        None
    };
    if mode == BundleMode::Register
        && authority.active_mode() == AuthMode::Sessions
        && request.authorization_namespaces.len() != entry.queries.len()
    {
        return Err(bundle_refusal(
            code::ENTRY_INVALID,
            "register-mode authorizationNamespaces must match manifest order",
        ));
    }
    let route = request.route.clone();
    let params = request.params.clone();
    let auth = request.auth.clone();
    match mode {
        BundleMode::Read => {
            let response = with_snapback(&state, move |snapback| {
                snapback.evaluate_bundle(&entry, &params, &route, &auth, &authority, None)
            })
            .await
            .map_err(ApiError::from)?;
            Ok(Json(response))
        }
        BundleMode::Register => {
            if !authority.resolved().carries_user() {
                // Refused explicitly so the client retries in read mode —
                // never a silent mode substitution (LLP 0092 §0D.2).
                return Err(bundle_refusal(
                    code::REGISTER_REQUIRES_CREDENTIAL,
                    "register mode requires a credentialed caller; retry in read mode",
                ));
            }
            let key = request
                .idempotency_key
                .clone()
                .expect("register mode validated the key present");
            let generation = with_snapback(&state, |snapback| snapback.rqs_generation_digest())
                .await
                .map_err(ApiError::from)?;
            // @ref LLP 0077#http-binding — sender-constrained replay scope is
            // the proof-verified thumbprint plus durable replay epoch, not a
            // session-id projection that another custody key can share.
            let (sender_identity, credential_incarnation) = sender_binding
                .as_ref()
                .map(|Extension(binding)| {
                    (
                        format!("jkt:{}", binding.jwk_thumbprint),
                        binding.sender_replay_epoch_at_issuance,
                    )
                })
                .unwrap_or_else(|| bundle_sender_identity(authority.resolved()));
            let identity_of = |value: serde_json::Value| {
                crate::rqs_contract::sha256_identity(&value).map_err(|_| {
                    bundle_refusal(
                        code::ENTRY_INVALID,
                        "bundle entry is not canonically hashable",
                    )
                })
            };
            let entry_identity =
                identity_of(serde_json::to_value(&entry).unwrap_or(serde_json::Value::Null))?;
            let args_identity = identity_of(serde_json::json!({
                "route": route,
                "params": params,
            }))?;
            let scope = bundle::BundleReplayScope {
                authority_key,
                sender_identity,
                credential_incarnation,
                generation,
                entry_identity,
                args_identity,
                auth_invalidation_protocol: request.auth_invalidation_protocol,
                authorization_namespaces: request.authorization_namespaces.clone(),
                wire_format_version: request.format_version,
                wire_profile: request.profile.clone(),
                plan_hash: request.plan_hash.clone(),
            };
            let admission_outcome = runtime
                .bundle_pending
                .begin_register(&key, &scope)
                .map_err(|code| bundle_refusal(code, "bundle idempotency-key admission refused"))?;
            match admission_outcome {
                RegisterAdmission::New => {
                    let presented = presented_session_bearer(&headers);
                    let mut prepared_open =
                        match prepare_connection_open_authority_with_scoped_token(
                            &runtime,
                            presented,
                            epoch_now_ms,
                            monotonic_now,
                            None,
                        )
                        .await
                        {
                            Ok(prepared_open) => prepared_open,
                            Err(error) => {
                                runtime.bundle_pending.abandon_register(&key);
                                return Err(error);
                            }
                        };
                    // @ref LLP 0077#websocket-and-connection-binding — the
                    // proof-gated hosted request must mint the sender-bound
                    // sct2 grant family; dropping this binding here would
                    // create a legacy grant that later uses can bypass.
                    prepared_open.hosted_sender = sender_binding
                        .as_ref()
                        .map(|Extension(binding)| binding.clone());
                    // Atomic mint (LLP 0031 amendment): the grant is
                    // discarded on any downstream failure, so a failed
                    // bundle mints nothing and strands no server state.
                    let opened =
                        match runtime
                            .connections
                            .open_prepared(ConnectionOpenAttempt::new(
                                None,
                                None,
                                false,
                                prepared_open.clone(),
                                epoch_now_ms,
                                monotonic_now,
                                request.auth_invalidation_protocol,
                            )) {
                            Ok(opened) => opened,
                            Err(error) => {
                                runtime.bundle_pending.abandon_register(&key);
                                return Err(ApiError::from(error));
                            }
                        };
                    let target = crate::local::BundleRegisterTarget {
                        connection_id: opened.grant.connection_id.clone(),
                        effect_fence: prepared_open.bound.effect_fence(&opened.grant_id),
                        invalidation_connection: opened.grant.authorization_invalidation.clone(),
                        authorization_namespaces: request.authorization_namespaces.clone(),
                        mixed_children: mixed_children.clone(),
                    };
                    let evaluated = {
                        let entry = entry.clone();
                        let params = params.clone();
                        let route = route.clone();
                        let auth = auth.clone();
                        let authority = authority.clone();
                        let target = target.clone();
                        with_snapback(&state, move |snapback| {
                            snapback.evaluate_bundle(
                                &entry,
                                &params,
                                &route,
                                &auth,
                                &authority,
                                Some(target),
                            )
                        })
                        .await
                    };
                    let mut response = match evaluated {
                        Ok(response) => response,
                        Err(error) => {
                            runtime.connections.discard_unpublished_open(&opened);
                            runtime.bundle_pending.abandon_register(&key);
                            return Err(ApiError::from(error));
                        }
                    };
                    let attach_deadline = epoch_now_ms + bundle_attach_grace_ms();
                    runtime
                        .bundle_pending
                        .commit_register(bundle::PendingRegistrationOwner {
                            idempotency_key: key,
                            scope,
                            connection_id: opened.grant.connection_id.clone(),
                            grant_id: opened.grant_id.clone(),
                            subscription_ids: response
                                .entries
                                .iter()
                                .filter_map(|entry| entry.subscription_id.clone())
                                .collect(),
                            attach_deadline_ms: attach_deadline,
                        });
                    runtime
                        .ephemeral
                        .touch_connection(&opened.grant.connection_id);
                    response.connection = Some(bundle::BundleConnection {
                        connection_id: opened.grant.connection_id.clone(),
                        grant: opened.grant.connection_token.clone(),
                        attach_deadline,
                        authorization_invalidation: opened.grant.authorization_invalidation.clone(),
                    });
                    Ok(Json(response))
                }
                RegisterAdmission::Replay {
                    connection_id,
                    grant_id,
                } => {
                    // Lost-response retry: atomically supersede the pending
                    // set — fresh evaluation at a new commit cut, the same
                    // connection identity, a freshly rotated grant secret.
                    let token = runtime
                        .connections
                        .rotate_grant_token(&connection_id, &grant_id)
                        .map_err(ApiError::from)?;
                    let Some((effect_fence, invalidation_connection)) = runtime
                        .connections
                        .bundle_register_identity(&connection_id, &grant_id)
                    else {
                        runtime
                            .bundle_pending
                            .resolve_key(&key, bundle::PendingResolution::Reaped);
                        return Err(bundle_refusal(
                            code::IDEMPOTENCY_EXPIRED,
                            "the pending connection is no longer installed",
                        ));
                    };
                    let target = crate::local::BundleRegisterTarget {
                        connection_id: connection_id.clone(),
                        effect_fence,
                        invalidation_connection: invalidation_connection.clone(),
                        authorization_namespaces: request.authorization_namespaces.clone(),
                        mixed_children: mixed_children.clone(),
                    };
                    let evaluated = {
                        let entry = entry.clone();
                        let params = params.clone();
                        let route = route.clone();
                        let auth = auth.clone();
                        let authority = authority.clone();
                        let target = target.clone();
                        with_snapback(&state, move |snapback| {
                            // Supersede under the same local cut: purge the
                            // prior pending set, then register afresh.
                            snapback.purge_connection_topology(
                                &target.connection_id,
                                &target.effect_fence,
                            );
                            snapback.evaluate_bundle(
                                &entry,
                                &params,
                                &route,
                                &auth,
                                &authority,
                                Some(target.clone()),
                            )
                        })
                        .await
                    };
                    match evaluated {
                        Ok(mut response) => {
                            let attach_deadline = epoch_now_ms + bundle_attach_grace_ms();
                            runtime.bundle_pending.commit_register(
                                bundle::PendingRegistrationOwner {
                                    idempotency_key: key,
                                    scope,
                                    connection_id: connection_id.clone(),
                                    grant_id,
                                    subscription_ids: response
                                        .entries
                                        .iter()
                                        .filter_map(|entry| entry.subscription_id.clone())
                                        .collect(),
                                    attach_deadline_ms: attach_deadline,
                                },
                            );
                            response.connection = Some(bundle::BundleConnection {
                                connection_id,
                                grant: token,
                                attach_deadline,
                                authorization_invalidation: invalidation_connection,
                            });
                            Ok(Json(response))
                        }
                        Err(error) => {
                            // The prior set is already purged; a failed
                            // supersede reaps the owner entirely so the
                            // client starts a fresh boot with a new key.
                            bundle_reap_connection(&runtime, connection_id, grant_id);
                            runtime
                                .bundle_pending
                                .resolve_key(&key, bundle::PendingResolution::Reaped);
                            Err(ApiError::from(error))
                        }
                    }
                }
            }
        }
    }
}

/// Run a fresh full query, sign outside the app lock (preserving the global
/// provider-before-app lock order), then reacquire the app lane for one exact
/// head/auth/activation/no-pending reservation transaction.
async fn invoke_authorized_lease_query(
    State(runtime): State<AppState>,
    State(state): State<SharedSnapback>,
    Extension(authority): Extension<PreparedAuthority>,
    Path(name): Path<String>,
    headers: HeaderMap,
    request: Result<Json<AuthorizedLeaseQueryRequest>, JsonRejection>,
) -> Result<Json<AuthorizedLeaseQueryResponse>, ApiError> {
    if !runtime.auth_program_readiness().authorized_lease {
        return Err(SnapbackError::error(
            "SNAPBACK_AUTH_POLICY_UNAVAILABLE",
            "auth",
            "authorized retained reads are unavailable in this process",
        )
        .into());
    }
    // @ref LLP 0096#2-per-profile-contract — the lease POST is an ordinary
    // HTTP route: offers ride only the named decimal headers, and a forged
    // `Sec-WebSocket-Protocol` header must not become a second grammar.
    let offers = AuthClientProtocolOffers::from_http_headers(&headers);
    if offers.authorized_lease != Some(u64::from(AUTHORIZED_LEASE_PROTOCOL_VERSION))
        || offers.auth_invalidation != Some(AUTH_PROTOCOL_V1)
    {
        return Err(SnapbackError::error(
            "SNAPBACK_AUTH_PROFILE_CLIENT_UNSUPPORTED",
            "auth",
            "authorized retained reads require exact lease and invalidation protocol offers",
        )
        .into());
    }
    let Json(request) = request.map_err(ApiError::from_json_rejection)?;
    let (input, expected_generation, lease_request) = request.into_parts();
    let (capture, facts) = with_snapback(&state, move |snapback| {
        let facts_mode = authority.active_mode();
        let capture = snapback.capture_authorized_lease_query_generation(
            &name,
            input,
            authority,
            lease_request,
            expected_generation.as_ref(),
        )?;
        Ok::<_, SnapbackError>((capture, snapback.function_invocation_facts(facts_mode)?))
    })
    .await?;

    // Never acquire the protocol keyring while the app instance lock is held.
    let provider = installed_auth_provider(&runtime)?;
    let issued_at_server_ms = provider.now_ms();
    let config = runtime.authorized_lease_config;
    let target_profile_id = capture.target_profile_id.clone();
    let app_id = capture.app_id.clone();
    let lease = provider
        .issue_authorized_lease_at(
            capture.issue.clone(),
            config,
            issued_at_server_ms,
            &target_profile_id,
            &app_id,
        )
        .map_err(ApiError::from)?;
    let lease_for_reservation = lease.clone();
    let completeness = capture.completeness.clone();
    let output = with_snapback(&state, move |snapback| {
        snapback.reserve_captured_authorized_lease(
            capture,
            &lease_for_reservation,
            config,
            issued_at_server_ms,
        )
    })
    .await?;
    Ok(Json(AuthorizedLeaseQueryResponse::from_parts(
        output,
        lease,
        facts,
        completeness,
    )))
}

/// Standalone authenticated settlement acknowledgement. A consumed replay
/// result must be reclaimable even when it was the client's final mutation;
/// requiring a later write to piggyback the ACK otherwise strands every
/// one-shot client's durable result indefinitely.
async fn acknowledge_mutations(
    State(state): State<SharedSnapback>,
    Extension(authority): Extension<PreparedAuthority>,
    input: Result<Json<MutationAcknowledgementRequest>, JsonRejection>,
) -> Result<Json<MutationAcknowledgementResponse>, ApiError> {
    let Json(request) = input.map_err(ApiError::from_json_rejection)?;
    let acknowledged = with_snapback(&state, move |snapback| {
        snapback.acknowledge_client_mutations_with_authority_descriptor(
            &authority,
            request.authority_descriptor.as_ref(),
            &request.client_mutation_ids,
        )
    })
    .await?;
    Ok(Json(MutationAcknowledgementResponse { acknowledged }))
}

async fn issue_operation_identity_range(
    State(state): State<SharedSnapback>,
    Extension(authority): Extension<PreparedAuthority>,
    input: Result<Json<crate::commit_envelope::OperationIdentityRangeRequestV1>, JsonRejection>,
) -> Result<Json<crate::commit_envelope::OperationIdentityRangeResponseV1>, ApiError> {
    let Json(request) = input.map_err(ApiError::from_json_rejection)?;
    if request.schema_version != crate::commit_envelope::operation_identity_range_schema_version() {
        return Err(SnapbackError::error(
            "SNAPBACK_OPERATION_IDENTITY_RANGE_VERSION_UNSUPPORTED",
            "protocol",
            "operation identity range request schema version is unsupported",
        )
        .into());
    }
    let range = with_snapback(&state, move |snapback| {
        snapback.issue_client_operation_identity_range(
            &authority,
            &request.client_audience_id,
            request.authority_descriptor.as_ref(),
            request.previous_range.as_ref(),
        )
    })
    .await?;
    Ok(Json(
        crate::commit_envelope::OperationIdentityRangeResponseV1 {
            schema_version: crate::commit_envelope::operation_identity_range_schema_version(),
            range,
        },
    ))
}

async fn explain_operation_public(
    State(state): State<SharedSnapback>,
    Extension(authority): Extension<PreparedAuthority>,
    input: Result<Json<crate::commit_envelope::OperationExplanationRequestV1>, JsonRejection>,
) -> Result<Json<crate::commit_envelope::OperationExplanationResponseV1>, ApiError> {
    let Json(request) = input.map_err(ApiError::from_json_rejection)?;
    if request.schema_version != crate::commit_envelope::operation_explanation_schema_version() {
        return Err(SnapbackError::error(
            "SNAPBACK_OPERATION_EXPLANATION_VERSION_UNSUPPORTED",
            "protocol",
            "operation explanation request schema version is unsupported",
        )
        .into());
    }
    let client_audience_id = request.client_audience_id.ok_or_else(|| {
        SnapbackError::error(
            "SNAPBACK_OPERATION_EXPLANATION_AUDIENCE_REQUIRED",
            "protocol",
            "public operation explanation requires clientAudienceId",
        )
    })?;
    let explanation = with_snapback(&state, move |snapback| {
        snapback.explain_operation_with_authority(
            &authority,
            request.authority_descriptor.as_ref(),
            &client_audience_id,
            &request.identity,
        )
    })
    .await?;
    Ok(Json(
        crate::commit_envelope::OperationExplanationResponseV1 {
            schema_version: crate::commit_envelope::operation_explanation_schema_version(),
            explanation,
        },
    ))
}

async fn explain_operation_admin(
    State(state): State<SharedSnapback>,
    State(ctx): State<Arc<ServerContext>>,
    headers: HeaderMap,
    input: Result<Json<crate::commit_envelope::OperationExplanationRequestV1>, JsonRejection>,
) -> Result<Json<crate::commit_envelope::OperationExplanationResponseV1>, ApiError> {
    crate::admin::authorize(&ctx, &headers, false)?;
    let Json(request) = input.map_err(ApiError::from_json_rejection)?;
    if request.schema_version != crate::commit_envelope::operation_explanation_schema_version() {
        return Err(SnapbackError::error(
            "SNAPBACK_OPERATION_EXPLANATION_VERSION_UNSUPPORTED",
            "protocol",
            "operation explanation request schema version is unsupported",
        )
        .into());
    }
    let explanation = with_snapback(&state, move |snapback| {
        snapback.explain_operation_as_admin(&request.identity)
    })
    .await?;
    Ok(Json(
        crate::commit_envelope::OperationExplanationResponseV1 {
            schema_version: crate::commit_envelope::operation_explanation_schema_version(),
            explanation,
        },
    ))
}

/// Mutations respond with the MutationOutput fields plus the provider-core
/// MutationReceipt (LLP 0034 §3.2, ENG-22478). A REJECTED mutation still
/// produces a receipt; it rides the error envelope.
async fn invoke_mutation(
    State(runtime): State<AppState>,
    State(state): State<SharedSnapback>,
    Extension(authority): Extension<PreparedAuthority>,
    Extension(route): Extension<RouteSpec>,
    effect_link: Option<Extension<ResolvedCapabilityLink>>,
    Path(name): Path<String>,
    input: Result<Json<MutationRequest>, JsonRejection>,
) -> Response {
    let network_profiles = runtime.network_profiles.clone();
    let mut network_basis = crate::network_profile::MutationEgressBasis::ResultReady;
    let mut trace_client_mutation_id = None;
    // @ref LLP 0200#21-settlement-is-decoupled-from-subscriber-work — the
    // commit-ack instant travels from the write turn to the response boundary
    // so the settlement gap is measured per applied mutation.
    let mut settlement_observation: Option<(
        Instant,
        std::sync::Arc<std::sync::Mutex<crate::local::LiveSettlementStats>>,
    )> = None;
    let result: Result<Json<MutationResponse>, ApiError> = async {
        let attribution = authority.function_attribution();
        let Json(request) = input
            .map_err(ApiError::from_json_rejection)
            .map_err(|error| error.with_attribution(attribution.clone()))?;
        if crate::spike_trace::enabled() {
            trace_client_mutation_id = request.client_mutation_id.clone();
        }
        validate_external_api_request(&state, route, &name, request.expected_generation.is_some())
            .await
            .map_err(|error| error.with_attribution(attribution.clone()))?;
        require_effect_approval_if_configured(
            &state,
            &authority,
            &name,
            &request.input.args,
            effect_link.as_ref().map(|Extension(link)| &link.0),
        )
        .await
        .map_err(|error| error.with_attribution(attribution.clone()))?;
        if let Some(current_id) = request.client_mutation_id.as_deref()
            && request
                .acknowledged_client_mutation_ids
                .iter()
                .any(|acknowledged| acknowledged == current_id)
        {
            return Err(ApiError::from(
                SnapbackError::error(
                    "SNAPBACK_CLIENT_MUTATION_ACK_OVERLAP",
                    "sync",
                    "the current client mutation id cannot be acknowledged by the same request",
                )
                .with_details(json!({ "clientMutationId": current_id })),
            )
            .with_attribution(attribution));
        }
        // Receipt emission rides the L7 blocking offload: the recording call
        // (Hermes eval + rusqlite) runs via with_snapback, and the envelope is
        // assembled from its (result, receipt) pair back on the async side.
        let stage_name = name.clone();
        let stage_input = request.input.clone();
        let stage_client_mutation_id = request.client_mutation_id.clone();
        let stage_authority_descriptor = request.authority_descriptor.clone();
        let stage_acknowledgements = request.acknowledged_client_mutation_ids.clone();
        let stage_expected_generation = request.expected_generation.clone();
        let stage_wire_version = request.wire_version.clone();
        let stage_operation_issuance = request.operation_issuance.clone();
        let stage_settlement = request.settlement.clone();
        let stage_authority = authority.clone();
        let facts_mode = authority.active_mode();
        let facts_authority = authority.clone();
        let (
            result,
            receipt,
            response_authority_descriptor,
            committed_network_basis,
            facts,
            commit_ack,
        ) = with_snapback_staged_authorization_write(
            &state,
            runtime.live_fanout_coalescer.clone(),
            move |snapback| {
                let response_authority_descriptor =
                    snapback.descriptor_for_prepared_authority(&stage_authority)?;
                let (preflight, staged) = snapback
                    .stage_recorded_authorization_mutation_with_wire_version(
                        &stage_name,
                        stage_input.clone(),
                        stage_client_mutation_id.clone(),
                        stage_authority_descriptor.clone(),
                        &stage_acknowledgements,
                        "http",
                        stage_authority.clone(),
                        stage_expected_generation.as_ref(),
                        stage_operation_issuance.clone(),
                        stage_settlement.clone(),
                        stage_wire_version.as_deref(),
                    )?;
                Ok((preflight, (response_authority_descriptor, staged)))
            },
            move |snapback, (response_authority_descriptor, staged)| {
                snapback
                    .commit_staged_recorded_authorization_mutation_with_network_egress(staged)
                    .and_then(|(result, receipt, network_basis)| {
                        let facts = if result.is_ok() {
                            facts_authority.validate_admission("mutation generation facts")?;
                            snapback.function_invocation_facts(facts_mode)?
                        } else {
                            None
                        };
                        // Taken inside the same Local turn that stamped
                        // it, so a concurrent mutation cannot mispair.
                        let commit_ack = snapback
                            .take_last_commit_ack_at()
                            .map(|at| (at, snapback.live_settlement_stats_cell()));
                        Ok((
                            result,
                            receipt,
                            response_authority_descriptor,
                            network_basis,
                            facts,
                            commit_ack,
                        ))
                    })
            },
        )
        .await
        .map_err(ApiError::from)
        .map_err(|error| error.with_attribution(attribution.clone()))?
        .map_err(ApiError::from)
        .map_err(|error| error.with_attribution(attribution.clone()))?;
        network_basis = committed_network_basis;
        settlement_observation = commit_ack;
        crate::spike_trace::mutate_settle(
            crate::spike_trace::timestamp_ms(),
            "handler_result_ready",
            &name,
            trace_client_mutation_id.as_deref(),
            None,
        );
        match result {
            // The mutation envelope carries its attribution member directly
            // (never through the FunctionResponse flatten) so the served bytes
            // stay inside the closed generated mutation.output schema.
            // @ref LLP 0094#0c6-response-shape-divergences-audited-at-137dee8c-defects-not-contract — item 4.
            Ok(output) => Ok(Json(MutationResponse::from_output(
                output,
                receipt,
                attribution,
                response_authority_descriptor,
                facts,
            ))),
            Err(error) => Err(ApiError::with_receipt(error, receipt).with_attribution(attribution)),
        }
    }
    .await;
    // The invocation lease is deliberately released before egress waiting.
    drop(authority);
    let response = result.into_response();
    let prepared =
        prepare_mutation_network_egress(&network_profiles, network_basis, Instant::now());
    let response = release_network_profiled_response(response, prepared).await;
    observe_mutation_settlement(
        response,
        name,
        trace_client_mutation_id,
        settlement_observation,
    )
}

/// Record the first response data frame yielded to Hyper. This is the last
/// application-owned boundary before the transport writes the mutation
/// response, and unlike handler return it includes configured egress delay.
/// It closes §2.1's settlement milestone: the commit-ack→settlement gap for an
/// applied mutation, plus the optional `mutate_settle` measurement trace.
struct MutationSettleBody {
    inner: Body,
    mutation: String,
    client_mutation_id: Option<String>,
    settlement: Option<(
        Instant,
        std::sync::Arc<std::sync::Mutex<crate::local::LiveSettlementStats>>,
    )>,
    status: u16,
    recorded: bool,
}

impl HttpBody for MutationSettleBody {
    type Data = Bytes;
    type Error = axum::Error;

    fn poll_frame(
        self: std::pin::Pin<&mut Self>,
        context: &mut std::task::Context<'_>,
    ) -> std::task::Poll<Option<Result<http_body::Frame<Self::Data>, Self::Error>>> {
        let this = self.get_mut();
        let frame = std::pin::Pin::new(&mut this.inner).poll_frame(context);
        if !this.recorded
            && matches!(
                &frame,
                std::task::Poll::Ready(Some(Ok(frame))) if frame.data_ref().is_some()
            )
        {
            this.recorded = true;
            if let Some((commit_ack_at, stats)) = this.settlement.take() {
                let gap_ms = commit_ack_at.elapsed().as_secs_f64() * 1_000.0;
                let mut stats = stats
                    .lock()
                    .unwrap_or_else(|poisoned| poisoned.into_inner());
                stats.last_commit_ack_to_settlement_ms = gap_ms;
                stats.cumulative_commit_ack_to_settlement_ms += gap_ms;
            }
            crate::spike_trace::mutate_settle(
                crate::spike_trace::timestamp_ms(),
                "http_response_written",
                &this.mutation,
                this.client_mutation_id.as_deref(),
                Some(this.status),
            );
        }
        frame
    }

    fn is_end_stream(&self) -> bool {
        self.inner.is_end_stream()
    }

    fn size_hint(&self) -> http_body::SizeHint {
        self.inner.size_hint()
    }
}

fn observe_mutation_settlement(
    response: Response,
    mutation: String,
    client_mutation_id: Option<String>,
    settlement: Option<(
        Instant,
        std::sync::Arc<std::sync::Mutex<crate::local::LiveSettlementStats>>,
    )>,
) -> Response {
    if settlement.is_none() && !crate::spike_trace::enabled() {
        return response;
    }
    let status = response.status().as_u16();
    let (parts, body) = response.into_parts();
    Response::from_parts(
        parts,
        Body::new(MutationSettleBody {
            inner: body,
            mutation,
            client_mutation_id,
            settlement,
            status,
            recorded: false,
        }),
    )
}

/// Freeze a mutating invocation as a disclosed pending effect when the
/// compiled function gate or a link's per-use posture requires approval.
/// The typed ACCEPTED diagnostic is shared by bare HTTP, `/api/v1`, MCP, and
/// capability-link invocation.
// @ref LLP 0204#d95--approval-gated-effects — all external ingress converges
// here before the ordinary mutation/action effect path.
async fn require_effect_approval_if_configured(
    state: &SharedSnapback,
    authority: &PreparedAuthority,
    name: &str,
    args: &Value,
    link: Option<&crate::storage::capability_links::CapabilityLinkRecord>,
) -> Result<(), ApiError> {
    if authority.source() == InvocationSource::EffectExecution {
        return Ok(());
    }
    let name = name.to_owned();
    let args = args.clone();
    let authority = authority.clone();
    let link = link.cloned();
    let record = with_snapback(state, move |snapback| {
        let function = match snapback.function_definition(&name).cloned() {
            Some(function) => function,
            None => {
                return Err(crate::authoring_suggestion::unknown_function_error(
                    snapback.served_function_manifest(),
                    &name,
                    &[FunctionKind::Mutation, FunctionKind::Action],
                ));
            }
        };
        if !matches!(function.kind, FunctionKind::Mutation | FunctionKind::Action) {
            return Ok(None);
        }
        let approval = function
            .api_exposure
            .as_ref()
            .and_then(|exposure| exposure.approval);
        let gated = match approval {
            Some(crate::manifest::ApiFunctionApproval::Required) => true,
            Some(crate::manifest::ApiFunctionApproval::External) => {
                !matches!(authority.resolved(), ResolvedAppAuthority::Session { .. })
            }
            None => link.as_ref().is_some_and(|link| link.approval_per_use),
        };
        if !gated {
            return Ok(None);
        }
        if !function
            .api_exposure
            .as_ref()
            .is_some_and(|exposure| exposure.expose)
        {
            return Err(SnapbackError::error(
                "SNAPBACK_EFFECT_BINDING_STALE",
                "effects",
                "the approval gate no longer names an exposed function",
            ));
        }
        crate::args_contract::validate_function_args(&function, &args)?;
        let _prepared = InvocationGate::prepare_function(authority.clone(), &function)?;
        let generation = snapback
            .function_invocation_facts(authority.active_mode())?
            .map(|facts| facts.active_generation)
            .ok_or_else(|| {
                SnapbackError::error(
                    "SNAPBACK_EFFECT_BINDING_STALE",
                    "effects",
                    "the active function generation cannot be frozen for approval",
                )
            })?;
        let caller = authority
            .telemetry_caller_details()
            .unwrap_or_else(|| json!({ "callerLane": "first-party", "callerKey": "first-party" }));
        let caller_lane = caller
            .get("callerLane")
            .and_then(Value::as_str)
            .unwrap_or("first-party")
            .to_owned();
        let caller_key = caller
            .get("callerKey")
            .and_then(Value::as_str)
            .filter(|key| !key.is_empty())
            .map(str::to_owned)
            .unwrap_or_else(|| match authority.resolved() {
                ResolvedAppAuthority::Session { user_id, .. } => user_id.clone(),
                ResolvedAppAuthority::ServicePrincipal { actor_user_id, .. } => {
                    actor_user_id.clone()
                }
                _ => "anonymous".to_owned(),
            });
        let snapshot = match authority.resolved() {
            ResolvedAppAuthority::Anonymous => {
                crate::storage::pending_effects::PendingEffectAuthority::Anonymous
            }
            ResolvedAppAuthority::Session {
                user_id,
                session_id,
                provider,
                generation,
                authority_instance_id,
                ..
            } => crate::storage::pending_effects::PendingEffectAuthority::Session {
                user_id: user_id.clone(),
                session_id: session_id.clone(),
                provider: provider.clone(),
                generation: *generation,
                authority_instance_id: authority_instance_id.clone(),
                authorization_stream_incarnation: authority
                    .authorization_stream_incarnation()
                    .ok_or_else(|| {
                        SnapbackError::error(
                            "SNAPBACK_EFFECT_BINDING_STALE",
                            "effects",
                            "session effect authority has no authorization-stream binding",
                        )
                    })?
                    .to_owned(),
            },
            ResolvedAppAuthority::ServicePrincipal {
                actor_user_id,
                credential_id,
                credential_generation,
                grant_id,
                token_id,
                effective_user_id,
                token_expires_at_ms,
                ..
            } => crate::storage::pending_effects::PendingEffectAuthority::ServicePrincipal {
                actor_user_id: actor_user_id.clone(),
                credential_id: credential_id.clone(),
                credential_generation: *credential_generation,
                grant_id: grant_id.clone(),
                token_id: token_id.clone(),
                effective_user_id: effective_user_id.clone(),
                token_expires_at_ms: *token_expires_at_ms,
            },
            _ => {
                return Err(SnapbackError::error(
                    "SNAPBACK_EFFECT_INPUT_INVALID",
                    "effects",
                    "this internal authority class cannot create an external approval intent",
                ));
            }
        };
        let mut declared_write_set = function.write_set_summary.tables.clone();
        if let Some(primary) = function.write_set_summary.primary_table.clone() {
            declared_write_set.push(primary);
        }
        let link_origin_id = link.as_ref().map(|link| link.id.clone());
        let approver_principal_id = link.as_ref().map(|link| link.minter_principal_id.clone());
        snapback
            .auth_database_mut()
            .create_pending_effect(crate::storage::pending_effects::CreatePendingEffect {
                function_id: function.id,
                function_name: function.name,
                function_kind: function.kind,
                args,
                caller_lane,
                caller_key,
                authority: snapshot,
                generation,
                link_origin_id,
                approver_principal_id,
                declared_write_set,
                now_ms: now_millis(),
                ttl_ms: crate::storage::pending_effects::DEFAULT_TTL_MS,
            })
            .map(Some)
    })
    .await?;
    let Some(record) = record else {
        return Ok(());
    };
    Err(ApiError::from(
        SnapbackError::error(
            "SNAPBACK_EFFECT_APPROVAL_PENDING",
            "effects",
            "the effect is frozen and awaits approval",
        )
        .with_details(json!({
            "effectId": record.id,
            "approvalPointer": format!("/effects/{}/approve", record.id),
            "expiresAtMs": record.expires_at_ms,
            "preview": record.preview,
        })),
    ))
}

/// App-data action runner for side-effectful app work that is not a transaction:
/// browser clients can trigger action egress without reaching through the admin
/// function runner, while writes still happen only through declared mutations.
///
/// Ibex actions are staged under the lock, then run detached from it under a
/// wall-clock watchdog, so a hung outbound fetch cannot wedge the instance.
///
/// @ref LLP 0031#the-invariant — app-data routes live at the root.
/// @ref LLP 0028#open-questions — per-request app actions
/// include the All Aboard walk/bike routing call, not just cron jobs.
/// @ref LLP 0028#execution-the-action-class — ENG-23324 detached execution.
#[allow(clippy::too_many_arguments)] // established internal signature; regrouping is out of scope for the lint sweep
async fn invoke_action(
    State(runtime): State<AppState>,
    State(state): State<SharedSnapback>,
    headers: HeaderMap,
    Extension(authority): Extension<PreparedAuthority>,
    Extension(route): Extension<RouteSpec>,
    effect_link: Option<Extension<ResolvedCapabilityLink>>,
    Path(name): Path<String>,
    input: Result<Json<FunctionCallRequest>, JsonRejection>,
) -> Result<Json<FunctionResponse<crate::local::FunctionRunResult>>, ApiError> {
    let attribution = authority.function_attribution();
    let Json(request) = input
        .map_err(ApiError::from_json_rejection)
        .map_err(|error| error.with_attribution(attribution.clone()))?;
    validate_external_api_request(&state, route, &name, request.expected_generation.is_some())
        .await
        .map_err(|error| error.with_attribution(attribution.clone()))?;
    require_effect_approval_if_configured(
        &state,
        &authority,
        &name,
        &request.input.args,
        effect_link.as_ref().map(|Extension(link)| &link.0),
    )
    .await
    .map_err(|error| error.with_attribution(attribution.clone()))?;
    let input = request.input;
    let stream_connection_id = request.stream_connection_id;
    let expected_generation = request.expected_generation;
    let facts_mode = authority.active_mode();
    let facts_authority = authority.clone();
    let mut staged = {
        let name = name.clone();
        with_snapback(&state, move |snapback| {
            snapback.stage_app_action_with_authority_generation(
                &name,
                authority,
                expected_generation.as_ref(),
            )
        })
        .await
    };
    if let StagedAppAction::Ready(stage) = &mut staged
        && let StagedAction::Detached(action) = &mut stage.mode
        && action.stream
        && action.stream_initiator.is_none()
    {
        let connection_id = stream_connection_id.ok_or_else(|| {
            ApiError::from(SnapbackError::error(
                "SNAPBACK_STREAM_INITIATOR_REQUIRED",
                "auth",
                "an anonymous streaming action requires streamConnectionId and its connection token",
            ))
        })?;
        let presented = header_connection_token(&headers);
        let (epoch_now_ms, monotonic_now) = auth_runtime_now(&runtime);
        let prepared = runtime.connections.prepare_act(
            &connection_id,
            presented.as_deref(),
            runtime.auth_coordinator.as_deref(),
            facts_mode == AuthMode::Dev,
            epoch_now_ms,
            monotonic_now,
        )?;
        if !matches!(prepared.resolved, ResolvedAppAuthority::Anonymous) {
            return Err(ApiError::from(SnapbackError::error(
                "SNAPBACK_STREAM_FORBIDDEN",
                "auth",
                "streamConnectionId may bind only anonymous stream authority",
            )));
        }
        action.stream_initiator = Some(
            crate::stream_attempt::StreamInitiator::AnonymousConnection(connection_id),
        );
    }
    let stream_start = match &mut staged {
        StagedAppAction::Ready(stage) => match &mut stage.mode {
            StagedAction::Detached(action) if action.stream => {
                let (started, receiver) = tokio::sync::oneshot::channel();
                action.stream_started = Some(started);
                Some((receiver, stage.reads.clone(), stage.writes.clone()))
            }
            _ => None,
        },
        StagedAppAction::Done(_) => None,
    };
    let result = match (staged, stream_start) {
        (StagedAppAction::Done(result), _) => *result,
        (StagedAppAction::Ready(stage), Some((receiver, reads, writes))) => {
            let background_state = state.clone();
            let background_name = name.clone();
            let task = tokio::spawn(async move {
                run_staged_app_action(&background_state, &background_name, input, stage, "action")
                    .await
            });
            match receiver.await {
                Ok(attempt_token) => crate::local::action_run_result(
                    &name,
                    reads,
                    writes,
                    0,
                    Ok(json!({ "attemptToken": attempt_token })),
                ),
                Err(_) => task.await.unwrap_or_else(|error| {
                    crate::local::action_run_result(
                        &name,
                        reads,
                        writes,
                        0,
                        Err(SnapbackError::error(
                            "SNAPBACK_ACTION_THREAD_FAILED",
                            "runtime",
                            format!(
                                "streaming action task terminated before initialization: {error}"
                            ),
                        )),
                    )
                }),
            }
        }
        (StagedAppAction::Ready(stage), None) => {
            run_staged_app_action(&state, &name, input, stage, "action").await
        }
    };
    if let Some(diagnostic) = result
        .diagnostic
        .as_ref()
        .filter(|diagnostic| diagnostic.code == "SNAPBACK_ARTIFACT_IDENTITY_MISMATCH")
    {
        return Err(
            ApiError::from(SnapbackError::new(diagnostic.clone())).with_attribution(attribution)
        );
    }
    let facts = if result.ok {
        with_snapback(&state, move |snapback| {
            facts_authority.validate_admission("action generation facts")?;
            snapback.function_invocation_facts(facts_mode)
        })
        .await?
    } else {
        None
    };
    Ok(Json(FunctionResponse::with_facts(
        result,
        attribution,
        facts,
    )))
}

fn stream_initiator_from_authority(
    authority: &ResolvedAppAuthority,
) -> Option<crate::stream_attempt::StreamInitiator> {
    match authority {
        ResolvedAppAuthority::Session { user_id, .. }
        | ResolvedAppAuthority::DevImpersonation { user_id, .. } => Some(
            crate::stream_attempt::StreamInitiator::SessionUser(user_id.clone()),
        ),
        ResolvedAppAuthority::ServicePrincipal { credential_id, .. } => Some(
            crate::stream_attempt::StreamInitiator::ServiceCredential(credential_id.clone()),
        ),
        _ => None,
    }
}

async fn read_stream_transcript(
    State(state): State<SharedSnapback>,
    Extension(authority): Extension<PreparedAuthority>,
    Path(attempt_token): Path<String>,
) -> Result<Json<crate::storage::stream_transcripts::StreamTranscriptRecord>, ApiError> {
    let transcript = with_snapback(&state, {
        let attempt_token = attempt_token.clone();
        move |snapback| snapback.stream_transcript(&attempt_token)
    })
    .await?
    .ok_or_else(|| {
        ApiError::from(SnapbackError::error(
            "SNAPBACK_STREAM_TRANSCRIPT_NOT_FOUND",
            "storage",
            "the stream transcript does not exist",
        ))
    })?;
    let candidate = stream_initiator_from_authority(authority.resolved());
    if candidate.as_ref() != Some(&transcript.initiator) {
        return Err(ApiError::from(SnapbackError::error(
            "SNAPBACK_STREAM_TRANSCRIPT_FORBIDDEN",
            "auth",
            "only the stream initiator may read its transcript",
        )));
    }
    Ok(Json(transcript))
}

async fn cancel_stream_attempt(
    State(state): State<SharedSnapback>,
    Extension(authority): Extension<PreparedAuthority>,
    Path(attempt_token): Path<String>,
) -> Result<Json<crate::stream_attempt::StreamAttemptTerminal>, ApiError> {
    let initiator = stream_initiator_from_authority(authority.resolved()).ok_or_else(|| {
        ApiError::from(SnapbackError::error(
            "SNAPBACK_STREAM_FORBIDDEN",
            "auth",
            "stream cancellation requires the initiating authority",
        ))
    })?;
    let output = with_snapback(&state, move |snapback| {
        let registry = crate::stream_attempt::global_stream_attempt_registry();
        let terminal = registry.cancel_by_initiator(&attempt_token, &initiator)?;
        let namespace = snapback.stream_attempt_namespace();
        let snapshots = registry.dirty_snapshots(namespace);
        let rows = snapshots
            .iter()
            .map(crate::stream_attempt::PersistedStreamAttempt::to_row)
            .collect::<SnapbackResult<Vec<_>>>()?;
        snapback.persist_stream_attempts(&rows)?;
        if let Some(snapshot) = registry.stream_output(&attempt_token) {
            snapback.settle_stream_transcript(
                &crate::storage::stream_transcripts::StreamTranscriptRecord {
                    attempt_token: snapshot.attempt_token,
                    function_id: snapshot.function_id,
                    initiator: snapshot.initiator,
                    started_at_ms: snapshot.started_at_ms,
                    settled_at_ms: snapshot.settled_at_ms.unwrap_or_else(now_millis),
                    terminal_cause: terminal.cause,
                    final_text: None,
                    chunk_count: snapshot.chunk_count,
                    prompt_tokens: None,
                    completion_tokens: None,
                },
            )?;
        }
        registry.clear_flushed(&snapshots);
        Ok::<_, SnapbackError>(terminal)
    })
    .await?;
    Ok(Json(output))
}

/// Commit one already-preflighted provisioning pair. Cross-mode changes and
/// every settled-sessions same-mode request own the admission transition:
/// predecessor finite work drains before SQLite can activate, and the local
/// authorization projection completes under the closed epoch before the
/// successor reopens.
async fn commit_prepared_auth_provision(
    runtime: &AppState,
    prepared: PreparedAuthProvision,
    profile: String,
) -> Result<AuthProvisionCommit, ApiError> {
    let predecessor = runtime.auth_mode_state();
    let owns_transition =
        prepared.requested_mode() != predecessor.active || predecessor.active == AuthMode::Sessions;
    let (committed, runtime_state_published) = if owns_transition {
        let controller = runtime.auth_admission_controller();
        let terminal_lifecycle = runtime.auth_terminal_lifecycle.clone();
        let runtime_projection = runtime.clone();
        let snapback = runtime.snapback.clone();
        let transition_task = spawn_owned_auth_transaction(async move {
            let transition = tokio::task::spawn_blocking(move || controller.begin_transition())
                .await
                .map_err(|_| {
                    SnapbackError::error(
                        "SNAPBACK_AUTH_MODE_QUIESCENCE_TIMEOUT",
                        "auth",
                        "auth-mode transition task terminated before closing admission",
                    )
                })??;
            let committed_transition = with_snapback_authorization_write(
                &snapback,
                |_| Ok(crate::storage::AuthorizationCommitPreflight::AllProtectedRooms),
                move |snapback| {
                    transition.commit_and_project_mode_state(|projection_admission| {
                        let committed = snapback.commit_auth_provision_classified(
                            prepared,
                            &profile,
                            Some(projection_admission),
                        )?;
                        let state = committed.state.clone();
                        Ok((committed, state))
                    })
                },
            )
            .await??;
            if let Some(reason) =
                committed_mode_terminal_reason(predecessor.as_ref(), committed_transition.mode())
            {
                let close_by = Instant::now()
                    .checked_add(crate::auth::session_projection::TERMINAL_CLOSE_GRACE)
                    .unwrap_or_else(Instant::now);
                terminal_lifecycle
                    .committed_mode_transition_before_reopen(reason, close_by)
                    .await;
            }
            runtime_projection.publish_auth_mode_state_while_transition_closed(
                committed_transition.mode().clone(),
            )?;
            let (committed, _state, _published) = committed_transition.publish_successor()?;
            Ok::<_, SnapbackError>(committed)
        });
        let committed = await_owned_auth_transaction(transition_task).await??;
        (committed, true)
    } else {
        let committed = match with_snapback_authorization_write(
            &runtime.snapback,
            |_| Ok(crate::storage::AuthorizationCommitPreflight::AllProtectedRooms),
            move |snapback| snapback.commit_auth_provision_classified(prepared, &profile, None),
        )
        .await?
        {
            Ok(committed) => committed,
            Err(ModeCommitFailure::RolledBack(error)) => return Err(ApiError::from(error)),
            Err(ModeCommitFailure::Uncertain(error)) => {
                runtime
                    .auth_admission_controller()
                    .fail_closed_after_uncertain_commit()?;
                return Err(ApiError::from(error));
            }
        };
        (committed, false)
    };

    if !runtime_state_published
        && let Err(error) = runtime.publish_auth_mode_state(committed.state.clone())
    {
        runtime
            .auth_admission_controller()
            .fail_closed_after_uncertain_commit()?;
        return Err(ApiError::from(error));
    }
    Ok(committed)
}

/// The closed mount-lifecycle ensure family (LLP 0012 / LLP 0034): legacy
/// v0-dev compatibility remains idempotent; explicit attestation is
/// observational; explicit provisioning is centrally AdminWrite and then
/// profile-gated before entering the local core.
async fn ensure_app(
    State(runtime): State<AppState>,
    input: Result<Json<EnsureAppRequest>, JsonRejection>,
) -> Result<Json<EnsureAppResponse>, ApiError> {
    let Json(input) = input.map_err(ApiError::from_json_rejection)?;
    match input {
        EnsureAppRequest::Legacy(input) => {
            let provisioning_allowed = runtime.server.profile.allows_provisioning();
            let profile = runtime.server.profile.as_str().to_owned();
            let outcome = with_snapback(&runtime.snapback, move |snapback| {
                snapback.ensure_app(*input, provisioning_allowed, &profile)
            })
            .await?;
            Ok(Json(EnsureAppResponse::Legacy(outcome)))
        }
        EnsureAppRequest::Explicit(explicit) => {
            explicit.validate()?;
            match explicit {
                EnsureAppExplicitInput::Attest {
                    requested_mode,
                    pair,
                } => {
                    let outcome = with_snapback(&runtime.snapback, move |snapback| {
                        snapback.attest_app(requested_mode, *pair)
                    })
                    .await?;
                    Ok(Json(EnsureAppResponse::Attest(outcome)))
                }
                EnsureAppExplicitInput::Provision {
                    requested_mode,
                    schema,
                    functions,
                    seed,
                    routes,
                    api_envelope,
                } => {
                    // HTTP provisioning always needs both AdminWrite (already
                    // consumed by the centralized operation gate) and the
                    // positive non-production profile capability. The latter
                    // runs before the core can inspect hashes or take effects.
                    crate::admin::require_operation_profile(
                        &runtime.server,
                        "app.ensure.provision",
                        false,
                    )?;
                    let prepared = with_snapback(&runtime.snapback, move |snapback| {
                        snapback.prepare_auth_provision_with_routes(
                            requested_mode,
                            schema.map(|manifest| *manifest),
                            functions.map(|manifest| *manifest),
                            seed.map(|seed| *seed),
                            routes.map(|routes| *routes),
                            api_envelope.map(|members| *members),
                        )
                    })
                    .await?;
                    let committed = commit_prepared_auth_provision(
                        &runtime,
                        prepared,
                        runtime.server.profile.as_str().to_owned(),
                    )
                    .await?;
                    Ok(Json(EnsureAppResponse::Provision(committed.outcome)))
                }
            }
        }
    }
}

async fn acknowledge_authorization_invalidation(
    State(runtime): State<AppState>,
    Extension(_authority): Extension<PreparedAuthority>,
    Extension(connection_act): Extension<PreparedConnectionAct>,
    Extension(admission): Extension<AdmissionLease>,
    input: Result<Json<AuthorizationInvalidationAckInput>, JsonRejection>,
) -> Result<Json<crate::local::AuthorizationInvalidationAckOutput>, ApiError> {
    let Json(input) = input.map_err(ApiError::from_json_rejection)?;
    let connection = connection_act
        .authorization_invalidation
        .clone()
        .ok_or_else(|| {
            SnapbackError::error(
                "SNAPBACK_AUTH_INVALIDATION_CLIENT_UNSUPPORTED",
                "auth",
                "open the connection with `authInvalidationProtocol: 1` \
                 (or configure SnapbackClient with that option) before acknowledging \
                 authorization invalidation",
            )
        })?;
    let effect_fence = connection_act.effect_fence();
    let connection_id = input.connection_id.clone();
    let staged_admission = admission.clone();
    let staged = with_snapback(&runtime.snapback, move |snapback| {
        snapback.prepare_authorization_invalidation_ack_for_transport(
            input,
            connection,
            staged_admission,
            effect_fence,
        )
    })
    .await?;
    let (epoch_now_ms, monotonic_now) = auth_runtime_now(&runtime);
    let authority_work = match connection_act.reserve_authority_work(epoch_now_ms, monotonic_now) {
        Ok(authority_work) => authority_work,
        Err(error) => {
            let abandoned = staged.clone();
            with_snapback(&runtime.snapback, move |snapback| {
                snapback.abandon_prepared_live_effect(&abandoned)
            })
            .await;
            return Err(error);
        }
    };
    let committed_stage = staged.clone();
    let committed_fence = connection_act.effect_fence();
    if let Err(error) =
        connection_act.try_act(&runtime.connections, epoch_now_ms, monotonic_now, || {
            let _effect = admission.effect_guard("authorization invalidation acknowledgement")?;
            committed_stage
                .try_commit(&connection_id, &committed_fence)
                .map_err(ApiError::from)
        })
    {
        drop(authority_work);
        let abandoned = staged.clone();
        with_snapback(&runtime.snapback, move |snapback| {
            snapback.abandon_prepared_live_effect(&abandoned)
        })
        .await;
        return Err(error);
    }
    let finalize_state = runtime.snapback.clone();
    let finalize = tokio::spawn(async move {
        with_snapback(&finalize_state, move |snapback| {
            authority_work.with_retained_service_authority(|| {
                snapback.finalize_authorization_invalidation_ack_for_transport(&staged)
            })
        })
        .await
    });
    let output = finalize
        .await
        .map_err(|_| live_finalize_task_failed())?
        .map_err(ApiError::from)?;
    Ok(Json(output))
}

async fn manual_retry_authorization_invalidation(
    State(runtime): State<AppState>,
    Extension(authority): Extension<PreparedAuthority>,
    Extension(connection_act): Extension<PreparedConnectionAct>,
    Extension(admission): Extension<AdmissionLease>,
    input: Result<Json<AuthorizationInvalidationManualRetryInput>, JsonRejection>,
) -> Result<Json<crate::local::AuthorizationInvalidationManualRetryOutput>, ApiError> {
    let Json(input) = input.map_err(ApiError::from_json_rejection)?;
    let connection = connection_act
        .authorization_invalidation
        .clone()
        .ok_or_else(|| {
            SnapbackError::error(
                "SNAPBACK_AUTH_INVALIDATION_CLIENT_UNSUPPORTED",
                "auth",
                "open the connection with `authInvalidationProtocol: 1` \
                 (or configure SnapbackClient with that option) before manually retrying \
                 authorization invalidation",
            )
        })?;
    let effect_fence = connection_act.effect_fence();
    let connection_id = input.connection_id.clone();
    let staged = with_snapback(&runtime.snapback, move |snapback| {
        snapback.prepare_authorization_invalidation_manual_retry_for_transport(
            input,
            connection,
            authority,
            effect_fence,
        )
    })
    .await?;
    let (epoch_now_ms, monotonic_now) = auth_runtime_now(&runtime);
    let authority_work = match connection_act.reserve_authority_work(epoch_now_ms, monotonic_now) {
        Ok(authority_work) => authority_work,
        Err(error) => {
            let abandoned = staged.clone();
            with_snapback(&runtime.snapback, move |snapback| {
                snapback.abandon_prepared_live_effect(&abandoned)
            })
            .await;
            return Err(error);
        }
    };
    let committed_stage = staged.clone();
    let committed_fence = connection_act.effect_fence();
    if let Err(error) =
        connection_act.try_act(&runtime.connections, epoch_now_ms, monotonic_now, || {
            let _effect = admission.effect_guard("authorization invalidation manual retry")?;
            committed_stage
                .try_commit(&connection_id, &committed_fence)
                .map_err(ApiError::from)
        })
    {
        drop(authority_work);
        let abandoned = staged.clone();
        with_snapback(&runtime.snapback, move |snapback| {
            snapback.abandon_prepared_live_effect(&abandoned)
        })
        .await;
        return Err(error);
    }
    let finalize_state = runtime.snapback.clone();
    let finalize = tokio::spawn(async move {
        with_snapback(&finalize_state, move |snapback| {
            authority_work.with_retained_service_authority(|| {
                snapback.finalize_authorization_invalidation_manual_retry_for_transport(&staged)
            })
        })
        .await
    });
    let output = finalize
        .await
        .map_err(|_| live_finalize_task_failed())?
        .map_err(ApiError::from)?;
    Ok(Json(output))
}

async fn subscribe_live(
    State(runtime): State<AppState>,
    Extension(authority): Extension<PreparedAuthority>,
    Extension(connection_act): Extension<PreparedConnectionAct>,
    Extension(admission): Extension<AdmissionLease>,
    Path(name): Path<String>,
    input: Result<Json<LiveSubscribeRequest>, JsonRejection>,
) -> Result<Response, ApiError> {
    let Json(request) = input.map_err(ApiError::from_json_rejection)?;
    let input = request.input;
    let invalidation = LiveInvalidationAdmission {
        connection: connection_act.authorization_invalidation.clone(),
        effect_fence: Some(connection_act.effect_fence()),
        #[cfg(test)]
        session_mode: false,
    };
    let connection_id = input.connection_id.clone();
    let staged = with_snapback(&runtime.snapback, move |snapback| {
        snapback.prepare_subscribe_live_for_transport_generation(
            name,
            input,
            authority,
            invalidation,
            request.expected_generation,
        )
    })
    .await?;
    let (epoch_now_ms, monotonic_now) = auth_runtime_now(&runtime);
    let authority_work = match connection_act.reserve_authority_work(epoch_now_ms, monotonic_now) {
        Ok(authority_work) => authority_work,
        Err(error) => {
            let abandoned = staged.clone();
            with_snapback(&runtime.snapback, move |snapback| {
                snapback.abandon_prepared_live_effect(&abandoned)
            })
            .await;
            return Err(error);
        }
    };
    let committed_stage = staged.clone();
    let committed_fence = connection_act.effect_fence();
    if let Err(error) =
        connection_act.try_act(&runtime.connections, epoch_now_ms, monotonic_now, || {
            let _effect = admission.effect_guard("live subscribe publication")?;
            committed_stage
                .try_commit(&connection_id, &committed_fence)
                .map_err(ApiError::from)
        })
    {
        drop(authority_work);
        let abandoned = staged.clone();
        with_snapback(&runtime.snapback, move |snapback| {
            snapback.abandon_prepared_live_effect(&abandoned)
        })
        .await;
        return Err(error);
    }
    let finalize_state = runtime.snapback.clone();
    let finalize = tokio::spawn(async move {
        with_snapback(&finalize_state, move |snapback| {
            authority_work.with_retained_service_authority(|| {
                snapback.finalize_subscribe_live_for_transport(&staged)
            })
        })
        .await
    });
    let publication = finalize
        .await
        .map_err(|_| live_finalize_task_failed())?
        .map_err(ApiError::from)?;
    let publication_authority = if let Some(authorization) = publication.authorization {
        runtime
            .ephemeral
            .begin_final_send(&RealtimeEnvelope::Durable(
                crate::ephemeral::DurableMessage::authorized(Vec::new(), authorization),
            ))
            .map_err(|error| ApiError::from(SnapbackError::new(diagnostic_from_ephemeral(error))))?
    } else {
        None
    };
    let mut response = Json(publication.output).into_response();
    if let Some(permit) = publication_authority {
        retain_realtime_authority_in(&mut response, vec![permit]);
    }
    Ok(response)
}

